const renderScenePreview = (node) => {
  if (!node || typeof node !== 'object') return '';
  if (node.type === 'slot') {
    const copy = {
      cover: '▣',
      title: fixtureTrack.title,
      artist: fixtureTrack.artist,
      album: fixtureTrack.album,
      lyrics: fixtureLyrics.join('\n'),
