export const nativeShellExePattern = /^(?!\/)(?![A-Za-z]:)(?!.*\\)(?!.*(?:^|\/)\.{1,2}(?:\/|$))[^<>:"|?*]+\.[eE][xX][eE]$/u;

const permissionSet = new Set(nativeShellPermissions);
const exePattern = nativeShellExePattern;

