export const validateNativeShellEntry = (value, expectedId) => {
  if (!value || typeof value !== 'object' || Array.isArray(value) || value.type !== 'echo-workshop-native-shell' || value.schemaVersion !== 1) {
    throw new Error('native-shell.json has an invalid package header');
  }
  if (value.id !== expectedId) throw new Error('native-shell id must match the outer manifest');
  if (value.protocolVersion !== 1) throw new Error('native-shell protocolVersion must be 1');
  if (!Array.isArray(value.platforms) || !value.platforms.includes('win32')) throw new Error('native-shell platforms must include win32');
  if (typeof value.exe !== 'string' || !exePattern.test(value.exe)) throw new Error('native-shell exe path is invalid');
  if (!Array.isArray(value.permissions) || value.permissions.length < 1) throw new Error('native-shell permissions are required');
  for (const permission of value.permissions) {
    if (!permissionSet.has(permission)) throw new Error(`Unsupported native-shell permission: ${permission}`);
  }
  for (const key of ['renderer', 'config', 'configSchema', 'configUi', 'icon']) {
    const path = value[key];
    if (path == null) continue;
    if (typeof path !== 'string' || path.includes('\\') || path.startsWith('/') || path.includes('..')) {
      throw new Error(`native-shell ${key} path is invalid`);
    }
  }
  return value;
};

export const testNativeShell = (entry) => {
  const checks = [];
  const push = (id, ok, error) => {
    checks.push({ id, ok, error: ok ? undefined : error });
  };
  try {
    validateNativeShellEntry(entry, entry?.id);
    push('header', true);
  } catch (error) {
    push('header', false, error instanceof Error ? error.message : String(error));
  }
  push('protocol', entry?.protocolVersion === 1, 'protocolVersion must be 1');
  push('exe-path', typeof entry?.exe === 'string' && exePattern.test(entry.exe), 'exe must be a relative .exe path');
  push('permissions', Array.isArray(entry?.permissions) && entry.permissions.every((item) => permissionSet.has(item)), 'permissions must be from the native-shell contract');
  push('exe-extension', extname(String(entry?.exe || '')).toLowerCase() === '.exe', 'exe extension must be .exe');
  return { ok: checks.every((check) => check.ok), kind: 'native-shell', fixtures: ['schema', 'protocol-v1'], checks };
};

import { isIP } from 'node:net';

const localHostnameSuffixes = ['.home.arpa', '.internal', '.lan', '.local', '.localdomain', '.localhost'];

const ipv4Number = (address) => {
  if (isIP(address) !== 4) return null;
  const octets = address.split('.').map(Number);
  return (((octets[0] << 24) >>> 0) + (octets[1] << 16) + (octets[2] << 8) + octets[3]) >>> 0;
};

const inIpv4Cidr = (address, base, prefixLength) => {
  const baseAddress = ipv4Number(base);
  if (baseAddress === null) return false;
  const mask = prefixLength === 0 ? 0 : (0xffffffff << (32 - prefixLength)) >>> 0;
  return ((address & mask) >>> 0) === ((baseAddress & mask) >>> 0);
};

const blockedIpv4Ranges = [
  ['0.0.0.0', 8], ['10.0.0.0', 8], ['100.64.0.0', 10], ['127.0.0.0', 8],
  ['169.254.0.0', 16], ['172.16.0.0', 12], ['192.0.0.0', 24], ['192.0.2.0', 24],
  ['192.88.99.0', 24], ['192.168.0.0', 16], ['198.18.0.0', 15], ['198.51.100.0', 24],
  ['203.0.113.0', 24], ['224.0.0.0', 4], ['240.0.0.0', 4],
];

export const isPublicWorkshopHost = (value) => {
  const host = typeof value === 'string' ? value.trim().toLowerCase() : '';
  if (!host || host.length > 253 || host === 'localhost' || host.includes('%')
    || host.includes('://') || host.includes('/') || host.includes(':') || host.includes('*')
    || host.startsWith('.') || host.endsWith('.')) return false;
  const numeric = ipv4Number(host);
  if (numeric !== null) {
    return !blockedIpv4Ranges.some(([base, prefixLength]) => inIpv4Cidr(numeric, base, prefixLength));
  }
  if (isIP(host) !== 0 || !host.includes('.') || host.split('.').some((label) => (
    !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/u.test(label)
  ))) return false;
  if (localHostnameSuffixes.some((suffix) => host.endsWith(suffix))) return false;
  try {
    return new URL(`https://${host}`).hostname === host;
  } catch {
    return false;
  }
};

export const normalizeWorkshopNetworkHosts = (value) => {
  if (value === undefined) return [];
  if (!Array.isArray(value) || value.length > 32) throw new Error('Workshop networkHosts are invalid');
  const hosts = value.map((entry) => typeof entry === 'string' ? entry.trim().toLowerCase() : '');
  if (hosts.some((host) => !isPublicWorkshopHost(host)) || new Set(hosts).size !== hosts.length) {
    throw new Error('Workshop networkHosts are invalid');
  }
  return hosts;
};

export const validateWorkshopNetworkDeclaration = (manifest, packageValue) => {
  const hosts = normalizeWorkshopNetworkHosts(manifest?.networkHosts);
  if (manifest?.content?.kind !== 'plugin-package' && hosts.length > 0) {
    throw new Error('Only plug-in packages may declare networkHosts');
  }
  const permissions = new Set(Array.isArray(packageValue?.manifest?.permissions) ? packageValue.manifest.permissions : []);
  if (permissions.has('network:request') && hosts.length === 0) {
    throw new Error('network:request requires fixed networkHosts on the outer manifest');
  }
  if (hosts.length > 0 && !permissions.has('network:request') && !permissions.has('playback:share')) {
    throw new Error('networkHosts require network:request or playback:share');
  }
  return hosts;
};

export const assertWorkshopMockUrl = (value, declaredHosts, errorCode = 'network-url-invalid') => {
  let url;
  try {
    url = new URL(value);
  } catch {
    throw new Error(errorCode);
  }
  if ((url.protocol !== 'https:' && url.protocol !== 'http:') || url.username || url.password) {
    throw new Error(errorCode === 'share-destination-denied' ? errorCode : 'network-url-unsupported');
  }
  if (url.port) throw new Error(errorCode === 'share-destination-denied' ? errorCode : 'network-port-denied');
  if (!declaredHosts.includes(url.hostname.toLowerCase())) {
    throw new Error(errorCode === 'share-destination-denied' ? errorCode : 'network-host-denied');
  }
  if (!isPublicWorkshopHost(url.hostname)) {
    throw new Error(errorCode === 'share-destination-denied' ? errorCode : 'network-address-denied');
  }
  return url;
};

import { deflateSync } from 'node:zlib';

const crcTable = new Uint32Array(256);
for (let index = 0; index < 256; index += 1) {
  let value = index;
  for (let bit = 0; bit < 8; bit += 1) {
    value = value & 1 ? 0xedb88320 ^ (value >>> 1) : value >>> 1;
  }
  crcTable[index] = value >>> 0;
}

const crc32 = (buffer) => {
  let crc = 0xffffffff;
  for (const byte of buffer) crc = crcTable[(crc ^ byte) & 0xff] ^ (crc >>> 8);
  return (crc ^ 0xffffffff) >>> 0;
};

const chunk = (type, data) => {
  const typeBuffer = Buffer.from(type, 'ascii');
  const length = Buffer.alloc(4);
  length.writeUInt32BE(data.length);
  const crc = Buffer.alloc(4);
  crc.writeUInt32BE(crc32(Buffer.concat([typeBuffer, data])));
  return Buffer.concat([length, typeBuffer, data, crc]);
};

export const listingPreviewSize = 256;

export const createListingPreviewPng = (width = listingPreviewSize, height = listingPreviewSize) => {
  const raw = Buffer.alloc((width * 3 + 1) * height);
  for (let y = 0; y < height; y += 1) {
    const row = y * (width * 3 + 1);
    raw[row] = 0;
    for (let x = 0; x < width; x += 1) {
      const pixel = row + 1 + x * 3;
      raw[pixel] = 18 + Math.floor((x / width) * 36);
      raw[pixel + 1] = 32 + Math.floor((y / height) * 72);
      raw[pixel + 2] = 56 + Math.floor(((x + y) / (width + height)) * 120);
    }
  }
  const header = Buffer.alloc(13);
  header.writeUInt32BE(width, 0);
  header.writeUInt32BE(height, 4);
  header[8] = 8;
  header[9] = 2;
  return Buffer.concat([
    Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]),
    chunk('IHDR', header),
    chunk('IDAT', deflateSync(raw)),
    chunk('IEND', Buffer.alloc(0)),
  ]);
};

