export const resolveRecipe = (value) => {
  const id = String(value ?? '').trim();
  if (!id) return null;
  const recipe = workshopRecipes.find((item) => item.id === id);
  if (!recipe) {
    throw new Error(`Unknown --recipe ${id}. Use: ${workshopRecipes.map((item) => item.id).join(', ')}`);
  }
  return recipe;
};

