    {
      "path": "panel.css",
      "content": "/*! Lattice Wall | Copyright (c) 2026 Lattice Wall contributors\n * SPDX-License-Identifier: AGPL-3.0-only\n * See LICENSE and NOTICE.md in the Workshop item for license and source information.\n */\n\n/* 00-base.css */\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\n/* Fallbacks only: main.ts writes the live host appearance tokens inline on <html>. */\n:root {\n  color-scheme: dark;\n  --host-accent: #6678ff;\n  --host-accent-text: #ffffff;\n  --host-app-bg: #0f1116;\n  --host-text: #f2f4f8;\n  --host-muted: #9aa3b5;\n  --host-panel: #171a22;\n  --host-border: #2a2f3b;\n  --host-player: #171a22;\n  --host-accent-2: color-mix(in srgb, var(--host-accent) 45%, var(--host-text));\n  --shade-color: #000000;\n  --wall-background: #000000;\n  --wall-text: #ffffff;\n  --wall-muted: rgb(255 255 255 / 72%);\n}\n\nhtml[data-color-scheme=\"light\"] {\n  color-scheme: light;\n  --host-app-bg: #f3f4f8;\n  --host-text: #15181f;\n  --host-muted: #5f6777;\n  --host-panel: #ffffff;\n  --host-border: #d7dbe4;\n  --host-player: #ffffff;\n}\n\nhtml,\nbody {\n  margin: 0;\n  height: 100%;\n  overflow: hidden;\n}\n\nbody {\n  font-family: var(--ui-font, system-ui, -apple-system, \"Segoe UI\", \"PingFang SC\", \"Microsoft YaHei\", sans-serif);\n  color: var(--host-text);\n  background: var(--wall-background);\n  -webkit-font-smoothing: antialiased;\n}\n\n/* Transparent from the first frame, before the bridge or library has finished booting. */\nhtml:has(body[data-opening=\"true\"]) {\n  color-scheme: normal;\n  background: transparent;\n}\n\nbody[data-opening=\"true\"] {\n  background: transparent;\n}\n\n:focus-visible {\n  outline: 2px solid var(--host-accent);\n  outline-offset: 2px;\n}\n\n.sr-only {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  margin: -1px;\n  padding: 0;\n  border: 0;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\nbody[data-reduced-motion=\"true\"] .field__vignette,\nbody[data-reduced-motion=\"true\"] .world {\n  transition: none;\n}\n\n/* 10-wall.css */\n.lattice{\n  position: fixed;\n  inset: 0;\n  overflow: hidden;\n}\n\n.field{\n  position: absolute;\n  inset: 0;\n  /* The camera owns movement; focusing controls must never scroll this canvas. */\n  overflow: clip;\n  touch-action: none;\n  user-select: none;\n  -webkit-user-select: none;\n  cursor: grab;\n  outline: none;\n  isolation: isolate;\n  background: var(--wall-background);\n}\n\n/* Unfilled areas reveal the actual previous ECHO page, not a substitute colour. */\nbody[data-opening=\"true\"] .field{ background: transparent; }\n\nbody[data-dragging=\"true\"] .field{\n  cursor: grabbing;\n}\n\n/* Paint the focus outline above the poster cards. */\n.field:focus-visible{\n  outline: 2px solid color-mix(in srgb, var(--host-accent) 55%, transparent);\n  outline-offset: -2px;\n}\n\n.world{\n  position: absolute;\n  left: 0;\n  top: 0;\n  width: 0;\n  height: 0;\n  transform-origin: 0 0;\n  will-change: transform;\n  z-index: 1;\n}\n\n.wall-depth-scene{\n  position: absolute;\n  inset: 0;\n  transform-origin: 50% 50%;\n  --depth-x: 0;\n  --depth-y: 0;\n  --depth-amount: 0;\n}\n.wall-depth-scene[data-depth-active=\"true\"]::after{\n  content: '';\n  position: absolute;\n  inset: 0;\n  z-index: 2;\n  pointer-events: none;\n  opacity: calc(var(--depth-amount) * .34);\n  background: radial-gradient(ellipse 80% 75% at calc(50% + var(--depth-x) * 30%) calc(50% + var(--depth-y) * 30%), rgb(255 255 255 / 18%), transparent 70%);\n  mix-blend-mode: screen;\n}\n/* Project the shared wall plane after flattening its native UI layers. Keeping a 3D context\n   here lets the full-size scene hit plane occlude controls on the tilted-away half. The scene\n   matrix still supplies perspective; foreground depth comes from the per-layer XY parallax. */\n\n.fisheye-surface{\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  pointer-events: none;\n  z-index: 0;\n}\n.fisheye-surface[hidden]{ display: none; }\n\n.field__vignette{\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n  z-index: 2;\n  opacity: 0;\n  transition: opacity 0.3s;\n  background: radial-gradient(ellipse at center, transparent 46%, rgb(0 0 0 / 74%) 100%);\n}\n\nbody[data-vignette=\"true\"] .field__vignette{\n  opacity: 1;\n}\n\nbody[data-lighting=\"daytime\"] .field__vignette{\n  opacity: 0;\n}\n\nhtml[data-color-scheme=\"light\"] .field__vignette{\n  background: radial-gradient(ellipse at center, transparent 46%, rgb(0 0 0 / 48%) 100%);\n}\n\nbody[data-opening=\"true\"] .field__vignette,\nbody[data-opening=\"true\"] .wall-depth-scene::after{ opacity: 0; transition: none; }\n\n/* 20-poster.css */\n/* Poster cards. Position and size come from inline `transform` / `width` / `height` written by\n   posterWall.ts; nothing below may set `transform` on `.poster` itself. */\n\n.poster{\n  --expanded-pad: clamp(18px, 4.5%, 40px);\n  position: absolute;\n  left: 0;\n  top: 0;\n  transform-origin: 0 0;\n  box-sizing: border-box;\n  border-radius: 0;\n  overflow: hidden;\n  contain: layout paint;\n  background: var(--host-panel);\n  color: #fff;\n  cursor: pointer;\n  user-select: none;\n  -webkit-tap-highlight-color: transparent;\n}\n\n.world[data-fisheye-surface=\"true\"] .poster{\n  background: transparent;\n  /* UI units follow the curved cover beyond the card's straight four-corner outline. */\n  overflow: visible;\n  contain: layout;\n}\n.world[data-fisheye-surface=\"true\"] .poster__body{ visibility: hidden; }\n\n.poster__meta,\n.poster__lyrics,\n.poster__controls,\n.poster__caption{ transform-origin: 0 0; }\n\n/* Covers stay borderless when focused or expanded. */\n.poster:focus-visible{\n  outline: none;\n}\n\n.poster[data-expanded=\"true\"] {\n  /* Keep the mounted node in place: re-appending it cancels its lighting transitions. */\n  z-index: 10;\n  cursor: default;\n}\n\n/* Layers ------------------------------------------------------------------------------------- */\n\n.poster__body{\n  position: absolute;\n  inset: 0;\n  transform-origin: center;\n  transition: transform .28s cubic-bezier(.2, .8, .2, 1), filter .28s ease;\n}\n\n/* Scale follows pointer or keyboard focus. Lighting is only hover / playing / expanded. */\n.poster:hover .poster__body,\n.poster[data-focused=\"true\"] .poster__body{\n  transform: scale(var(--hx, 1.06), var(--hy, 1.06));\n}\n\n.poster:hover .poster__body{\n  filter: saturate(1.22) brightness(1.16);\n}\n\nbody[data-dragging=\"true\"] .poster .poster__body{\n  transform: none;\n  filter: none;\n}\n\n.poster[data-expanded=\"true\"] .poster__body{\n  transform: none;\n  filter: brightness(1.18) saturate(1.12);\n}\n\n.poster__fallback{\n  position: absolute;\n  inset: 0;\n}\n\n.poster__art{\n  position: absolute;\n  inset: 0;\n  transform-origin: center;\n}\n.world[data-depth=\"true\"] .poster__art{\n  transform: translate(calc(var(--depth-x) * var(--depth-amount) * var(--depth-art-shift)), calc(var(--depth-y) * var(--depth-amount) * var(--depth-art-shift))) scale(calc(1 + var(--depth-amount) * var(--depth-art-scale)));\n}\n\n.poster__cover{\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  display: block;\n  object-fit: cover;\n  -webkit-user-drag: none;\n}\n\n/* Local album thumbs are centre-cropped squares; preserve that framing in the large variant. */\n.poster[data-square-cover=\"true\"] .poster__cover{\n  inset: auto;\n  left: 50%;\n  top: 50%;\n  width: var(--cover-side, 100%);\n  height: var(--cover-side, 100%);\n  transform: translate(-50%, -50%);\n}\n\n.poster__cover[hidden] {\n  display: none;\n}\n\n.poster__shade{\n  position: absolute;\n  inset: 0;\n  /* Keep the expanded gradient stable; idle covers use their separately configured tint. */\n  background:\n    linear-gradient(180deg, transparent 14%, color-mix(in srgb, var(--shade-color, #000) 48%, transparent) 56%, color-mix(in srgb, var(--shade-color, #000) 94%, transparent) 100%),\n    linear-gradient(90deg, color-mix(in srgb, var(--sh