// Harness-only, bounded DOM observations. No playback or host API calls.
const frame = document.getElementById('frame');
const output = document.getElementById('motion-audit');
let cleanup = () => {};
frame.addEventListener('load', () => {
  cleanup();
  const doc = frame.contentDocument;
  if (!doc || new URL(frame.src).pathname !== '/panel.html') return;
  let raf = 0, observer = null, mutations = 0, started = 0;
  let samples = [], lastSample = 0;
  const read = () => {
    const root = doc.querySelector('.poster[data-expanded="true"]');
    const rect = selector => root?.querySelector(selector)?.getBoundingClientRect();
    const controls = rect('.poster__controls'), artist = rect('.poster__artist');
    const slot = rect('.poster__lyrics'), text = rect('.lyrics__line--current .lyrics__text');
    const title = rect('.poster__title-text');
    if (!controls || !artist || !slot || !title) return null;
    return {
      controlsX: controls.x, controlsY: controls.y, artistX: artist.x,
      artistToSlot: artist.bottom - slot.y,
      textToSlot: text ? text.y - slot.y : null,
      titleX: title.x, titleY: title.y, titleHeight: title.height, slotHeight: slot.height,
    };
  };
  const report = () => {
    const span = key => {
      const values = samples.map(s => s[key]).filter(v => v !== null);
      return values.length ? +(Math.max(...values) - Math.min(...values)).toFixed(4) : 0;
    };
    const drift = Object.fromEntries(['controlsX', 'controlsY', 'artistX', 'artistToSlot', 'textToSlot', 'titleX'].map(k => [k, span(k)]));
    // Full measurements remain inspectable in the DOM, with a single bounded latest run.
    output.dataset.samples = JSON.stringify(samples);
    output.dataset.result = JSON.stringify({ frames: samples.length, drift, mutations });
    output.textContent = `motion: ${samples.length} frames · controls Δ ${drift.controlsX}/${drift.controlsY}px · lyric Δ ${drift.textToSlot}px · text edits ${mutations}`;
  };
  const tick = time => {
    const sample = read();
    if (sample && time - lastSample >= 8 && samples.length < 240) { samples.push(sample); lastSample = time; }
    if (time - started < 1200) raf = requestAnimationFrame(tick);
    else { observer?.disconnect(); observer = null; report(); }
  };
  const click = event => {
    if (!event.target.closest('.controls__button--lyrics')) return;
    if (!raf || performance.now() - started > 1200) {
      samples = [];
      mutations = 0;
      observer?.disconnect();
      observer = new MutationObserver(records => {
        mutations += records.filter(r => r.type === 'characterData' || [...r.addedNodes, ...r.removedNodes].some(n => n.nodeType === 3 || n.nodeType === 1 && n.matches?.('.lyrics__word'))).length;
      });
      const slot = doc.querySelector('.poster[data-expanded="true"] .poster__lyrics');
      if (slot) observer.observe(slot, { subtree: true, childList: true, characterData: true });
    }
    cancelAnimationFrame(raf);
    started = performance.now();
    const sample = read();
    if (sample) samples.push(sample);
    raf = requestAnimationFrame(tick);
  };
  doc.addEventListener('click', click, true);
  cleanup = () => {
    cancelAnimationFrame(raf);
    observer?.disconnect();
    doc.removeEventListener('click', click, true);
    samples = [];
  };
});

// Block layout solver (SPEC §5). Searches the block templates and the expansion reflows instead of
// hand-drawing them inside a fixed 12×8 box:
//   1. Templates: large-neighbourhood simulated annealing over exact covers of the whole block,
//      scored for looks (no long straight gutters, no "+" crossings, a balanced size mix, heroes
//      kept apart, neighbours of different sizes).
//   2. Reflows: for every template slot, the 6×6 is placed as close to the card's centre as
//      possible and only a local neighbourhood is re-tiled, growing ring by ring when that spreads
//      the squeeze over more cards; displaced cards are assigned with the Hungarian algorithm.
// Deterministic (seeded). Writes source/panel/geometry/blockLayouts.json. Run with `npm run reflows`.

import { statSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { performance } from 'node:perf_hooks';
import { Worker, isMainThread, parentPort, workerData } from 'node:worker_threads';
import { BLOCK_COLS, BLOCK_ROWS, EXPANDED_SIZE, SLOTS_PER_BLOCK, TEMPLATE_COUNT } from '../source/panel/types.ts';
import { ALLOWED_SIZES, isAllowedSize, isExactCover } from '../source/panel/geometry/blockShapes.ts';

const COLS = BLOCK_COLS;
const ROWS = BLOCK_ROWS;
const CELLS = COLS * ROWS;
const MIN_AREA = Math.min(...ALLOWED_SIZES.map(([w, h]) => w * h));
const MAX_AREA = Math.max(...ALLOWED_SIZES.map(([w, h]) => w * h));
const ANNEAL_STEPS = 150000;
const COVER_CAP = 4000;
const outputPath = resolve(import.meta.dirname, '..', 'source', 'panel', 'geometry', 'blockLayouts.json');
const startedAt = performance.now();

if (CELLS !== SLOTS_PER_BLOCK * 8) throw new Error('Expected an average card area of 8 cells');

// --- seeded randomness --------------------------------------------------------------------------

function mulberry32(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let z = state;
    z = Math.imul(z ^ (z >>> 15), z | 1);
    z ^= z + Math.imul(z ^ (z >>> 7), z | 61);
    return ((z ^ (z >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffled(list, random) {
  const out = list.slice();
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [out[i], out[j]] = [out[j], out[i]];
  }
  return out;
}

// --- exact covers of a free-cell mask -----------------------------------------------------------

/**
 * Depth-first exact cover of the cells where `blocked[i] === 0`, using exactly `pieces` allowed
 * rects. Always fills the first free cell in row-major order, so each cover is visited once.
 * `visit(rects)` returns true to stop. Sizes are tried in `options.order(col, row)` order when given,
 * shuffled with `options.random`, or in `ALLOWED_SIZES` order.
 */
function forEachCover(blocked, pieces, visit, options = {}) {
  const grid = Uint8Array.from(blocked);
  let free = 0;
  for (let i = 0; i < CELLS; i++) if (grid[i] === 0) free++;
  const placed = [];
  const random = options.random;
  let budget = options.budget ?? Infinity;
  let stopped = false;

  const fits = (c, r, w, h) => {
    if (c + w > COLS || r + h > ROWS) return false;
    for (let y = r; y < r + h; y++) {
      for (let x = c; x < c + w; x++) if (grid[y * COLS + x]) return false;
    }
    return true;
  };
  const paint = (c, r, w, h, value) => {
    for (let y = r; y < r + h; y++) {
      for (let x = c; x < c + w; x++) grid[y * COLS + x] = value;
    }
  };
  const search = (from, cellsLeft, piecesLeft) => {
    if (stopped || --budget < 0) { stopped = true; return; }
    if (piecesLeft === 0) {
      if (cellsLeft === 0 && visit(placed.map((rect) => ({ ...rect })))) stopped = true;
      return;
    }
    if (cellsLeft < piecesLeft * MIN_AREA || cellsLeft > piecesLeft * MAX_AREA) return;
    let index = from;
    while (grid[index]) index++;
    const c = index % COLS;
    const r = (index - c) / COLS;
    const sizes = options.order ? options.order(c, r) : random ? shuffled(ALLOWED_SIZES, random) : ALLOWED_SIZES;
    for (const [w, h] of sizes) {
      if (!fits(c, r, w, h)) continue;
      paint(c, r, w, h, 1);
      placed.push({ col: c, row: r, w, h });
      search(index + 1, cellsLeft - w * h, piecesLeft - 1);
      placed.pop();
      paint(c, r, w, h, 0);
      if (stopped) return;
    }
  };
  search(0, free, pieces);
}

/** One random exact cover of the free cells with exactly `pieces` rects, or null. */
function randomCover(blocked, pieces, random, budget = 20000) {
  let found = null;
  forEachCover(blocked, pieces, (rects) => { found = rects; return true; }, { random, budget });
  return found;
}

// --- aesthetic score (lower is better) ------------------------------------------------------------

/** Target card counts per area class for one block (sums to SLOTS_PER_BLOCK cards, CELLS cells). */
const MIX_TARGET = new Map([[4, 11], [6, 7], [8, 4], [12, 4], [16, 2], [18, 1], [24, 1]]);
{
  const cards = [...MIX_TARGET.values()].reduce((sum, count) => sum + count, 0);
  const area = [...MIX_TARGET].reduce((sum, [cells, count]) => sum + cells * count, 0);
  if (cards !== SLOTS_PER_BLOCK || area !== CELLS) throw new Error(`MIX_TARGET must describe ${SLOTS_PER_BLOCK} cards over ${CELLS} cells`);
}
const HERO_AREA = 16;
const W = {
  seam: 1, // per (run − 6)² of a straight gutter running past one card edge
  cross: 4, // four cards meeting at one point ("+" instead of "T")
  same: 2, // neighbours with the identical size read as a repeated grid
  heroTouch: 6, // two heroes sharing an edge
  heroNear: 0.4, // per (9 − centre distance)² between heroes
  mix: 1.5, // per squared deviation from MIX_TARGET
  orient: 0.5, // per squared portrait / landscape imbalance
};

function ownerGrid(layout) {
  const owner = new Int16Array(CELLS).fill(-1);
  layout.forEach(({ col, row, w, h }, index) => {
    for (let y = row; y < row + h; y++) {
      for (let x = col; x < col + w; x++) owner[y * COLS + x] = index;
    }
  });
  return owner;
}

function scoreLayout(layout) {
  const owner = ownerGrid(layout);
  let score = 0;
  const runPenalty = (length) => (length > 6 ? (length - 6) ** 2 : 0);
  // Straight gutters: maximal runs of consecutive edge cells along each interior line.
  for (let y = 1; y < ROWS; y++) {
    let run = 0;
    for (let x = 0; x <= COLS; x++) {
      const edge = x < COLS && owner[(y - 1) * COLS + x] !== owner[y * COLS + x];
      if (edge) run++;
      else { score += W.seam * runPenalty(run); run = 0; }
    }
  }
  for (let x = 1; x < COLS; x++) {
    let run = 0;
    for (let y = 0; y <= ROWS; y++) {
      const edge = y < ROWS && owner[y * COLS + x - 1] !== owner[y * COLS + x];
      if (edge) run++;
      else { score += W.seam * runPenalty(run); run = 0; }
    }
  }
  // "+" junctions.
  for (let y = 1; y < ROWS; y++) {
    for (let x = 1; x < COLS; x++) {
      const a = owner[(y - 1) * COLS + x - 1];
      const b = owner[(y - 1) * COLS + x];
      const c = owner[y * COLS + x - 1];
      const d = owner[y * COLS + x];
      if (a !== b && c !== d && a !== c && b !== d) score += W.cross;
    }
  }
  // Neighbour pairs (each counted once).
  const seen = new Set();
  const visitPair = (i, j) => {
    if (i === j) return;
    const key = i < j ? i * 64 + j : j * 64 + i;
    if (seen.has(key)) return;
    seen.add(key);
    const p = layout[i];
    const q = layout[j];
    if (p.w === q.w && p.h === q.h) score += W.same;
    if (p.w * p.h >= HERO_AREA && q.w * q.h >= HERO_AREA) score += W.heroTouch;
  };
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      const here = owner[y * COLS + x];
      if (x + 1 < COLS) visitPair(here, owner[y * COLS + x + 1]);
      if (y + 1 < ROWS) visitPair(here, owner[(y + 1) * COLS + x]);
    }
  }
  // Size mix, orientation balance and hero spacing.
  const counts = new Map();
  let portrait = 0;
  let landscape = 0;
  const heroes = [];
  for (const rect of layout) {
    const area = rect.w * rect.h;
    counts.set(area, (counts.get(area) ?? 0) + 1);
    if (rect.h > rect.w) portrait++;
    else if (rect.w > rect.h) landscape++;
    if (area >= HERO_AREA) heroes.push([rect.col + rect.w / 2, rect.row + rect.h / 2]);
  }
  for (const [area, target] of MIX_TARGET) score += W.mix * ((counts.get(area) ?? 0) - target) ** 2;
  score += W.orient * (portrait - landscape) ** 2;
  for (let i = 0; i < heroes.length; i++) {
    for (let j = i + 1; j < heroes.length; j++) {
      const distance = Math.hypot(heroes[i][0] - heroes[j][0], heroes[i][1] - heroes[j][1]);
      if (distance < 9) score += W.heroNear * (9 - distance) ** 2;
    }
  }
  return score;
}

// --- template search ------------------------------------------------------------------------------

function byReadingOrder(a, b) {
  return a.row - b.row || a.col - b.col;
}

/** Large-neighbourhood annealing: free the cards inside a random window, re-tile them, keep or undo. */
function searchTemplate(seed) {
  const random = mulberry32(seed);
  let layout = null;
  while (layout === null) layout = randomCover(new Uint8Array(CELLS), SLOTS_PER_BLOCK, random, 400000);
  let score = scoreLayout(layout);
  let best = layout;
  let bestScore = score;
  const hot = 6;
  const cold = 0.03;
  for (let step = 0; step < ANNEAL_STEPS; step++) {
    const temperature = hot * (cold / hot) ** (step / ANNEAL_STEPS);
    const ww = 4 + Math.floor(random() * 7);
    const wh = 4 + Math.floor(random() * 6);
    const x0 = Math.floor(random() * (COLS - ww + 1));
    const y0 = Math.floor(random() * (ROWS - wh + 1));
    const inside = [];
    const keep = [];
    for (const rect of layout) {
      const contained = rect.col >= x0 && rect.row >= y0 && rect.col + rect.w <= x0 + ww && rect.row + rect.h <= y0 + wh;
      (contained ? inside : keep).push(rect);
    }
    if (inside.length < 2) continue;
    const blocked = new Uint8Array(CELLS).fill(1);
    for (const { col, row, w, h } of inside) {
      for (let y = row; y < row + h; y++) {
        for (let x = col; x < col + w; x++) blocked[y * COLS + x] = 0;
      }
    }
    const replacement = randomCover(blocked, inside.length, random, 4000);
    if (replacement === null) continue;
    const candidate = keep.concat(replacement);
    const candidateScore = scoreLayout(candidate);
    if (candidateScore <= score || random() < Math.exp((score - candidateScore) / temperature)) {
      layout = candidate;
      score = candidateScore;
      if (score < bestScore) {
        best = layout;
        bestScore = score;
      }
    }
  }
  return { layout: best.slice().sort(byReadingOrder), score: bestScore };
}

// --- reflows --------------------------------------------------------------------------------------

const LAMBDA = 0.35; // area change, per cell, in the assignment cost
const MOVE_COST = 0.6; // per displaced card, so untouched neighbours stay put
const SHIFT_COST = 2.5; // per cell between the 6×6 centre and the card's own centre
const SHIFT_EXCESS = 8; // per squared cell beyond the nearest feasible 6×6, so a card grows in place
const LOOK_COST = 0.5; // weight of the block score change, judged for every candidate cover
const MAX_RINGS = 2;
const CANDIDATE_LIMIT = 10;
const REFLOW_COVER_CAP = 600; // covers in the near-original pass
// Short passes in seeded random size order: DFS backtracking only varies the last pieces of a cover,
// so several short random starts reach more distinct layouts than one long pass.
const RANDOM_PASSES = 6;
const RANDOM_PASS_CAP = 120;

/** Minimum-cost perfect assignment (Kuhn–Munkres with potentials), O(n³). */
function hungarian(cost, n) {
  const u = new Float64Array(n + 1);
  const v = new Float64Array(n + 1);
  const p = new Int32Array(n + 1);
  const way = new Int32Array(n + 1);
  for (let i = 1; i <= n; i++) {
    p[0] = i;
    let j0 = 0;
    const minv = new Float64Array(n + 1).fill(Infinity);
    const used = new Uint8Array(n + 1);
    do {
      used[j0] = 1;
      const i0 = p[j0];
      let delta = Infinity;
      let j1 = 0;
      for (let j = 1; j <= n; j++) {
        if (used[j]) continue;
        const current = cost[(i0 - 1) * n + j - 1] - u[i0] - v[j];
        if (current < minv[j]) { minv[j] = current; way[j] = j0; }
        if (minv[j] < delta) { delta = minv[j]; j1 = j; }
      }
      for (let j = 0; j <= n; j++) {
        if (used[j]) { u[p[j]] += delta; v[j] -= delta; } else minv[j] -= delta;
      }
      j0 = j1;
    } while (p[j0] !== 0);
    do { const j1 = way[j0]; p[j0] = p[j1]; j0 = j1; } while (j0);
  }
  const assignment = new Int32Array(n);
  for (let j = 1; j <= n; j++) assignment[p[j] - 1] = j - 1;
  let total = 0;
  for (let i = 0; i < n; i++) total += cost[i * n + assignment[i]];
  return { assignment, total };
}

const overlaps = (a, b) => a.col < b.col + b.w && b.col < a.col + a.w && a.row < b.row + b.h && b.row < a.row + a.h;
const touches = (a, b) =>
  (a.col + a.w === b.col || b.col + b.w === a.col) && a.row < b.row + b.h && b.row < a.row + a.h
  || (a.row + a.h === b.row || b.row + b.h === a.row) && a.col < b.col + b.w && b.col < a.col + a.w;

/** Re-tile the cells of `affected` cards around a 6×6 at `box`; null when no cover exists. */
function retile(template, owner, slot, box, affected, baseScore) {
  const blocked = new Uint8Array(CELLS).fill(1);
  for (const index of affected) {
    const { col, row, w, h } = template[index];
    for (let y = row; y < row + h; y++) {
      for (let x = col; x < col + w; x++) blocked[y * COLS + x] = 0;
    }
  }
  for (let y = box.row; y < box.row + EXPANDED_SIZE; y++) {
    for (let x = box.col; x < box.col + EXPANDED_SIZE; x++) blocked[y * COLS + x] = 1;
  }
  const displaced = [...affected].filter((index) => index !== slot).sort((a, b) => a - b);
  const k = displaced.length;
  if (k === 0) return null;
  // Try shapes close to the card that used to cover a cell first, so early covers resemble the original.
  const order = (c, r) => {
    const before = template[owner[r * COLS + c]];
    const area = before.w * before.h;
    return ALLOWED_SIZES.slice().sort((a, b) =>
      Math.abs(a[0] * a[1] - area) + 0.1 * (Math.abs(a[0] - before.w) + Math.abs(a[1] - before.h))
      - Math.abs(b[0] * b[1] - area) - 0.1 * (Math.abs(b[0] - before.w) + Math.abs(b[1] - before.h)));
  };
  const cost = new Float64Array(k * k);
  const fixed = SHIFT_COST * box.distance + SHIFT_EXCESS * box.excess ** 2;
  let best = null;
  let visited = 0;
  let cap = REFLOW_COVER_CAP;
  const visit = (cover) => {
    let bound = 0;
    for (let i = 0; i < k; i++) {
      const from = template[displaced[i]];
      const fx = from.col + from.w / 2;
      const fy = from.row + from.h / 2;
      let cheapest = Infinity;
      for (let j = 0; j < k; j++) {
        const to = cover[j];
        const value = Math.hypot(to.col + to.w / 2 - fx, to.row + to.h / 2 - fy) + LAMBDA * Math.abs(to.w * to.h - from.w * from.h);
        cost[i * k + j] = value;
        if (value < cheapest) cheapest = value;
      }
      bound += cheapest;
    }
    // Scores are never negative, so a cover can improve the looks by at most `baseScore`.
    if (best === null || bound + fixed - LOOK_COST * baseScore < best.cost) {
      const { assignment, total } = hungarian(cost, k);
      const layout = template.map((rect) => ({ ...rect }));
      layout[slot] = { col: box.col, row: box.row, w: EXPANDED_SIZE, h: EXPANDED_SIZE };
      let moved = 0;
      displaced.forEach((index, i) => {
        const next = cover[assignment[i]];
        const before = template[index];
        if (next.col !== before.col || next.row !== before.row || next.w !== before.w || next.h !== before.h) moved++;
        layout[index] = { ...next };
      });
      const combined = total + MOVE_COST * moved + fixed + LOOK_COST * (scoreLayout(layout) - baseScore);
      if (best === null || combined < best.cost) best = { layout, cost: combined, moved, box };
    }
    return ++visited >= cap;
  };
  forEachCover(blocked, k, visit, { order, budget: 400000 });
  const random = mulberry32(slot * 7919 + box.row * 131 + box.col * 17 + affected.size);
  cap = RANDOM_PASS_CAP;
  for (let pass = 0; pass < RANDOM_PASSES; pass++) {
    visited = 0;
    forEachCover(blocked, k, visit, { random, budget: 200000 });
  }
  return best;
}

function solveReflow(template, slot, baseScore) {
  const owner = ownerGrid(template);
  const target = template[slot];
  const tx = target.col + target.w / 2;
  const ty = target.row + target.h / 2;
  const boxes = [];
  for (let row = 0; row + EXPANDED_SIZE <= ROWS; row++) {
    for (let col = 0; col + EXPANDED_SIZE <= COLS; col++) {
      boxes.push({ col, row, w: EXPANDED_SIZE, h: EXPANDED_SIZE, distance: Math.hypot(col + EXPANDED_SIZE / 2 - tx, row + EXPANDED_SIZE / 2 - ty) });
    }
  }
  boxes.sort((a, b) => a.distance - b.distance || a.row - b.row || a.col - b.col);
  for (const box of boxes) box.excess = box.distance - boxes[0].distance;
  // The 6×6 always covers part of the card that was clicked, so it visibly grows out of it.
  const growing = boxes.filter((box) => overlaps(box, target));
  let best = null;
  for (const box of growing.slice(0, CANDIDATE_LIMIT)) {
    const affected = new Set([slot]);
    template.forEach((rect, index) => { if (overlaps(rect, box)) affected.add(index); });
    for (let ring = 0; ring <= MAX_RINGS; ring++) {
      if (ring > 0) {
        const grown = [...affected];
        template.forEach((rect, index) => {
          if (!affected.has(index) && grown.some((other) => touches(rect, template[other]))) affected.add(index);
        });
      }
      const result = retile(template, owner, slot, box, affected, baseScore);
      if (result !== null && (best === null || result.cost < best.cost)) best = result;
    }
  }
  return best;
}

// --- driver: one worker per template (template search + its reflows) ------------------------------

const TEMPLATE_SEEDS = [11, 23, 37, 51, 73];

function validate(layout, label, expandedSlot = -1) {
  if (layout.length !== SLOTS_PER_BLOCK) throw new Error(`${label}: ${layout.length} rects`);
  if (!isExactCover(layout)) throw new Error(`${label}: not an exact cover`);
  layout.forEach((rect, index) => {
    if (index === expandedSlot) {
      if (rect.w !== EXPANDED_SIZE || rect.h !== EXPANDED_SIZE) throw new Error(`${label}: expanded slot is not 6×6`);
    } else if (!isAllowedSize(rect.w, rect.h)) {
      throw new Error(`${label}: slot ${index} is ${rect.w}×${rect.h}`);
    }
  });
}

function solveTemplate(t) {
  const { layout, score } = searchTemplate(TEMPLATE_SEEDS[t]);
  const table = [];
  let moved = 0;
  let shift = 0;
  for (let s = 0; s < SLOTS_PER_BLOCK; s++) {
    const solved = solveReflow(layout, s, score);
    if (solved === null) throw new Error(`No reflow for template ${t} slot ${s}`);
    table.push(solved.layout);
    moved += solved.moved;
    shift += solved.box.distance;
  }
  return { layout, score, table, moved, shift };
}

if (!isMainThread) {
  parentPort.postMessage(solveTemplate(workerData.template));
  process.exit(0);
}

const solvedTemplates = await Promise.all(Array.from({ length: TEMPLATE_COUNT }, (_, t) => new Promise((done, fail) => {
  const worker = new Worker(new URL(import.meta.url), { workerData: { template: t } });
  worker.once('message', (result) => {
    console.log(`template ${t}: score ${result.score.toFixed(1)}, reflows solved`);
    done(result);
  });
  worker.once('error', fail);
  worker.once('exit', (code) => { if (code !== 0) fail(new Error(`template ${t} worker exited with ${code}`)); });
})));

const templates = [];
const reflows = [];
let movedTotal = 0;
let shiftTotal = 0;
solvedTemplates.forEach(({ layout: template, table, moved, shift }, t) => {
  validate(template, `template ${t}`);
  templates.push({ layout: template });
  reflows.push(table.map((layout, s) => {
    validate(layout, `template ${t} slot ${s}`, s);
    const delta = [];
    layout.forEach((rect, index) => {
      const before = template[index];
      if (rect.col !== before.col || rect.row !== before.row || rect.w !== before.w || rect.h !== before.h) {
        delta.push(index, rect.col, rect.row, rect.w, rect.h);
      }
    });
    return delta;
  }));
  movedTotal += moved;
  shiftTotal += shift;
});

const flat = (layout) => layout.flatMap(({ col, row, w, h }) => [col, row, w, h]);
const lines = [
  '{',
  '  "version": 2,',
  `  "block": [${COLS}, ${ROWS}],`,
  `  "slots": ${SLOTS_PER_BLOCK},`,
  `  "expanded": ${EXPANDED_SIZE},`,
  '  "templates": [',
  ...templates.map(({ layout }, t) => `    ${JSON.stringify(flat(layout))}${t < templates.length - 1 ? ',' : ''}`),
  '  ],',
  '  "reflows": [',
];
reflows.forEach((table, t) => {
  lines.push('    [');
  table.forEach((delta, s) => lines.push(`      ${JSON.stringify(delta)}${s < table.length - 1 ? ',' : ''}`));
  lines.push(`    ]${t < reflows.length - 1 ? ',' : ''}`);
});
lines.push('  ]', '}', '');
const json = lines.join('\n');
JSON.parse(json);
writeFileSync(outputPath, json, 'utf8');

const count = TEMPLATE_COUNT * SLOTS_PER_BLOCK;
console.log(`\nWrote ${outputPath} (${statSync(outputPath).size} bytes)`);
console.log(`${count} reflows: ${(movedTotal / count).toFixed(1)} cards moved and ${(shiftTotal / count).toFixed(2)} cells of 6×6 shift on average`);
console.log(`${(performance.now() - startedAt).toFixed(0)} ms`);

// Release-only corresponding-source snapshot; it is data and is not loaded by the plug-in.
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { lstat, readdir, readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';

const root = resolve(import.meta.dirname, '..');
const packageJson = JSON.parse(await readFile(resolve(root, 'package.json'), 'utf8'));
const workshop = JSON.parse(await readFile(resolve(root, 'content/echo.workshop.json'), 'utf8'));
const plugin = JSON.parse(await readFile(resolve(root, 'content/community.echo'), 'utf8'));
if (workshop.version !== packageJson.version || plugin.manifest.version !== packageJson.version) {
  throw new Error('Source snapshot and plug-in versions must match');
}
const paths = ['.gitignore', 'ASSET_SOURCES.md', 'CUSTOMIZE.md', 'LICENSE', 'NOTICE.md',
  'README.md', 'README.zh-CN.md', 'build.mjs', 'echo.workshop.project.json',
  'package.json', 'package-lock.json', 'preview.png', 'tsconfig.json',
  'content/community.echo', 'content/echo.workshop.json', 'content/LICENSE', 'content/NOTICE.md'];
async function collect(directory) {
  for (const entry of await readdir(resolve(root, directory), { withFileTypes: true })) {
    const path = `${directory}/${entry.name}`;
    if (entry.isSymbolicLink()) throw new Error(`Source symlink is not allowed: ${path}`);
    if (entry.isDirectory()) await collect(path);
    else if (entry.isFile()) paths.push(path);
    else throw new Error(`Special source file is not allowed: ${path}`);
  }
}
for (const directory of ['source', 'scripts', 'src', '.echo-sdk']) await collect(directory);
const files = [];
for (const path of paths.sort()) {
  if (!(await lstat(resolve(root, path))).isFile()) throw new Error(`Invalid source file: ${path}`);
  let bytes = await readFile(resolve(root, path));
  // The archive cannot contain itself; its reconstructed manifest inventories the remaining files.
  if (path === 'content/echo.workshop.json') {
    const manifest = JSON.parse(bytes.toString('utf8'));
    manifest.files = manifest.files.filter(file => file.path !== 'SOURCE.json');
    bytes = Buffer.from(`${JSON.stringify(manifest, null, 2)}\n`);
  }
  const encoding = path === 'preview.png' ? 'base64' : 'utf8';
  files.push({ path, encoding, sha256: createHash('sha256').update(bytes).digest('hex'), content: bytes.toString(encoding) });
}
const snapshot = { format: 'lattice-wall-source', schemaVersion: 1, id: workshop.id,
  version: packageJson.version, generatedAt: new Date().toISOString(),
  baseCommit: execFileSync('git', ['rev-parse', 'HEAD'], { cwd: root, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim(),
  build: ['npm ci', 'npm run check'], files };
const output = `${JSON.stringify(snapshot, null, 2)}\n`;
if (Buffer.byteLength(output) > 4 * 1024 * 1024) throw new Error('Source snapshot exceeds 4 MiB');
await writeFile(resolve(root, 'content/SOURCE.json'), output);
console.log(`Packaged corresponding source ${snapshot.version}: ${files.length} files, ${Buffer.byteLength(output)} bytes.`);

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { albumTiles, currentAlbumIndex, createPageLoader, ALBUM_PAGE_SIZE, ALBUM_PROBES } from '../source/panel/albums/albumModel.ts';
import { deriveMissingCapabilities } from '../source/panel/host/bridge.ts';

const album = (overrides = {}) => ({ id: 'a', title: 'Album', albumArtist: 'Artist', mediaType: 'local', year: 2026, trackCount: 12, durationSeconds: 2400, coverUrl: null, ...overrides });
const track = (overrides = {}) => ({ id: 'song', album: 'Album', artist: 'Guest', albumArtist: 'Artist', mediaType: 'local', ...overrides });

test('album identity and numbering use the host one-based pages, independently of queue IDs', () => {
  const first = albumTiles([album()], 1)[0];
  const next = albumTiles([album()], 2)[0];
  assert.equal(first.index, 0);
  assert.equal(next.index, 60);
  assert.equal(next.queueId, first.queueId);
  assert.equal(next.albumId, 'a');
  assert.equal(next.coverUrl, null);
});

test('current album requires a unique title, album artist and media type match', () => {
  assert.equal(currentAlbumIndex([album()], track()), 0);
  assert.equal(currentAlbumIndex([album({ title: ' ALBUM ' })], track()), 0);
  assert.equal(currentAlbumIndex([album()], track({ albumArtist: 'Other' })), null);
  assert.equal(currentAlbumIndex([album()], track({ mediaType: 'remote' })), null);
  assert.equal(currentAlbumIndex([album(), album({ id: 'b' })], track()), null);
  assert.equal(currentAlbumIndex([album()], null), null);
  assert.equal(currentAlbumIndex([album()], track({ albumArtist: '', artist: 'Artist' })), 0);
});

test('a delayed page never replaces a newer search; cancel also discards in-flight pages', async () => {
  const requests = [];
  const loader = createPageLoader(query => new Promise((resolve, reject) => requests.push({ query, resolve, reject })), ALBUM_PAGE_SIZE);
  const old = loader.load(1, 'old');
  const fresh = loader.load(2, 'new');
  assert.deepEqual(requests[1].query, { page: 2, pageSize: 60, search: 'new', sourceProvider: 'local' });
  requests[1].resolve({ page: 2, pageSize: 60, total: 90, hasMore: false, items: [album()] });
  assert.equal((await fresh).page, 2);
  requests[0].reject(new Error('late failure'));
  assert.equal(await old, null);
  const cancelled = loader.load(1);
  loader.cancel();
  requests[2].resolve({ items: [album()] });
  assert.equal(await cancelled, null);
});

test('the page loader retains only the requested page size and exposes current errors', async () => {
  const loader = createPageLoader(async () => ({ items: Array.from({ length: 1000 }, () => album()) }), ALBUM_PAGE_SIZE);
  assert.equal((await loader.load(1)).items.length, 60);
  const failed = createPageLoader(async () => { throw new Error('offline'); }, 50);
  await assert.rejects(failed.load(1), /offline/);
});

test('album capability probing requires library and collection playback but not lyrics', () => {
  const features = Object.fromEntries(ALBUM_PROBES.map(([, action]) => [action, { granted: true, available: true }]));
  assert.deepEqual(deriveMissingCapabilities({ features }, ALBUM_PROBES), []);
  features['library:getAlbums'].granted = false;
  assert.deepEqual(deriveMissingCapabilities({ features }, ALBUM_PROBES), ['library:read']);
  features['queue:playAlbum'].available = false;
  assert.deepEqual(deriveMissingCapabilities({ features }, ALBUM_PROBES), ['library:read', 'queue:control']);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createCamera } from '../source/panel/wall/camera.ts';

function near(actual, expected, epsilon = 1e-9) {
  assert.ok(Math.abs(actual - expected) <= epsilon, `expected ${actual} ≈ ${expected} (±${epsilon})`);
}

/** Tick from `fromMs` (exclusive) to `toMs` (inclusive) in steps no longer than the camera's 50 ms frame clamp. */
function run(camera, fromMs, toMs, stepMs) {
  let changedFrames = 0;
  for (let t = fromMs + stepMs; t <= toMs + 1e-9; t += stepMs) {
    if (camera.tick(t)) changedFrames += 1;
  }
  return changedFrames;
}

test('bounds() is the visible world rect for centre, viewport and scale', () => {
  const camera = createCamera({ x: 100, y: 50, scale: 2 });
  camera.setViewport(800, 600);
  assert.deepEqual(camera.viewport, { width: 800, height: 600 });
  assert.deepEqual(camera.bounds(), { x: -100, y: -100, w: 400, h: 300 });

  camera.setScale(0.5);
  assert.deepEqual(camera.bounds(), { x: 100 - 800, y: 50 - 600, w: 1600, h: 1200 });
});

test('screenToWorld and worldToScreen invert each other at any scale', () => {
  for (const scale of [1, 0.5, 1.75]) {
    const camera = createCamera({ x: 320.5, y: -140.25, scale });
    camera.setViewport(1280, 720);
    for (const [px, py] of [[0, 0], [640, 360], [1280, 720], [13, 999]]) {
      const world = camera.screenToWorld(px, py);
      const screen = camera.worldToScreen(world.x, world.y);
      near(screen.x, px);
      near(screen.y, py);
    }
    const centre = camera.screenToWorld(640, 360);
    near(centre.x, 320.5);
    near(centre.y, -140.25);
    // One screen px covers 1/scale world px.
    const step = camera.screenToWorld(641, 360);
    near(step.x - centre.x, 1 / scale);
  }
});

function applyTransform(transform, x, y) {
  const match = /^translate3d\((-?[\d.]+)px, (-?[\d.]+)px, 0\) scale\((-?[\d.]+)\)$/.exec(transform);
  assert.ok(match, `unrecognised transform: ${transform}`);
  const tx = Number(match[1]);
  const ty = Number(match[2]);
  const scale = Number(match[3]);
  return { x: tx + x * scale, y: ty + y * scale };
}

test('transform() matches worldToScreen and uses one scale for translate and scale()', () => {
  const camera = createCamera({ x: 100, y: 50, scale: 2 });
  camera.setViewport(800, 600);
  assert.equal(camera.transform(), 'translate3d(200px, 200px, 0) scale(2)');

  camera.setCenter(100.123456, -0.001);
  camera.setScale(1);
  assert.equal(camera.transform(), 'translate3d(299.88px, 300px, 0) scale(1)');
  const origin = camera.worldToScreen(0, 0);
  near(origin.x, 400 - 100.123456);
  near(origin.y, 300 + 0.001);

  camera.setScale(0.333333);
  assert.equal(camera.transform(), 'translate3d(366.63px, 300px, 0) scale(0.3333)');
});

test('transform() keeps the camera centre on the viewport centre while zooming far from the origin', () => {
  const camera = createCamera({ x: 8000, y: -4500, scale: 0.6 });
  camera.setViewport(1280, 720);
  for (const scale of [0.6, 0.603, 0.609, 0.6149, 0.78, 0.333333]) {
    camera.setScale(scale);
    const screen = applyTransform(camera.transform(), 8000, -4500);
    near(screen.x, 640, 0.5);
    near(screen.y, 360, 0.5);
  }
});

test('a zoom-only flight keeps the centre on-screen every frame', () => {
  const camera = createCamera({ x: 7200, y: 5100, scale: 0.78 });
  camera.setViewport(1600, 900);
  camera.flyTo({ x: 7200, y: 5100, scale: 0.6 }, 300);
  camera.tick(0);
  for (let t = 16; t <= 320; t += 16) {
    camera.tick(t);
    const screen = applyTransform(camera.transform(), 7200, 5100);
    near(screen.x, 800, 0.5);
    near(screen.y, 450, 0.5);
  }
  assert.equal(camera.animating, false);
});

test('panBy moves the world with the pointer, divided by scale, and cancels animation', () => {
  const camera = createCamera({ x: 0, y: 0, scale: 2 });
  camera.setViewport(800, 600);
  camera.flyTo({ x: 500, y: 500 }, 400);
  assert.equal(camera.animating, true);

  camera.panBy(20, -10);
  assert.equal(camera.animating, false);
  near(camera.state.x, -10);
  near(camera.state.y, 5);
  // The world point that was under the viewport centre followed the pointer by (20, -10) screen px.
  const moved = camera.worldToScreen(0, 0);
  near(moved.x, 420);
  near(moved.y, 290);
});

test('instant moves are reported by exactly one following tick', () => {
  const camera = createCamera();
  camera.setViewport(800, 600);
  assert.equal(camera.tick(0), false);

  camera.panBy(12, 0);
  assert.equal(camera.tick(16), true);
  assert.equal(camera.tick(32), false);

  camera.setCenter(40, 40);
  camera.setScale(0.8);
  assert.equal(camera.tick(48), true);
  assert.equal(camera.tick(64), false);

  camera.flyTo({ x: 100, y: 100 }, 0);
  assert.equal(camera.tick(80), true);

  camera.panBy(0, 0);
  camera.setCenter(100, 100);
  assert.equal(camera.tick(96), false);
});

test('flyTo eases out (ease-out cubic) and lands exactly on the target', () => {
  const camera = createCamera({ x: 0, y: 0, scale: 1 });
  camera.setViewport(800, 600);
  camera.flyTo({ x: 1000, y: 500, scale: 1.5 }, 400);
  assert.equal(camera.animating, true);
  // The first tick only establishes the time base.
  assert.equal(camera.tick(1000), false);
  assert.equal(camera.state.x, 0);

  assert.equal(run(camera, 1000, 1200, 40), 5);
  const { x, y, scale } = camera.state;
  assert.ok(x > 500 && x < 1000, `at half time x=${x} should be past the linear midpoint`);
  near(x, 875);
  near(y, 437.5);
  near(scale, 1 + 0.5 * 0.875);

  run(camera, 1200, 1400, 40);
  assert.equal(camera.state.x, 1000);
  assert.equal(camera.state.y, 500);
  assert.equal(camera.state.scale, 1.5);
  assert.equal(camera.animating, false);
  assert.equal(camera.tick(1416), false);
});

test('flyTo clamps long frames instead of jumping, and is instant for durationMs <= 0', () => {
  const camera = createCamera();
  camera.setViewport(800, 600);
  camera.flyTo({ x: 1000, y: 0 }, 400);
  camera.tick(0);
  camera.tick(500); // a 500 ms stall counts as a 50 ms frame
  near(camera.state.x, 1000 * (1 - 0.875 ** 3));
  assert.equal(camera.animating, true);

  camera.flyTo({ x: -20, y: 30, scale: 0.5 }, 0);
  assert.equal(camera.animating, false);
  assert.deepEqual({ ...camera.state }, { x: -20, y: 30, scale: 0.5 });
});

test('flyTo keeps the current scale when the target omits it', () => {
  const camera = createCamera({ x: 0, y: 0, scale: 1.25 });
  camera.setViewport(800, 600);
  camera.flyTo({ x: 10, y: 10 }, 100);
  camera.tick(0);
  run(camera, 0, 100, 50);
  assert.equal(camera.state.scale, 1.25);
  assert.equal(camera.state.x, 10);
});

test('fling coasts in the pointer direction, decays exponentially and stops below 5 px/s', () => {
  const camera = createCamera({ x: 0, y: 0, scale: 1 });
  camera.setViewport(800, 600);
  camera.fling(600, 0);
  assert.equal(camera.animating, true);
  assert.equal(camera.tick(0), false);

  let t = 0;
  let previousX = 0;
  let frames = 0;
  let xAtHalfSecond = null;
  while (camera.animating && frames < 1000) {
    t += 16;
    frames += 1;
    assert.equal(camera.tick(t), true);
    // Dragging/flinging to the right carries the world right, i.e. the camera centre moves left.
    assert.ok(camera.state.x < previousX, 'keeps moving in the flung direction');
    previousX = camera.state.x;
    if (t === 496) xAtHalfSecond = camera.state.x;
  }
  assert.equal(camera.animating, false);
  assert.equal(camera.state.y, 0);
  // v(t) = 600·e^(−4.2t): total travel ≈ 600/4.2 ≈ 143 px, rest reached at t ≈ ln(120)/4.2 ≈ 1.14 s.
  assert.ok(camera.state.x < -135 && camera.state.x > -145, `travelled to ${camera.state.x}`);
  assert.ok(t > 1000 && t < 1300, `stopped after ${t} ms`);
  near(xAtHalfSecond, -(600 * (1 - Math.exp(-4.2 * 0.496))) / 4.2, 1e-6);
  assert.equal(camera.tick(t + 16), false);
});

test('fling travel in world px shrinks with zoom (same screen→world conversion as panBy)', () => {
  const zoomed = createCamera({ x: 0, y: 0, scale: 2 });
  zoomed.setViewport(800, 600);
  zoomed.fling(0, -600);
  zoomed.tick(0);
  let t = 0;
  while (zoomed.animating) zoomed.tick((t += 16));
  assert.equal(zoomed.state.x, 0);
  assert.ok(zoomed.state.y > 67 && zoomed.state.y < 73, `travelled to ${zoomed.state.y}`);
});

test('flings slower than 40 px/s are ignored', () => {
  const camera = createCamera({ x: 5, y: 5, scale: 1 });
  camera.fling(20, 20);
  assert.equal(camera.animating, false);
  assert.equal(camera.tick(0), false);
  assert.equal(camera.tick(16), false);
  assert.deepEqual({ ...camera.state }, { x: 5, y: 5, scale: 1 });
});

test('stop() cancels a flight and inertia in place', () => {
  const camera = createCamera();
  camera.setViewport(800, 600);
  camera.flyTo({ x: 1000, y: 0 }, 400);
  camera.tick(0);
  run(camera, 0, 100, 50);
  const midX = camera.state.x;
  assert.ok(midX > 0 && midX < 1000);
  camera.stop();
  assert.equal(camera.animating, false);
  assert.equal(camera.tick(150), false);
  assert.equal(camera.state.x, midX);

  camera.fling(500, 0);
  camera.tick(200);
  camera.tick(216);
  const flungX = camera.state.x;
  camera.stop();
  assert.equal(camera.animating, false);
  assert.equal(camera.tick(232), false);
  assert.equal(camera.state.x, flungX);
});

test('a new fling replaces a flight and a flight replaces inertia', () => {
  const camera = createCamera();
  camera.setViewport(800, 600);
  camera.flyTo({ x: 1000, y: 0 }, 400);
  camera.tick(0);
  camera.tick(50);
  camera.fling(0, 300);
  camera.tick(66);
  camera.tick(82);
  assert.ok(camera.state.y < 0, 'inertia took over');
  const xAfterFlightCancelled = camera.state.x;
  camera.tick(98);
  assert.equal(camera.state.x, xAfterFlightCancelled, 'the flight no longer advances');

  camera.flyTo({ x: 0, y: 0 }, 100);
  camera.tick(114);
  camera.tick(164);
  camera.tick(214);
  assert.equal(camera.state.x, 0);
  assert.equal(camera.state.y, 0);
  assert.equal(camera.animating, false);
});

test('scale is clamped to 0.25..2 everywhere it can be set', () => {
  const camera = createCamera({ scale: 10 });
  assert.equal(camera.state.scale, 2);
  camera.setScale(0.01);
  assert.equal(camera.state.scale, 0.25);
  camera.flyTo({ x: 0, y: 0, scale: 5 }, 0);
  assert.equal(camera.state.scale, 2);
});

test('state and viewport are read-only live views', () => {
  const camera = createCamera({ x: 1, y: 2, scale: 1 });
  const view = camera.state;
  assert.throws(() => {
    view.x = 99;
  }, TypeError);
  camera.setCenter(7, 8);
  assert.equal(view.x, 7);
  assert.equal(view.y, 8);
  assert.throws(() => {
    camera.viewport.width = 1;
  }, TypeError);
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import {
  createPlaybackClock,
  HARD_CORRECTION_SECONDS,
  SOFT_CORRECTION_MS,
} from '../source/panel/host/clock.ts';

const status = (overrides = {}) => ({
  state: 'playing',
  currentTrackId: 'track-a',
  positionSeconds: 40,
  durationSeconds: 221,
  volume: 1,
  ...overrides,
});

const near = (actual, expected, tolerance = 1e-6) => {
  assert.ok(
    Math.abs(actual - expected) <= tolerance,
    `expected ${actual} to be within ${tolerance} of ${expected}`,
  );
};

test('interpolates linearly between samples while playing', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ positionSeconds: 40 }), 1_000);
  near(clock.read(1_000).positionSeconds, 40);
  near(clock.read(1_250).positionSeconds, 40.25);
  near(clock.read(1_999).positionSeconds, 40.999);
  assert.equal(clock.running, true);
  assert.equal(clock.read(1_500).running, true);
  assert.equal(clock.read(1_500).durationSeconds, 221);
  assert.equal(clock.read(1_500).trackId, 'track-a');
});

test('uses host playback rate for progress and rebases when the rate changes', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ positionSeconds: 40, playbackRate: 2 }), 0);
  near(clock.read(500).positionSeconds, 41);
  clock.ingest(status({ positionSeconds: 41, playbackRate: 0.5 }), 500);
  near(clock.read(1500).positionSeconds, 41.5);
  clock.ingest(status({ positionSeconds: 41.5, state: 'paused', playbackRate: 0.5 }), 1500);
  near(clock.read(2500).positionSeconds, 41.5);
});

test('freezes the position while paused', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ state: 'paused', positionSeconds: 12.5 }), 0);
  near(clock.read(0).positionSeconds, 12.5);
  near(clock.read(5_000).positionSeconds, 12.5);
  assert.equal(clock.running, false);
  assert.equal(clock.read(5_000).running, false);
  assert.equal(clock.read(5_000).state, 'paused');
});

test('snaps to the host value when drift reaches the hard threshold', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ positionSeconds: 40 }), 0);
  const predicted = clock.read(1_000).positionSeconds;
  clock.ingest(status({ positionSeconds: predicted + HARD_CORRECTION_SECONDS }), 1_000);
  near(clock.read(1_000).positionSeconds, predicted + HARD_CORRECTION_SECONDS);
  clock.ingest(status({ positionSeconds: 10 }), 2_000);
  near(clock.read(2_000).positionSeconds, 10);
});

test('snaps when the playback state changes even for tiny drift', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ positionSeconds: 40 }), 0);
  clock.ingest(status({ state: 'paused', positionSeconds: 40.9 }), 1_000);
  near(clock.read(1_000).positionSeconds, 40.9);
  near(clock.read(1_400).positionSeconds, 40.9);
  clock.ingest(status({ state: 'playing', positionSeconds: 41.1 }), 2_000);
  near(clock.read(2_000).positionSeconds, 41.1);
  near(clock.read(2_500).positionSeconds, 41.6);
});

test('snaps when the track changes', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ positionSeconds: 200 }), 0);
  clock.ingest(status({ currentTrackId: 'track-b', positionSeconds: 0.9, durationSeconds: 180 }), 1_000);
  const snapshot = clock.read(1_000);
  near(snapshot.positionSeconds, 0.9);
  assert.equal(snapshot.trackId, 'track-b');
  assert.equal(snapshot.durationSeconds, 180);
});

test('soft-converges small drift within 500 ms without going backwards', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ positionSeconds: 40 }), 0);
  // Host is 0.2 s behind our prediction of 41.0.
  clock.ingest(status({ positionSeconds: 40.8 }), 1_000);
  near(clock.read(1_000).positionSeconds, 41);
  let previous = clock.read(1_000).positionSeconds;
  for (let t = 1_000; t <= 1_000 + SOFT_CORRECTION_MS; t += 20) {
    const position = clock.read(t).positionSeconds;
    assert.ok(position >= previous - 1e-9, `position went backwards at ${t}: ${previous} -> ${position}`);
    previous = position;
  }
  // After the window the correction is fully applied: 40.8 + 0.5 s of playback.
  near(clock.read(1_500).positionSeconds, 41.3);
  near(clock.read(2_000).positionSeconds, 41.8);
});

test('soft-converges forward drift too', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ positionSeconds: 40 }), 0);
  clock.ingest(status({ positionSeconds: 41.3 }), 1_000);
  near(clock.read(1_000).positionSeconds, 41);
  near(clock.read(1_250).positionSeconds, 41.4);
  near(clock.read(1_500).positionSeconds, 41.8);
});

test('optimistic seek holds through two disagreeing samples, then accepts the host', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ positionSeconds: 40 }), 0);
  clock.seek(100, 100);
  near(clock.read(100).positionSeconds, 100);
  near(clock.read(600).positionSeconds, 100.5);

  clock.ingest(status({ positionSeconds: 41 }), 1_000);
  near(clock.read(1_000).positionSeconds, 100.9);
  near(clock.read(1_500).positionSeconds, 101.4);

  clock.ingest(status({ positionSeconds: 42 }), 2_000);
  near(clock.read(2_000).positionSeconds, 101.9);

  clock.ingest(status({ positionSeconds: 43 }), 3_000);
  near(clock.read(3_000).positionSeconds, 43);
  near(clock.read(3_500).positionSeconds, 43.5);
});

test('optimistic seek accepts the host as soon as it agrees', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ positionSeconds: 40 }), 0);
  clock.seek(100, 100);
  // Stale sample first, then the host catches up within tolerance.
  clock.ingest(status({ positionSeconds: 41 }), 1_000);
  clock.ingest(status({ positionSeconds: 101.8 }), 2_000);
  const start = clock.read(2_000).positionSeconds;
  near(start, 101.9);
  near(clock.read(2_500).positionSeconds, 102.3);
  // Optimism is spent: a later disagreeing sample snaps immediately.
  clock.ingest(status({ positionSeconds: 50 }), 3_000);
  near(clock.read(3_000).positionSeconds, 50);
});

test('optimistic seek while paused keeps the local position until the host catches up', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ state: 'paused', positionSeconds: 40 }), 0);
  clock.seek(90, 100);
  near(clock.read(500).positionSeconds, 90);
  clock.ingest(status({ state: 'paused', positionSeconds: 40 }), 1_000);
  near(clock.read(1_000).positionSeconds, 90);
  clock.ingest(status({ state: 'paused', positionSeconds: 90 }), 2_000);
  near(clock.read(2_000).positionSeconds, 90);
});

test('a track change during the optimistic window wins over the local seek', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ positionSeconds: 40 }), 0);
  clock.seek(100, 100);
  clock.ingest(status({ currentTrackId: 'track-b', positionSeconds: 0.5, durationSeconds: 200 }), 1_000);
  near(clock.read(1_000).positionSeconds, 0.5);
  assert.equal(clock.read(1_000).trackId, 'track-b');
});

test('ended freezes at the duration', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ positionSeconds: 220 }), 0);
  clock.ingest(status({ state: 'ended', positionSeconds: 220.4 }), 1_000);
  const snapshot = clock.read(1_000);
  assert.equal(snapshot.state, 'ended');
  near(snapshot.positionSeconds, 221);
  assert.equal(snapshot.running, false);
  assert.equal(clock.running, false);
  near(clock.read(9_000).positionSeconds, 221);
});

test('clamps interpolation to the duration and never below zero', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ positionSeconds: 220.5 }), 0);
  near(clock.read(2_000).positionSeconds, 221);
  clock.seek(-5, 2_000);
  near(clock.read(2_000).positionSeconds, 0);
  clock.seek(999, 2_000);
  near(clock.read(2_000).positionSeconds, 221);
});

test('tolerates non-finite host numbers', () => {
  const clock = createPlaybackClock();
  clock.ingest(status({ positionSeconds: Number.NaN, durationSeconds: Number.POSITIVE_INFINITY }), 0);
  const snapshot = clock.read(500);
  near(snapshot.positionSeconds, 0.5);
  assert.equal(snapshot.durationSeconds, 0);
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { readFileSync } from 'node:fs';
import { ENTRANCE_BLACK_HOLD_MS, ENTRANCE_REVEAL_MS, ENTRANCE_DURATION_MS, sampleCoverMotion } from '../source/panel/wall/coverMotion.ts';

test('entrance places a solid black tile, then quickly removes black without moving or scaling', () => {
  const motion = { kind: 'enter', startedAt: 1000, delayMs: 200 };
  assert.deepEqual(sampleCoverMotion(motion, 1100, false), { opacity: 0, blackOpacity: 1, running: true });
  for (const time of [1200, 1220, 1200 + ENTRANCE_BLACK_HOLD_MS]) {
    assert.deepEqual(sampleCoverMotion(motion, time, false), { opacity: 1, blackOpacity: 1, running: true });
  }
  const middle = sampleCoverMotion(motion, 1200 + ENTRANCE_BLACK_HOLD_MS + ENTRANCE_REVEAL_MS / 2, false);
  assert.equal(middle.opacity, 1, 'the tile itself never crossfades');
  assert.ok(middle.blackOpacity > 0 && middle.blackOpacity < .5, 'ease-out exposes the artwork quickly');
  assert.equal(middle.running, true);
  assert.equal(ENTRANCE_REVEAL_MS, 160);
  assert.deepEqual(sampleCoverMotion(motion, 1200 + ENTRANCE_DURATION_MS, false), { opacity: 1, blackOpacity: 0, running: false });
  assert.deepEqual(sampleCoverMotion(motion, 10_000, false), { opacity: 1, blackOpacity: 0, running: false });
});

test('cards mounted later use the original short fade without moving their edges', () => {
  const motion = { kind: 'fade', startedAt: 1000, delayMs: 0 };
  const middle = sampleCoverMotion(motion, 1060, false);
  assert.ok(middle.opacity > 0 && middle.opacity < 1);
  assert.equal(middle.blackOpacity, 0);
  assert.equal(middle.running, true);
  assert.deepEqual(sampleCoverMotion(motion, 1120, false), { opacity: 1, blackOpacity: 0, running: false });
});

test('reduced motion snaps both animations and normal sampling stays monotonic and bounded', () => {
  for (const kind of ['enter', 'fade']) {
    const motion = { kind, startedAt: 1000, delayMs: 200 };
    assert.deepEqual(sampleCoverMotion(motion, 1000, true), { opacity: 1, blackOpacity: 0, running: false });
    let previous = 0;
    let previousBlack = 1;
    for (let time = 900; time <= 1800; time += 20) {
      const sample = sampleCoverMotion(motion, time, false);
      assert.ok(sample.opacity >= previous && sample.opacity <= 1);
      assert.ok(sample.blackOpacity <= previousBlack && sample.blackOpacity >= 0);
      previous = sample.opacity;
      previousBlack = sample.blackOpacity;
    }
  }
  assert.deepEqual(sampleCoverMotion(null, 1000, false), { opacity: 1, blackOpacity: 0, running: false });
});

test('native CSS and lens shader agree on fast black reveal with no entrance transform', () => {
  const css = readFileSync(new URL('../source/styles/20-poster.css', import.meta.url), 'utf8');
  assert.match(css, /animation: poster-enter-black \.2s both/);
  assert.match(css, /0%, 20% \{ opacity: 1; animation-timing-function: ease-out; \}/);
  assert.doesNotMatch(css, /poster-enter-body|translate3d\(0, 18px/);
  assert.match(css, /\.poster\.poster--enter \.poster__body\{ transform: none; transition: none; \}/);
  assert.equal(ENTRANCE_BLACK_HOLD_MS / ENTRANCE_DURATION_MS, .2);
  const shader = readFileSync(new URL('../source/panel/wall/fisheyeSurface.ts', import.meta.url), 'utf8');
  assert.match(shader, /color \* \(1\.0 - uBlackOpacity\)/);
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { depthProjectPoint, depthSceneMatrix } from '../source/panel/wall/depthScene.ts';
import { createCamera } from '../source/panel/wall/camera.ts';
import { uiParallaxOffset } from '../source/panel/wall/uiParallax.ts';
import { fisheyeCardMatrix, fisheyeChildMatrix } from '../source/panel/wall/fisheye.ts';

const near = (actual, expected) => assert.ok(Math.abs(actual - expected) < 1e-5, `${actual} != ${expected}`);

test('perspective input stays aligned with the wall, including the lens and long camera pans', () => {
  for (const viewport of [{ width: 375, height: 812 }, { width: 1600, height: 900 }, { width: 3840, height: 2160 }]) {
    const camera = createCamera({ x: 1e7, y: -1e7, scale: .78 });
    camera.setViewport(viewport.width, viewport.height);
    for (const fisheye of [false, true]) {
      camera.setFisheye(fisheye);
      for (const pose of [{ x: 0, y: 0, amount: 0 }, { x: -.8, y: .6, amount: .4 }, { x: 1, y: -1, amount: 1 }]) {
        const matrix = depthSceneMatrix(pose, viewport);
        for (const point of [{ x: 0, y: 0 }, { x: viewport.width / 2, y: viewport.height / 2 }, { x: viewport.width, y: viewport.height }]) {
          const source = camera.screenToWorld(point.x, point.y);
          const screen = depthProjectPoint(camera.worldToScreen(source.x, source.y), matrix, viewport);
          const plane = depthProjectPoint(screen, matrix, viewport, true);
          const picked = camera.screenToWorld(plane.x, plane.y);
          near(picked.x, source.x); near(picked.y, source.y);
        }
      }
    }
  }
});

test('scene overscan fills all four viewport corners at extreme pointer positions and during entry', () => {
  for (const viewport of [{ width: 375, height: 812 }, { width: 1600, height: 900 }, { width: 3840, height: 2160 }]) {
    for (const x of [-1, 1]) for (const y of [-1, 1]) for (const amount of [.1, .5, 1]) {
      const matrix = depthSceneMatrix({ x, y, amount }, viewport);
      for (const screen of [{ x: 0, y: 0 }, { x: viewport.width, y: 0 }, { x: 0, y: viewport.height }, { x: viewport.width, y: viewport.height }]) {
        const source = depthProjectPoint(screen, matrix, viewport, true);
        assert.ok(source.x >= 0 && source.x <= viewport.width && source.y >= 0 && source.y <= viewport.height,
          `${JSON.stringify({ viewport, x, y, amount, source })} leaves a black viewport edge`);
      }
    }
  }
});

test('foreground depths have different motion, stable screen distances and zero offset when disabled', () => {
  const card = { x: 0, y: 0, w: 1200, h: 1200 }, viewport = { width: 1600, height: 1200 };
  const pose = { x: .8, y: -.6, amount: 1 };
  for (const scale of [.6, 1.3]) {
    const title = uiParallaxOffset(pose, 'meta', card, scale, viewport);
    const lyrics = uiParallaxOffset(pose, 'lyrics', card, scale, viewport);
    const controls = uiParallaxOffset(pose, 'controls', card, scale, viewport);
    near(title.x * scale, .8 * 26); near(controls.x * scale, .8 * 32);
    assert.ok(controls.x > title.x && title.x > lyrics.x);
    assert.deepEqual(uiParallaxOffset({ ...pose, amount: 0 }, 'controls', card, scale, viewport), { x: 0, y: 0 });
  }
  const small = { ...card, w: 260, h: 260 };
  const shift = uiParallaxOffset(pose, 'controls', small, .42, { width: 375, height: 812 });
  assert.ok(Math.abs(shift.x * .42) < small.w * .42 * .05);
});

test('UI parallax translates after the fish lens and retains native fallback geometry', () => {
  const viewport = { width: 1600, height: 900 }, view = { x: 0, y: 0, scale: .78 };
  const card = { x: 540, y: -240, w: 788, h: 788 }, local = { x: 40, y: 640, w: 708, h: 64 };
  const shift = uiParallaxOffset({ x: .9, y: -.8, amount: 1 }, 'controls', card, view.scale, viewport);
  const apply = (matrix, x, y) => {
    const w = matrix[3] * x + matrix[7] * y + matrix[15];
    return { x: (matrix[0] * x + matrix[4] * y + matrix[12]) / w,
      y: (matrix[1] * x + matrix[5] * y + matrix[13]) / w };
  };
  for (const amount of [0, .5, 1]) for (const surface of [false, true]) {
    const parent = fisheyeCardMatrix(card, view, viewport, amount);
    const base = fisheyeChildMatrix(card, local, view, viewport, amount, { x: 0, y: 0 }, surface);
    const moved = fisheyeChildMatrix(card, local, view, viewport, amount, shift, surface);
    for (const [x, y] of [[0, 0], [local.w, 0], [0, local.h], [local.w, local.h]]) {
      const b = apply(base, x, y), m = apply(moved, x, y);
      const before = apply(parent, local.x + b.x, local.y + b.y);
      const after = apply(parent, local.x + m.x, local.y + m.y);
      near(after.x - before.x, shift.x); near(after.y - before.y, shift.y);
    }
  }
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { createCamera } from '../source/panel/wall/camera.ts';
