const TOGGLE_MARKUP =
  `<span class="controls__glyph" data-glyph="play">${ICONS.play}</span>` +
  `<span class="controls__glyph" data-glyph="pause">${ICONS.pause}</span>`;

type Action = 'previous' | 'next' | 'primary' | 'album' | 'shuffle' | 'repeatOne' | 'tracks' | 'lyrics';

export type AlbumActionHandlers = {
  playAlbum(): void;
  play(): void;
  pause(): void;
  togglePlay(): void;
  previous(): void;
  next(): void;
  seek(positionSeconds: number): void;
  toggleShuffle(): void;
  toggleRepeatOne(): void;
};

function isSpaceKey(event: KeyboardEvent): boolean {
  return event.code === 'Space' || event.key === ' ';
}

function setLabel(button: HTMLButtonElement, label: string): void {
  button.setAttribute('aria-label', label);
  button.title = label;
}

function createButton(className: string, action: Action, label: string, markup: string): HTMLButtonElement {
  const button = document.createElement('button');
  button.type = 'button';
  button.className = className;
  button.dataset.action = action;
  setLabel(button, label);
  button.innerHTML = markup;
  return button;
}

/** Footer cluster with playback controls and mutually exclusive content toggles. */
export function createAlbumActions(handlers: AlbumActionHandlers, onToggleTracks: () => void, onToggleLyrics: () => void) {
  const cluster = document.createElement('div');
  cluster.className = 'controls album-actions';
  cluster.dataset.mode = 'other';
  cluster.dataset.state = 'paused';

  const row = document.createElement('div');
  row.className = 'controls__row';
  const previous = createButton('controls__button controls__button--skip', 'previous', '上一曲', ICONS.previous);
  const primary = createButton('controls__button controls__button--primary', 'primary', '播放', TOGGLE_MARKUP);
  const next = createButton('controls__button controls__button--skip', 'next', '下一曲', ICONS.next);
  const shuffle = createButton('controls__button controls__button--shuffle', 'shuffle', '随机播放', ICONS.shuffle);
  shuffle.setAttribute('aria-pressed', 'false');
  shuffle.dataset.on = 'false';
  const repeatOne = createButton('controls__button controls__button--repeat', 'repeatOne', '单曲循环', ICONS.repeatOne);
  repeatOne.setAttribute('aria-pressed', 'false');
  repeatOne.dataset.on = 'false';
  const album = createButton('controls__button controls__button--album', 'album', '播放整张专辑', ICONS.album);
  const tracksToggle = createButton('controls__button album-content-toggle album-tracks-toggle', 'tracks', '收起曲目列表',
    ICONS.tracks);
  const lyricsToggle = createButton('controls__button album-content-toggle album-lyrics-toggle', 'lyrics', '显示歌词',
    ICONS.lyrics);
  const contentToggles = document.createElement('div');
  contentToggles.className = 'album-content-toggles';
  contentToggles.append(lyricsToggle, tracksToggle);
  row.append(previous, primary, next, shuffle, repeatOne, album, contentToggles);

  const seek = document.createElement('div');
  seek.className = 'controls__seek';
  const slider = document.createElement('input');
  slider.className = 'controls__slider';
  slider.type = 'range';
  slider.min = '0';
  slider.max = '0';
  slider.step = '0.1';
  slider.value = '0';
  slider.setAttribute('aria-label', '播放进度');
  const time = document.createElement('span');
  time.className = 'controls__time';
  time.textContent = '0:00 / 0:00';
  seek.append(slider, time);
  cluster.append(row, seek);

  let mode: 'current' | 'other' = 'other';
  let playing = false;
  let dragging = false;
  let shownDuration = -1;
  let shownValue = -1;
  let shownProgress = '';
  let shownWholeSecond = -1;
  let shownState = '';

  const updateLabels = (): void => {
    setLabel(primary, mode === 'other' || !playing ? '播放' : '暂停');
    const collapsed = mode === 'other';
    for (const button of [previous, primary, next, shuffle, repeatOne]) {
      button.tabIndex = collapsed ? -1 : 0;
      button.setAttribute('aria-hidden', String(collapsed));
    }
    if (collapsed && document.activeElement === lyricsToggle) tracksToggle.focus({ preventScroll: true });
    lyricsToggle.hidden = collapsed;
    lyricsToggle.disabled = collapsed;
  };
  updateLabels();

  const progressRatio = (position: number, duration: number): string =>
    (duration > 0 ? Math.min(1, Math.max(0, position / duration)) : 0).toFixed(3);

  const setSliderProgress = (ratio: string): void => {
    if (ratio === shownProgress) return;
    shownProgress = ratio;
    slider.style.setProperty('--progress', ratio);
  };

  const runAction = (action: string): void => {
    switch (action) {
      case 'tracks':
        onToggleTracks();
        break;
      case 'lyrics':
        if (mode !== 'other') onToggleLyrics();
        break;
      case 'album':
        handlers.playAlbum();
        break;
      case 'previous':
        if (mode !== 'other') handlers.previous();
        break;
      case 'next':
        if (mode !== 'other') handlers.next();
        break;
      case 'primary':
        if (mode === 'other') handlers.playAlbum();
        else if (playing) handlers.pause();
        else handlers.play();
        break;
      case 'shuffle':
        if (mode !== 'other') handlers.toggleShuffle();
        break;
      case 'repeatOne':
        if (mode !== 'other') handlers.toggleRepeatOne();
        break;
      default:
        break;
    }
  };

  cluster.addEventListener('click', (event) => {
    const target = event.target instanceof Element ? event.target : null;
    const button = target?.closest<HTMLButtonElement>('button[data-action]');
    if (button?.dataset.action) runAction(button.dataset.action);
  });
  cluster.addEventListener('keydown', (event) => {
    if (event.repeat || event.ctrlKey || event.metaKey || event.altKey || !isSpaceKey(event)) return;
    const target = event.target instanceof Element ? event.target : null;
    const action = target?.closest<HTMLButtonElement>('button[data-action]')?.dataset.action;
    // Space on a focused <button> synthesizes a click. After play-album the focus stays on that
    // button, so the native click would call playAlbum again and restart the record.
    if (action !== 'album' || mode !== 'current') return;
    event.preventDefault();
    handlers.togglePlay();
  });
  cluster.addEventListener('pointerdown', (event) => event.stopPropagation());

  slider.addEventListener('input', () => {
    const value = Number(slider.value);
    setSliderProgress(progressRatio(value, Number(slider.max)));
    handlers.seek(value);
  });
  slider.addEventListener('pointerdown', () => {
    dragging = true;
  });
  const endDrag = (): void => {
    dragging = false;
  };
  slider.addEventListener('pointerup', endDrag);
  slider.addEventListener('pointercancel', endDrag);
  slider.addEventListener('lostpointercapture', endDrag);
  slider.addEventListener('change', endDrag);

  return {
    element: cluster,
    tracksToggle,
    lyricsToggle,
    playAlbum() {
      handlers.playAlbum();
    },
    setMode(next: 'current' | 'other') {
      if (mode === next) return;
      mode = next;
      cluster.dataset.mode = next;
      updateLabels();
    },
    update(clock: { positionSeconds: number; durationSeconds: number; state: string }) {
      const duration = Number.isFinite(clock.durationSeconds) && clock.durationSeconds > 0 ? clock.durationSeconds : 0;
      let position = Number.isFinite(clock.positionSeconds) ? Math.max(0, clock.positionSeconds) : 0;
      if (duration > 0 && position > duration) position = duration;
      if (duration !== shownDuration) {
        shownDuration = duration;
        slider.max = String(duration);
      }
      if (!dragging) {
        const value = Math.round(position * 10) / 10;
        if (value !== shownValue) {
          shownValue = value;
          slider.value = String(value);
        }
      }
      setSliderProgress(progressRatio(position, duration));
      const wholeSecond = Math.floor(position);
      if (duration !== shownDuration || wholeSecond !== shownWholeSecond) {
        shownWholeSecond = wholeSecond;
        time.textContent = `${formatTime(wholeSecond)} / ${formatTime(duration)}`;
      }
      const state = clock.state === 'playing' ? 'playing' : 'paused';
      if (state !== shownState) {
        shownState = state;
        playing = state === 'playing';
        cluster.dataset.state = state;
        updateLabels();
      }
    },
    setShuffleEnabled(enabled: boolean) {
      shuffle.dataset.on = String(enabled);
      shuffle.setAttribute('aria-pressed', String(enabled));
      setLabel(shuffle, enabled ? '关闭随机播放' : '随机播放');
    },
    setRepeatOne(enabled: boolean) {
      repeatOne.dataset.on = String(enabled);
      repeatOne.setAttribute('aria-pressed', String(enabled));
      setLabel(repeatOne, enabled ? '关闭单曲循环' : '单曲循环');
    },
    focusSeek() {
      if (!slider.isConnected || mode === 'other') return false;
      slider.focus({ preventScroll: true });
      return document.activeElement === slider;
    },
    get seekFocused() {
      return mode === 'current' && document.activeElement === slider;
    },
  };
}

import type { LibrarySource } from '../host/librarySource.ts';
import type { ClockSnapshot, ExpandedContent, LyricsViewOptions } from '../types.ts';
import type { WallHostApi } from '../host/api.ts';
import { createAlbumActions, type AlbumActionHandlers } from './albumActions.ts';
import { createAlbumTrackList } from './albumTrackList.ts';
import { createAlbumLyrics, type AlbumLyricsHost } from './albumLyrics.ts';
import { createAlbumLayout, type AlbumContentMode } from './albumLayout.ts';

export type AlbumDetailsHost = AlbumActionHandlers & AlbumLyricsHost & { onRenderNeeded?(): void };

/** One expanded album owns a bounded scrolling list and a single set of playback controls. */
export function createAlbumDetails(api: WallHostApi, host: AlbumDetailsHost) {
  const element = document.createElement('div');
  element.className = 'album-details';
  element.dataset.scrollable = 'true';
  element.id = `album-tracks-${crypto.randomUUID()}`;
  const message = document.createElement('p');
  message.className = 'album-details__message';
  message.setAttribute('role', 'status');
  let album: EchoWorkshopAlbum | null = null;
  let generation = 0;
  let busy = false;
  let currentTrackId: string | null = null;
  let metadataTrackId: string | null = null;
  let thisAlbum = false;
  let contentMode: AlbumContentMode = 'none';
  let lastOpenMode: Exclude<AlbumContentMode, 'none'> = 'tracks';
  let contentSlot: HTMLElement | null = null;
  const abort = new AbortController();
  const { signal } = abort;
  const run = async (action: () => Promise<unknown>, success = '已开始播放') => {
    if (busy) return;
    const request = generation;
    busy = true;
    element.setAttribute('aria-busy', 'true');
    message.textContent = '正在开始播放…';
    try {
      const result = await action() as EchoWorkshopCollectionPlayResult;
      if (request === generation) message.textContent = typeof result?.count === 'number' ? `已播放 ${result.count} 首` : success;
    } catch {
      if (request === generation) message.textContent = '播放失败，请重试或在 ECHO 中检查歌曲是否可用。';
    } finally {
      if (request === generation) {
        busy = false;
        element.removeAttribute('aria-busy');
      }
    }
  };
  const wrapped: AlbumActionHandlers = {
    playAlbum: () => {
      if (!album || album.trackCount === 0) return;
      const id = album.id;
      void run(() => api.queue.playAlbum(id));
    },
    play: () => host.play(),
    pause: () => host.pause(),
    togglePlay: () => host.togglePlay(),
    previous: () => host.previous(),
    next: () => host.next(),
    seek: (position) => host.seek(position),
    toggleShuffle: () => host.toggleShuffle(),
    toggleRepeatOne: () => host.toggleRepeatOne(),
  };
  const cluster = createAlbumActions(wrapped,
    () => setContentMode(contentMode === 'tracks' ? 'none' : 'tracks'),
    () => setContentMode(contentMode === 'lyrics' ? 'none' : 'lyrics'));
  cluster.tracksToggle.setAttribute('aria-controls', element.id);
  const lyrics = createAlbumLyrics(host, () => layout.refreshLyrics());
  const layout = createAlbumLayout(lyrics);
  cluster.lyricsToggle.setAttribute('aria-controls', lyrics.element.id);
  const tracks = createAlbumTrackList(api, (id) => void run(() => api.queue.playTrack(id)), (text) => {
    message.textContent = text;
  });
  element.append(message, tracks.element);

  const setContentMode = (mode: AlbumContentMode): void => {
    contentMode = mode;
    if (mode !== 'none') lastOpenMode = mode;
    if (contentSlot) contentSlot.dataset.albumView = mode;
    // A single mode controls both panels. Keep list position while removing hidden rows from focus.
    const panels = [
      { panel: element, button: cluster.tracksToggle, open: mode === 'tracks', label: mode === 'tracks' ? '收起曲目列表' : '展开曲目列表' },
      { panel: lyrics.element, button: cluster.lyricsToggle, open: mode === 'lyrics', label: mode === 'lyrics' ? '隐藏歌词' : '显示歌词' },
    ];
    for (const { panel, button, open, label } of panels) {
      if (!open && panel.contains(document.activeElement)) {
        (button.hidden ? cluster.tracksToggle : button).focus({ preventScroll: true });
      }
      panel.inert = !open;
      panel.setAttribute('aria-hidden', String(!open));
      panel.dataset.open = String(open);
      button.setAttribute('aria-expanded', String(open));
      button.setAttribute('aria-label', label);
      button.title = label;
    }
    lyrics.setActive(mode === 'lyrics' && album !== null && thisAlbum);
    layout.setMode(mode);
    // Wake the projected backdrop even when playback is paused and reduced motion skips the fade.
    if (contentSlot) host.onRenderNeeded?.();
  };
  setContentMode(contentMode);

  const applyMode = (): void => {
    const current = thisAlbum && currentTrackId !== null;
    cluster.setMode(current ? 'current' : 'other');
    // Playback status and queue metadata can arrive in either order. Never put another album's
    // lyrics on this cover while waiting for the matching metadata / authoritative clock.
    const confirmed = current && currentTrackId === metadataTrackId && host.readClock().trackId === currentTrackId;
    lyrics.setTrack(album && confirmed ? currentTrackId : null);
    if (!current && contentMode === 'lyrics') setContentMode('tracks');
    else setContentMode(contentMode);
  };

  for (const node of [element, lyrics.element, cluster.element]) {
    for (const name of ['pointerdown', 'click']) node.addEventListener(name, (event) => event.stopPropagation(), { signal });
    node.addEventListener('keydown', (event) => {
      if (event.key !== 'Escape') event.stopPropagation();
      if (event.repeat || event.ctrlKey || event.metaKey || event.altKey) return;
      if (event.code !== 'Space' && event.key !== ' ') return;
      const target = event.target instanceof Element ? event.target : null;
      const track = target?.closest<HTMLButtonElement>('button[data-track]');
      if (!thisAlbum || !track || track.disabled || track.dataset.track !== currentTrackId) return;
      event.preventDefault();
      host.togglePlay();
    }, { signal });
  }

  const clear = (): void => {
    generation += 1;
    layout.reset();
    lyrics.setActive(false);
    lyrics.setTrack(null);
    lyrics.element.remove();
    tracks.clear();
    album = null;
    busy = false;
    element.removeAttribute('aria-busy');
    element.remove();
    cluster.element.remove();
    contentSlot = null;
  };

  return {
    mount(content: ExpandedContent, nextAlbum: EchoWorkshopAlbum, currentAlbum: boolean, source: LibrarySource = 'local') {
      clear();
      album = nextAlbum;
      thisAlbum = currentAlbum;
      content.root.classList.add('poster__expanded--album');
      contentSlot = content.lyrics;
      content.lyrics.replaceChildren(element, lyrics.element);
      content.controls.replaceChildren(cluster.element);
      layout.mount(content);
      tracks.mount(nextAlbum, source);
      applyMode();
    },
    updateCurrent(id: string | null, currentAlbum: boolean) {
      metadataTrackId = id;
      currentTrackId = id;
      thisAlbum = currentAlbum;
      tracks.setCurrent(id);
      applyMode();
    },
    updateStatus(status: EchoWorkshopPlaybackStatus, currentAlbum: boolean) {
      currentTrackId = status.currentTrackId;
      thisAlbum = currentAlbum;
      tracks.setCurrent(currentTrackId);
      applyMode();
    },
    updateClock(snapshot: ClockSnapshot) {
      if (thisAlbum) cluster.update(snapshot);
      lyrics.update(snapshot);
    },
    setLyricsOptions(options: LyricsViewOptions) {
      lyrics.setOptions(options);
      layout.setReducedMotion(options.reducedMotion);
    },
    setShuffleEnabled(enabled: boolean) {
      cluster.setShuffleEnabled(enabled);
    },
    setRepeatOne(enabled: boolean) {
      cluster.setRepeatOne(enabled);
    },
    play() {
      wrapped.playAlbum();
    },
    toggle() {
      const next = contentMode === 'none' ? lastOpenMode : 'none';
      setContentMode(next === 'lyrics' && !thisAlbum ? 'tracks' : next);
    },
    focusSeek() {
      return cluster.focusSeek();
    },
    get clockVisible() {
      return cluster.element.isConnected;
    },
    get seekFocused() {
      return cluster.seekFocused;
    },
    clear() {
      clear();
    },
    dispose() {
      clear();
      tracks.dispose();
      lyrics.dispose();
      abort.abort();
    },
  };
}

import type { ExpandedContent } from '../types.ts';
import { measureLyricsOpenHeight } from '../lyrics/lyricsSlot.ts';
import { createLyricsTransition, LYRICS_TRANSITION_TIMING } from '../lyrics/lyricsTransition.ts';

export type AlbumContentMode = 'tracks' | 'lyrics' | 'none';
type LyricsLayout = { element: HTMLElement; viewElement: HTMLElement; hasFollowingLine(): boolean };

/** The library wall's title/slot animation, with a bounded full-height slot for album tracks. */
export function createAlbumLayout(lyrics: LyricsLayout) {
  const transition = createLyricsTransition();
  let content: ExpandedContent | null = null;
  let observer: ResizeObserver | null = null;
  let frame = 0;
  let mode: AlbumContentMode = 'none';
  let reducedMotion = false;
  let shownHeight = 0;
  let heightAnimation: Animation | null = null;

  const fit = (): void => {
    if (!content || mode === 'none') return;
    const style = getComputedStyle(content.root);
    const px = (value: string): number => Number.parseFloat(value) || 0;
    const naturalTitle = px(style.getPropertyValue('--title-natural-height'));
    const titleScale = px(style.getPropertyValue('--title-open-scale')) || 1;
    const artist = content.meta.querySelector<HTMLElement>('.poster__artist');
    const artistHeight = artist && artist.textContent
      ? artist.offsetHeight + px(getComputedStyle(artist).marginTop) : 0;
    // Use the final compact title height, never its animated height: that would feed the animation
    // back into its own target and resize the virtual track list on every frame.
    const available = Math.max(0, content.root.clientHeight - px(style.paddingTop) - px(style.paddingBottom)
      - naturalTitle * titleScale - artistHeight - content.controls.offsetHeight - px(style.rowGap) * 2);
    const height = mode === 'tracks' ? available : Math.min(available,
      measureLyricsOpenHeight(content.root, lyrics.element, lyrics.hasFollowingLine(), lyrics.viewElement));
    if (Math.abs(height - shownHeight) < 0.5) return;
    const from = px(style.getPropertyValue('--album-slot-height'));
    const open = px(style.getPropertyValue('--lyrics-open'));
    heightAnimation?.cancel();
    heightAnimation = null;
    shownHeight = height;
    transition.fit(content, height);
    content.root.style.setProperty('--album-slot-height', `${height}px`);
    // Switching between lyrics and tracks must not jump the title. The list itself keeps a
    // stable final viewport while the outer slot moves with the library wall's timing.
    if (!reducedMotion && open > 0 && Math.abs(from - height) >= 0.5) {
      const effect = content.root.animate(
        [{ '--album-slot-height': `${from}px` }, { '--album-slot-height': `${height}px` }],
        LYRICS_TRANSITION_TIMING,
      );
      heightAnimation = effect;
      effect.onfinish = () => {
        if (heightAnimation !== effect) return;
        heightAnimation = null;
        effect.cancel();
      };
    }
  };
  const scheduleFit = (): void => {
    if (!frame) frame = requestAnimationFrame(() => { frame = 0; fit(); });
  };
  const reset = (): void => {
    if (frame) cancelAnimationFrame(frame);
    frame = 0;
    observer?.disconnect();
    observer = null;
    heightAnimation?.cancel();
    heightAnimation = null;
    content?.root.style.removeProperty('--album-slot-height');
    transition.reset();
    content = null;
    shownHeight = 0;
    mode = 'none';
  };

  return {
    mount(next: ExpandedContent) {
      reset();
      content = next;
      transition.fit(next, 0);
      observer = new ResizeObserver(scheduleFit);
      for (const element of [next.root, next.meta.querySelector('.poster__title-text'), next.controls, lyrics.viewElement, lyrics.element.firstElementChild]) {
        if (element) observer.observe(element);
      }
    },
    setMode(next: AlbumContentMode) {
      if (!content || next === mode) return;
      mode = next;
      fit();
      transition.toggle(content, next !== 'none', reducedMotion);
    },
    setReducedMotion(reduced: boolean) {
      reducedMotion = reduced;
      if (reduced) {
        transition.finish();
        heightAnimation?.finish();
      }
    },
    refreshLyrics() {
      // The clipped viewport can keep the same size while its rows grow. A row change must
      // request measurement explicitly; ResizeObserver alone cannot detect that overflow.
      if (content && mode === 'lyrics') scheduleFit();
    },
    reset,
  };
}

import type { ClockSnapshot, LyricsViewOptions } from '../types.ts';
import { buildLyricsTimeline } from '../lyrics/lyricsModel.ts';
import { createLyricsView } from '../lyrics/lyricsView.ts';

export type AlbumLyricsHost = {
  getLyrics(trackId: string): Promise<EchoWorkshopSandboxLyrics | null>;
  readClock(): ClockSnapshot;
};

/** Reuse the library wall's lyric renderer, retaining only the active track and one pending read. */
export function createAlbumLyrics(host: AlbumLyricsHost, onLayoutChange: () => void = () => undefined) {
  const element = document.createElement('div');
  element.className = 'album-lyrics';
  element.id = `album-lyrics-${crypto.randomUUID()}`;
  const message = document.createElement('p');
  message.className = 'album-details__message';
  message.textContent = '正在同步歌曲…';
  message.setAttribute('role', 'status');
  const view = createLyricsView();
  element.append(message, view.element);
  let trackId: string | null = null;
  let loadedId: string | null = null;
  let generation = 0;
  let active = false, pending = false, failed = false, disposed = false;

  const update = (clock: ClockSnapshot): void => {
    if (active && clock.trackId === trackId && view.update(clock.positionSeconds * 1000)) onLayoutChange();
  };
  const ensure = async (): Promise<void> => {
    if (disposed || !active || !trackId || loadedId === trackId || pending) return;
    const id = trackId, request = generation;
    pending = true;
    message.hidden = false;
    message.textContent = '正在加载歌词…';
    onLayoutChange();
    try {
      const lyrics = await host.getLyrics(id);
      if (disposed || request !== generation) return;
      loadedId = id;
      const timeline = buildLyricsTimeline(lyrics);
      view.setTimeline(timeline);
      message.hidden = timeline.kind !== 'empty';
      message.textContent = timeline.kind === 'empty' ? '暂无歌词' : '';
      update(host.readClock());
      onLayoutChange();
    } catch {
      if (disposed || request !== generation) return;
      loadedId = id;
      failed = true;
      message.textContent = '歌词加载失败，重新打开可重试';
      onLayoutChange();
    } finally {
      pending = false;
      // Rapid skips coalesce to the latest track instead of queuing a read for every song.
      void ensure();
    }
  };

  return {
    element,
    viewElement: view.element,
    hasFollowingLine: view.hasFollowingLine,
    setTrack(id: string | null) {
      if (disposed || id === trackId) return;
      generation++;
      trackId = id;
      loadedId = null;
      failed = false;
      view.setTimeline(null);
      message.hidden = false;
      message.textContent = id ? '正在加载歌词…' : '正在同步歌曲…';
      onLayoutChange();
      void ensure();
    },
    setActive(enabled: boolean) {
      if (disposed || active === enabled) return;
      active = enabled;
      if (enabled && failed) { loadedId = null; failed = false; }
      void ensure();
      if (enabled) update(host.readClock());
    },
    setOptions(options: LyricsViewOptions) {
      view.setOptions(options);
      onLayoutChange();
    },
    update,
    dispose() {
      disposed = true;
      generation++;
      trackId = loadedId = null;
      view.dispose();
      element.remove();
    },
  };
}

import type { LibrarySource, LibraryPageQuery } from '../host/librarySource.ts';
import type { RequiredCapability, Tile } from '../types.ts';

export const ALBUM_PAGE_SIZE = 60;
export const TRACK_PAGE_SIZE = 50;
export const ALBUM_PROBES: ReadonlyArray<readonly [RequiredCapability, string]> = [
  ['library:read', 'library:getAlbums'],
  ['library:read', 'library:getAlbumTracks'],
  ['queue:read', 'queue:get'],
  ['queue:control', 'queue:playAlbum'],
  ['queue:control', 'queue:playTrack'],
  ['playback:read', 'playback:getStatus'],
  ['playback:control', 'playback:play'],
  ['fs:plugin', 'settings:get'],
];

export function albumTiles(albums: EchoWorkshopAlbum[], page: number): Tile[] {
  return albums.map((album, index) => ({
    index: (page - 1) * ALBUM_PAGE_SIZE + index,
    queueId: `album:${album.id}`,
    albumId: album.id,
    trackId: album.id,
    title: album.title || '未知专辑',
    artist: album.albumArtist || '未知艺术家',
    album: `${album.trackCount} 首${album.year ? ` · ${album.year}` : ''}`,
    coverUrl: album.coverUrl,
    durationSeconds: album.durationSeconds,
  }));
}

const normalized = (value: string): string => value.trim().normalize('NFKC').toLocaleLowerCase();

/** The SDK track DTO has no albumId. Highlight only an unambiguous metadata match on this page. */
export function currentAlbumIndex(albums: EchoWorkshopAlbum[], track: EchoWorkshopTrack | null): number | null {
  if (!track?.album) return null;
  const title = normalized(track.album);
  const artist = normalized(track.albumArtist || track.artist);
  const matches = albums.flatMap((album, i) =>
    normalized(album.title) === title && normalized(album.albumArtist) === artist && album.mediaType === track.mediaType ? [i] : []);
  return matches.length === 1 ? matches[0]! : null;
}

/** Ignore stale responses without accumulating a cache of old album/track pages. */
export function createPageLoader<T>(read: (query: LibraryPageQuery) => Promise<EchoWorkshopPage<T>>, pageSize: number) {
  let generation = 0;
  return {
    async load(page: number, search = '', sourceProvider: LibrarySource = 'local'): Promise<EchoWorkshopPage<T> | null> {
      const request = ++generation;
      try {
        const result = await read({ page, pageSize, search, sourceProvider });
        if (request !== generation) return null;
        return { ...result, items: result.items.slice(0, pageSize) };
      } catch (error) {
        if (request !== generation) return null;
        throw error;
      }
    },
    cancel() { generation++; },
  };
}

import type { LibrarySource, LibraryPageQuery } from '../host/librarySource.ts';
import { formatTime } from '../wall/poster.ts';
import { TRACK_PAGE_SIZE } from './albumModel.ts';
import type { WallHostApi } from '../host/api.ts';

const OVERSCAN = 5;
const MAX_ROWS = 50;

/** A continuous scrollbar backed by at most two visible pages and one pending read. */
export function createAlbumTrackList(api: Pick<WallHostApi, 'library'>, onPlay: (id: string) => void, onMessage: (text: string) => void) {
  const element = document.createElement('div');
  element.className = 'album-tracks'; element.dataset.scrollable = 'true';
  element.tabIndex = -1;
  element.setAttribute('aria-label', '专辑曲目');
  const top = document.createElement('div');
  const rows = document.createElement('div'); rows.className = 'album-tracks__rows';
  const bottom = document.createElement('div');
  for (const spacer of [top, bottom]) spacer.setAttribute('aria-hidden', 'true');
  element.append(top, rows, bottom);
  const abort = new AbortController();
  const pages = new Map<number, EchoWorkshopTrack[]>();
  const failures = new Set<number>();
  const mounted = new Map<number, HTMLElement>();
  let albumId: string | null = null, currentId: string | null = null;
  let sourceProvider: LibrarySource = 'local';
  let total = 0, generation = 0, frame = 0, pending: Promise<void> | null = null;
  let firstPage = 1, lastPage = 1, previousRange = '', revision = 0;
  let initial = true;
  let scrollIdleTimer: ReturnType<typeof setTimeout> | undefined;
  let lastScrollTop = 0;
  let keyboardTarget: number | null = null, keyboardDirection = 1;

  const schedule = () => { if (!frame && albumId) frame = requestAnimationFrame(render); };
  const markCurrent = () => {
    for (const button of rows.querySelectorAll<HTMLButtonElement>('button[data-track]')) {
      if (button.dataset.track === currentId) button.setAttribute('aria-current', 'true');
      else button.removeAttribute('aria-current');
    }
  };
  const getTrack = (index: number) => pages.get(Math.floor(index / TRACK_PAGE_SIZE) + 1)?.[index % TRACK_PAGE_SIZE];
  const putRow = (index: number, row: HTMLElement) => {
    const previous = mounted.get(index);
    const focused = previous === document.activeElement;
    if (previous) previous.replaceWith(row); else rows.append(row);
    mounted.set(index, row);
    if (focused) (row instanceof HTMLButtonElement ? row : element).focus({ preventScroll: true });
  };

  function readNext(): void {
    if (pending || !albumId) return;
    const page = Array.from({ length: lastPage - firstPage + 1 }, (_, i) => firstPage + i)
      .find(value => !pages.has(value) && !failures.has(value));
    if (page === undefined) return;
    const request = generation, id = albumId;
    element.setAttribute('aria-busy', 'true');
    const task = (async () => {
      try {
        const query: LibraryPageQuery = { page, pageSize: TRACK_PAGE_SIZE, sourceProvider };
        const result = await api.library.getAlbumTracks(id, query);
        if (request !== generation) return;
        total = Math.max(0, result.total);
        // A fast scroll may move past this request before it completes; do not retain it.
        if (page >= firstPage && page <= lastPage) pages.set(page, result.items.slice(0, TRACK_PAGE_SIZE));
        if (initial) { initial = false; onMessage(total ? `${total} 首曲目` : '这张专辑没有可用曲目。'); }
      } catch {
        if (request === generation && page >= firstPage && page <= lastPage) failures.add(page);
      } finally {
        if (request === generation) { revision++; schedule(); }
      }
    })();
    pending = task;
    void task.finally(() => {
      if (pending === task) pending = null;
      element.removeAttribute('aria-busy');
      schedule();
    });
  }

  function render(): void {
    frame = 0;
    if (!albumId || element.clientHeight === 0) return;
    const scale = Number.parseFloat(getComputedStyle(element).getPropertyValue('--album-scale')) || 1;
    const rowHeight = 48 / scale;
    element.style.setProperty('--album-track-height', `${rowHeight}px`);
    if (keyboardTarget !== null) {
      while (keyboardTarget >= 0 && keyboardTarget < total && getTrack(keyboardTarget)?.unavailable) keyboardTarget += keyboardDirection;
      if (keyboardTarget < 0 || keyboardTarget >= total) keyboardTarget = null;
      else if (keyboardTarget * rowHeight < element.scrollTop) element.scrollTop = keyboardTarget * rowHeight;
      else if ((keyboardTarget + 1) * rowHeight > element.scrollTop + element.clientHeight) element.scrollTop = (keyboardTarget + 1) * rowHeight - element.clientHeight;
    }
    const count = Math.max(total, initial ? 1 : 0);
    const visible = Math.min(MAX_ROWS, Math.ceil(element.clientHeight / rowHeight) + OVERSCAN * 2);
    const start = Math.max(0, Math.min(count - 1, Math.floor(element.scrollTop / rowHeight) - OVERSCAN));
    const end = Math.min(count, start + visible);
    firstPage = Math.floor(start / TRACK_PAGE_SIZE) + 1;
    lastPage = Math.max(firstPage, Math.ceil(end / TRACK_PAGE_SIZE));
    for (const page of pages.keys()) if (page < firstPage || page > lastPage) pages.delete(page);
    for (const page of failures) if (page < firstPage || page > lastPage) failures.delete(page);
    const range = `${start}:${end}:${revision}`;
    if (range !== previousRange) {
      for (const [index, row] of mounted) {
        if (index < start || index >= end) { row.remove(); mounted.delete(index); }
      }
      let lastPlaceholderPage = -1;
      for (let index = start; index < end; index++) {
        const track = getTrack(index);
        const page = Math.floor(index / TRACK_PAGE_SIZE) + 1;
        if (!track) {
          const failed = failures.has(page);
          const firstPlaceholder = lastPlaceholderPage !== page;
          const row = document.createElement(failed && firstPlaceholder ? 'button' : 'div');
          row.className = 'album-track-row album-tracks__placeholder';
          if (row instanceof HTMLButtonElement) {
            row.type = 'button'; row.dataset.retryPage = String(page);
            row.textContent = '加载失败，点击重试';
          } else {
            row.textContent = !failed && firstPlaceholder ? '正在加载…' : '';
            row.setAttribute('aria-hidden', 'true');
          }
          lastPlaceholderPage = page; putRow(index, row); continue;
        }
        if (mounted.get(index)?.dataset.track === track.id) continue;
        const button = document.createElement('button');
        button.type = 'button'; button.className = 'album-track-row'; button.dataset.track = track.id;
        button.dataset.index = String(index);
        button.disabled = track.unavailable;
        const number = document.createElement('span'); number.className = 'album-track__number';
        number.textContent = String(index + 1).padStart(2, '0');
        const title = document.createElement('span'); title.className = 'album-track__title'; title.textContent = track.title || '未知标题';
        title.title = title.textContent;
        const time = document.createElement('span'); time.className = 'album-track__time';
        time.textContent = track.unavailable ? '不可用' : formatTime(track.durationSeconds);
        button.append(number, title, time); putRow(index, button);
      }
      top.style.height = `${start * rowHeight}px`;
      bottom.style.height = `${Math.max(0, count - end) * rowHeight}px`;
      // Insert new edges in order without detaching retained rows or their keyboard focus.
      let cursor = rows.firstElementChild;
      for (let index = start; index < end; index++) {
        const row = mounted.get(index)!;
        if (row === cursor) cursor = cursor.nextElementSibling;
        else rows.insertBefore(row, cursor);
      }
      previousRange = range;
      markCurrent();
    } else {
      top.style.height = `${start * rowHeight}px`;
      bottom.style.height = `${Math.max(0, count - end) * rowHeight}px`;
    }
    readNext();
    if (keyboardTarget !== null) {
      const failedPage = Math.floor(keyboardTarget / TRACK_PAGE_SIZE) + 1;
      const target = failures.has(failedPage)
        ? rows.querySelector<HTMLButtonElement>(`button[data-retry-page="${failedPage}"]`)
        : mounted.get(keyboardTarget);
      if (target instanceof HTMLButtonElement) { keyboardTarget = null; target.focus({ preventScroll: true }); }
      else if (!element.contains(document.activeElement)) element.focus({ preventScroll: true });
    }
  }

  element.addEventListener('scroll', () => {
    if (!albumId || element.scrollTop === lastScrollTop) return;
    lastScrollTop = element.scrollTop;
    element.dataset.scrolling = 'true';
    clearTimeout(scrollIdleTimer);
    scrollIdleTimer = setTimeout(() => {
      delete element.dataset.scrolling;
      scrollIdleTimer = undefined;
    }, 600);
    schedule();
  }, { passive: true, signal: abort.signal });
  element.addEventListener('keydown', event => {
    if (event.key !== 'Tab') return;
    const button = (event.target as HTMLElement).closest<HTMLButtonElement>('button[data-index]');
    if (!button && keyboardTarget === null) return;
    keyboardDirection = event.shiftKey ? -1 : 1;
    let next = (keyboardTarget ?? Number(button!.dataset.index)) + keyboardDirection;
    while (next >= 0 && next < total && getTrack(next)?.unavailable) next += keyboardDirection;
    if (next < 0 || next >= total) return;
    event.preventDefault(); keyboardTarget = next;
    // Keep the logical destination while its data loads instead of tabbing past unloaded rows.
    if (frame) cancelAnimationFrame(frame);
    render();
  }, { signal: abort.signal });
  for (const name of ['pointerdown', 'wheel']) element.addEventListener(name, () => { keyboardTarget = null; }, { passive: true, signal: abort.signal });
  element.addEventListener('focusout', event => {
    if (event.relatedTarget instanceof Node && !element.contains(event.relatedTarget)) keyboardTarget = null;
  }, { signal: abort.signal });
  element.addEventListener('click', event => {
    const button = (event.target as Element).closest<HTMLButtonElement>('button');
    if (button?.dataset.retryPage) { failures.delete(Number(button.dataset.retryPage)); revision++; schedule(); }
    const id = button?.dataset.track;
    if (id && !button.disabled && Array.from(pages.values()).some(tracks => tracks.some(track => track.id === id && !track.unavailable))) onPlay(id);
  }, { signal: abort.signal });
  const resize = new ResizeObserver(schedule); resize.observe(element);
  function clear(): void {
    generation++; albumId = null; total = 0; initial = true;
    keyboardTarget = null;
    clearTimeout(scrollIdleTimer); scrollIdleTimer = undefined;
    lastScrollTop = 0;
    delete element.dataset.scrolling;
    pages.clear(); failures.clear(); mounted.clear(); rows.replaceChildren(); previousRange = ''; revision++;
    top.style.height = '0px'; bottom.style.height = '0px'; element.scrollTop = 0;
    if (frame) cancelAnimationFrame(frame); frame = 0;
    element.removeAttribute('aria-busy');
  }
  return {
    element,
    mount(album: EchoWorkshopAlbum, source: LibrarySource = 'local') {
      clear(); albumId = album.id; total = album.trackCount;
      sourceProvider = source;
      onMessage('正在加载曲目…'); schedule();
    },
    setCurrent(id: string | null) { if (id !== currentId) { currentId = id; markCurrent(); } },
    clear,
    dispose() { clear(); abort.abort(); resize.disconnect(); },
  };
}

import { startLatticeAlbumWall } from './main.ts';
import { createPluginWallApi } from '../host/pluginApi.ts';

void startLatticeAlbumWall(createPluginWallApi(echo));

import type { LibrarySource } from '../host/librarySource.ts';
import type { Instance, Lattice, LatticeSettings, Point, Tile } from '../types.ts';
import type { WallHostApi } from '../host/api.ts';
import { createHostBridge } from '../host/bridge.ts';
import { applyContext } from '../host/context.ts';
import { createPlaybackClock } from '../host/clock.ts';
import { applyAppearance, cellMetricsFor, resolveSettings, settingEntries, wallExpandedScale, wallOverviewScale, wallVisualsFromSettings } from '../host/settings.ts';
import { createLattice } from '../geometry/lattice.ts';
import { createSpreadLattice, reseatPlayingToSquare } from '../geometry/tileSpread.ts';
import { createCamera } from '../wall/camera.ts';
import { createWallFrameLoop, INTERACTIVE_FRAME_MS } from '../wall/frameLoop.ts';
import { createPosterWall } from '../wall/posterWall.ts';
import { attachPointerPan } from '../wall/pointerPan.ts';
import { attachKeyboardNav } from '../wall/keyboardNav.ts';
import { createStateOverlay } from '../stateOverlay.ts';
import { createWallOpening } from '../wallOpening.ts';
import { ALBUM_PAGE_SIZE, ALBUM_PROBES, albumTiles, createPageLoader, currentAlbumIndex } from './albumModel.ts';
import { createControlPanel } from '../controlPanel.ts';
import { createAlbumDetails } from './albumDetails.ts';

const TITLE = 'Lattice · 专辑拼贴墙';

export async function startLatticeAlbumWall(echo: WallHostApi, signal?: AbortSignal): Promise<() => void> {
  const field = document.getElementById('field')!;
  const world = document.getElementById('world')!;
  const state = document.getElementById('state')!;
  const root = document.getElementById('lattice')!;
  const locate = document.getElementById('locate') as HTMLButtonElement;
  const opening = createWallOpening(document.body);
  const overlay = createStateOverlay(state, root, opening.finish);
  const bridge = createHostBridge(echo, { probes: ALBUM_PROBES });
  // Exit is available even if the host refuses library access or boot fails.
  const earlyExit = (event: KeyboardEvent) => {
    if (event.key === 'Escape' && !event.ctrlKey && !event.metaKey && !event.altKey) void bridge.closePanel();
  };
  document.addEventListener('keydown', earlyExit);
  const boot = await bridge.boot().catch(() => null);
  if (signal?.aborted) {
    opening.finish();
    document.removeEventListener('keydown', earlyExit);
    bridge.dispose();
    return () => undefined;
  }
  if (!boot) {
    document.removeEventListener('keydown', earlyExit);
    overlay.show('denied');
    bridge.dispose();
    return () => undefined;
  }
  applyContext(boot.context);
  opening.configure(boot.context);
  if (boot.missing.length) {
    document.removeEventListener('keydown', earlyExit);
    overlay.show('denied', { missing: [...new Set(boot.missing)] });
    bridge.dispose();
    return () => undefined;
  }
  document.removeEventListener('keydown', earlyExit);
  let context = boot.context;
  let settings = resolveSettings(boot.settings);
  applyAppearance(settings);
  void bridge.requestPresentation(TITLE, settings.immersive);
  let sourceProvider: LibrarySource = 'local';
  let albums: EchoWorkshopAlbum[] = [];
  let tiles: Tile[] = [];
  let track = boot.queue?.currentTrack ?? null;
  let current: number | null = null;
  let lattice: Lattice | null = null;
  let ready = false, disposed = false;
  let wallAnimating = false;
  let mounted: string | null = null;
  let shuffleEnabled = boot.status?.shuffleEnabled === true || boot.queue?.shuffleEnabled === true;
  let repeatOne = boot.status?.repeatMode === 'one' || boot.queue?.repeatMode === 'one';
  const camera = createCamera();
  const clock = createPlaybackClock();
  const now = () => performance.now();
  const isExpandedCurrent = () => wall.expanded !== null && current !== null && wall.expanded.tileIndex === current;
  const togglePlay = () => {
    if (clock.read(now()).state === 'playing') void bridge.pause();
    else void bridge.play();
  };
  const details = createAlbumDetails(echo, {
    onRenderNeeded: () => requestFrame(),
    getLyrics: id => bridge.getLyrics(id),
    readClock: () => clock.read(now()),
    playAlbum: () => undefined,
    play: () => void bridge.play(),
    pause: () => void bridge.pause(),
    togglePlay,
    previous: () => void bridge.previous(),
    next: () => void bridge.next(),
    seek: (position) => {
      clock.seek(position, now());
      void bridge.seek(position);
      requestFrame();
    },
    toggleShuffle: () => {
      shuffleEnabled = !shuffleEnabled;
      details.setShuffleEnabled(shuffleEnabled);
      void bridge.toggleShuffle();
    },
    toggleRepeatOne: () => {
      repeatOne = !repeatOne;
      details.setRepeatOne(repeatOne);
      void bridge.setRepeat(repeatOne ? 'one' : 'off');
    },
  });
  details.setShuffleEnabled(shuffleEnabled);
  details.setRepeatOne(repeatOne);
  const loader = createPageLoader(query => echo.library.getAlbums(query), ALBUM_PAGE_SIZE);
  const frameIntervalMs = (): number => document.body.dataset.dragging !== 'true'
    && !camera.animating && !wallAnimating ? 33 : INTERACTIVE_FRAME_MS;
  const frames = createWallFrameLoop(frame, frameIntervalMs, context.visible);
  const requestFrame = frames.request;
  const updateLocate = () => {
    locate.dataset.visible = String(ready && current !== null && (wall.expanded?.tileIndex !== current || !wall.expandedVisible(camera)));
  };
  function frame(time: number): boolean {
    if (!ready || disposed) return false;
    if (camera.tick(time)) world.style.transform = camera.transform();
    wallAnimating = wall.render(camera, time);
    mountDetails();
    if (isExpandedCurrent() && wall.expandedVisible(camera)) details.updateClock(clock.read(time));
    updateLocate();
    return wallAnimating || camera.animating || (clock.running && isExpandedCurrent() && details.clockVisible && wall.expandedVisible(camera));
  }
  function mountDetails() {
    const instance = wall.expanded;
    const content = wall.expandedContent();
    const album = instance ? albums[instance.tileIndex] : null;
    if (!content || !instance || !album || mounted === instance.id) return;
    mounted = instance.id;
    const currentAlbum = current !== null && instance.tileIndex === current;
    details.mount(content, album, currentAlbum, sourceProvider);
    details.updateCurrent(track?.id ?? null, currentAlbum);
    content.root.style.setProperty('--album-scale', String(wallExpandedScale(camera.viewport.width)));
  }
  function reseatPlayingNear(near: Point): void {
    if (!lattice || current === null || tiles.length === 0) return;
    const playingAt = lattice.nearestInstance(current, near, null);
    lattice = createLattice(tiles.length, lattice.metrics, reseatPlayingToSquare(lattice, playingAt, current));
    wall.setLattice(lattice, tiles, { followTiles: true });
    wall.setCurrent(current);
  }
  function expand(instance: Instance, flyMs = 420) {
    if (!lattice || !ready) return;
    const same = wall.expanded?.id === instance.id;
    if (!same) {
      const previous = wall.expanded;
      const targetTile = instance.tileIndex;
      const targetNear = lattice.centerOf(instance.rect);
      details.clear();
      mounted = null;
      if (current !== null && targetTile !== current) {
        reseatPlayingNear(previous ? lattice.centerOf(previous.rect) : { x: camera.state.x, y: camera.state.y });
        instance = lattice.nearestInstance(targetTile, targetNear, null);
      }
    }
    wall.setExpanded(instance);
    wall.setFocus(wall.expanded);
    const expanded = wall.expanded!;
    const center = lattice.centerOf(expanded.rect);
    const duration = context.reducedMotion ? 0 : flyMs;
    if (duration <= 0) {
      camera.setCenter(center.x, center.y);
      camera.setScale(wallExpandedScale(camera.viewport.width));
      world.style.transform = camera.transform();
    } else {
      camera.flyTo({ ...center, scale: wallExpandedScale(camera.viewport.width) }, duration);
    }
    requestFrame();
  }
  function collapse(options?: { reshuffle?: boolean }) {
    if (!wall.expanded || !lattice) return;
    const expanded = wall.expanded;
    const playing = current !== null && expanded.tileIndex === current;
    const near = lattice.centerOf(expanded.rect);
    details.clear();
    mounted = null;
    wall.setExpanded(null);
    wall.setFocus(null);
    field.focus({ preventScroll: true });
    const overview = wallOverviewScale(camera.viewport.width);
    if (options?.reshuffle !== false && current !== null && tiles.length > 0) {
      const playingAt = lattice.nearestInstance(current, near, null);
      reseatPlayingNear(near);
      const landed = lattice.nearestInstance(current, lattice.centerOf(playingAt.rect), null);
      if (playing) {
        camera.flyTo(
          { x: lattice.centerOf(landed.rect).x, y: lattice.centerOf(landed.rect).y, scale: overview },
          context.reducedMotion ? 0 : 300,
        );
      } else if (Math.abs(camera.state.scale - overview) > 0.01) {
        camera.flyTo({ x: camera.state.x, y: camera.state.y, scale: overview }, context.reducedMotion ? 0 : 300);
      }
    } else if (Math.abs(camera.state.scale - overview) > 0.01) {
      camera.flyTo({ x: camera.state.x, y: camera.state.y, scale: overview }, context.reducedMotion ? 0 : 300);
    }
    requestFrame();
  }
  const wall = createPosterWall(world, {
    onEntranceComplete: opening.finish,
    onRenderNeeded: requestFrame,
    onActivate: expand,
    onFocusChange: () => undefined,
    onExpandSettled: mountDetails,
    onExpandedTap: () => { details.toggle(); requestFrame(); },
    onHoverCurrent: () => undefined,
  });
  const visuals = () => {
    camera.setFisheye(settings.fisheye, !context.reducedMotion);
    applyAppearance(settings);
    details.setLyricsOptions({ showTranslation: settings.showTranslation, reducedMotion: context.reducedMotion });
    wall.setVisualOptions(wallVisualsFromSettings(settings, context.reducedMotion));
    requestFrame();
  };
  const commitSettings = (previous: LatticeSettings, persist: Partial<LatticeSettings> | null): void => {
    visuals();
    browser.syncSettings(settings);
    if (previous.cellSize !== settings.cellSize) {
      collapse({ reshuffle: false });
      rebuild();
    }
    if (previous.immersive !== settings.immersive) void bridge.requestPresentation(TITLE, settings.immersive);
    if (persist) {
      for (const [id, value] of settingEntries(persist)) void bridge.setSetting(id, value);
    }
  };
  const patchSettings = (patch: Partial<LatticeSettings>): void => {
    const previous = settings;
    settings = { ...settings, ...patch };
    commitSettings(previous, patch);
  };
  const focusCurrent = () => {
    if (lattice && current !== null) expand(lattice.nearestInstance(current, camera.state, wall.expanded));
  };
  const rebuild = () => {
    if (!tiles.length) return;
    lattice = createSpreadLattice(tiles, cellMetricsFor(settings.cellSize));
    wall.setLattice(lattice, tiles); wall.setCurrent(current); visuals(); requestFrame();
  };
  // Paging reuses the renderer while dropping old tile references and mounted cards via clear().
  async function loadPage(page: number, search: string, source: LibrarySource = 'local') {
    collapse({ reshuffle: false }); ready = false; camera.stop();
    sourceProvider = source;
    albums = []; tiles = []; current = null;
    wall.clear(); lattice = null;
    updateLocate(); browser.loading(page);
    overlay.setNotice(null);
    overlay.show('booting');
    state.querySelector('h2')!.textContent = '正在读取专辑';
    state.querySelector('p')!.textContent = '从 ECHO 曲库加载…';
    try {
      const result = await loader.load(page, search, source);
      if (!result || disposed) return;
      browser.update(result);
      albums = result.items; tiles = albumTiles(albums, result.page);
      current = currentAlbumIndex(albums, track);
      ready = albums.length > 0;
      document.body.dataset.state = ready ? 'ready' : 'empty';
      overlay.show(ready ? 'ready' : 'empty');
      if (!ready) {
        state.querySelector('h2')!.textContent = search ? '没有找到专辑' : '曲库中还没有专辑';
        state.querySelector('p')!.textContent = search ? '打开功能面板修改关键词，或清空搜索。' : '在 ECHO 中导入音乐后，打开功能面板并刷新。';
        return;
      }
      rebuild();
      const instance = lattice!.nearestInstance(current ?? 0, { x: 0, y: 0 }, null);
      if (current !== null) expand(instance, 0);
      else {
        const center = lattice!.centerOf(instance.rect);
        camera.setCenter(center.x, center.y);
        camera.setScale(wallOverviewScale(camera.viewport.width));
        world.style.transform = camera.transform();
        wall.setFocus(instance);
      }
      if (!context.desktop) wall.playEntrance(performance.now());
      requestFrame();
    } catch {
      if (disposed) return;
      browser.error(); overlay.show('empty');
      state.querySelector('h2')!.textContent = '暂时无法读取专辑';
      state.querySelector('p')!.textContent = '打开功能面板并刷新重试；如尚未授权，请在 Workshop → 已安装 中确认读取曲库权限。';
    }
  }
  const browser = createControlPanel(root, {
    speed: echo.speed,
    desktop: echo.desktop,
    wall: 'albums',
    settings,
    search: {
      placeholder: '输入专辑关键词',
      searchLabel: '搜索专辑',
      unit: '张',
    },
    onLoad: (page, search, source) => { void loadPage(page, search, source); },
    onSwitchWall: (target) => {
      if (target !== 'library') return;
      void bridge.openPanel('wall');
    },
    onPatchSettings: patchSettings,
  });
  const pointer = attachPointerPan(field, {
    projectPointer: (x, y) => wall.pointerPoint(x, y),
    onPan: (x, y) => { camera.panBy(x, y); requestFrame(); },
    onFling: (x, y) => { camera.fling(x, y); requestFrame(); },
    onWheel: (x, y) => { camera.panBy(-x, -y); frames.requestInteractive(); },
    onTap: () => undefined,
    onDragStart: () => { document.body.dataset.dragging = 'true'; },
    onDragEnd: () => { delete document.body.dataset.dragging; requestFrame(); },
  });
  const keyboard = attachKeyboardNav(document.body, {
    move: direction => {
      if (!lattice || !ready) return;
      const from = wall.focused ?? lattice.nearestInstance(current ?? 0, camera.state, wall.expanded);
      const to = lattice.neighbor(from, direction, wall.expanded);
      wall.setFocus(to);
      camera.flyTo(lattice.centerOf(to.rect), context.reducedMotion ? 0 : 260); requestFrame();
    },
    activate: () => {
      if (!wall.focused) return;
      if (wall.expanded?.id !== wall.focused.id) {
        expand(wall.focused);
        return;
      }
      if (isExpandedCurrent()) togglePlay();
      else details.play();
    },
    secondary: () => {
      if (!wall.expanded) {
        if (wall.focused) expand(wall.focused);
        return;
      }
      if (isExpandedCurrent()) togglePlay();
      else { details.toggle(); requestFrame(); }
    },
    escape: () => { if (wall.expanded) collapse(); else void bridge.closePanel(); },
    focusCurrent,
    toggle: setting => {
      const patch: Partial<LatticeSettings> = {};
      if (settings.lightingMode === 'daytime') patch.lightingMode = 'spotlight';
      if (setting === 'lights-out') patch.lightsOut = !settings.lightsOut;
      if (setting === 'vignette') patch.vignette = !settings.vignette;
      if (setting === 'tint') patch.posterTint = !settings.posterTint;
      patchSettings(patch);
    },
    seekBy: (delta) => {
      if (!details.seekFocused) return false;
      const snapshot = clock.read(now());
      const next = Math.max(0, snapshot.positionSeconds + delta);
      clock.seek(next, now());
      void bridge.seek(next);
      requestFrame();
      return true;
    },
  });
  locate.addEventListener('click', focusCurrent);
  const stop = [
    bridge.onQueueChanged(snapshot => {
      const before = current;
      track = snapshot.currentTrack; current = currentAlbumIndex(albums, track);
      wall.setCurrent(current);
      details.updateCurrent(track?.id ?? null, isExpandedCurrent());
      if (settings.autoFocus && before !== current && current !== null) focusCurrent();
      requestFrame();
    }),
    bridge.onPlaybackStatus(status => {
      clock.ingest(status, now());
      details.updateStatus(status, isExpandedCurrent());
      if (status.shuffleEnabled === true || status.shuffleEnabled === false) {
        shuffleEnabled = status.shuffleEnabled;
        details.setShuffleEnabled(shuffleEnabled);
      }
      if (status.repeatMode === 'off' || status.repeatMode === 'one' || status.repeatMode === 'all') {
        repeatOne = status.repeatMode === 'one';
        details.setRepeatOne(repeatOne);
      }
      requestFrame();
    }),
    bridge.onContextChanged(next => { context = next; applyContext(next); visuals(); frames.setVisible(next.visible); }),
    bridge.onSettingsChanged(values => {
      const previous = settings;
      settings = resolveSettings(values);
      commitSettings(previous, null);
    }),
  ];
  stop.push(echo.events.on('library:changed', () => {
    overlay.setNotice('曲库已更新，打开功能面板即可刷新');
  }));
  const resize = new ResizeObserver(entries => {
    const rect = entries[0]?.contentRect;
    if (!rect || rect.width < 1 || rect.height < 1) return;
    camera.setViewport(rect.width, rect.height);
    if (!camera.animating) {
      camera.setScale((wall.expanded ? wallExpandedScale : wallOverviewScale)(rect.width));
    }
    if (wall.expanded) {
      wall.expandedContent()?.root.style.setProperty('--album-scale', String(wallExpandedScale(rect.width)));
    }
    world.style.transform = camera.transform(); requestFrame();
  });
  resize.observe(field);
  if (boot.status) {
    clock.ingest(boot.status, now());
    details.updateStatus(boot.status, false);
  }
  visuals();
  void loadPage(1, '');
  const dispose = (): void => {
    if (disposed) return;
    disposed = true; opening.finish(); frames.dispose(); loader.cancel(); camera.stop();
    window.removeEventListener('pagehide', dispose);
    signal?.removeEventListener('abort', dispose);
    lattice = null;
    for (const off of stop) off();
    locate.removeEventListener('click', focusCurrent);
    resize.disconnect(); pointer.dispose(); keyboard.dispose(); browser.dispose();
    details.dispose(); wall.dispose(); bridge.dispose(); albums = []; tiles = [];
  };
  window.addEventListener('pagehide', dispose, { once: true });
  signal?.addEventListener('abort', dispose, { once: true });
  if (signal?.aborted) dispose();
  return dispose;
}

import type { LibrarySource } from './host/librarySource.ts';
import type { LatticeSettings } from './types.ts';
import { createControlPanelSettings } from './controlPanelSettings.ts';
import { createControlPanelTabs } from './controlPanelTabs.ts';
import { createControlPanelShortcut } from './controlPanelShortcut.ts';
import { matchesPanelShortcut, panelShortcutAria } from './host/controlPanelShortcut.ts';
import { createControlPanelSpeed } from './controlPanelSpeed.ts';
import { createControlPanelDesktop } from './controlPanelDesktop.ts';
import { button, el, group, icon, keyChips, press, row, segments } from './controlPanelUi.ts';
import type { SpeedControl, DesktopControl } from './host/api.ts';

export type ControlPanelWall = 'library' | 'albums';

export type ControlPanelSearchCopy = {
  placeholder: string;
  searchLabel: string;
  unit: string;
};

export type ControlPanel = {
  loading(page: number): void;
  update(result: EchoWorkshopPage<unknown>): void;
  error(): void;
  refresh(): void;
  syncSettings(settings: LatticeSettings): void;
  dispose(): void;
};

const WALLS: ReadonlyArray<{ value: ControlPanelWall; label: string; description: string }> = [
  { value: 'library', label: '曲库拼贴墙', description: '按歌曲铺满，每页 200 首' },
  { value: 'albums', label: '专辑拼贴墙', description: '按专辑浏览，每页 60 张' },
];
const SOURCES: ReadonlyArray<{ value: LibrarySource; label: string }> = [
  { value: 'local', label: '本地' },
  { value: 'remote', label: '远程' },
];
/** Wall keys from `wall/keyboardNav.ts`; Enter and Space differ per wall. */
const WALL_KEYS = (wall: ControlPanelWall): ReadonlyArray<[string, string]> => [
  ['方向键', '在封面间移动'],
  ['Enter', wall === 'library' ? '展开；再按播放 / 暂停' : '展开；再按播放整张'],
  ['Space', wall === 'library' ? '展开；再按显示 / 隐藏控制' : '展开；再按切换曲目区'],
  ['C', wall === 'library' ? '定位正在播放的歌曲' : '定位正在播放的专辑'],
  ['L / V / T', '关灯 / 暗角 / 叠色'],
  ['Esc', '收起卡片；再按关闭'],
];

const focusables = (root: HTMLElement): HTMLElement[] =>
  [...root.querySelectorAll<HTMLButtonElement | HTMLInputElement | HTMLSelectElement>('button, input, select')].filter(
    (node) => node.tabIndex >= 0 && !node.disabled && !node.hidden && !node.closest('[hidden]') && node.getAttribute('aria-hidden') !== 'true',
  );

const wallKeys = (wall: ControlPanelWall): HTMLElement => {
  const list = el('dl', 'control-panel__keys');
  for (const [keys, action] of WALL_KEYS(wall)) {
    const item = el('div', 'control-panel__keys-item');
    const term = el('dt');
    term.append(...keys.split(' / ').flatMap((key, index) =>
      index === 0 ? [el('kbd', undefined, key)] : [document.createTextNode(' '), el('kbd', undefined, key)]));
    item.append(term, el('dd', undefined, action));
    list.append(item);
  }
  return list;
};

/**
 * Function panel: a sidebar of five pages (browse, playback, appearance, lighting, general), each a
 * stack of titled cards. Owns no library data.
 */
export function createControlPanel(
  container: HTMLElement,
  options: {
    wall: ControlPanelWall;
    settings: LatticeSettings;
    search: ControlPanelSearchCopy;
    lyrics?: boolean;
    speed?: SpeedControl;
    desktop?: DesktopControl;
    onLoad: (page: number, search: string, source: LibrarySource) => void;
    onSwitchWall: (target: ControlPanelWall) => void;
    onPatchSettings: (patch: Partial<LatticeSettings>) => void;
  },
): ControlPanel {
  const abort = new AbortController();
  const { signal } = abort;
  const dialog = el('dialog', 'control-panel');
  dialog.setAttribute('aria-labelledby', 'control-panel-title');
  let panelShortcut = options.settings.controlPanelShortcut;
  const wallName = options.wall === 'library' ? '曲库拼贴墙' : '专辑拼贴墙';

  // ---- browse -----------------------------------------------------------------------------------
  const walls = el('div', 'control-panel__walls');
  walls.setAttribute('role', 'group');
  walls.setAttribute('aria-label', '切换拼贴墙');
  const wallButtons = new Map<ControlPanelWall, HTMLButtonElement>();
  for (const item of WALLS) {
    const node = button('', { className: 'control-panel__wall' });
    node.dataset.wall = item.value;
    const text = el('span', 'control-panel__wall-text');
    text.append(el('span', 'control-panel__wall-name', item.label), el('span', 'control-panel__wall-description', item.description));
    const dot = el('span', 'control-panel__wall-dot');
    dot.setAttribute('aria-hidden', 'true');
    node.append(text, dot);
    wallButtons.set(item.value, node);
    walls.append(node);
  }

  const searchField = el('label', 'control-panel__search');
  const search = el('input');
  search.type = 'search';
  search.placeholder = options.search.placeholder;
  search.setAttribute('aria-label', options.search.searchLabel);
  search.maxLength = 160;
  search.spellcheck = false;
  searchField.append(icon('search'), search);
  const sources = segments('曲库来源', SOURCES);
  let source: LibrarySource = 'local';
  const sourceRow = row({ label: '曲库来源', hint: '远程曲库需先在 ECHO 中同步', controls: [sources.root] });
  const status = el('span', 'control-panel__status');
  status.setAttribute('role', 'status');
  const previous = button('上一页', { icon: 'previous' });
  const next = button('');
  next.append(el('span', undefined, '下一页'), icon('next'));
  const refresh = button('刷新', { icon: 'refresh' });
  const pagerButtons = el('div', 'control-panel__pager-buttons');
  pagerButtons.append(previous, next, refresh);
  const pager = el('div', 'control-panel__pager');
  pager.append(status, pagerButtons);
  const searchBody = el('div', 'control-panel__search-body');
  searchBody.append(searchField);
  const browse = [
    group('拼贴墙', [walls]),
    group(options.search.searchLabel, [searchBody, sourceRow.root, pager]),
  ];

  // ---- settings ---------------------------------------------------------------------------------
  const settings = createControlPanelSettings({
    titleLabel: options.wall === 'library' ? '常显歌名' : '常显专辑名',
    lyrics: options.lyrics === true,
    settings: options.settings,
    onPatchSettings: options.onPatchSettings,
    signal,
  });
  const shortcutSetting = createControlPanelShortcut({
    value: panelShortcut,
    onChange: value => options.onPatchSettings({ controlPanelShortcut: value }),
    signal,
  });
  const speed = options.speed ? createControlPanelSpeed(options.speed) : null;
  const desktop = options.desktop ? createControlPanelDesktop(options.desktop, signal) : null;
  const { rows, groups } = settings;

  const tabs = createControlPanelTabs([
    { id: 'browse', label: '浏览', description: '切换拼贴墙，搜索与翻页', sections: browse },
    {
      id: 'playback', label: '播放', description: options.lyrics ? '播放速度、切歌与歌词' : '播放速度与切歌',
      sections: [group('播放', [...(speed ? [speed.root] : []), rows.autoFocus]), groups.lyrics],
    },
    { id: 'appearance', label: '外观', description: '封面、格子尺寸、字体与立体效果', sections: [groups.wall, groups.depth] },
    { id: 'lighting', label: '光影', description: '灯光模式、暗角、关灯与叠色', sections: [groups.light, groups.tint] },
    {
      id: 'general', label: '通用', description: '窗口、桌面墙与快捷键',
      sections: [
        group('窗口', [rows.immersive, ...(desktop ? [desktop.root] : [])]),
        group('快捷键', [shortcutSetting.root, wallKeys(options.wall)], '快捷键只在拼贴墙内生效；墙面按键在功能面板关闭时可用。'),
      ],
    },
  ], signal, category => {
    if (category !== 'general') shortcutSetting.cancel();
    if (dialog.open && category === 'playback') speed?.open();
    else speed?.close();
    if (dialog.open && category === 'general') desktop?.open();
  });

  // ---- layout -----------------------------------------------------------------------------------
  const form = el('form', 'control-panel__form');
  const sidebar = el('div', 'control-panel__sidebar');
  const brand = el('div', 'control-panel__brand');
  const title = el('h2', undefined, '功能面板');
  title.id = 'control-panel-title';
  const wordmark = el('p', 'control-panel__wordmark', 'Lattice');
  wordmark.setAttribute('aria-hidden', 'true');
  brand.append(wordmark, title, el('p', 'control-panel__brand-wall', wallName));
  const footer = el('div', 'control-panel__footer');
  const shortcut = el('span', 'control-panel__shortcut');
  footer.append(el('span', undefined, '设置即时生效'), shortcut);
  sidebar.append(brand, tabs.navigation, footer);
  const main = el('div', 'control-panel__main');
  const header = el('div', 'control-panel__header');
  const dismiss = button('', { icon: 'close', label: '关闭功能面板（Esc）', className: 'control-panel__dismiss' });
  header.append(tabs.heading, dismiss);
  main.append(header, tabs.pages);
  form.append(sidebar, main);
  dialog.append(form);
  container.append(dialog);

  let returnFocus: HTMLElement | null = null;
  let page = 1;
  let hasMore = false;
  let busy = false;
  let timer: ReturnType<typeof setTimeout> | undefined;

  const close = (): void => {
    shortcutSetting.cancel();
    speed?.close();
    dialog.close();
    const target = returnFocus?.isConnected ? returnFocus : document.getElementById('field');
    target?.focus({ preventScroll: true });
    returnFocus = null;
  };

  const load = (target: number): void => {
    clearTimeout(timer);
    options.onLoad(target, search.value.trim(), source);
  };

  const buttons = (): void => {
    previous.disabled = busy || page === 1;
    next.disabled = busy || !hasMore;
    refresh.disabled = busy;
  };

  const syncSource = (): void => {
    for (const [value, node] of sources.buttons) press(node, value === source);
  };

  const syncWall = (): void => {
    for (const [value, node] of wallButtons) {
      const active = value === options.wall;
      press(node, active);
      if (active) node.setAttribute('aria-current', 'true');
      else node.removeAttribute('aria-current');
    }
  };

  const syncSettings = (latest: LatticeSettings): void => {
    panelShortcut = latest.controlPanelShortcut;
    shortcutSetting.sync(panelShortcut);
    dialog.setAttribute('aria-keyshortcuts', panelShortcutAria(panelShortcut));
    const field = container.querySelector<HTMLElement>('#field');
    field?.setAttribute('aria-label', wallName);
    field?.setAttribute('aria-keyshortcuts', panelShortcutAria(panelShortcut));
    field?.setAttribute('aria-description', `按 ${panelShortcut.split('+').join(' + ')} 打开功能面板`);
    shortcut.replaceChildren(...keyChips(panelShortcut));
    settings.sync(latest);
    syncWall();
  };

  document.addEventListener('keydown', (event) => {
    if (shortcutSetting.recording || !matchesPanelShortcut(event, panelShortcut)) return;
    event.preventDefault();
    event.stopPropagation();
    if (event.repeat) return;
    if (!dialog.open) {
      returnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : null;
      dialog.showModal();
    }
    tabs.select('browse');
    search.focus();
    search.select();
  }, { signal, capture: true });

  dismiss.addEventListener('click', close, { signal });
  dialog.addEventListener('cancel', (event) => { event.preventDefault(); close(); }, { signal });
  dialog.addEventListener('click', (event) => {
    if (event.target !== dialog) return;
    const rect = dialog.getBoundingClientRect();
    if (event.clientX < rect.left || event.clientX > rect.right
      || event.clientY < rect.top || event.clientY > rect.bottom) close();
  }, { signal });

  for (const [value, node] of sources.buttons) {
    node.addEventListener('click', () => {
      if (value === source) return;
      source = value;
      syncSource();
      load(1);
    }, { signal });
  }
  search.addEventListener('input', () => {
    clearTimeout(timer);
    timer = setTimeout(() => load(1), 350);
  }, { signal });
  search.addEventListener('keydown', (event) => {
    if (event.key !== 'Enter' || event.isComposing || event.keyCode === 229) return;
    event.preventDefault();
    if (!event.repeat) load(1);
  }, { signal });
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    if (tabs.selected === 'browse') load(1);
  }, { signal });
  previous.addEventListener('click', () => load(Math.max(1, page - 1)), { signal });
  next.addEventListener('click', () => load(page + 1), { signal });
  refresh.addEventListener('click', () => load(page), { signal });

  for (const [value, node] of wallButtons) {
    node.addEventListener('click', () => {
      if (value !== options.wall) options.onSwitchWall(value);
    }, { signal });
  }

  dialog.addEventListener('keydown', (event) => {
    if (event.ctrlKey || event.metaKey || event.altKey) return;
    if (event.key === 'Tab') {
      const nodes = focusables(dialog);
      const first = nodes[0];
      const last = nodes[nodes.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last?.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first?.focus();
      }
    }
    if (event.key === 'Escape' && !event.isComposing) {
      event.preventDefault();
      close();
    }
    event.stopPropagation();
  }, { signal });

  syncSource();
  syncSettings(options.settings);
  buttons();

  return {
    loading(target) {
      page = target;
      busy = true;
      form.setAttribute('aria-busy', 'true');
      status.textContent = '正在加载…';
      buttons();
    },
    update(result) {
      page = result.page;
      hasMore = result.hasMore;
      busy = false;
      form.removeAttribute('aria-busy');
      const pages = Math.max(1, Math.ceil(result.total / Math.max(1, result.pageSize)));
      status.textContent = pages <= 1
        ? `共 ${result.total} ${options.search.unit}`
        : `第 ${page} / ${pages} 页 · 共 ${result.total} ${options.search.unit}`;
      buttons();
    },
    error() {
      busy = false;
      form.removeAttribute('aria-busy');
      status.textContent = '加载失败，请刷新重试';
      buttons();
    },
    refresh() {
      if (!busy) load(page);
    },
    syncSettings,
    dispose() {
      speed?.dispose();
      clearTimeout(timer);
      abort.abort();
      dialog.close();
      dialog.remove();
      returnFocus = null;
    },
  };
}

import type { DesktopControl, DesktopState } from './host/api.ts';
import { dimRow, press, switchRow } from './controlPanelUi.ts';

/** Optional host-owned desktop wall; unavailable hosts never show an enabled switch. */
export function createControlPanelDesktop(desktop: DesktopControl, signal: AbortSignal) {
  const toggle = switchRow({ label: '桌面音乐拼贴墙', hint: '' });
  const root = toggle.root;
  const hint = toggle.hint!;
  let enabled = false;
  let busy = false;
  let revision = 0;
  const render = (state: DesktopState): void => {
    enabled = state.enabled === true;
    root.disabled = state.supported !== true || busy;
    dimRow(root, state.supported !== true);
    press(root, enabled);
    hint.textContent = state.supported ? '把拼贴墙铺到桌面，窗口与播放由 ECHO 管理' : '当前 ECHO 或平台暂不支持桌面拼贴墙';
  };
  render({ supported: false, enabled: false });
  const open = (): void => {
    const current = ++revision;
    void desktop.get().then(state => {
      if (!signal.aborted && current === revision && !busy) render(state);
    }).catch(() => {
      if (!signal.aborted && current === revision) render({ supported: false, enabled: false });
    });
  };
  root.addEventListener('click', () => {
    if (busy || root.disabled) return;
    busy = true;
    root.disabled = true;
    const current = ++revision;
    void desktop.set(!enabled).then(state => {
      if (!signal.aborted && current === revision) { busy = false; render(state); }
    }).catch(() => {
      if (!signal.aborted && current === revision) {
        busy = false;
        hint.textContent = '桌面墙切换失败，请重试';
        root.disabled = false;
      }
    });
  }, { signal });
  return { root, open };
}

import type { LatticeSettings } from './types.ts';
import {
  HUD_MIN_TILT_ANGLE,
  HUD_MAX_TILT_ANGLE,
  HUD_DEFAULT_TILT_ANGLE,
  normalizeHudTiltAngle,
} from './hudSettings.ts';
import { dimRow, row, slider } from './controlPanelUi.ts';

const ON_HINT = `最大倾斜角，默认 ${HUD_DEFAULT_TILT_ANGLE.toFixed(1)}°；0° 只保留悬浮视差`;
const OFF_HINT = '开启 HUD 后可调';

/** Saves one setting update per completed drag, while the value label follows the thumb. */
export function createControlPanelHudTilt(options: {
  settings: LatticeSettings;
  onPatchSettings(patch: Partial<LatticeSettings>): void;
  signal: AbortSignal;
}): { root: HTMLElement; sync(settings: LatticeSettings): void } {
  const angle = slider({
    min: HUD_MIN_TILT_ANGLE,
    max: HUD_MAX_TILT_ANGLE,
    step: 0.1,
    format: value => `${normalizeHudTiltAngle(value).toFixed(1)}°`,
    spoken: value => `${normalizeHudTiltAngle(value).toFixed(1)} 度`,
  });
  const tiltRow = row({ label: '墙面倾斜角度', hint: ON_HINT, sub: true, wide: true, controls: [angle.input, angle.value] });

  let settings = options.settings;
  let editing = false;
  const sync = (next: LatticeSettings): void => {
    settings = next;
    angle.input.disabled = !next.pointer3d;
    dimRow(tiltRow.root, !next.pointer3d);
    if (tiltRow.hint) tiltRow.hint.textContent = next.pointer3d ? ON_HINT : OFF_HINT;
    if (!next.pointer3d) editing = false;
    if (!editing) angle.input.value = String(normalizeHudTiltAngle(next.hudTiltAngle));
    angle.render();
  };
  angle.input.addEventListener('input', () => {
    if (angle.input.disabled) return;
    editing = true;
    angle.render();
  }, { signal: options.signal });
  angle.input.addEventListener('change', () => {
    if (angle.input.disabled) return;
    editing = false;
    const value = normalizeHudTiltAngle(Number(angle.input.value));
    angle.input.value = String(value);
    angle.render();
    if (value !== normalizeHudTiltAngle(settings.hudTiltAngle)) {
      options.onPatchSettings({ hudTiltAngle: value });
    }
  }, { signal: options.signal });
  angle.input.addEventListener('pointercancel', () => {
    editing = false;
    sync(settings);
  }, { signal: options.signal });
  sync(settings);
  return { root: tiltRow.root, sync };
}

import type { CellSizeId, LatticeSettings, LightingMode, TintGradient } from './types.ts';
import { controlPanelSettingLocks, sanitizeUiFont } from './host/settings.ts';
import { createControlPanelHudTilt } from './controlPanelHudTilt.ts';
import { dimRow, el, group, note, press, row, segments, slider, switchRow } from './controlPanelUi.ts';

const FONT_PRESETS: ReadonlyArray<{ value: string; label: string }> = [
  { value: '', label: '系统默认' },
  { value: 'Microsoft YaHei, PingFang SC, sans-serif', label: '微软雅黑' },
  { value: 'SimSun, Songti SC, serif', label: '宋体' },
  { value: 'SimHei, Heiti SC, sans-serif', label: '黑体' },
  { value: 'KaiTi, Kaiti SC, serif', label: '楷体' },
  { value: 'Inter, system-ui, sans-serif', label: 'Inter' },
  { value: 'Georgia, Times New Roman, serif', label: 'Georgia' },
];

const CUSTOM_FONT = '__custom__';
const CELL_SIZES: ReadonlyArray<{ value: CellSizeId; label: string }> = [
  { value: 'S', label: '小' },
  { value: 'M', label: '中' },
  { value: 'L', label: '大' },
];
const LIGHTING_MODES: ReadonlyArray<{ value: LightingMode; label: string }> = [
  { value: 'spotlight', label: '聚光灯' },
  { value: 'daytime', label: '白天' },
];
const TINT_GRADIENTS: ReadonlyArray<{ value: TintGradient; label: string }> = [
  { value: 'none', label: '纯色' },
  { value: 'diagonal', label: '斜向渐变' },
  { value: 'vertical', label: '竖向渐变' },
];

const option = (value: string, label: string): HTMLOptionElement => {
  const node = document.createElement('option');
  node.value = value;
  node.textContent = label;
  return node;
};

const presetOf = (font: string): string =>
  FONT_PRESETS.some((item) => item.value === font) ? font : CUSTOM_FONT;

type Toggle = 'immersive' | 'autoFocus' | 'fisheye' | 'pointer3d' | 'vignette' | 'lightsOut' | 'posterTint'
  | 'posterTintCustom' | 'showTitles' | 'showLyrics' | 'showTranslation';

/**
 * Lattice settings as titled groups. Rows that share a group with other modules (auto-focus next to
 * playback speed, immersive next to the desktop wall) are returned on their own.
 */
export function createControlPanelSettings(
  options: {
    titleLabel: string;
    lyrics: boolean;
    settings: LatticeSettings;
    onPatchSettings: (patch: Partial<LatticeSettings>) => void;
    signal: AbortSignal;
  },
) {
  const { signal } = options;
  let settings = options.settings;
  const patch = (next: Partial<LatticeSettings>): void => options.onPatchSettings(next);
  const switches = new Map<Toggle, HTMLButtonElement>();
  const toggle = (key: Toggle, item: { root: HTMLButtonElement }): HTMLButtonElement => {
    switches.set(key, item.root);
    item.root.addEventListener('click', () => patch({ [key]: !settings[key] }), { signal });
    return item.root;
  };

  // ---- playback ---------------------------------------------------------------------------------
  const autoFocus = toggle('autoFocus', switchRow({ label: '切歌自动聚焦', hint: '当前曲变化时，镜头飞到当前曲并展开' }));
  const showLyrics = toggle('showLyrics', switchRow({ label: '当前曲歌词', hint: '展开当前曲时显示逐字歌词' }));
  const showTranslation = toggle('showTranslation', switchRow({ label: '翻译行', hint: '在歌词下方显示翻译', sub: true }));
  const lyrics = group('歌词', [showLyrics, showTranslation], '只作用于曲库墙展开的当前曲。');
  lyrics.hidden = !options.lyrics;

  // ---- appearance -------------------------------------------------------------------------------
  const showTitles = toggle('showTitles', switchRow({ label: options.titleLabel, hint: '在封面上始终显示标题' }));
  const cells = segments('格子尺寸', CELL_SIZES);
  const cellRow = row({ label: '格子尺寸', hint: '封面的基础大小', controls: [cells.root] });
  const font = el('select');
  for (const item of FONT_PRESETS) font.append(option(item.value, item.label));
  font.append(option(CUSTOM_FONT, '自定义…'));
  const fontRow = row({ label: '界面字体', controls: [font] });
  const customFont = el('input');
  customFont.type = 'text';
  customFont.maxLength = 80;
  customFont.placeholder = '例如 Cascadia Code';
  customFont.spellcheck = false;
  const customFontRow = row({ label: '字体名称', hint: '回车或移开焦点后应用', sub: true, wide: true, controls: [customFont] });
  const wall = group('墙面', [showTitles, cellRow.root, fontRow.root, customFontRow.root]);

  const fisheye = toggle('fisheye', switchRow({ label: '鱼眼模式', hint: '墙面四周向屏幕内弯曲，营造镜头感' }));
  const pointer3d = toggle('pointer3d', switchRow({ label: 'HUD 悬浮视差', hint: '随指针悬浮倾斜，封面与文字分层移动' }));
  const hudTilt = createControlPanelHudTilt(options);
  const depth = group('立体效果', [fisheye, pointer3d, hudTilt.root], '两面墙共享，可叠加使用；拖动或悬停控件时保持稳定，减少动态效果时暂停视差。');

  // ---- lighting ---------------------------------------------------------------------------------
  const lighting = segments('灯光模式', LIGHTING_MODES);
  const lightingRow = row({ label: '灯光模式', hint: '', controls: [lighting.root] });
  // The mode gates the three effects below it, so they share one card.
  const vignette = toggle('vignette', switchRow({ label: '边缘暗角', hint: '压暗墙面四周', keyHint: 'V' }));
  const lightsOut = toggle('lightsOut', switchRow({ label: '关灯', hint: '调暗当前曲以外的封面', keyHint: 'L' }));
  const posterTint = toggle('posterTint', switchRow({ label: '非活动海报叠色', hint: '给当前曲以外的封面覆盖一层颜色', keyHint: 'T' }));
  const shadeNote = note();
  const light = group('灯光', [lightingRow.root, vignette, lightsOut, posterTint], shadeNote);

  const gradients = segments('叠色方式', TINT_GRADIENTS);
  const gradientRow = row({ label: '叠色方式', controls: [gradients.root] });
  const custom = toggle('posterTintCustom', switchRow({ label: '自定义颜色', hint: '关闭时叠色为纯黑' }));
  const color = el('input');
  color.type = 'color';
  const colorValue = el('span', 'control-panel__value control-panel__value--code');
  colorValue.setAttribute('aria-hidden', 'true');
  const colorRow = row({ label: '叠色颜色', sub: true, controls: [color, colorValue] });
  const intensity = slider({ min: 0, max: 1, step: 0.05, format: value => `${Math.round(value * 100)}%` });
  const intensityRow = row({ label: '叠色强度', wide: true, controls: [intensity.input, intensity.value] });
  const tintNote = note();
  const tint = group('叠色', [gradientRow.root, custom, colorRow.root, intensityRow.root], tintNote);

  // ---- general ----------------------------------------------------------------------------------
  const immersive = toggle('immersive', switchRow({ label: '打开时全屏沉浸', hint: '进入时最大化 ECHO 窗口并隐藏标题栏，Esc 退出' }));

  let customPending = false;
  let shadeTimer: ReturnType<typeof setTimeout> | undefined;

  const sync = (next: LatticeSettings): void => {
    settings = next;
    const locks = controlPanelSettingLocks(next);
    for (const [key, node] of switches) press(node, next[key]);
    hudTilt.sync(next);
    for (const [size, node] of cells.buttons) press(node, next.cellSize === size);
    for (const [mode, node] of lighting.buttons) press(node, next.lightingMode === mode);
    lightingRow.hint!.textContent = locks.spotlight
      ? '突出当前封面，周围封面带有光影层次'
      : '所有封面均匀照亮，光影效果暂停';

    for (const node of [vignette, lightsOut, posterTint]) {
      node.disabled = !locks.spotlight;
      dimRow(node, !locks.spotlight);
    }
    shadeNote.textContent = locks.spotlight
      ? '在墙面上按 V / L / T 也能快速切换。'
      : '白天模式下光影效果暂停；在墙面上按 V / L / T 会切回聚光灯。';

    for (const [gradient, node] of gradients.buttons) {
      press(node, next.posterTintGradient === gradient);
      node.disabled = !locks.tint;
    }
    custom.disabled = !locks.tint;
    color.disabled = !locks.customColor;
    intensity.input.disabled = !locks.tint;
    dimRow(gradientRow.root, !locks.tint);
    dimRow(custom, !locks.tint);
    dimRow(colorRow.root, !locks.customColor);
    dimRow(intensityRow.root, !locks.tint);
    tintNote.hidden = locks.tint;
    tintNote.textContent = locks.spotlight ? '开启「非活动海报叠色」后可调。' : '白天模式下叠色暂停。';
    if (color.value !== next.posterTintColor) color.value = next.posterTintColor;
    colorValue.textContent = next.posterTintColor.toUpperCase();
    const intensitySetting = String(next.posterTintIntensity);
    if (intensity.input.value !== intensitySetting) intensity.input.value = intensitySetting;
    intensity.render();

    const preset = customPending ? CUSTOM_FONT : presetOf(next.uiFont);
    font.value = preset;
    customFontRow.root.hidden = preset !== CUSTOM_FONT;
    if (preset === CUSTOM_FONT && document.activeElement !== customFont) customFont.value = FONT_PRESETS.some(item => item.value === next.uiFont) ? '' : next.uiFont;

    showTranslation.disabled = !next.showLyrics;
    dimRow(showTranslation, !next.showLyrics);
  };

  for (const [size, node] of cells.buttons) {
    node.addEventListener('click', () => {
      if (settings.cellSize !== size) patch({ cellSize: size });
    }, { signal });
  }
  for (const [mode, node] of lighting.buttons) {
    node.addEventListener('click', () => {
      if (settings.lightingMode !== mode) patch({ lightingMode: mode });
    }, { signal });
  }
  for (const [gradient, node] of gradients.buttons) {
    node.addEventListener('click', () => {
      if (settings.posterTintGradient !== gradient) patch({ posterTintGradient: gradient });
    }, { signal });
  }
  color.addEventListener('input', () => {
    const value = color.value.toLowerCase();
    if (!/^#[0-9a-f]{6}$/i.test(value)) return;
    colorValue.textContent = value.toUpperCase();
    patch({ posterTintColor: value });
  }, { signal });
  const commitIntensity = (): void => {
    const value = Number(intensity.input.value);
    if (!Number.isFinite(value)) return;
    patch({ posterTintIntensity: Math.min(1, Math.max(0, value)) });
  };
  intensity.input.addEventListener('input', () => {
    intensity.render();
    clearTimeout(shadeTimer);
    shadeTimer = setTimeout(commitIntensity, 80);
  }, { signal });
  intensity.input.addEventListener('change', () => {
    clearTimeout(shadeTimer);
    commitIntensity();
  }, { signal });
  font.addEventListener('change', () => {
    if (font.value === CUSTOM_FONT) {
      customPending = true;
      customFontRow.root.hidden = false;
      customFont.focus();
      return;
    }
    customPending = false;
    customFontRow.root.hidden = true;
    customFont.value = '';
    patch({ uiFont: font.value });
  }, { signal });
  customFont.addEventListener('change', () => {
    patch({ uiFont: sanitizeUiFont(customFont.value) });
  }, { signal });
  customFont.addEventListener('keydown', (event) => {
    if (event.key !== 'Enter' || event.isComposing || event.keyCode === 229) return;
    event.preventDefault();
    if (!event.repeat) patch({ uiFont: sanitizeUiFont(customFont.value) });
  }, { signal });
  signal.addEventListener('abort', () => clearTimeout(shadeTimer), { once: true });

  sync(settings);
  return {
    rows: { autoFocus, immersive },
    groups: { lyrics, wall, depth, light, tint },
    sync,
  };
}

import { DEFAULT_PANEL_SHORTCUT, shortcutFromEvent } from './host/controlPanelShortcut.ts';
import { button, keyChips, row } from './controlPanelUi.ts';

const HINT = '点击后按下新的组合键，Esc 取消';
const display = (value: string): string => value.split('+').join(' + ');

/** The recorder owns only temporary listeners in this sandbox document. */
export function createControlPanelShortcut(options: {
  value: string;
  onChange(value: string): void;
  signal: AbortSignal;
}) {
  const record = button('', { className: 'control-panel__shortcut-record' });
  // Named by `render()` with the current keys, so the row label must not take over.
  record.setAttribute('aria-label', '打开功能面板的快捷键');
  const reset = button('恢复默认', { icon: 'reset', className: 'control-panel__chip' });
  const shortcutRow = row({ label: '打开功能面板', hint: HINT, controls: [record, reset] });
  const hint = shortcutRow.hint!;
  hint.setAttribute('role', 'status');
  let value = options.value;
  let recorder: AbortController | null = null;
  const render = (): void => {
    if (recorder) record.replaceChildren('请按下快捷键…');
    else record.replaceChildren(...keyChips(value));
    record.setAttribute('aria-label', recorder ? '正在录入快捷键，按 Esc 取消' : `打开功能面板的快捷键：${display(value)}，点击修改`);
    record.setAttribute('aria-pressed', String(recorder !== null));
    reset.disabled = value === DEFAULT_PANEL_SHORTCUT;
  };
  const cancel = (): void => {
    recorder?.abort();
    recorder = null;
    hint.textContent = HINT;
    render();
  };
  record.addEventListener('click', () => {
    if (recorder) { cancel(); return; }
    recorder = new AbortController();
    document.addEventListener('keydown', event => {
      event.preventDefault();
      event.stopImmediatePropagation();
      if (event.isComposing || event.keyCode === 229 || event.repeat) return;
      if (event.key === 'Escape') { cancel(); return; }
      if (['Control', 'Alt', 'Shift', 'Meta'].includes(event.key)) return;
      const next = shortcutFromEvent(event);
      if (!next) {
        hint.textContent = '请使用 Ctrl / Alt / ⌘ 组合键或 F1–F24，避开关闭窗口的快捷键';
        return;
      }
      cancel();
      options.onChange(next);
      hint.textContent = `已设为 ${display(next)}`;
    }, { capture: true, signal: recorder.signal });
    hint.textContent = '请按下新的快捷键；Esc 或再次点击取消';
    render();
  }, { signal: options.signal });
  reset.addEventListener('click', () => { cancel(); options.onChange(DEFAULT_PANEL_SHORTCUT); }, { signal: options.signal });
  window.addEventListener('blur', cancel, { signal: options.signal });
  document.addEventListener('visibilitychange', () => { if (document.hidden) cancel(); }, { signal: options.signal });
  options.signal.addEventListener('abort', cancel, { once: true });
  cancel();
  return {
    root: shortcutRow.root, cancel,
    get recording() { return recorder !== null; },
    sync(next: string) { if (next !== value) { value = next; cancel(); } },
  };
}

import type { SpeedControl } from './host/api.ts';
import { button, row, slider } from './controlPanelUi.ts';

const clampRate = (rate: number): number => Math.max(0.5, Math.min(2, rate));
const HINT = '0.5× – 2×，松开滑杆后应用';

export const createControlPanelSpeed = (speed: SpeedControl) => {
  const rate = slider({ min: 0.5, max: 2, step: 0.05, format: value => `${value.toFixed(2)}×`, spoken: value => `${value.toFixed(2)} 倍` });
  const reset = button('1×', { className: 'control-panel__chip', label: '恢复 1 倍速' });
  const speedRow = row({ label: '播放速度', hint: HINT, wide: true, controls: [rate.input, rate.value, reset] });
  const render = (value: number): void => {
    rate.input.value = String(clampRate(value));
    rate.render();
    reset.disabled = rate.input.disabled || Number(rate.input.value) === 1;
  };
  const setEnabled = (on: boolean): void => {
    rate.input.disabled = !on;
    reset.disabled = !on || Number(rate.input.value) === 1;
  };
  render(1);

  let disposed = false;
  let busy = false;
  let dragging = false;
  let revision = 0;
  let off: (() => void) | null = null;
  const onInput = (): void => { rate.render(); };
  const commit = (): void => {
    dragging = false;
    if (busy) return;
    busy = true;
    setEnabled(false);
    const currentRevision = ++revision;
    void speed.set(Number(rate.input.value)).then((value) => {
      if (!disposed && revision === currentRevision) render(value);
    }).catch(() => {
      if (!disposed) void speed.get().then(value => {
        if (!disposed && revision === currentRevision) render(value);
      }).catch(() => undefined);
    }).finally(() => {
      if (!disposed) { busy = false; setEnabled(true); }
    });
  };
  const onReset = (): void => {
    if (busy || Number(rate.input.value) === 1) return;
    rate.input.value = '1';
    rate.render();
    commit();
  };
  rate.input.addEventListener('input', onInput);
  rate.input.addEventListener('change', commit);
  reset.addEventListener('click', onReset);
  const onPointerDown = (): void => { dragging = true; };
  const onPointerUp = (): void => { dragging = false; };
  rate.input.addEventListener('pointerdown', onPointerDown);
  rate.input.addEventListener('pointerup', onPointerUp);
  rate.input.addEventListener('pointercancel', onPointerUp);
  return {
    /** Setting row; the panel places it in a group. */
    root: speedRow.root,
    open: () => {
      if (disposed || off) return;
      off = speed.onChanged((value) => {
        if (!disposed && !busy && !dragging) render(value);
      });
      const requestRevision = revision;
      setEnabled(false);
      void speed.get().then((value) => {
        if (!disposed && off && !busy && !dragging && revision === requestRevision) {
          setEnabled(true); render(value);
          if (speedRow.hint) speedRow.hint.textContent = HINT;
        }
      }).catch(() => {
        if (!disposed && off && revision === requestRevision) {
          rate.value.textContent = '—';
          if (speedRow.hint) speedRow.hint.textContent = '当前 ECHO 暂不支持变速';
        }
      });
    },
    close: () => {
      off?.();
      off = null;
    },
    dispose: () => {
      disposed = true;
      off?.();
      off = null;
      rate.input.removeEventListener('input', onInput);
      rate.input.removeEventListener('change', commit);
      reset.removeEventListener('click', onReset);
      rate.input.removeEventListener('pointerdown', onPointerDown);
      rate.input.removeEventListener('pointerup', onPointerUp);
      rate.input.removeEventListener('pointercancel', onPointerUp);
    },
  };
};

export type ControlPanelCategory = 'browse' | 'playback' | 'appearance' | 'lighting' | 'general';
type Category = { id: ControlPanelCategory; label: string; description: string; sections: HTMLElement[] };

/** Same breakpoint as `65-control-panel.css`, where the sidebar becomes a top strip. */
const NARROW = '(max-width: 640px)';

/** Accessible local navigation: one mounted page is visible, with a single tab stop in the tablist. */
export function createControlPanelTabs(categories: Category[], signal: AbortSignal, onSelect: (id: ControlPanelCategory) => void) {
  const navigation = document.createElement('div');
  navigation.className = 'control-panel__tabs';
  navigation.setAttribute('role', 'tablist');
  navigation.setAttribute('aria-label', '功能分类');
  const narrow = window.matchMedia(NARROW);
  const orient = (): void => navigation.setAttribute('aria-orientation', narrow.matches ? 'horizontal' : 'vertical');
  orient();
  narrow.addEventListener('change', orient, { signal });
  const pages = document.createElement('div');
  pages.className = 'control-panel__pages';
  // Visual page title; the tabpanel is named by its tab and described by the description line.
  const heading = document.createElement('div');
  heading.className = 'control-panel__page-heading';
  const title = document.createElement('p');
  title.className = 'control-panel__page-title';
  title.setAttribute('aria-hidden', 'true');
  const description = document.createElement('p');
  description.className = 'control-panel__page-description';
  const prefix = `control-category-${crypto.randomUUID()}`;
  description.id = `${prefix}-description`;
  heading.append(title, description);
  const entries = categories.map((category, order) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.id = `${prefix}-${category.id}-tab`;
    button.className = 'control-panel__tab';
    button.setAttribute('role', 'tab');
    // Editorial index (01–05); visual only, the tab is named by its label.
    const index = document.createElement('span');
    index.className = 'control-panel__tab-index';
    index.setAttribute('aria-hidden', 'true');
    index.textContent = String(order + 1).padStart(2, '0');
    const label = document.createElement('span');
    label.textContent = category.label;
    button.append(index, label);
    const page = document.createElement('div');
    page.id = `${prefix}-${category.id}`;
    page.className = 'control-panel__page';
    page.dataset.category = category.id;
    page.setAttribute('role', 'tabpanel');
    page.setAttribute('aria-labelledby', button.id);
    page.setAttribute('aria-describedby', description.id);
    button.setAttribute('aria-controls', page.id);
    page.append(...category.sections);
    navigation.append(button);
    pages.append(page);
    return { ...category, button, page };
  });
  let selected: ControlPanelCategory = 'browse';
  const select = (id: ControlPanelCategory): void => {
    const next = entries.find(entry => entry.id === id);
    if (!next) return;
    if (entries.some(entry => entry.id !== id && entry.page.contains(document.activeElement))) next.button.focus();
    selected = id;
    for (const entry of entries) {
      const active = entry.id === id;
      entry.button.setAttribute('aria-selected', String(active));
      entry.button.tabIndex = active ? 0 : -1;
      entry.page.hidden = !active;
    }
    title.textContent = next.label;
    description.textContent = next.description;
    pages.scrollTop = 0;
    if (narrow.matches) next.button.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    onSelect(id);
  };
  for (const [index, entry] of entries.entries()) {
    entry.button.addEventListener('click', () => select(entry.id), { signal });
    entry.button.addEventListener('keydown', event => {
      if (event.altKey || event.ctrlKey || event.metaKey) return;
      // Vertical in the sidebar, horizontal on narrow windows: both arrow pairs move.
      const step = event.key === 'ArrowDown' || event.key === 'ArrowRight' ? 1
        : event.key === 'ArrowUp' || event.key === 'ArrowLeft' ? -1 : 0;
      let next: number;
      if (step !== 0) next = (index + step + entries.length) % entries.length;
      else if (event.key === 'Home') next = 0;
      else if (event.key === 'End') next = entries.length - 1;
      else return;
      event.preventDefault();
      entries[next]!.button.focus();
      select(entries[next]!.id);
    }, { signal });
  }
  select(selected);
  return { navigation, pages, heading, select, get selected() { return selected; } };
}

/** DOM builders shared by the function panel: titled groups, cards and setting rows. */

export const el = <K extends keyof HTMLElementTagNameMap>(
  tag: K,
  className?: string,
  text?: string,
): HTMLElementTagNameMap[K] => {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
};

let uid = 0;
export const nextId = (prefix: string): string => `control-panel-${prefix}-${++uid}`;

// No xmlns: the purity gate rejects URLs, and the HTML parser places inline <svg> in the SVG namespace.
const SVG_OPEN = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">';
const ICONS = {
  close: '<path d="M6.5 6.5l11 11M17.5 6.5l-11 11"/>',
  search: '<circle cx="11" cy="11" r="6"/><path d="m15.5 15.5 4 4"/>',
  previous: '<path d="m14.5 6-6 6 6 6"/>',
  next: '<path d="m9.5 6 6 6-6 6"/>',
  refresh: '<path d="M19 12a7 7 0 1 1-2.05-4.95"/><path d="M19 5v4h-4"/>',
  reset: '<path d="M5 12a7 7 0 1 0 2.05-4.95"/><path d="M5 5v4h4"/>',
} as const;
export type IconName = keyof typeof ICONS;

export const icon = (name: IconName, className = 'control-panel__icon'): HTMLSpanElement => {
  const node = el('span', className);
  node.setAttribute('aria-hidden', 'true');
  node.innerHTML = `${SVG_OPEN}${ICONS[name]}</svg>`;
  return node;
};

/** Plain button; icon-only buttons need an accessible `label`. */
export const button = (text: string, options: { icon?: IconName; label?: string; className?: string } = {}): HTMLButtonElement => {
  const node = el('button', options.className);
  node.type = 'button';
  if (options.icon) node.append(icon(options.icon));
  if (text) node.append(el('span', undefined, text));
  if (options.label) {
    node.setAttribute('aria-label', options.label);
    node.title = options.label;
  }
  return node;
};

export const press = (target: HTMLButtonElement, on: boolean): void => {
  target.setAttribute(target.getAttribute('role') === 'switch' ? 'aria-checked' : 'aria-pressed', String(on));
};

/** `Ctrl+Space` as key caps. */
export const keyChips = (shortcut: string): Node[] =>
  shortcut.split('+').flatMap((key, index) =>
    index === 0 ? [el('kbd', undefined, key)] : [document.createTextNode(' + '), el('kbd', undefined, key)]);

export type RowOptions = {
  label: string;
  hint?: string;
  /** Indented under the setting it depends on. */
  sub?: boolean;
  /** Wider control column for sliders and text fields. */
  wide?: boolean;
};

export type Row<T extends HTMLElement = HTMLElement> = { root: T; label: HTMLElement; hint: HTMLElement | null };

const itemClass = (base: string, options: RowOptions): string =>
  [base, options.sub ? 'control-panel__item--sub' : '', options.wide ? 'control-panel__item--wide' : '']
    .filter(Boolean).join(' ');

const rowText = (options: RowOptions, keyHint?: string) => {
  const text = el('span', 'control-panel__item-text');
  const label = el('span', 'control-panel__item-label');
  label.id = nextId('label');
  label.append(el('span', undefined, options.label));
  if (keyHint) {
    // The switch carries `aria-keyshortcuts`; the key cap is visual only.
    const key = el('kbd', 'control-panel__key', keyHint);
    key.setAttribute('aria-hidden', 'true');
    label.append(key);
  }
  text.append(label);
  let hint: HTMLElement | null = null;
  if (options.hint !== undefined) {
    hint = el('span', 'control-panel__item-hint', options.hint);
    hint.id = nextId('hint');
    text.append(hint);
  }
  return { text, label, hint };
};

const describe = (node: HTMLElement, label: HTMLElement, hint: HTMLElement | null): void => {
  if (!node.hasAttribute('aria-label')) node.setAttribute('aria-labelledby', label.id);
  if (hint && !node.hasAttribute('aria-describedby')) node.setAttribute('aria-describedby', hint.id);
};

/** Label and hint on the left, controls on the right. The first control is named by the row label unless it has its own. */
export function row(options: RowOptions & { controls: HTMLElement[] }): Row {
  const root = el('div', itemClass('control-panel__item', options));
  const { text, label, hint } = rowText(options);
  const control = el('div', 'control-panel__item-control');
  control.append(...options.controls);
  if (options.controls[0]) describe(options.controls[0], label, hint);
  root.append(text, control);
  return { root, label, hint };
}

/** Whole-row switch: label, hint and track form one large target. */
export function switchRow(options: RowOptions & { keyHint?: string }): Row<HTMLButtonElement> {
  const root = el('button', itemClass('control-panel__item control-panel__toggle', options));
  root.type = 'button';
  root.setAttribute('role', 'switch');
  root.setAttribute('aria-checked', 'false');
  if (options.keyHint) root.setAttribute('aria-keyshortcuts', options.keyHint);
  const { text, label, hint } = rowText(options, options.keyHint);
  const track = el('span', 'control-panel__switch');
  track.setAttribute('aria-hidden', 'true');
  root.append(text, track);
  describe(root, label, hint);
  return { root, label, hint };
}

/** One-of-n choice as a group of pressed buttons. */
export function segments<T extends string>(
  label: string,
  items: ReadonlyArray<{ value: T; label: string }>,
  className?: string,
): { root: HTMLElement; buttons: Map<T, HTMLButtonElement> } {
  const root = el('div', className ? `control-panel__segments ${className}` : 'control-panel__segments');
  root.setAttribute('role', 'group');
  root.setAttribute('aria-label', label);
  const buttons = new Map<T, HTMLButtonElement>();
  for (const item of items) {
    const node = button(item.label);
    node.dataset.value = item.value;
    buttons.set(item.value, node);
    root.append(node);
  }
  return { root, buttons };
}

/** Range input with a live value label; `format` also feeds `aria-valuetext`. */
export function slider(options: {
  min: number;
  max: number;
  step: number;
  format(value: number): string;
  spoken?(value: number): string;
}): { input: HTMLInputElement; value: HTMLElement; render(): void } {
  const input = el('input');
  input.type = 'range';
  input.min = String(options.min);
  input.max = String(options.max);
  input.step = String(options.step);
  const value = el('output', 'control-panel__value');
  value.setAttribute('aria-hidden', 'true');
  const render = (): void => {
    const current = Number(input.value);
    value.textContent = options.format(current);
    input.setAttribute('aria-valuetext', (options.spoken ?? options.format)(current));
    // Filled part of the track; see `.control-panel input[type="range"]`.
    const span = options.max - options.min;
    input.style.setProperty('--fill', `${span > 0 ? ((current - options.min) / span) * 100 : 0}%`);
  };
  return { input, value, render };
}

/** Dims a row's text; its controls are disabled by the caller. */
export const dimRow = (root: HTMLElement, off: boolean): void => {
  root.classList.toggle('is-disabled', off);
};

/** Titled group: rows share one card, with an optional note below. */
export function group(title: string, rows: HTMLElement[], note?: string | HTMLElement): HTMLElement {
  const root = el('section', 'control-panel__group');
  const heading = el('h3', 'control-panel__group-title', title);
  heading.id = nextId('group');
  root.setAttribute('aria-labelledby', heading.id);
  const card = el('div', 'control-panel__card');
  card.append(...rows);
  root.append(heading, card);
  if (note !== undefined) root.append(typeof note === 'string' ? el('p', 'control-panel__note', note) : note);
  return root;
}

/** Note element for `group`, updated by its owner. */
export const note = (text = ''): HTMLParagraphElement => el('p', 'control-panel__note', text);

