import { startLatticeLibraryWall } from './main.ts';
import { createPluginWallApi } from './host/pluginApi.ts';

void startLatticeLibraryWall(createPluginWallApi(echo));

/**
 * Card shape rules shared by the offline layout solver (`scripts/generate-reflows.mjs`) and the
 * runtime. No generated data is imported here, so the solver can run before any layout exists.
 */

import { BLOCK_COLS, BLOCK_ROWS } from '../types.ts';

export type TemplateRect = { col: number; row: number; w: number; h: number };

/** Card sizes (w × h, grid cells) a template or reflow layout may use. */
export const ALLOWED_SIZES: ReadonlyArray<readonly [w: number, h: number]> = [
  [2, 2],
  [2, 3],
  [3, 2],
  [2, 4],
  [4, 2],
  [3, 4],
  [4, 3],
  [4, 4],
  [6, 3],
  [3, 6],
  [6, 4],
  [4, 6],
];

export function isAllowedSize(w: number, h: number): boolean {
  for (const size of ALLOWED_SIZES) {
    if (size[0] === w && size[1] === h) return true;
  }
  return false;
}

/** True when `rects` tile the `cols × rows` area with no gap and no overlap. */
export function isExactCover(rects: ReadonlyArray<TemplateRect>, cols = BLOCK_COLS, rows = BLOCK_ROWS): boolean {
  const covered = new Uint8Array(cols * rows);
  let filled = 0;
  for (const { col, row, w, h } of rects) {
    if (!Number.isInteger(col) || !Number.isInteger(row) || !Number.isInteger(w) || !Number.isInteger(h)) return false;
    if (w < 1 || h < 1 || col < 0 || row < 0 || col + w > cols || row + h > rows) return false;
    for (let r = row; r < row + h; r++) {
      for (let c = col; c < col + w; c++) {
        const index = r * cols + c;
        if (covered[index] === 1) return false;
        covered[index] = 1;
        filled++;
      }
    }
  }
  return filled === cols * rows;
}

/**
 * Block templates and expansion reflows (SPEC §5), searched offline by `scripts/generate-reflows.mjs`
 * on the whole BLOCK_COLS × BLOCK_ROWS block rather than hand-drawn in a 12×8 box.
 *
 * Each template lists its SLOTS_PER_BLOCK rects in reading order (row-major by top-left corner) so
 * consecutive queue items flow left-to-right, top-to-bottom. Mirroring multiplies the templates into
 * TEMPLATE_COUNT × 4 looks. A reflow is stored as the rects that change when one slot grows to
 * EXPANDED_SIZE × EXPANDED_SIZE; every other card keeps its template rect.
 */

import { BLOCK_COLS, BLOCK_ROWS, EXPANDED_SIZE, SLOTS_PER_BLOCK, TEMPLATE_COUNT, type Mirror } from '../types.ts';
import { type TemplateRect } from './blockShapes.ts';
import layouts from './blockLayouts.json' with { type: 'json' };

export { ALLOWED_SIZES, isAllowedSize, isExactCover, type TemplateRect } from './blockShapes.ts';

const VALUES_PER_RECT = 4;
const VALUES_PER_DELTA = 5;

if (layouts.block[0] !== BLOCK_COLS || layouts.block[1] !== BLOCK_ROWS
  || layouts.slots !== SLOTS_PER_BLOCK || layouts.expanded !== EXPANDED_SIZE) {
  throw new Error('blockLayouts.json was generated for a different block geometry; run `npm run reflows`');
}
if (layouts.templates.length !== TEMPLATE_COUNT || layouts.reflows.length !== TEMPLATE_COUNT) {
  throw new Error(`blockLayouts.json must define ${TEMPLATE_COUNT} templates and reflow tables`);
}

function readTemplate(values: readonly number[], index: number): TemplateRect[] {
  if (values.length !== SLOTS_PER_BLOCK * VALUES_PER_RECT) {
    throw new Error(`Block template ${index} must define ${SLOTS_PER_BLOCK} slots`);
  }
  const rects: TemplateRect[] = [];
  for (let o = 0; o < values.length; o += VALUES_PER_RECT) {
    rects.push({ col: values[o]!, row: values[o + 1]!, w: values[o + 2]!, h: values[o + 3]! });
  }
  return rects;
}

export const BLOCK_TEMPLATES: ReadonlyArray<ReadonlyArray<TemplateRect>> = layouts.templates.map(readTemplate);

/** Block-local layout of template `template` with `slot` expanded: the template plus the stored delta. */
export function reflowRects(template: number, slot: number): TemplateRect[] {
  const base = BLOCK_TEMPLATES[template];
  const delta = layouts.reflows[template]?.[slot];
  if (base === undefined || delta === undefined || delta.length % VALUES_PER_DELTA !== 0) {
    throw new Error(`blockLayouts.json has no reflow for template ${template} slot ${slot}`);
  }
  const rects = base.map((rect) => ({ ...rect }));
  for (let o = 0; o < delta.length; o += VALUES_PER_DELTA) {
    const index = delta[o]!;
    if (!Number.isInteger(index) || index < 0 || index >= SLOTS_PER_BLOCK) {
      throw new Error(`blockLayouts.json has a malformed reflow for template ${template} slot ${slot}`);
    }
    rects[index] = { col: delta[o + 1]!, row: delta[o + 2]!, w: delta[o + 3]!, h: delta[o + 4]! };
  }
  return rects;
}

/** Reflect a block-local rect inside the block; the slot order of a layout is unaffected. */
export function mirrorRect(rect: TemplateRect, mirror: Mirror): TemplateRect {
  return {
    col: (mirror & 1) !== 0 ? BLOCK_COLS - rect.col - rect.w : rect.col,
    row: (mirror & 2) !== 0 ? BLOCK_ROWS - rect.row - rect.h : rect.row,
    w: rect.w,
    h: rect.h,
  };
}

function mod(value: number, modulus: number): number {
  const remainder = value % modulus;
  return remainder < 0 ? remainder + modulus : remainder;
}

/**
 * Template for a world block. `(bc + 2·br) mod 5` differs from all eight neighbours, since the
 * differences ±1, ±2, ±3 are never 0 modulo 5.
 */
export function templateIndexFor(bc: number, br: number): number {
  return mod(bc + 2 * br, TEMPLATE_COUNT);
}

/**
 * Mirror for a world block: a 32-bit multiply–xorshift mix of the two coordinates. Each input is
 * scaled by its own odd constant, then two rounds of xorshift-multiply spread every input bit into
 * the top bits, which select the mirror (the top bits are the best mixed).
 */
export function mirrorFor(bc: number, br: number): Mirror {
  let h = Math.imul(bc | 0, 0x27d4eb2f) ^ Math.imul(br | 0, 0x165667b1) ^ 0x3c6ef372;
  h ^= h >>> 16;
  h = Math.imul(h, 0x7feb352d);
  h ^= h >>> 15;
  h = Math.imul(h, 0x846ca68b);
  h ^= h >>> 16;
  return (h >>> 30) as Mirror;
}

/**
 * Pure geometry of the infinite wall (SPEC §5): a periodic cell of blocks, a hashed template + mirror
 * per world block, the pre-solved reflow for the block hosting the expanded card, culling, nearest
 * occurrence and keyboard neighbour search. No DOM, no host, no growing state.
 */

import {
  BLOCK_COLS,
  BLOCK_ROWS,
  EXPANDED_SIZE,
  SLOTS_PER_BLOCK,
  TEMPLATE_COUNT,
  type Direction,
  type GridRect,
  type Instance,
  type Lattice,
  type Metrics,
  type Mirror,
  type PixelRect,
  type Point,
} from '../types.ts';
import { BLOCK_TEMPLATES, mirrorFor, mirrorRect, reflowRects, templateIndexFor, type TemplateRect } from './blockTemplates.ts';

const MIRROR_COUNT = 4;
const VALUES_PER_RECT = 4;
const LAYOUT_STRIDE = SLOTS_PER_BLOCK * VALUES_PER_RECT;
const TEMPLATE_LAYOUT_COUNT = TEMPLATE_COUNT * MIRROR_COUNT;
const REFLOW_LAYOUT_COUNT = TEMPLATE_COUNT * SLOTS_PER_BLOCK * MIRROR_COUNT;
const DEFAULT_CULL_LIMIT = 250;
const ID_PATTERN = /^(0|[1-9]\d*):(0|-?[1-9]\d*):(0|-?[1-9]\d*)$/;

function templateLayoutOffset(template: number, mirror: Mirror): number {
  return (template * MIRROR_COUNT + mirror) * LAYOUT_STRIDE;
}

function reflowLayoutOffset(template: number, expandedSlot: number, mirror: Mirror): number {
  return (TEMPLATE_LAYOUT_COUNT + (template * SLOTS_PER_BLOCK + expandedSlot) * MIRROR_COUNT + mirror) * LAYOUT_STRIDE;
}

function writeLayout(out: Uint8Array, offset: number, rects: ReadonlyArray<TemplateRect>, mirror: Mirror): void {
  rects.forEach((rect, slot) => {
    const mirrored = mirrorRect(rect, mirror);
    const o = offset + slot * VALUES_PER_RECT;
    out[o] = mirrored.col;
    out[o + 1] = mirrored.row;
    out[o + 2] = mirrored.w;
    out[o + 3] = mirrored.h;
  });
}

/**
 * Every block-local layout the wall can show, flattened to `[col, row, w, h]` per slot: the
 * template × mirror variants first, then the reflow × mirror variants. Mirroring a reflow table
 * is valid because reflection preserves both exact cover and slot order.
 */
function buildLayouts(): Uint8Array {
  const out = new Uint8Array((TEMPLATE_LAYOUT_COUNT + REFLOW_LAYOUT_COUNT) * LAYOUT_STRIDE);
  for (let t = 0; t < TEMPLATE_COUNT; t++) {
    const template = BLOCK_TEMPLATES[t];
    if (template === undefined) throw new Error(`Missing block template ${t}`);
    for (let m = 0; m < MIRROR_COUNT; m++) {
      writeLayout(out, templateLayoutOffset(t, m as Mirror), template, m as Mirror);
    }
    for (let s = 0; s < SLOTS_PER_BLOCK; s++) {
      const table = reflowRects(t, s);
      for (let m = 0; m < MIRROR_COUNT; m++) {
        writeLayout(out, reflowLayoutOffset(t, s, m as Mirror), table, m as Mirror);
      }
    }
  }
  return out;
}

const LAYOUTS = buildLayouts();

function layoutValue(index: number): number {
  return LAYOUTS[index] ?? 0;
}

function mod(value: number, modulus: number): number {
  const remainder = value % modulus;
  return remainder < 0 ? remainder + modulus : remainder || 0;
}

function layoutOffsetFor(bc: number, br: number, expanded: Instance | null): number {
  const template = templateIndexFor(bc, br);
  const mirror = mirrorFor(bc, br);
  return expanded !== null && expanded.bc === bc && expanded.br === br
    ? reflowLayoutOffset(template, expanded.slot, mirror)
    : templateLayoutOffset(template, mirror);
}

/** Periodic cell size and origin-cell slot centres / rects for `tileCount` / `metrics`. */
export type LatticeSlotPlan = {
  tileCount: number;
  cellCols: number;
  cellRows: number;
  blocksPerCell: number;
  cellSlotCount: number;
  gridCols: number;
  gridRows: number;
  unit: number;
  cellPixelSize: { w: number; h: number };
  centers: Point[];
  /** Origin-cell grid rects, in the same order as `centers` (cellSlot 0..cellSlotCount-1). */
  rects: GridRect[];
};

/**
 * Geometry of one periodic cell, including the centre of every origin-cell slot. The queue wall
 * uses the centres to spread identical covers before `createLattice` binds the mapping.
 */
export function planLatticeSlots(tileCount: number, metrics: Metrics): LatticeSlotPlan {
  if (!Number.isInteger(tileCount) || tileCount < 1) {
    throw new RangeError(`tileCount must be a positive integer, got ${tileCount}`);
  }
  const { cell, gap } = metrics;
  if (!Number.isFinite(cell) || cell <= 0 || !Number.isFinite(gap) || gap < 0) {
    throw new RangeError(`metrics must satisfy cell > 0 and gap >= 0, got cell=${cell} gap=${gap}`);
  }

  const blocksNeeded = Math.ceil(tileCount / SLOTS_PER_BLOCK);
  // Blocks are wider than they are tall. Balance physical dimensions and avoid excess copies. Neighbouring
  // world blocks use different templates, so a cell at least 2 × 2 blocks keeps a tile's next copy a
  // whole block away instead of possibly beside it.
  const cellCols = Math.max(2, Math.round(Math.sqrt(blocksNeeded * BLOCK_ROWS / BLOCK_COLS)));
  const cellRows = Math.max(2, Math.ceil(blocksNeeded / cellCols));
  const blocksPerCell = cellCols * cellRows;
  const cellSlotCount = blocksPerCell * SLOTS_PER_BLOCK;
  const gridCols = cellCols * BLOCK_COLS;
  const gridRows = cellRows * BLOCK_ROWS;
  const unit = cell + gap;
  const cellPixelSize = {
    w: gridCols * unit,
    h: gridRows * unit,
  };
  const centers: Point[] = [];
  const rects: GridRect[] = [];
  for (let br = 0; br < cellRows; br++) {
    for (let bc = 0; bc < cellCols; bc++) {
      const offset = layoutOffsetFor(bc, br, null);
      for (let slot = 0; slot < SLOTS_PER_BLOCK; slot++) {
        const o = offset + slot * VALUES_PER_RECT;
        const rect = {
          col: bc * BLOCK_COLS + layoutValue(o),
          row: br * BLOCK_ROWS + layoutValue(o + 1),
          w: layoutValue(o + 2),
          h: layoutValue(o + 3),
        };
        rects.push(rect);
        centers.push({
          x: (rect.col + rect.w / 2) * unit - gap / 2,
          y: (rect.row + rect.h / 2) * unit - gap / 2,
        });
      }
    }
  }
  return {
    tileCount,
    cellCols,
    cellRows,
    blocksPerCell,
    cellSlotCount,
    gridCols,
    gridRows,
    unit,
    cellPixelSize,
    centers,
    rects,
  };
}

function resolveSlotToTile(
  tileCount: number,
  cellSlotCount: number,
  given: readonly number[] | undefined,
): { slotToTile: Int32Array; tileSlots: number[][] } {
  const slotToTile = new Int32Array(cellSlotCount);
  if (given === undefined) {
    for (let i = 0; i < cellSlotCount; i++) slotToTile[i] = i % tileCount;
  } else {
    if (given.length !== cellSlotCount) {
      throw new RangeError(`slotToTile length must be ${cellSlotCount}, got ${given.length}`);
    }
    const seen = new Uint8Array(tileCount);
    for (let i = 0; i < cellSlotCount; i++) {
      const tile = given[i];
      if (tile === undefined || !Number.isInteger(tile) || tile < 0 || tile >= tileCount) {
        throw new RangeError(`slotToTile[${i}] must be in 0..${tileCount - 1}, got ${tile}`);
      }
      slotToTile[i] = tile;
      seen[tile] = 1;
    }
    for (let t = 0; t < tileCount; t++) {
      if (seen[t] === 0) throw new RangeError(`slotToTile is missing tile ${t}`);
    }
  }
  const tileSlots: number[][] = Array.from({ length: tileCount }, () => []);
  for (let i = 0; i < cellSlotCount; i++) {
    const mapped = slotToTile[i];
    if (mapped !== undefined) tileSlots[mapped]?.push(i);
  }
  return { slotToTile, tileSlots };
}

export function createLattice(tileCount: number, metrics: Metrics, slotToTile?: readonly number[]): Lattice {
  const plan = planLatticeSlots(tileCount, metrics);
  const { cell, gap } = metrics;
  const { cellCols, cellRows, blocksPerCell, cellSlotCount, unit, cellPixelSize } = plan;
  const { slotToTile: tileAtSlot, tileSlots } = resolveSlotToTile(tileCount, cellSlotCount, slotToTile);

  // The cell is a full rectangle of blocks so the plane tiles without holes; leftover slots
  // show extra copies assigned by `slotToTile` (identity: `cellSlot % tileCount`).
  const blockPixelWidth = BLOCK_COLS * unit;
  const blockPixelHeight = BLOCK_ROWS * unit;
  const cellPixelWidth = cellPixelSize.w;
  const cellPixelHeight = cellPixelSize.h;

  const layoutOffset = layoutOffsetFor;

  const makeInstance = (bc: number, br: number, slot: number, offset: number): Instance => {
    const o = offset + slot * VALUES_PER_RECT;
    const blockInCell = mod(bc, cellCols) + mod(br, cellRows) * cellCols;
    const repeatX = Math.floor(bc / cellCols);
    const repeatY = Math.floor(br / cellRows);
    const cellSlot = blockInCell * SLOTS_PER_BLOCK + slot;
    return {
      id: `${cellSlot}:${repeatX}:${repeatY}`,
      cellSlot,
      blockInCell,
      slot,
      repeatX,
      repeatY,
      bc,
      br,
      tileIndex: tileAtSlot[cellSlot] ?? 0,
      rect: {
        col: bc * BLOCK_COLS + layoutValue(o),
        row: br * BLOCK_ROWS + layoutValue(o + 1),
        w: layoutValue(o + 2),
        h: layoutValue(o + 3),
      },
    };
  };

  /** Grid-unit centre column of a slot in a laid-out block (pixel centre = value·unit − gap/2). */
  const centreCol = (bc: number, o: number): number => bc * BLOCK_COLS + layoutValue(o) + layoutValue(o + 2) / 2;
  const centreRow = (br: number, o: number): number => br * BLOCK_ROWS + layoutValue(o + 1) + layoutValue(o + 3) / 2;

  const toPixels = (rect: GridRect): PixelRect => ({
    x: rect.col * unit,
    y: rect.row * unit,
    w: rect.w * cell + (rect.w - 1) * gap,
    h: rect.h * cell + (rect.h - 1) * gap,
  });

  const centerOf = (rect: GridRect): Point => ({
    x: (rect.col + rect.w / 2) * unit - gap / 2,
    y: (rect.row + rect.h / 2) * unit - gap / 2,
  });

  const instanceAt = (bc: number, br: number, slot: number, expanded: Instance | null): Instance =>
    makeInstance(bc, br, slot, layoutOffset(bc, br, expanded));

  const blockInstances = (bc: number, br: number, expanded: Instance | null): Instance[] => {
    const offset = layoutOffset(bc, br, expanded);
    const instances: Instance[] = [];
    for (let slot = 0; slot < SLOTS_PER_BLOCK; slot++) instances.push(makeInstance(bc, br, slot, offset));
    return instances;
  };

  const cull = (bounds: PixelRect, overscan: number, expanded: Instance | null, limit = DEFAULT_CULL_LIMIT): Instance[] => {
    const x0 = bounds.x - overscan;
    const y0 = bounds.y - overscan;
    const x1 = bounds.x + bounds.w + overscan;
    const y1 = bounds.y + bounds.h + overscan;
    const centreX = (x0 + x1) / 2;
    const centreY = (y0 + y1) / 2;
    const bcMin = Math.floor(x0 / blockPixelWidth);
    const bcMax = Math.floor(x1 / blockPixelWidth);
    const brMin = Math.floor(y0 / blockPixelHeight);
    const brMax = Math.floor(y1 / blockPixelHeight);

    const hits: { distance: number; instance: Instance }[] = [];
    for (let br = brMin; br <= brMax; br++) {
      for (let bc = bcMin; bc <= bcMax; bc++) {
        const offset = layoutOffset(bc, br, expanded);
        const originX = bc * blockPixelWidth;
        const originY = br * blockPixelHeight;
        for (let slot = 0; slot < SLOTS_PER_BLOCK; slot++) {
          const o = offset + slot * VALUES_PER_RECT;
          const x = originX + layoutValue(o) * unit;
          const y = originY + layoutValue(o + 1) * unit;
          const w = layoutValue(o + 2) * unit - gap;
          const h = layoutValue(o + 3) * unit - gap;
          if (x >= x1 || x + w <= x0 || y >= y1 || y + h <= y0) continue;
          const dx = x + w / 2 - centreX;
          const dy = y + h / 2 - centreY;
          hits.push({ distance: dx * dx + dy * dy, instance: makeInstance(bc, br, slot, offset) });
        }
      }
    }
    hits.sort((a, b) => a.distance - b.distance);
    return hits.slice(0, limit).map((hit) => hit.instance);
  };

  const nearestInstance = (tileIndex: number, point: Point, expanded: Instance | null): Instance => {
    if (!Number.isInteger(tileIndex) || tileIndex < 0 || tileIndex >= tileCount) {
      throw new RangeError(`tileIndex must be in 0..${tileCount - 1}, got ${tileIndex}`);
    }
    let bestDistance = Infinity;
    let bestBc = 0;
    let bestBr = 0;
    let bestSlot = 0;
    let bestOffset = 0;
    const occurrences = tileSlots[tileIndex];
    if (occurrences === undefined || occurrences.length === 0) {
      throw new RangeError(`tileIndex ${tileIndex} has no slot in the periodic cell`);
    }
    for (const cellSlot of occurrences) {
      const slot = cellSlot % SLOTS_PER_BLOCK;
      const blockInCell = (cellSlot - slot) / SLOTS_PER_BLOCK;
      const cx = blockInCell % cellCols;
      const cy = (blockInCell - cx) / cellCols;
      // The card centre lies within half a block of the block centre and a cell is at least one
      // block in each direction, so the nearest repeat is within ±1 of the block-centre estimate.
      const rx0 = Math.round((point.x - (cx + 0.5) * blockPixelWidth) / cellPixelWidth);
      const ry0 = Math.round((point.y - (cy + 0.5) * blockPixelHeight) / cellPixelHeight);
      for (let ry = ry0 - 1; ry <= ry0 + 1; ry++) {
        for (let rx = rx0 - 1; rx <= rx0 + 1; rx++) {
          const bc = rx * cellCols + cx;
          const br = ry * cellRows + cy;
          const offset = layoutOffset(bc, br, expanded);
          const o = offset + slot * VALUES_PER_RECT;
          const dx = centreCol(bc, o) * unit - gap / 2 - point.x;
          const dy = centreRow(br, o) * unit - gap / 2 - point.y;
          const distance = dx * dx + dy * dy;
          if (distance < bestDistance) {
            bestDistance = distance;
            bestBc = bc;
            bestBr = br;
            bestSlot = slot;
            bestOffset = offset;
          }
        }
      }
    }
    return makeInstance(bestBc, bestBr, bestSlot, bestOffset);
  };

  const fromId = (id: string, expanded: Instance | null): Instance | null => {
    const match = ID_PATTERN.exec(id);
    if (match === null) return null;
    const cellSlot = Number(match[1]);
    const repeatX = Number(match[2]);
    const repeatY = Number(match[3]);
    if (!Number.isSafeInteger(cellSlot) || !Number.isSafeInteger(repeatX) || !Number.isSafeInteger(repeatY)) return null;
    if (cellSlot >= blocksPerCell * SLOTS_PER_BLOCK) return null;
    const slot = cellSlot % SLOTS_PER_BLOCK;
    const blockInCell = (cellSlot - slot) / SLOTS_PER_BLOCK;
    const bc = repeatX * cellCols + (blockInCell % cellCols);
    const br = repeatY * cellRows + Math.floor(blockInCell / cellCols);
    return instanceAt(bc, br, slot, expanded);
  };

  const neighbor = (from: Instance, direction: Direction, expanded: Instance | null): Instance => {
    const fromOffset = layoutOffset(from.bc, from.br, expanded) + from.slot * VALUES_PER_RECT;
    const fromX = centreCol(from.bc, fromOffset);
    const fromY = centreRow(from.br, fromOffset);
    const horizontal = direction === 'left' || direction === 'right';
    const sign = direction === 'right' || direction === 'down' ? 1 : -1;

    let bestScore = Infinity;
    let bestBc = 0;
    let bestBr = 0;
    let bestSlot = 0;
    let bestOffset = 0;
    for (let br = from.br - 1; br <= from.br + 1; br++) {
      for (let bc = from.bc - 1; bc <= from.bc + 1; bc++) {
        const offset = layoutOffset(bc, br, expanded);
        for (let slot = 0; slot < SLOTS_PER_BLOCK; slot++) {
          if (bc === from.bc && br === from.br && slot === from.slot) continue;
          const o = offset + slot * VALUES_PER_RECT;
          const dx = centreCol(bc, o) - fromX;
          const dy = centreRow(br, o) - fromY;
          const along = (horizontal ? dx : dy) * sign;
          if (along <= 1e-6) continue;
          const score = along + 2.5 * Math.abs(horizontal ? dy : dx);
          if (score < bestScore) {
            bestScore = score;
            bestBc = bc;
            bestBr = br;
            bestSlot = slot;
            bestOffset = offset;
          }
        }
      }
    }
    if (bestScore === Infinity) {
      const bc = horizontal ? from.bc + sign : from.bc;
      const br = horizontal ? from.br : from.br + sign;
      return instanceAt(bc, br, from.slot, expanded);
    }
    return makeInstance(bestBc, bestBr, bestSlot, bestOffset);
  };

  const sameBlock = (a: Instance, b: Instance): boolean => a.bc === b.bc && a.br === b.br;

  return {
    tileCount,
    metrics: { cell, gap },
    blocksPerCell,
    cellCols,
    cellRows,
    cellPixelSize: { w: cellPixelWidth, h: cellPixelHeight },
    unit,
    toPixels,
    centerOf,
    blockInstances,
    instanceAt,
    cull,
    nearestInstance,
    fromId,
    neighbor,
    sameBlock,
  };
}

import type { GridRect } from '../types.ts';
import type { LatticeSlotPlan } from './lattice.ts';

const COVER_GAP = 4;
const REPAIR_PASSES = 4;

/** Distance between card edges, including the seam where the wall repeats. */
export function slotGap2(a: GridRect, b: GridRect, cols: number, rows: number): number {
  const dx = Math.abs(a.col + a.w / 2 - b.col - b.w / 2);
  const dy = Math.abs(a.row + a.h / 2 - b.row - b.h / 2);
  const gapX = Math.max(0, Math.min(dx, cols - dx) - (a.w + b.w) / 2);
  const gapY = Math.max(0, Math.min(dy, rows - dy) - (a.h + b.h) / 2);
  return gapX * gapX + gapY * gapY;
}

/**
 * Improve crowded pairs without adding/removing copies or moving a pinned card. Exact tile copies
 * need much more separation than different songs sharing artwork. All scratch data is page-local;
 * no pair table is retained by the lattice or consulted while dragging/playing.
 */
export function repairSlotSpacing(assigned: number[], keys: readonly string[], plan: LatticeSlotPlan, lockedSlot = -1): void {
  const count = assigned.length;
  const duplicateGap = Math.max(COVER_GAP, Math.min(plan.gridCols, plan.gridRows) * .45);
  const coverPenalty = new Float32Array(count * count);
  const duplicatePenalty = new Float32Array(count * count);
  for (let a = 0; a < count; a++) {
    for (let b = a + 1; b < count; b++) {
      const gap = Math.sqrt(slotGap2(plan.rects[a]!, plan.rects[b]!, plan.gridCols, plan.gridRows));
      const cover = Math.max(0, 1 - gap / COVER_GAP) ** 2;
      const duplicate = 16 * Math.max(0, 1 - gap / duplicateGap) ** 2;
      coverPenalty[a * count + b] = coverPenalty[b * count + a] = cover;
      duplicatePenalty[a * count + b] = duplicatePenalty[b * count + a] = duplicate;
    }
  }
  const groups = new Map<string, Set<number>>();
  for (let slot = 0; slot < count; slot++) {
    const key = keys[assigned[slot]!]!;
    let group = groups.get(key);
    if (!group) { group = new Set(); groups.set(key, group); }
    group.add(slot);
  }

  function cost(slot: number, tile: number, except = -1): number {
    const group = groups.get(keys[tile]!);
    if (!group) return 0;
    let sum = 0;
    for (const other of group) {
      if (other === slot || other === except) continue;
      const offset = slot * count + other;
      if (assigned[other] === tile) sum += duplicatePenalty[offset]!;
      // With only one artwork every cover pair is unavoidable; optimize exact copies only.
      else if (groups.size > 1) sum += coverPenalty[offset]!;
    }
    return sum;
  }

  for (let pass = 0; pass < REPAIR_PASSES; pass++) {
    let moved = false;
    for (let slot = 0; slot < count; slot++) {
      if (slot === lockedSlot || cost(slot, assigned[slot]!) === 0) continue;
      const tile = assigned[slot]!;
      let best = -1;
      let bestGain = 1e-6;
      for (let candidate = 0; candidate < count; candidate++) {
        const otherTile = assigned[candidate]!;
        if (candidate === slot || candidate === lockedSlot || otherTile === tile) continue;
        const before = cost(slot, tile, candidate) + cost(candidate, otherTile, slot);
        const after = cost(slot, otherTile, candidate) + cost(candidate, tile, slot);
        const gain = before - after;
        if (gain > bestGain) { bestGain = gain; best = candidate; }
      }
      if (best < 0) continue;
      const otherTile = assigned[best]!;
      const group = groups.get(keys[tile]!)!;
      const otherGroup = groups.get(keys[otherTile]!)!;
      if (group !== otherGroup) {
        group.delete(slot); group.add(best);
        otherGroup.delete(best); otherGroup.add(slot);
      }
      assigned[slot] = otherTile;
      assigned[best] = tile;
      moved = true;
    }
    if (!moved) break;
  }
}

/**
 * Identity- and cover-aware slot assignment shared by the library and album walls. Repeated tiles
 * take priority over shared artwork when spreading cards across the periodic cell. Geometry stays in
 * `lattice.ts`; this file only decides `slot → tileIndex`.
 */

import { SLOTS_PER_BLOCK, type Instance, type Lattice, type Metrics, type Point, type Tile } from '../types.ts';
import { createLattice, planLatticeSlots, type LatticeSlotPlan } from './lattice.ts';
import { repairSlotSpacing, slotGap2 } from './slotSpacing.ts';

/** Pin one tile to a slot (used after collapsing the playing track onto a nearby square). */
export type SlotPin = { tileIndex: number; slot: number };
export type SpreadPin = { tileIndex: number; near: Point };

const LOCAL_COVER_VARIANT = /^echo-cover:\/\/(?:thumb|album|large)\//u;

export function tileCoverKey(tile: Pick<Tile, 'album' | 'artist' | 'coverUrl' | 'trackId' | 'albumId'>): string {
  if (tile.coverUrl) return tile.coverUrl.replace(LOCAL_COVER_VARIANT, 'echo-cover://cover/');
  if (tile.albumId) return `album-id:${tile.albumId}`;
  const album = tile.album.trim();
  if (album !== '') return `album:${tile.artist.trim()}\0${album}`;
  return `track:${tile.trackId}`;
}

export function torusDistance2(
  ax: number,
  ay: number,
  bx: number,
  by: number,
  cell: { w: number; h: number },
): number {
  let dx = Math.abs(ax - bx);
  let dy = Math.abs(ay - by);
  if (dx > cell.w * 0.5) dx = cell.w - dx;
  if (dy > cell.h * 0.5) dy = cell.h - dy;
  return dx * dx + dy * dy;
}

function extraTileIndexes(coverKeys: readonly string[], extra: number, pinnedTile = -1): number[] {
  if (extra <= 0) return [];
  const freq = new Map<string, number>();
  for (const key of coverKeys) freq.set(key, (freq.get(key) ?? 0) + 1);
  // Keep the pinned card's square as its only copy when other tiles can fill the gaps.
  const order = coverKeys.map((_, index) => index).filter(index => index !== pinnedTile || coverKeys.length === 1);
  order.sort((a, b) => {
    const freqA = freq.get(coverKeys[a] ?? '') ?? 0;
    const freqB = freq.get(coverKeys[b] ?? '') ?? 0;
    return freqA - freqB || a - b;
  });
  return Array.from({ length: extra }, (_, index) => order[index % order.length]!);
}

function groupsLargestFirst(copies: readonly number[], coverKeys: readonly string[]): number[][] {
  const groups = new Map<string, number[]>();
  for (const tileIndex of copies) {
    const key = coverKeys[tileIndex] ?? `tile:${tileIndex}`;
    const group = groups.get(key);
    if (group) group.push(tileIndex);
    else groups.set(key, [tileIndex]);
  }
  return [...groups.values()].sort((a, b) => b.length - a.length || (a[0] ?? 0) - (b[0] ?? 0));
}

function wrapCoord(value: number, size: number): number {
  if (!(size > 0)) return 0;
  const wrapped = value % size;
  return wrapped < 0 ? wrapped + size : wrapped;
}

function pullMinDistFrom(slot: number, plan: LatticeSlotPlan, used: Uint8Array, minDist: Float64Array): void {
  const placed = plan.rects[slot];
  if (placed === undefined) return;
  for (let other = 0; other < used.length; other++) {
    if (used[other] === 1) continue;
    const rect = plan.rects[other];
    if (rect === undefined) continue;
    const distance = slotGap2(placed, rect, plan.gridCols, plan.gridRows);
    const current = minDist[other];
    if (current !== undefined && distance < current) minDist[other] = distance;
  }
}

/** Prefer a nearby 4×4, otherwise the nearest 2×2, so a collapsed playing track lands on a square. */
export function pickSquareSlot(plan: LatticeSlotPlan, near: Point): number {
  const wrapped = {
    x: wrapCoord(near.x, plan.cellPixelSize.w),
    y: wrapCoord(near.y, plan.cellPixelSize.h),
  };
  let bestSlot = -1;
  let bestScore = Infinity;
  for (let slot = 0; slot < plan.rects.length; slot++) {
    const rect = plan.rects[slot];
    const center = plan.centers[slot];
    if (rect === undefined || center === undefined || rect.w !== rect.h) continue;
    const score = torusDistance2(center.x, center.y, wrapped.x, wrapped.y, plan.cellPixelSize) / (rect.w * rect.h);
    if (score < bestScore || (score === bestScore && (bestSlot < 0 || slot < bestSlot))) {
      bestScore = score;
      bestSlot = slot;
    }
  }
  if (bestSlot < 0) throw new Error('pickSquareSlot: no square slots in the lattice plan');
  return bestSlot;
}

/** Place every tile, spreading its extra copies before optimizing shared-artwork spacing. */
export function spreadSlotToTile(coverKeys: readonly string[], plan: LatticeSlotPlan, pin?: SlotPin): number[] {
  const tileCount = coverKeys.length;
  const slotCount = plan.centers.length;
  if (tileCount < 1 || slotCount < tileCount) {
    throw new RangeError(`need at least as many slots as tiles, got tiles=${tileCount} slots=${slotCount}`);
  }
  let pinSlot = -1;
  let pinTile = -1;
  if (pin && pin.slot >= 0 && pin.slot < slotCount && pin.tileIndex >= 0 && pin.tileIndex < tileCount) {
    pinSlot = pin.slot;
    pinTile = pin.tileIndex;
  }

  const copies = coverKeys.map((_, index) => index);
  copies.push(...extraTileIndexes(coverKeys, slotCount - tileCount, pinTile));
  if (pinTile >= 0) {
    const removeAt = copies.indexOf(pinTile);
    if (removeAt >= 0) copies.splice(removeAt, 1);
  }

  const assigned = new Array<number>(slotCount).fill(-1);
  const used = new Uint8Array(slotCount);
  const minDist = new Float64Array(slotCount);
  const tileSlots: number[][] = Array.from({ length: tileCount }, () => []);
  if (pinSlot >= 0 && pinTile >= 0) {
    assigned[pinSlot] = pinTile;
    used[pinSlot] = 1;
    tileSlots[pinTile]!.push(pinSlot);
  }

  const pinKey = pinTile >= 0 ? (coverKeys[pinTile] ?? '') : '';
  for (const group of groupsLargestFirst(copies, coverKeys)) {
    minDist.fill(Number.POSITIVE_INFINITY);
    if (pinSlot >= 0 && pinKey !== '' && (coverKeys[group[0] ?? -1] ?? '') === pinKey) {
      pullMinDistFrom(pinSlot, plan, used, minDist);
    }
    for (const tileIndex of group) {
      let bestSlot = -1;
      let best = -1;
      let bestTileDistance = -1;
      for (let slot = 0; slot < slotCount; slot++) {
        if (used[slot] === 1) continue;
        const distance = minDist[slot] ?? 0;
        let tileDistance = Infinity;
        for (const prior of tileSlots[tileIndex]!) {
          tileDistance = Math.min(tileDistance, slotGap2(plan.rects[slot]!, plan.rects[prior]!, plan.gridCols, plan.gridRows));
        }
        if (tileDistance > bestTileDistance || (tileDistance === bestTileDistance && distance > best)) {
          bestTileDistance = tileDistance;
          best = distance;
          bestSlot = slot;
        }
      }
      if (bestSlot < 0) throw new Error('spreadSlotToTile ran out of slots');
      assigned[bestSlot] = tileIndex;
      used[bestSlot] = 1;
      tileSlots[tileIndex]!.push(bestSlot);
      pullMinDistFrom(bestSlot, plan, used, minDist);
    }
  }

  repairSlotSpacing(assigned, coverKeys, plan, pinSlot);
  return assigned;
}

export function createSpreadLattice(tiles: readonly Tile[], metrics: Metrics, pin?: SpreadPin): Lattice {
  const plan = planLatticeSlots(tiles.length, metrics);
  const keys = tiles.map(tileCoverKey);
  if (!pin || pin.tileIndex < 0 || pin.tileIndex >= tiles.length) {
    return createLattice(tiles.length, metrics, spreadSlotToTile(keys, plan));
  }
  const slot = pickSquareSlot(plan, pin.near);
  return createLattice(tiles.length, metrics, spreadSlotToTile(keys, plan, { tileIndex: pin.tileIndex, slot }));
}

/** Origin-cell `cellSlot → tileIndex` taken from an existing lattice. */
export function readSlotToTile(lattice: Lattice): number[] {
  const mapping = new Array<number>(lattice.blocksPerCell * SLOTS_PER_BLOCK).fill(0);
  for (let br = 0; br < lattice.cellRows; br++) {
    for (let bc = 0; bc < lattice.cellCols; bc++) {
      for (const instance of lattice.blockInstances(bc, br, null)) {
        mapping[instance.cellSlot] = instance.tileIndex;
      }
    }
  }
  return mapping;
}

/**
 * Keep the current spread. Only swap the playing tile with the nearest square in the same block
 * so collapse can land on a 4×4 / 2×2 without rebuilding the wall.
 */
export function reseatPlayingToSquare(lattice: Lattice, from: Instance, tileIndex: number): number[] {
  const mapping = readSlotToTile(lattice);
  if (tileIndex < 0 || tileIndex >= lattice.tileCount) return mapping;
  const block = lattice.blockInstances(from.bc, from.br, null);
  const near = lattice.centerOf(from.rect);
  let best = -1;
  let bestScore = Infinity;
  for (let index = 0; index < block.length; index++) {
    const instance = block[index];
    if (!instance || instance.rect.w !== instance.rect.h) continue;
    const center = lattice.centerOf(instance.rect);
    const dx = center.x - near.x;
    const dy = center.y - near.y;
    const score = (dx * dx + dy * dy) / (instance.rect.w * instance.rect.h);
    if (score < bestScore || (score === bestScore && (best < 0 || index < best))) {
      bestScore = score;
      best = index;
    }
  }
  const square = best >= 0 ? block[best] : undefined;
  const current = block.find((instance) => instance.slot === from.slot) ?? block.find((instance) => instance.tileIndex === tileIndex);
  if (!square || !current || square.cellSlot === current.cellSlot) return mapping;
  const displaced = mapping[square.cellSlot] ?? square.tileIndex;
  mapping[square.cellSlot] = tileIndex;
  mapping[current.cellSlot] = displaced;
  return mapping;
}

