export type HostBridgeOptions = {
  now?: () => number;
  setTimeout?: typeof setTimeout;
  clearTimeout?: typeof clearTimeout;
  probes?: ReadonlyArray<readonly [RequiredCapability, string]>;
};

/** Minimum spacing between `playback:seek` requests (≤ 4 per second). */
export const SEEK_THROTTLE_MS = 250;
/** Quiet period before the camera centre is persisted. */
export const CAMERA_SAVE_DEBOUNCE_MS = 2000;
/** Error messages handed to `onError` are cut to the host's own error-length limit. */
export const ERROR_MESSAGE_LIMIT = 160;

const MAX_ERROR_HANDLERS = 16;
const MAX_TRACKED_SUBSCRIPTIONS = 64;
const CAMERA_STORAGE_KEY = 'camera';

/**
 * Representative action per required permission; a permission counts as missing when the host does
 * not report this action as `granted && available` (feature ids are action ids, see plugin-api.json).
 */
export const CAPABILITY_PROBES: ReadonlyArray<readonly [RequiredCapability, string]> = [
  ['library:read', 'library:getTracks'],
  ['playback:read', 'playback:getStatus'],
  ['playback:control', 'playback:play'],
  ['queue:control', 'queue:playTrack'],
  ['lyrics:read', 'lyrics:get'],
  ['fs:plugin', 'settings:get'],
];

// The SDK declaration may not list `immersive` yet; the host rejects it with `invalid-payload` when unsupported.
const IMMERSIVE_SIZE = 'immersive' as string as EchoWorkshopPanelSize;

type TimerHandle = ReturnType<typeof setTimeout>;
type Unsubscribe = () => void;
type Settled<T> = { ok: true; value: T } | { ok: false; error: unknown };

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null;

const isFiniteNumber = (value: unknown): value is number =>
  typeof value === 'number' && Number.isFinite(value);

const isQueueSnapshot = (value: unknown): value is EchoWorkshopQueueSnapshot =>
  isRecord(value) && Array.isArray(value.items);

const isPlaybackStatus = (value: unknown): value is EchoWorkshopPlaybackStatus =>
  isRecord(value) && isFiniteNumber(value.positionSeconds);

const isUiContext = (value: unknown): value is EchoWorkshopUiContext => isRecord(value);

const isSettingValues = (value: unknown): value is SettingValues => isRecord(value);

const isLyrics = (value: unknown): value is EchoWorkshopSandboxLyrics =>
  isRecord(value) && typeof value.kind === 'string';

const toCamera = (value: unknown): Point | null =>
  isRecord(value) && isFiniteNumber(value.x) && isFiniteNumber(value.y) ? { x: value.x, y: value.y } : null;

const describeError = (error: unknown): string => {
  if (isRecord(error) && typeof error.message === 'string' && error.message !== '') return error.message;
  if (typeof error === 'string' && error !== '') return error;
  return 'unknown-error';
};

/** Invokes a host method so that synchronous throws surface as rejections instead of escaping. */
const invoke = <T>(fn: () => Promise<T> | T): Promise<T> => {
  try {
    return Promise.resolve(fn());
  } catch (error) {
    return Promise.reject(error);
  }
};

const settle = <T>(promise: Promise<T>): Promise<Settled<T>> =>
  promise.then(
    (value) => ({ ok: true, value }) as Settled<T>,
    (error) => ({ ok: false, error }) as Settled<T>,
  );

export function deriveMissingCapabilities(capabilities: unknown, probes = CAPABILITY_PROBES): RequiredCapability[] {
  if (!isRecord(capabilities) || !isRecord(capabilities.features)) return [];
  const features = capabilities.features;
  const missing: RequiredCapability[] = [];
  for (const [capability, action] of probes) {
    const feature = features[action];
    if (!isRecord(feature) || feature.granted !== true || feature.available !== true) missing.push(capability);
  }
  return missing;
}

export function createHostBridge(api: WallHostApi, options?: HostBridgeOptions): HostBridge {
  const now = options?.now ?? (() => performance.now());
  const schedule = options?.setTimeout ?? setTimeout;
  const cancel = options?.clearTimeout ?? clearTimeout;

  const errorHandlers = new Set<(message: string) => void>();
  const subscriptions = new Set<Unsubscribe>();
  let disposed = false;

  const report = (action: string, error: unknown): void => {
    const message = `${action}: ${describeError(error)}`.slice(0, ERROR_MESSAGE_LIMIT);
    for (const handler of errorHandlers) {
      try {
        handler(message);
      } catch {
        // A failing error listener must not take the bridge down with it.
      }
    }
  };

  /** Fire-and-forget control call: resolves either way and routes failures to `onError`. */
  const control = (action: string, fn: () => Promise<unknown>): Promise<void> =>
    invoke(fn).then(
      () => undefined,
      (error) => report(action, error),
    );

  /** Read that degrades to `fallback` on failure or an unexpected payload shape. */
  const degraded = <T>(action: string, fn: () => Promise<unknown>, accept: (value: unknown) => value is T, fallback: T): Promise<T> =>
    invoke(fn).then(
      (value) => {
        if (accept(value)) return value;
        report(action, 'invalid-response');
        return fallback;
      },
      (error) => {
        report(action, error);
        return fallback;
      },
    );

  const boot = async (): Promise<BootData> => {
    const missingPromise = invoke(() => api.host.getCapabilities()).then(
      (value) => deriveMissingCapabilities(value, options?.probes),
      (error) => {
        report('host:getCapabilities', error);
        return [] as RequiredCapability[];
      },
    );
    const contextPromise = settle(invoke(() => api.ui.getContext()));

    const missing = await missingPromise;
    const probes = options?.probes ?? CAPABILITY_PROBES;
    const requested = new Set(probes.map(([capability]) => capability));
    const has = (capability: RequiredCapability): boolean => requested.has(capability) && !missing.includes(capability);

    const [settings, queue, status, camera] = await Promise.all([
      has('fs:plugin')
        ? degraded<SettingValues>('settings:get', () => api.settings.get(), isSettingValues, {})
        : Promise.resolve<SettingValues>({}),
      has('queue:read')
        ? degraded<EchoWorkshopQueueSnapshot | null>('queue:get', () => api.queue.get(), isQueueSnapshot, null)
        : Promise.resolve(null),
      has('playback:read')
        ? degraded<EchoWorkshopPlaybackStatus | null>('playback:getStatus', () => api.playback.getStatus(), isPlaybackStatus, null)
        : Promise.resolve(null),
      has('fs:plugin')
        ? invoke(() => api.storage.get(CAMERA_STORAGE_KEY)).then(toCamera, (error) => {
          report('storage:get', error);
          return null;
        })
        : Promise.resolve(null),
    ]);

    const context = await contextPromise;
    if (!context.ok) throw context.error instanceof Error ? context.error : new Error(`ui:getContext: ${describeError(context.error)}`);
    if (!isUiContext(context.value)) throw new Error('ui:getContext: invalid-response');

    return { missing, context: context.value, settings, queue, status, camera };
  };

  const requestPresentation = async (title: string, immersive: boolean): Promise<'immersive' | 'full' | 'unchanged'> => {
    const apply = async (size: EchoWorkshopPanelSize): Promise<boolean> => {
      const result = await invoke(() => api.ui.setPanelPresentation({ size, title }));
      return !isRecord(result) || typeof result.size !== 'string' || result.size === size;
    };
    if (immersive) {
      try {
        if (await apply(IMMERSIVE_SIZE)) return 'immersive';
      } catch {
        // Older hosts reject the size with `invalid-payload`; `full` is the documented fallback.
      }
    }
    try {
      if (await apply('full')) return 'full';
    } catch (error) {
      report('ui:setPanelPresentation', error);
    }
    return 'unchanged';
  };

  const listen = <T>(
    name: string,
    source: (handler: (payload: unknown) => void) => unknown,
    accept: (value: unknown) => value is T,
    handler: (value: T) => void,
  ): Unsubscribe => {
    const wrapped = (payload: unknown): void => {
      if (!accept(payload)) return;
      try {
        handler(payload);
      } catch (error) {
        report(`event:${name}`, error);
      }
    };
    let raw: unknown;
    try {
      raw = source(wrapped);
    } catch (error) {
      report(`event:${name}`, error);
      return () => undefined;
    }
    const off: Unsubscribe = () => {
      subscriptions.delete(off);
      if (typeof raw !== 'function') return;
      try {
        (raw as () => void)();
      } catch {
        // Unsubscribing from a torn-down host must stay silent.
      }
    };
    if (subscriptions.size < MAX_TRACKED_SUBSCRIPTIONS) subscriptions.add(off);
    return off;
  };

  let seekTimer: TimerHandle | null = null;
  let seekPending: number | null = null;
  let lastSeekAt = Number.NEGATIVE_INFINITY;

  const sendSeek = (positionSeconds: number): Promise<void> => {
    lastSeekAt = now();
    return control('playback:seek', () => api.playback.seek(positionSeconds));
  };

  const flushSeek = (): void => {
    seekTimer = null;
    if (seekPending === null) return;
    const value = seekPending;
    seekPending = null;
    void sendSeek(value);
  };

  const seek = (positionSeconds: number): Promise<void> => {
    if (disposed || !Number.isFinite(positionSeconds)) return Promise.resolve();
    const value = Math.max(0, positionSeconds);
    const elapsed = now() - lastSeekAt;
    if (seekTimer === null && elapsed >= SEEK_THROTTLE_MS) return sendSeek(value);
    seekPending = value;
    if (seekTimer === null) seekTimer = schedule(flushSeek, Math.max(0, SEEK_THROTTLE_MS - elapsed));
    return Promise.resolve();
  };

  let cameraTimer: TimerHandle | null = null;
  let cameraPending: Point | null = null;

  const flushCamera = (): void => {
    cameraTimer = null;
    const value = cameraPending;
    cameraPending = null;
    if (!value) return;
    void control('storage:set', () => api.storage.set(CAMERA_STORAGE_KEY, value));
  };

  const saveCamera = (camera: Point): void => {
    if (disposed || !isRecord(camera) || !isFiniteNumber(camera.x) || !isFiniteNumber(camera.y)) return;
    cameraPending = { x: Math.round(camera.x), y: Math.round(camera.y) };
    if (cameraTimer !== null) cancel(cameraTimer);
    cameraTimer = schedule(flushCamera, CAMERA_SAVE_DEBOUNCE_MS);
  };

  const dispose = (): void => {
    disposed = true;
    if (seekTimer !== null) cancel(seekTimer);
    seekTimer = null;
    seekPending = null;
    if (cameraTimer !== null) cancel(cameraTimer);
    cameraTimer = null;
    cameraPending = null;
    for (const off of Array.from(subscriptions)) off();
    subscriptions.clear();
    errorHandlers.clear();
  };

  return {
    boot,
    requestPresentation,
    onQueueChanged: (handler) =>
      listen('queue:changed', (h) => api.events.on('queue:changed', h), isQueueSnapshot, handler),
    onPlaybackStatus: (handler) =>
      listen('playback:status', (h) => api.events.on('playback:status', h), isPlaybackStatus, handler),
    onContextChanged: (handler) =>
      listen('ui:context-changed', (h) => api.ui.onContextChanged(h), isUiContext, handler),
    onSettingsChanged: (handler) =>
      listen('settings:changed', (h) => api.settings.onChanged(h), isSettingValues, handler),
    onError: (handler) => {
      if (typeof handler !== 'function' || errorHandlers.size >= MAX_ERROR_HANDLERS) return () => undefined;
      errorHandlers.add(handler);
      return () => {
        errorHandlers.delete(handler);
      };
    },
    play: () => control('playback:play', () => api.playback.play()),
    pause: () => control('playback:pause', () => api.playback.pause()),
    next: () => control('playback:next', () => api.playback.next()),
    previous: () => control('playback:previous', () => api.playback.previous()),
    toggleShuffle: () => control('playback:toggleShuffle', () => api.playback.toggleShuffle()),
    setRepeat: (mode) => control('playback:setRepeat', () => api.playback.setRepeat(mode)),
    seek,
    playItem: (queueId) => control('queue:playItem', () => api.queue.playItem(queueId)),
    playTrack: (trackId, queueTrackIds) => control('queue:playTrack', () => api.queue.playTrack(trackId, queueTrackIds)),
    getLyrics: (trackId) =>
      invoke(() => api.lyrics.get(trackId)).then(
        (value) => (isLyrics(value) ? value : null),
        (error) => {
          report('lyrics:get', error);
          return null;
        },
      ),
    setSetting: (id, value) => control('settings:set', () => api.settings.set(id, value)),
    saveCamera,
    closePanel: () => control('ui:closePanel', () => api.ui.closePanel()),
    openPanel: (panelId) => control('ui:openPanel', () => {
      const open = api.ui.openPanel;
      if (typeof open !== 'function') throw new Error('unsupported');
      return open(panelId);
    }),
    dispose,
  };
}

import type { ClockSnapshot, PlaybackClock } from '../types.ts';
import type { WallPlaybackStatus } from './api.ts';

/** Drift at or above this many seconds snaps to the host value instead of gliding. */
export const HARD_CORRECTION_SECONDS = 0.35;
/** Soft corrections are spread linearly over this window so the progress bar never jumps. */
export const SOFT_CORRECTION_MS = 500;
/** Host samples a local seek may lag behind before the host value wins again. */
export const OPTIMISTIC_SEEK_SAMPLES = 2;

const finiteOr = (value: unknown, fallback: number): number =>
  typeof value === 'number' && Number.isFinite(value) ? value : fallback;

const clamp01 = (value: number): number => (value < 0 ? 0 : value > 1 ? 1 : value);

export function createPlaybackClock(): PlaybackClock {
  // `base` is the position shown at `sampledAt`; while playing the clock extrapolates from there.
  let base = 0;
  let sampledAt = 0;
  let duration = 0;
  let state = 'stopped';
  let playbackRate = 1;
  let trackId: string | null = null;
  let hasSample = false;
  // A pending soft correction: `softDelta` seconds folded in linearly from `softStart`.
  let softDelta = 0;
  let softStart = 0;
  // Remaining host samples allowed to disagree with a local seek before the host wins.
  let optimisticHold = 0;

  const clampToDuration = (position: number): number => {
    if (position < 0) return 0;
    return duration > 0 && position > duration ? duration : position;
  };

  const positionAt = (nowMs: number): number => {
    let position = base;
    if (state === 'playing') position += Math.max(0, nowMs - sampledAt) / 1000 * playbackRate;
    if (softDelta !== 0) position += softDelta * clamp01((nowMs - softStart) / SOFT_CORRECTION_MS);
    return clampToDuration(position);
  };

  const rebase = (position: number, nowMs: number): void => {
    base = position;
    sampledAt = nowMs;
    softDelta = 0;
  };

  const ingest = (status: WallPlaybackStatus, nowMs: number): void => {
    const incomingState = typeof status.state === 'string' ? status.state : 'stopped';
    const incomingTrack = typeof status.currentTrackId === 'string' ? status.currentTrackId : null;
    const incomingPosition = Math.max(0, finiteOr(status.positionSeconds, 0));
    const predicted = positionAt(nowMs);

    const first = !hasSample;
    const stateChanged = incomingState !== state;
    const incomingRate = Math.max(0.5, Math.min(2, finiteOr(status.playbackRate, 1)));
    const rateChanged = incomingRate !== playbackRate;
    const trackChanged = incomingTrack !== trackId;
    duration = Math.max(0, finiteOr(status.durationSeconds, 0));
    state = incomingState;
    playbackRate = incomingRate;
    trackId = incomingTrack;
    hasSample = true;

    const hostPosition = incomingState === 'ended' && duration > 0 ? duration : incomingPosition;
    const drift = hostPosition - predicted;
    const agrees = Math.abs(drift) < HARD_CORRECTION_SECONDS;

    if (optimisticHold > 0 && !first && !stateChanged && !rateChanged && !trackChanged && !agrees) {
      // The host has not applied our seek yet (its sample predates it); keep the local position.
      optimisticHold -= 1;
      rebase(clampToDuration(predicted), nowMs);
      return;
    }
    optimisticHold = 0;

    if (first || stateChanged || rateChanged || trackChanged || !agrees) {
      rebase(clampToDuration(hostPosition), nowMs);
      return;
    }
    rebase(clampToDuration(predicted), nowMs);
    softDelta = drift;
    softStart = nowMs;
  };

  const seek = (positionSeconds: number, nowMs: number): void => {
    rebase(clampToDuration(Math.max(0, finiteOr(positionSeconds, 0))), nowMs);
    optimisticHold = OPTIMISTIC_SEEK_SAMPLES;
  };

  const read = (nowMs: number): ClockSnapshot => ({
    positionSeconds: positionAt(nowMs),
    durationSeconds: duration,
    state,
    trackId,
    running: state === 'playing',
  });

  return {
    ingest,
    seek,
    read,
    get running(): boolean {
      return state === 'playing';
    },
  };
}

export const applyContext = (context: EchoWorkshopUiContext): void => {
  const root = document.documentElement;
  root.dataset.colorScheme = context.colorScheme;
  document.body.dataset.colorScheme = context.colorScheme;
  document.body.dataset.reducedMotion = String(context.reducedMotion);
  root.lang = context.locale || 'zh-CN';
  root.dir = context.direction;
  const tokens: Array<[string, string]> = [
    ['--host-accent', context.appearance.accent],
    ['--host-accent-text', context.appearance.accentText],
    ['--host-app-bg', context.appearance.appBg],
    ['--host-text', context.appearance.text],
    ['--host-muted', context.appearance.muted],
    ['--host-panel', context.appearance.panel],
    ['--host-border', context.appearance.border],
    ['--host-player', context.appearance.player],
  ];
  for (const [name, value] of tokens) {
    if (typeof value === 'string' && value) root.style.setProperty(name, value);
  }
};

/** Panel-local shortcuts. No desktop/global shortcut registration or host utilities. */
export const DEFAULT_PANEL_SHORTCUT = 'Ctrl+Space';
const MODIFIERS = ['Ctrl', 'Alt', 'Shift', 'Command'];
const RESERVED = new Set(['Alt+F4', 'Ctrl+W', 'Command+W', 'Command+Q']);
const NAMED: Record<string, string> = {
  space: 'Space', enter: 'Enter', backspace: 'Backspace', delete: 'Delete', insert: 'Insert',
  home: 'Home', end: 'End', pageup: 'PageUp', pagedown: 'PageDown',
  arrowleft: 'Left', arrowright: 'Right', arrowup: 'Up', arrowdown: 'Down',
  left: 'Left', right: 'Right', up: 'Up', down: 'Down', plus: 'Plus',
};
const ALIASES: Record<string, string> = { ctrl: 'Ctrl', control: 'Ctrl', alt: 'Alt', shift: 'Shift', command: 'Command', meta: 'Command' };

export function normalizePanelShortcut(value: unknown): string | null {
  if (typeof value !== 'string' || value.length > 80) return null;
  const parts = value.trim().split('+').map(part => part.trim());
  const rawKey = parts.pop() ?? '';
  const key = NAMED[rawKey.toLowerCase()] ?? rawKey.toUpperCase();
  const functionKey = /^F(?:[1-9]|1[0-9]|2[0-4])$/.test(key);
  if (!functionKey && !Object.values(NAMED).includes(key) && !/^[A-Z0-9,./;\[\]'`\\=\-]$/.test(key)) return null;
  const modifiers = parts.map(part => ALIASES[part.toLowerCase()]);
  if (modifiers.some(modifier => !modifier) || new Set(modifiers).size !== modifiers.length) return null;
  if (!functionKey && !modifiers.some(modifier => modifier !== 'Shift')) return null;
  const result = [...MODIFIERS.filter(modifier => modifiers.includes(modifier)), key].join('+');
  return RESERVED.has(result) ? null : result;
}

export function shortcutFromEvent(event: KeyboardEvent): string | null {
  if (event.isComposing || event.keyCode === 229 || event.getModifierState?.('AltGraph')) return null;
  const key = event.code === 'Space' ? 'Space'
    : /^Key[A-Z]$/.test(event.code) ? event.code.slice(3)
    : /^Digit[0-9]$/.test(event.code) ? event.code.slice(5)
    : event.key === '+' ? 'Plus' : event.key;
  return normalizePanelShortcut([
    ...(event.ctrlKey ? ['Ctrl'] : []), ...(event.altKey ? ['Alt'] : []),
    ...(event.shiftKey ? ['Shift'] : []), ...(event.metaKey ? ['Command'] : []), key,
  ].join('+'));
}

export function matchesPanelShortcut(event: KeyboardEvent, shortcut: string): boolean {
  return !event.defaultPrevented && shortcutFromEvent(event) === shortcut;
}

export function panelShortcutAria(shortcut: string): string {
  return shortcut.split('+').map(key => key === 'Ctrl' ? 'Control' : key === 'Command' ? 'Meta' : key).join('+');
}

import type { LibrarySource, LibraryPageQuery } from './librarySource.ts';
import type { RequiredCapability, Tile } from '../types.ts';
import { FALLBACK_ARTIST, FALLBACK_TITLE } from './queueModel.ts';

/** Tracks shown on one wall. Above this, the browser pages; the host still serves at most 100 per call. */
export const LIBRARY_WALL_PAGE_SIZE = 200;
/** Host `library:getTracks` cap (`WorkshopPluginMediaBridge.maximumPageSize`). */
export const LIBRARY_HOST_PAGE_SIZE = 100;
/** Host `queue.playTrack` accepts at most this many context ids. */
export const LIBRARY_PLAY_CONTEXT_LIMIT = 200;

const HOST_PAGES_PER_WALL = LIBRARY_WALL_PAGE_SIZE / LIBRARY_HOST_PAGE_SIZE;

export const LIBRARY_WALL_PROBES: ReadonlyArray<readonly [RequiredCapability, string]> = [
  ['library:read', 'library:getTracks'],
  ['playback:read', 'playback:getStatus'],
  ['playback:control', 'playback:play'],
  ['queue:control', 'queue:playTrack'],
  ['lyrics:read', 'lyrics:get'],
  ['fs:plugin', 'settings:get'],
];

const text = (value: unknown, fallback: string): string =>
  typeof value === 'string' && value.trim() !== '' ? value : fallback;

export function libraryTrackTiles(tracks: readonly EchoWorkshopTrack[], page: number): Tile[] {
  const origin = Math.max(0, page - 1) * LIBRARY_WALL_PAGE_SIZE;
  return tracks.map((track, offset) => ({
    index: origin + offset,
    queueId: track.id,
    trackId: track.id,
    title: text(track.title, FALLBACK_TITLE),
    artist: text(track.artist, FALLBACK_ARTIST),
    album: text(track.album, ''),
    coverUrl: typeof track.coverUrl === 'string' && track.coverUrl !== '' ? track.coverUrl : null,
    durationSeconds: typeof track.durationSeconds === 'number' && Number.isFinite(track.durationSeconds) && track.durationSeconds > 0
      ? track.durationSeconds
      : 0,
  }));
}

export function currentLibraryIndex(tiles: readonly Tile[], trackId: string | null | undefined): number | null {
  if (!trackId) return null;
  const found = tiles.findIndex((tile) => tile.trackId === trackId);
  return found >= 0 ? found : null;
}

export function libraryPageNotice(page: Pick<EchoWorkshopPage<unknown>, 'page' | 'pageSize' | 'total'>): string {
  const pages = Math.max(1, Math.ceil(page.total / Math.max(1, page.pageSize)));
  if (pages <= 1) return `共 ${page.total} 首`;
  return `第 ${page.page} / ${pages} 页 · 共 ${page.total} 首`;
}

/** Window of track ids around the chosen card; never exceeds the host play-context cap. */
export function playContextIds(tiles: readonly Tile[], centerIndex: number, limit = LIBRARY_PLAY_CONTEXT_LIMIT): string[] {
  if (tiles.length <= limit) return tiles.map((tile) => tile.trackId);
  const safeCenter = Math.min(Math.max(0, centerIndex), tiles.length - 1);
  const half = Math.floor(limit / 2);
  let start = Math.max(0, safeCenter - half);
  let end = Math.min(tiles.length, start + limit);
  start = Math.max(0, end - limit);
  const ids: string[] = [];
  for (let index = start; index < end; index++) {
    const tile = tiles[index];
    if (tile) ids.push(tile.trackId);
  }
  return ids;
}

/**
 * Assembles one wall page from several host pages. Stops early when the library (or search)
 * has fewer than 200 remaining tracks. Only the current wall page is retained.
 */
export function createLibraryTrackLoader(
  read: (query: LibraryPageQuery) => Promise<EchoWorkshopPage<EchoWorkshopTrack>>,
) {
  let generation = 0;
  return {
    async load(wallPage: number, search = '', sourceProvider: LibrarySource = 'local'): Promise<EchoWorkshopPage<EchoWorkshopTrack> | null> {
      const request = ++generation;
      const page = Number.isInteger(wallPage) && wallPage > 0 ? wallPage : 1;
      const hostStart = (page - 1) * HOST_PAGES_PER_WALL + 1;
      const items: EchoWorkshopTrack[] = [];
      let total = 0;

      for (let step = 0; step < HOST_PAGES_PER_WALL; step++) {
        let result: EchoWorkshopPage<EchoWorkshopTrack>;
        try {
          result = await read({
            page: hostStart + step,
            pageSize: LIBRARY_HOST_PAGE_SIZE,
            search,
            sourceProvider,
          });
        } catch (error) {
          if (request !== generation) return null;
          throw error;
        }
        if (request !== generation) return null;
        total = result.total;
        items.push(...result.items.slice(0, LIBRARY_HOST_PAGE_SIZE));
        const offset = (hostStart - 1) * LIBRARY_HOST_PAGE_SIZE + items.length;
        if (!result.hasMore || items.length >= LIBRARY_WALL_PAGE_SIZE || offset >= total) break;
      }

      if (request !== generation) return null;
      const kept = items.slice(0, LIBRARY_WALL_PAGE_SIZE);
      const seen = (page - 1) * LIBRARY_WALL_PAGE_SIZE + kept.length;
      return {
        page,
        pageSize: LIBRARY_WALL_PAGE_SIZE,
        total,
        hasMore: seen < total,
        items: kept,
      };
    },
    cancel() { generation++; },
  };
}

/** Supported by the ECHO 26.10.4 panel bridge; absent from the vendored SDK types. */
export type LibrarySource = 'local' | 'remote';

export type LibraryPageQuery = EchoWorkshopPageQuery & { sourceProvider?: LibrarySource };

import type { WallHostApi } from './api.ts';

/** Keep the existing wall UI; adapt the host-owned plug-in controls at the entry point. */
export const createPluginWallApi = (sdk: EchoWorkshopApi): WallHostApi => ({
  ...sdk,
  ...(typeof sdk.playback.getRate === 'function' && typeof sdk.playback.setRate === 'function' ? { speed: {
    get: () => sdk.playback.getRate(), set: (rate: number) => sdk.playback.setRate(rate),
    onChanged: (handler: (rate: number) => void) => sdk.events.on('playback:status', value => {
      const rate = value && typeof value === 'object' ? (value as { playbackRate?: unknown }).playbackRate : undefined;
      if (typeof rate === 'number' && Number.isFinite(rate)) handler(rate);
    }),
  } } : {}),
  ...(sdk.window && typeof sdk.window.getDesktopWall === 'function' ? { desktop: {
    get: () => sdk.window.getDesktopWall(), set: (enabled: boolean) => sdk.window.setDesktopWall(enabled),
  } } : {}),
});

import type { QueueDiff, QueueModel, Tile } from '../types.ts';

/** The host caps queue snapshots at this many items (WorkshopPluginMediaBridge). */
export const QUEUE_TRUNCATION_LIMIT = 500;

export const FALLBACK_TITLE = '未知标题';
export const FALLBACK_ARTIST = '未知艺术家';

export const emptyQueueModel = (): QueueModel => ({
  tiles: [],
  currentIndex: null,
  currentQueueId: null,
  truncated: false,
});

const text = (value: unknown, fallback: string): string =>
  typeof value === 'string' && value.trim() !== '' ? value : fallback;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null;

function toTile(item: unknown, index: number): Tile | null {
  if (!isRecord(item) || typeof item.queueId !== 'string' || item.queueId === '') return null;
  const track: Record<string, unknown> = isRecord(item.track) ? item.track : {};
  const duration = track.durationSeconds;
  return {
    index,
    queueId: item.queueId,
    trackId: typeof track.id === 'string' && track.id !== '' ? track.id : item.queueId,
    title: text(track.title, FALLBACK_TITLE),
    artist: text(track.artist, FALLBACK_ARTIST),
    album: text(track.album, ''),
    coverUrl: typeof track.coverUrl === 'string' && track.coverUrl !== '' ? track.coverUrl : null,
    durationSeconds: typeof duration === 'number' && Number.isFinite(duration) && duration > 0 ? duration : 0,
  };
}

export function buildQueueModel(snapshot: EchoWorkshopQueueSnapshot | null): QueueModel {
  if (!snapshot || !Array.isArray(snapshot.items)) return emptyQueueModel();
  const tiles: Tile[] = [];
  for (const item of snapshot.items) {
    const tile = toTile(item, tiles.length);
    if (tile) tiles.push(tile);
  }
  const currentQueueId = typeof snapshot.currentQueueId === 'string' ? snapshot.currentQueueId : null;
  let currentIndex: number | null = null;
  if (currentQueueId !== null) {
    const found = tiles.findIndex((tile) => tile.queueId === currentQueueId);
    currentIndex = found >= 0 ? found : null;
  }
  return {
    tiles,
    currentIndex,
    currentQueueId,
    truncated: snapshot.items.length >= QUEUE_TRUNCATION_LIMIT,
  };
}

export function diffQueueModel(previous: QueueModel, next: QueueModel): QueueDiff {
  let tilesChanged = previous.tiles.length !== next.tiles.length;
  for (let i = 0; !tilesChanged && i < next.tiles.length; i += 1) {
    if (previous.tiles[i]?.queueId !== next.tiles[i]?.queueId) tilesChanged = true;
  }
  return { tilesChanged, currentChanged: previous.currentIndex !== next.currentIndex };
}

import { HUD_DEFAULT_TILT_ANGLE, normalizeHudTiltAngle } from '../hudSettings.ts';
import { DEFAULT_PANEL_SHORTCUT, normalizePanelShortcut } from './controlPanelShortcut.ts';
import type { CellSizeId, LatticeSettings, LightingMode, Metrics, SettingValues, WallVisualOptions } from '../types.ts';

/** Runtime key → manifest setting id (`contributes.settings[].id`, kebab-case). */
export const SETTING_IDS: Record<keyof LatticeSettings, string> = {
  controlPanelShortcut: 'control-panel-shortcut',
  immersive: 'immersive',
  autoFocus: 'auto-focus',
  fisheye: 'fisheye',
  pointer3d: 'pointer-3d',
  hudTiltAngle: 'hud-tilt-angle',
  lightingMode: 'lighting-mode',
  vignette: 'vignette',
  lightsOut: 'lights-out',
  posterTint: 'poster-tint',
  posterTintGradient: 'poster-tint-gradient',
  posterTintCustom: 'poster-tint-custom',
  posterTintColor: 'poster-tint-color',
  posterTintIntensity: 'poster-tint-intensity',
  cellSize: 'cell-size',
  showTitles: 'show-titles',
  showLyrics: 'show-lyrics',
  showTranslation: 'show-translation',
  uiFont: 'ui-font',
};

export const DEFAULT_SETTINGS: LatticeSettings = {
  controlPanelShortcut: DEFAULT_PANEL_SHORTCUT,
  immersive: true,
  autoFocus: true,
  fisheye: false,
  pointer3d: false,
  hudTiltAngle: HUD_DEFAULT_TILT_ANGLE,
  lightingMode: 'spotlight',
  vignette: true,
  lightsOut: false,
  posterTint: true,
  posterTintGradient: 'none',
  posterTintCustom: false,
  posterTintColor: '#000000',
  posterTintIntensity: 0.5,
  cellSize: 'M',
  showTitles: false,
  showLyrics: true,
  showTranslation: true,
  uiFont: '',
};

/** Neutral cover shading, independent of the host theme. */
export const FALLBACK_TINT = '#000000';

const CELL_SIDES: Record<CellSizeId, number> = { S: 104, M: 128, L: 152 };
const CELL_GAP = 4;

const HEX_COLOR = /^#[0-9a-f]{6}$/i;
const FONT_UNSAFE = /url\s*\(|expression\s*\(|[@;{}\\]|<\/?/i;
const FONT_SAFE = /^[\w\s\-"',\u4e00-\u9fff]+$/u;
const FONT_MAX = 80;

const bool = (value: unknown, fallback: boolean): boolean => (typeof value === 'boolean' ? value : fallback);

const isCellSize = (value: unknown): value is CellSizeId => value === 'S' || value === 'M' || value === 'L';

export const isLightingMode = (value: unknown): value is LightingMode => value === 'spotlight' || value === 'daytime';

/** Drop CSS injection and keep a short font-family stack. */
export function sanitizeUiFont(value: unknown): string {
  if (typeof value !== 'string') return '';
  const trimmed = value.trim().slice(0, FONT_MAX);
  if (!trimmed || FONT_UNSAFE.test(trimmed) || !FONT_SAFE.test(trimmed)) return '';
  return trimmed;
}

export function resolveSettings(values: SettingValues): LatticeSettings {
  const source: SettingValues = typeof values === 'object' && values !== null ? values : {};
  const read = (key: keyof LatticeSettings): unknown => source[SETTING_IDS[key]];

  const color = read('posterTintColor');
  const intensity = read('posterTintIntensity');
  const cellSize = read('cellSize');
  const lighting = read('lightingMode');
  const tintGradient = read('posterTintGradient');

  return {
    controlPanelShortcut: normalizePanelShortcut(read('controlPanelShortcut')) ?? DEFAULT_PANEL_SHORTCUT,
    immersive: bool(read('immersive'), DEFAULT_SETTINGS.immersive),
    autoFocus: bool(read('autoFocus'), DEFAULT_SETTINGS.autoFocus),
    fisheye: bool(read('fisheye'), DEFAULT_SETTINGS.fisheye),
    pointer3d: bool(read('pointer3d'), DEFAULT_SETTINGS.pointer3d),
    hudTiltAngle: normalizeHudTiltAngle(read('hudTiltAngle')),
    lightingMode: isLightingMode(lighting) ? lighting : DEFAULT_SETTINGS.lightingMode,
    vignette: bool(read('vignette'), DEFAULT_SETTINGS.vignette),
    lightsOut: bool(read('lightsOut'), DEFAULT_SETTINGS.lightsOut),
    posterTint: bool(read('posterTint'), DEFAULT_SETTINGS.posterTint),
    posterTintGradient: tintGradient === 'diagonal' || tintGradient === 'vertical'
      ? tintGradient : DEFAULT_SETTINGS.posterTintGradient,
    posterTintCustom: bool(read('posterTintCustom'), DEFAULT_SETTINGS.posterTintCustom),
    posterTintColor: typeof color === 'string' && HEX_COLOR.test(color) ? color.toLowerCase() : DEFAULT_SETTINGS.posterTintColor,
    posterTintIntensity: typeof intensity === 'number' && Number.isFinite(intensity)
      ? Math.min(1, Math.max(0, intensity))
      : DEFAULT_SETTINGS.posterTintIntensity,
    cellSize: isCellSize(cellSize) ? cellSize : DEFAULT_SETTINGS.cellSize,
    showTitles: bool(read('showTitles'), DEFAULT_SETTINGS.showTitles),
    showLyrics: bool(read('showLyrics'), DEFAULT_SETTINGS.showLyrics),
    showTranslation: bool(read('showTranslation'), DEFAULT_SETTINGS.showTranslation),
    uiFont: sanitizeUiFont(read('uiFont')),
  };
}

export function cellMetricsFor(size: CellSizeId): Metrics {
  return { cell: CELL_SIDES[size] ?? CELL_SIDES.M, gap: CELL_GAP };
}

/** Wall zoom. Narrower viewports pull back further so more posters stay on screen. */
export function wallOverviewScale(viewportWidth: number): number {
  if (!Number.isFinite(viewportWidth) || viewportWidth <= 0) return 0.6;
  if (viewportWidth < 720) return 0.42;
  if (viewportWidth < 1280) return 0.52;
  return 0.6;
}

/** Expanded-card zoom: closer than the wall, still short of filling the viewport. */
export function wallExpandedScale(viewportWidth: number): number {
  if (!Number.isFinite(viewportWidth) || viewportWidth <= 0) return 0.78;
  if (viewportWidth < 720) return 0.55;
  if (viewportWidth < 1280) return 0.68;
  return 0.78;
}

export function resolveTintColor(settings: LatticeSettings): string {
  return settings.posterTintCustom ? settings.posterTintColor : FALLBACK_TINT;
}

/** Which Folia-style tint / shade controls the function panel should keep live. */
export function controlPanelSettingLocks(settings: LatticeSettings): {
  spotlight: boolean;
  tint: boolean;
  customColor: boolean;
} {
  const spotlight = settings.lightingMode === 'spotlight';
  const tint = spotlight && settings.posterTint;
  return { spotlight, tint, customColor: tint && settings.posterTintCustom };
}

export function wallVisualsFromSettings(settings: LatticeSettings, reducedMotion: boolean): WallVisualOptions {
  const daytime = settings.lightingMode === 'daytime';
  return {
    pointer3d: settings.pointer3d,
    hudTiltAngle: settings.hudTiltAngle,
    lightsOut: daytime ? false : settings.lightsOut,
    vignette: daytime ? false : settings.vignette,
    tint: daytime ? false : settings.posterTint,
    tintGradient: settings.posterTintGradient,
    tintColor: resolveTintColor(settings),
    tintIntensity: daytime ? 0 : settings.posterTintIntensity,
    reducedMotion,
  };
}

export function applyUiFont(font: string): void {
  const clean = sanitizeUiFont(font);
  const root = document.documentElement;
  if (clean) root.style.setProperty('--ui-font', clean);
  else root.style.removeProperty('--ui-font');
}

/** Lighting dataset, shade colour token, and UI font. Call before `wall.setVisualOptions`. */
export function applyAppearance(settings: LatticeSettings): void {
  document.body.dataset.fisheye = String(settings.fisheye);
  document.body.dataset.showTitles = String(settings.showTitles);
  document.body.dataset.lighting = settings.lightingMode;
  document.body.dataset.vignette = String(settings.lightingMode !== 'daytime' && settings.vignette);
  document.body.style.setProperty('--shade-color', resolveTintColor(settings));
  applyUiFont(settings.uiFont);
}

export function settingEntries(patch: Partial<LatticeSettings>): Array<[string, string | number | boolean]> {
  const entries: Array<[string, string | number | boolean]> = [];
  for (const key of Object.keys(patch) as Array<keyof LatticeSettings>) {
    const value = patch[key];
    if (value === undefined) continue;
    entries.push([SETTING_IDS[key], value]);
  }
  return entries;
}

export const HUD_MIN_TILT_ANGLE = 0;
export const HUD_MAX_TILT_ANGLE = 10;
export const HUD_DEFAULT_TILT_ANGLE = 5.8;

/** Old settings keep the current HUD; invalid imports cannot produce a non-finite CSS matrix. */
export function normalizeHudTiltAngle(value: unknown): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) return HUD_DEFAULT_TILT_ANGLE;
  return Math.round(Math.max(HUD_MIN_TILT_ANGLE, Math.min(HUD_MAX_TILT_ANGLE, value)) * 10) / 10;
}

/**
 * Pure lyrics timeline model (SPEC §9): normalises host `EchoWorkshopSandboxLyrics` into the
 * `LyricsTimeline` contract and provides the time lookups the view runs every frame. No DOM, so Node
 * executes this file directly from `scripts/test-lyrics.mjs`.
 */
import type { LyricsLine, LyricsTimeline, LyricsWord } from '../types.ts';

type SandboxLine = EchoWorkshopSandboxLyrics['lines'][number];
type SandboxWord = SandboxLine['words'][number];

const LAST_LINE_DURATION_MS = 5000;
const WHITESPACE_RUN = /\s+/gu;
const WHITESPACE_CHAR = /\s/u;

export function buildLyricsTimeline(lyrics: EchoWorkshopSandboxLyrics | null): LyricsTimeline {
  if (!lyrics || lyrics.kind === 'empty') return { kind: 'empty' };
  if (lyrics.kind === 'instrumental') return { kind: 'instrumental' };
  const sourceLines = Array.isArray(lyrics.lines) ? lyrics.lines : [];
  if (lyrics.kind === 'plain') {
    const text = trimmed(lyrics.plainText) || joinLineTexts(sourceLines);
    return text ? { kind: 'plain', text } : { kind: 'empty' };
  }
  const lines = buildSyncedLines(sourceLines);
  if (lines.length === 0) return { kind: 'empty' };
  return { kind: 'synced', lines, offsetMs: Number.isFinite(lyrics.offsetMs) ? lyrics.offsetMs : 0 };
}

/** Index of the last line with `startMs <= timeMs`, or -1 before the first line. */
export function findLineIndex(lines: LyricsLine[], timeMs: number): number {
  let low = 0;
  let high = lines.length - 1;
  let found = -1;
  while (low <= high) {
    const mid = (low + high) >>> 1;
    const line = lines[mid];
    if (line !== undefined && line.startMs <= timeMs) {
      found = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return found;
}

/** 0..1 sweep progress of a word; a word without its own end runs until the line ends. */
export function wordProgress(word: LyricsWord, lineEndMs: number, timeMs: number): number {
  return progressBetween(word.startMs, word.endMs ?? lineEndMs, timeMs);
}

/** 0..1 progress of a whole line (used when the line has no word timings). */
export function lineProgress(line: LyricsLine, timeMs: number): number {
  return progressBetween(line.startMs, line.endMs, timeMs);
}

function progressBetween(startMs: number, endMs: number, timeMs: number): number {
  const span = endMs - startMs;
  if (!(span > 0)) return timeMs >= startMs ? 1 : 0;
  const progress = (timeMs - startMs) / span;
  if (!(progress > 0)) return 0;
  return progress < 1 ? progress : 1;
}

function trimmed(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function joinLineTexts(lines: SandboxLine[]): string {
  return lines.map((line) => trimmed(line.text)).join('\n').trim();
}

function buildSyncedLines(source: SandboxLine[]): LyricsLine[] {
  const ordered = source
    .filter((line) => Number.isFinite(line.timeMs) && line.timeMs >= 0)
    .map((line, order) => ({ line, order }))
    .sort((a, b) => a.line.timeMs - b.line.timeMs || a.order - b.order)
    .map((entry) => entry.line);
  return ordered.map((line, index) => {
    const startMs = line.timeMs;
    const text = trimmed(line.text);
    return {
      startMs,
      endMs: Math.max(startMs + 1, nextDistinctStart(ordered, index, startMs) ?? startMs + LAST_LINE_DURATION_MS),
      text,
      translation: trimmed(line.translation) || null,
      words: normaliseWords(line.words, startMs, text),
    };
  });
}

function nextDistinctStart(lines: SandboxLine[], index: number, startMs: number): number | null {
  for (let i = index + 1; i < lines.length; i += 1) {
    const candidate = lines[i];
    if (candidate !== undefined && candidate.timeMs > startMs) return candidate.timeMs;
  }
  return null;
}

function normaliseWords(source: SandboxWord[], lineStartMs: number, lineText: string): LyricsWord[] {
  if (!Array.isArray(source) || source.length === 0) return [];
  const words: LyricsWord[] = [];
  for (const candidate of source) {
    if (!Number.isFinite(candidate.startMs)) continue;
    const startMs = Math.max(lineStartMs, candidate.startMs);
    const endMs = typeof candidate.endMs === 'number' && Number.isFinite(candidate.endMs)
      ? Math.max(startMs + 1, candidate.endMs)
      : null;
    words.push({ text: typeof candidate.text === 'string' ? candidate.text : '', startMs, endMs });
  }
  return alignWordsToText(words, lineText) ?? [];
}

/**
 * The current row is rendered from word spans, so the words must spell the line text. The host trims
 * every word, which loses inter-word spaces ("Hello" + "world" for "Hello world"); they are restored
 * from the line text. Words that do not spell the line at all yield null (whole-line progress).
 */
function alignWordsToText(words: LyricsWord[], lineText: string): LyricsWord[] | null {
  const joined = words.map((word) => word.text).join('');
  if (joined === lineText) return words;
  if (joined.replace(WHITESPACE_RUN, '') !== lineText.replace(WHITESPACE_RUN, '')) return null;
  let cursor = 0;
  return words.map((word) => {
    const start = cursor;
    let remaining = word.text.replace(WHITESPACE_RUN, '').length;
    while (cursor < lineText.length && remaining > 0) {
      if (!WHITESPACE_CHAR.test(lineText.charAt(cursor))) remaining -= 1;
      cursor += 1;
    }
    while (cursor < lineText.length && WHITESPACE_CHAR.test(lineText.charAt(cursor))) cursor += 1;
    return { text: lineText.slice(start, cursor), startMs: word.startMs, endMs: word.endMs };
  });
}

/**
 * Lyrics slot sizing for the expanded card. The view can paint current + next after the first
 * open measure; keep a following-row reserve so the slot does not lock to one line.
 */

export const LYRICS_LINE_MIN_PX = 8;

export function resolveLyricsOpenHeight(input: {
  cap: number;
  scrollHeight: number;
  rowHeights: number[];
  gap: number;
  expectNext: boolean;
  currentVisible?: boolean;
  estimatedCurrent: number;
  estimatedNext: number;
}): number {
  if (!(input.cap > 1)) return 0;
  // Before the first timestamp only the upcoming preview exists. Reserving a current row
  // here lifts the title over an empty line (and a one-line timeline would otherwise get 0).
  if (input.currentVisible === false) return Math.min(Math.max(0, input.rowHeights[1] ?? 0), input.cap);
  const currentH = input.rowHeights[0] ?? 0;
  if (!input.expectNext) return Math.min(Math.max(0, currentH), input.cap);
  const measuredRows = input.rowHeights.filter((height) => height > 0);
  const rows = measuredRows.reduce((sum, height) => sum + height, 0);
  const rowGap = input.gap * Math.max(0, measuredRows.length - 1);
  const reserved = Math.max(currentH, input.estimatedCurrent) + Math.max(input.rowHeights[1] ?? 0, input.estimatedNext) + input.gap;
  return Math.min(Math.max(0, input.scrollHeight, rows + rowGap, reserved), input.cap);
}

export function estimateLyricsLineHeight(row: HTMLElement | null, fallback: number): number {
  if (!row) return fallback;
  const text = row.querySelector<HTMLElement>('.lyrics__text');
  const style = getComputedStyle(text ?? row);
  const font = Number.parseFloat(style.fontSize) || 0;
  const line = Number.parseFloat(style.lineHeight) || font * 1.25;
  const min = Number.parseFloat(style.minHeight) || 0;
  return Math.max(font, Number.isFinite(line) ? line : 0, Number.isFinite(min) ? min : 0, fallback);
}

export function measureLyricsOpenHeight(card: HTMLElement, slot: HTMLElement, expectNext: boolean, view?: HTMLElement): number {
  const cap = card.offsetHeight * 0.42;
  if (cap <= 1) return 0;
  const lyrics = view ?? (slot.firstElementChild instanceof HTMLElement ? slot.firstElementChild : null);
  const prevSlotMax = slot.style.maxHeight;
  const prevSlotHeight = slot.style.height;
  const prevLyricsHeight = lyrics?.style.height ?? '';
  const prevLyricsOverflow = lyrics?.style.overflow ?? '';
  slot.style.maxHeight = `${cap}px`;
  slot.style.height = 'auto';
  if (lyrics) {
    lyrics.style.height = 'auto';
    lyrics.style.overflow = 'visible';
  }
  const current = lyrics?.querySelector<HTMLElement>('.lyrics__line--current') ?? null;
  const next = lyrics?.querySelector<HTMLElement>('.lyrics__line--next') ?? null;
  const gap = lyrics ? Number.parseFloat(getComputedStyle(lyrics).rowGap) || 0 : 0;
  const rowHeights: number[] = [];
  // CSS layout pixels, including fractions; client rects include the wall camera's scale.
  // offsetHeight would round off the bottom of the last line when the slot has no reserve.
  const rowHeight = (row: HTMLElement): number => row.hidden ? 0 : Number.parseFloat(getComputedStyle(row).height) || 0;
  if (current) rowHeights.push(rowHeight(current));
  if (next) rowHeights.push(rowHeight(next));
  const scrollHeight = Math.max(slot.scrollHeight, lyrics?.scrollHeight ?? 0);
  const height = !current && !next ? Math.min(cap, scrollHeight) : resolveLyricsOpenHeight({
    cap,
    scrollHeight,
    rowHeights,
    gap,
    expectNext,
    currentVisible: current !== null && !current.hidden,
    estimatedCurrent: estimateLyricsLineHeight(current, 40),
    estimatedNext: estimateLyricsLineHeight(next, 28),
  });
  slot.style.maxHeight = prevSlotMax;
  slot.style.height = prevSlotHeight;
  if (lyrics) {
    lyrics.style.height = prevLyricsHeight;
    lyrics.style.overflow = prevLyricsOverflow;
  }
  return height;
}

export function lyricsContentReady(slot: HTMLElement, expectNext: boolean): boolean {
  const root = slot.firstElementChild;
  if (!(root instanceof HTMLElement) || root.hidden) return false;
  if (root.querySelector('.lyrics__plain, .lyrics__instrumental')) return true;
  const current = root.querySelector<HTMLElement>('.lyrics__line--current');
  const next = root.querySelector<HTMLElement>('.lyrics__line--next');
  const currentText = current?.querySelector('.lyrics__text')?.textContent?.trim() ?? '';
  const nextText = next?.querySelector('.lyrics__text')?.textContent?.trim() ?? '';
  const currentReady = Boolean(current && currentText && current.offsetHeight >= LYRICS_LINE_MIN_PX);
  const nextReady = Boolean(next && nextText && next.offsetHeight >= LYRICS_LINE_MIN_PX);
  // Before the first line the upcoming lyric sits in the next row.
  if (!currentReady) return nextReady;
  return !expectNext || nextReady;
}

export function clearLyricsSlotSize(slot: HTMLElement): void {
  slot.style.height = '';
  slot.style.maxHeight = '';
}

export function commitLyricsSlotSize(slot: HTMLElement, height: number): void {
  slot.style.height = `${height}px`;
  slot.style.maxHeight = `${height}px`;
}

import type { ExpandedContent } from '../types.ts';

export const LYRICS_TRANSITION_TIMING = { duration: 950, easing: 'cubic-bezier(.22, 1, .36, 1)' };

/** One progress value owns the title's occupied height, its uniform size and the lyric slot.
 * Text keeps its line breaks while toggling; no per-frame font layout or endpoint FLIP. */
export function createLyricsTransition() {
  let content: ExpandedContent | null = null;
  let animation: Animation | null = null;
  let heightAnimation: Animation | null = null;
  let observer: ResizeObserver | null = null;

  function measureTitle(): void {
    const title = content?.meta.querySelector<HTMLElement>('.poster__title');
    if (!title || !content) return;
    let text = title.querySelector<HTMLElement>('.poster__title-text');
    if (!text) {
      text = document.createElement('span');
      text.className = 'poster__title-text';
      text.textContent = title.textContent;
      title.replaceChildren(text);
    }
    const large = Number.parseFloat(getComputedStyle(title).fontSize);
    // Resolve the existing responsive small size in the same query container.
    text.style.fontSize = 'clamp(40px, 7.6cqw, 69px)';
    const small = Number.parseFloat(getComputedStyle(text).fontSize);
    text.style.removeProperty('font-size');
    content.root.style.setProperty('--title-natural-height', getComputedStyle(text).height);
    content.root.style.setProperty('--title-open-scale', String(small / large));
  }

  function bind(next: ExpandedContent): void {
    if (content === next) return;
    reset();
    content = next;
    measureTitle();
    const text = next.meta.querySelector('.poster__title-text');
    if (text) {
      observer = new ResizeObserver(measureTitle);
      observer.observe(text);
    }
  }

  function fit(next: ExpandedContent, height: number, animate = false): void {
    bind(next);
    const root = next.root;
    const target = Number.parseFloat(root.style.getPropertyValue('--lyrics-open-height'));
    if (Math.abs(target - height) < 0.5) return;
    const style = getComputedStyle(root);
    const from = Number.parseFloat(style.getPropertyValue('--lyrics-open-height')) || 0;
    const open = Number.parseFloat(style.getPropertyValue('--lyrics-open')) || 0;
    // Retarget from the visible height, including when a seek interrupts the previous line.
    heightAnimation?.cancel();
    heightAnimation = null;
    root.style.setProperty('--lyrics-open-height', `${height}px`);
    if (!animate || open <= 0 || Math.abs(from - height) < 0.5) return;
    const effect = root.animate(
      [{ '--lyrics-open-height': `${from}px` }, { '--lyrics-open-height': `${height}px` }],
      LYRICS_TRANSITION_TIMING,
    );
    heightAnimation = effect;
    effect.onfinish = () => {
      if (heightAnimation !== effect) return;
      heightAnimation = null;
      effect.cancel();
    };
  }

  function finish(): void {
    animation?.finish();
    heightAnimation?.finish();
  }

  function toggle(next: ExpandedContent, open: boolean, reduced: boolean, onFinish?: () => void): void {
    bind(next);
    const root = next.root;
    const from = Number.parseFloat(getComputedStyle(root).getPropertyValue('--lyrics-open')) || 0;
    animation?.cancel();
    animation = null;
    const to = open ? 1 : 0;
    // The base style is the exact endpoint. Removing the effect never changes geometry.
    root.style.setProperty('--lyrics-open', String(to));
    if (reduced || from === to) {
      onFinish?.();
      return;
    }
    const effect = root.animate(
      [{ '--lyrics-open': String(from) }, { '--lyrics-open': String(to) }],
      LYRICS_TRANSITION_TIMING,
    );
    animation = effect;
    effect.onfinish = () => {
      if (animation !== effect) return;
      animation = null;
      effect.cancel();
      onFinish?.();
    };
  }

  function reset(): void {
    animation?.cancel();
    animation = null;
    heightAnimation?.cancel();
    heightAnimation = null;
    observer?.disconnect();
    observer = null;
    if (content) {
      for (const name of ['--lyrics-open', '--lyrics-open-height', '--title-natural-height', '--title-open-scale']) {
        content.root.style.removeProperty(name);
      }
    }
    content = null;
  }

  return { fit, toggle, reset, finish, get running() { return animation !== null; } };
}

/**
 * Lyrics layer for the expanded current-track card (SPEC §9): current / next rows with a
 * word-by-word highlight driven by `update(positionMs)`. The caller owns the rAF loop; this module never
 * schedules timers or frames. Styles live in `source/styles/40-lyrics.css`.
 */
import type { LyricsLine, LyricsTimeline, LyricsView, LyricsViewOptions } from '../types.ts';
import { findLineIndex } from './lyricsModel.ts';

const INTERLUDE_TEXT = '· · ·';
const INSTRUMENTAL_TEXT = '♪ 纯音乐';
const ENTRANCE_MS = 320;

type RowRole = 'current' | 'next';
type Row = { root: HTMLElement; text: HTMLElement; translation: HTMLElement };
type WordGlow = 'upcoming' | 'active' | 'sung';

export function createLyricsView(): LyricsView {
  const root = document.createElement('div');
  root.className = 'lyrics';
  root.hidden = true;

  const live = document.createElement('span');
  live.className = 'sr-only';
  live.setAttribute('aria-live', 'polite');

  const rows: Record<RowRole, Row> = {
    current: createRow('current'),
    next: createRow('next'),
  };

  let options: LyricsViewOptions = { showTranslation: true, reducedMotion: false };
  let lines: LyricsLine[] | null = null;
  let offsetMs = 0;
  let lineIndex = -1;
  let lastTimeMs = Number.NaN;
  let wordSpans: HTMLSpanElement[] = [];
  let lastGlow: WordGlow[] = [];
  let entrance: Animation | null = null;
  let disposed = false;
  let shownTimeline: LyricsTimeline | null = null;

  applyOptionAttributes();

  function applyOptionAttributes(): void {
    root.dataset.translation = String(options.showTranslation);
    root.dataset.reducedMotion = String(options.reducedMotion);
  }

  function resetSyncedState(): void {
    lines = null;
    offsetMs = 0;
    lineIndex = -1;
    lastTimeMs = Number.NaN;
    wordSpans = [];
    lastGlow = [];
    entrance?.cancel();
    entrance = null;
  }

  function setTimeline(timeline: LyricsTimeline | null): void {
    if (disposed || timeline === shownTimeline) return;
    shownTimeline = timeline;
    resetSyncedState();
    if (!timeline || timeline.kind === 'empty') {
      root.replaceChildren();
      root.hidden = true;
      return;
    }
    root.hidden = false;
    if (timeline.kind === 'instrumental') {
      root.replaceChildren(createBlock('lyrics__instrumental', INSTRUMENTAL_TEXT));
      return;
    }
    if (timeline.kind === 'plain') {
      const block = createBlock('lyrics__plain', timeline.text);
      // Lets the wall's wheel handler hand scrolling back to this block (see pointerPan.ts).
      block.dataset.scrollable = 'true';
      root.replaceChildren(block);
      return;
    }
    lines = timeline.lines;
    offsetMs = timeline.offsetMs;
    root.replaceChildren(live, rows.current.root, rows.next.root);
    renderRows(-1, false);
  }

  function setOptions(next: LyricsViewOptions): void {
    const changed = next.showTranslation !== options.showTranslation || next.reducedMotion !== options.reducedMotion;
    options = { showTranslation: next.showTranslation, reducedMotion: next.reducedMotion };
    if (!changed || disposed) return;
    applyOptionAttributes();
    if (lines === null) return;
    renderRows(lineIndex, false);
    if (Number.isFinite(lastTimeMs)) applyProgress(lastTimeMs);
  }

  function update(positionMs: number): boolean {
    if (lines === null) return false;
    const timeMs = positionMs + offsetMs;
    const animate = Number.isFinite(lastTimeMs) && root.isConnected;
    lastTimeMs = timeMs;
    const index = findLineIndex(lines, timeMs);
    const changed = index !== lineIndex;
    if (changed) renderRows(index, animate);
    const hideNext = index + 1 >= lines.length;
    const nextVisibilityChanged = rows.next.root.hidden !== hideNext;
    if (nextVisibilityChanged) rows.next.root.hidden = hideNext;
    applyProgress(timeMs);
    return changed || nextVisibilityChanged;
  }

  function hasFollowingLine(): boolean {
    if (lines === null) return false;
    if (lineIndex < 0) return lines.length > 1;
    return lineIndex + 1 < lines.length;
  }

  function renderRows(index: number, animate: boolean): void {
    if (lines === null) return;
    lineIndex = index;
    const current = index >= 0 ? lines[index] : undefined;
    renderPlainRow(rows.next, lines[index + 1]);
    renderCurrentRow(current);
    const announcement = current?.text ?? '';
    if (live.textContent !== announcement) live.textContent = announcement;
    if (animate && current !== undefined && !options.reducedMotion) playEntrance();
  }

  function renderPlainRow(row: Row, line: LyricsLine | undefined): void {
    row.root.hidden = line === undefined;
    row.text.textContent = line === undefined ? '' : line.text || INTERLUDE_TEXT;
    row.translation.textContent = line?.translation ?? '';
  }

  function renderCurrentRow(line: LyricsLine | undefined): void {
    wordSpans = [];
    lastGlow = [];
    rows.current.root.hidden = line === undefined;
    rows.current.translation.textContent = line?.translation ?? '';
    if (line === undefined) {
      rows.current.text.replaceChildren();
      return;
    }
    if (line.words.length === 0) {
      const span = createWordSpan(line.text || INTERLUDE_TEXT, true);
      wordSpans.push(span);
      rows.current.text.replaceChildren(span);
      return;
    }
    // Inline-block spans would swallow their own trailing spaces, so surrounding whitespace becomes text nodes.
    const nodes: Array<Node | string> = [];
    for (const word of line.words) {
      const core = word.text.trim();
      const leading = word.text.slice(0, word.text.length - word.text.trimStart().length);
      const trailing = word.text.slice(leading.length + core.length);
      if (leading) nodes.push(leading);
      const span = createWordSpan(core, false);
      wordSpans.push(span);
      nodes.push(span);
      if (trailing) nodes.push(trailing);
    }
    rows.current.text.replaceChildren(...nodes);
  }

  function applyProgress(timeMs: number): void {
    if (lines === null || lineIndex < 0) return;
    const line = lines[lineIndex];
    if (line === undefined) return;
    if (line.words.length === 0) {
      writeGlow(0, glowForLine(line, timeMs));
      return;
    }
    for (let i = 0; i < line.words.length; i += 1) writeGlow(i, glowForWord(line, i, timeMs));
  }

  function writeGlow(index: number, glow: WordGlow): void {
    if (lastGlow[index] === glow) return;
    lastGlow[index] = glow;
    const span = wordSpans[index];
    if (!span) return;
    span.classList.toggle('lyrics__word--active', glow === 'active');
    span.classList.toggle('lyrics__word--sung', glow === 'sung');
  }

  function playEntrance(): void {
    entrance?.cancel();
    entrance = rows.current.text.animate(
      [{ opacity: 0.35 }, { opacity: 1 }],
      { duration: ENTRANCE_MS, easing: 'ease-out' },
    );
  }

  function dispose(): void {
    if (disposed) return;
    disposed = true;
    shownTimeline = null;
    resetSyncedState();
    for (const row of Object.values(rows)) {
      row.text.replaceChildren();
      row.translation.textContent = '';
    }
    live.textContent = '';
    root.replaceChildren();
    root.hidden = true;
    root.remove();
  }

  return {
    element: root,
    setTimeline,
    setOptions,
    update,
    hasFollowingLine,
    get needsFrames(): boolean {
      return lines !== null;
    },
    dispose,
  };
}

function createRow(role: RowRole): Row {
  const root = document.createElement('div');
  root.className = `lyrics__line lyrics__line--${role}`;
  root.setAttribute('aria-hidden', 'true');
  const text = document.createElement('div');
  text.className = 'lyrics__text';
  const translation = document.createElement('div');
  translation.className = 'lyrics__translation';
  root.append(text, translation);
  return { root, text, translation };
}

function glowForLine(line: LyricsLine, timeMs: number): WordGlow {
  if (timeMs < line.startMs) return 'upcoming';
  if (timeMs >= line.endMs) return 'sung';
  return 'active';
}

function glowForWord(line: LyricsLine, index: number, timeMs: number): WordGlow {
  const word = line.words[index];
  if (!word || timeMs < word.startMs) return 'upcoming';
  const next = line.words[index + 1];
  if (next && timeMs >= next.startMs) return 'sung';
  const endMs = word.endMs ?? next?.startMs ?? line.endMs;
  if (!next && timeMs >= endMs) return 'sung';
  return 'active';
}

function createWordSpan(text: string, wholeLine: boolean): HTMLSpanElement {
  const span = document.createElement('span');
  span.className = wholeLine ? 'lyrics__word lyrics__word--line' : 'lyrics__word';
  span.textContent = text;
  return span;
}

function createBlock(className: string, text: string): HTMLElement {
  const block = document.createElement('div');
  block.className = className;
  block.textContent = text;
  return block;
}

import type { LibrarySource } from './host/librarySource.ts';
import { applyContext } from './host/context.ts';
import type { WallHostApi } from './host/api.ts';
import type {
  BootData,
  Camera,
  ExpandedContent,
  Instance,
  Lattice,
  LatticeSettings,
  LyricsTimeline,
  Point,
  RequiredCapability,
  Tile,
} from './types.ts';
import { createHostBridge } from './host/bridge.ts';
import { createPlaybackClock } from './host/clock.ts';
import {
  createLibraryTrackLoader,
  currentLibraryIndex,
  libraryPageNotice,
  libraryTrackTiles,
  playContextIds,
} from './host/libraryModel.ts';
import { applyAppearance, cellMetricsFor, resolveSettings, SETTING_IDS, settingEntries, wallExpandedScale, wallOverviewScale, wallVisualsFromSettings } from './host/settings.ts';
import { createControlPanel } from './controlPanel.ts';
import { createLattice } from './geometry/lattice.ts';
import { createSpreadLattice, reseatPlayingToSquare } from './geometry/tileSpread.ts';
import { createCamera } from './wall/camera.ts';
import { projectedCardBounds } from './wall/fisheye.ts';
import { createWallFrameLoop, INTERACTIVE_FRAME_MS } from './wall/frameLoop.ts';
import { attachPointerPan } from './wall/pointerPan.ts';
import { attachKeyboardNav } from './wall/keyboardNav.ts';
import { createPosterWall } from './wall/posterWall.ts';
import { createWallControls } from './wall/controls.ts';
import { buildLyricsTimeline } from './lyrics/lyricsModel.ts';
import {
  lyricsContentReady,
  measureLyricsOpenHeight,
} from './lyrics/lyricsSlot.ts';
import { createLyricsTransition } from './lyrics/lyricsTransition.ts';
import { createLyricsView } from './lyrics/lyricsView.ts';
import { createStateOverlay } from './stateOverlay.ts';
import { createWallOpening } from './wallOpening.ts';

const PANEL_TITLE = 'Lattice · 曲库拼贴墙';
const FLY_MS = 420;
const FOLLOW_FLY_MS = 520;
const FOCUS_MARGIN_PX = 40;

type PanelState = 'booting' | 'ready' | 'empty' | 'denied' | 'error';

const byId = <T extends HTMLElement>(id: string): T => {
  const element = document.getElementById(id);
  if (!element) throw new Error(`missing #${id}`);
  return element as T;
};


export const startLatticeLibraryWall = async (echo: WallHostApi, signal?: AbortSignal): Promise<() => void> => {
  const root = document.body;
  const opening = createWallOpening(root);
  let disposed = false;
  let wallAnimating = false;
  const frameIntervalMs = (): number => root.dataset.dragging !== 'true' && !camera.animating && !wallAnimating ? 33 : INTERACTIVE_FRAME_MS;
  const field = byId<HTMLDivElement>('field');
  const world = byId<HTMLDivElement>('world');
  const locate = byId<HTMLButtonElement>('locate');
  const stateEl = byId<HTMLElement>('state');
  const overlay = createStateOverlay(stateEl, byId<HTMLElement>('lattice'), opening.finish);
  const bridge = createHostBridge(echo);
  bridge.onError((message) => console.warn('[lattice-wall]', message));

  let state: PanelState = 'booting';
  const setState = (next: PanelState, detail?: { missing?: RequiredCapability[] }): void => {
    state = next;
    root.dataset.state = next;
    overlay.show(next, detail);
  };

  let boot: BootData;
  try {
    boot = await bridge.boot();
  } catch {
    if (!signal?.aborted) setState('denied', { missing: [] });
    else opening.finish();
    bridge.dispose();
    return () => undefined;
  }

  if (signal?.aborted) { opening.finish(); bridge.dispose(); return () => undefined; }

  applyContext(boot.context);
  opening.configure(boot.context);
  let context = boot.context;
  let settings: LatticeSettings = resolveSettings(boot.settings);
  applyAppearance(settings);
  let tiles: Tile[] = [];
  let currentIndex: number | null = null;
  let playingTrackId: string | null = boot.status?.currentTrackId ?? null;
  let pageLoaded = false;

  if (boot.missing.length > 0) {
    setState('denied', { missing: boot.missing });
    bridge.dispose();
    return () => undefined;
  }

  void bridge.requestPresentation(PANEL_TITLE, settings.immersive);

  // ---- long-lived collaborators -------------------------------------------------------------------
  const camera: Camera = createCamera();
  const clock = createPlaybackClock();
  const lyricsView = createLyricsView();
  let lattice: Lattice | null = null;
  let wallReady = false;
  let viewportReady = false;
  let expandedUiFor: string | null = null;
  let lyricsMountedFor: string | null = null;
  const lyricsTransition = createLyricsTransition();
  let lyricsCache: { trackId: string; timeline: LyricsTimeline } | null = null;
  let lyricsRequest: string | null = null;
  let lyricsOpenFrame = 0;
  let focused: Instance | null = null;
  let locateVisible = false;

  const now = (): number => performance.now();
  const currentTile = () => (currentIndex === null ? null : tiles[currentIndex] ?? null);
  const currentTrackId = (): string | null => clock.read(now()).trackId ?? currentTile()?.trackId ?? playingTrackId;
  const playTile = (tile: Tile): void => {
    const wallIndex = tiles.indexOf(tile);
    void bridge.playTrack(tile.trackId, wallIndex >= 0 ? playContextIds(tiles, wallIndex) : undefined);
  };

  // ---- frame loop --------------------------------------------------------------------------------
  const frames = createWallFrameLoop((time) => frame(time), frameIntervalMs, context.visible);
  const requestFrame = frames.request;

  const setLocateVisible = (visible: boolean): void => {
    if (visible === locateVisible) return;
    locateVisible = visible;
    locate.dataset.visible = String(visible);
  };

  /** The locate button is offered whenever the current track's expanded card is not on screen. */
  const updateLocate = (): void => {
    const expanded = wall.expanded;
    const currentOnScreen = expanded !== null
      && expanded.tileIndex === currentIndex
      && wall.expandedVisible(camera);
    setLocateVisible(state === 'ready' && currentIndex !== null && !currentOnScreen);
  };

  const frame = (time: number): boolean => {
    if (!wallReady || disposed) return false;
    const cameraChanged = camera.tick(time);
    if (cameraChanged) {
      world.style.transform = camera.transform();
      bridge.saveCamera({ x: camera.state.x, y: camera.state.y });
    }
    wallAnimating = wall.render(camera, time);
    const snapshot = clock.read(time);
    if (wall.expandedVisible(camera)) controls.update(snapshot);
    if (wall.expandedVisible(camera) && lyricsMountedFor !== null && lyricsView.needsFrames) {
      const rowsChanged = lyricsView.update(snapshot.positionSeconds * 1000);
      if (rowsChanged) {
        const content = wall.expandedContent();
        if (content) fitLyricsSlot(content);
      }
    }
    updateLocate();
    const playbackVisible = wall.expandedVisible(camera)
      && wall.expanded?.tileIndex === currentIndex
      && (!controls.controlsHidden || (lyricsMountedFor !== null && lyricsView.needsFrames));
    return camera.animating || wallAnimating || (clock.running && playbackVisible);
  };

  // ---- lyrics ------------------------------------------------------------------------------------
  const expectFollowingLyric = (): boolean => lyricsView.hasFollowingLine();

  const fitLyricsSlot = (content: ExpandedContent): void => {
    const card = content.root.closest<HTMLElement>('.poster');
    if (!card || card.dataset.lyrics !== 'true') return;
    lyricsTransition.fit(content, measureLyricsOpenHeight(card, content.lyrics, expectFollowingLyric()), !context.reducedMotion);
  };

  const unmountLyrics = (animate = false): void => {
    cancelAnimationFrame(lyricsOpenFrame);
    lyricsOpenFrame = 0;
    const content = wall.expandedContent();
    const card = content?.root.closest<HTMLElement>('.poster');
    if (animate && content && card) {
      card.dataset.lyrics = 'false';
      // Keep the mounted timeline and nodes through a reversal. Closing must not restart
      // the current line's entrance, replace its words, or stop its playback clock.
      lyricsTransition.toggle(content, false, context.reducedMotion, () => {
        lyricsMountedFor = null;
        lyricsView.element.remove();
      });
      return;
    }
    lyricsTransition.reset();
    lyricsMountedFor = null;
    lyricsView.setTimeline(null);
    lyricsView.element.remove();
    card?.removeAttribute('data-lyrics');
  };

  const setLyricsOpen = (content: ExpandedContent, open: boolean): void => {
    const card = content.root.closest<HTMLElement>('.poster');
    if (!card) return;
    if (card.dataset.lyrics === String(open)) {
      if (open) fitLyricsSlot(content);
      return;
    }
    lyricsView.update(clock.read(now()).positionSeconds * 1000);
    if (open) lyricsTransition.fit(content, measureLyricsOpenHeight(card, content.lyrics, expectFollowingLyric()), !context.reducedMotion);
    card.dataset.lyrics = String(open);
    lyricsTransition.toggle(content, open, context.reducedMotion, () => {
      if (open) fitLyricsSlot(content);
    });
  };

  const mountLyricsIfReady = (): void => {
    const expanded = wall.expanded;
    const tile = currentTile();
    if (!expanded || !tile || expanded.tileIndex !== currentIndex || !settings.showLyrics) return;
    if (expandedUiFor !== expanded.id) return;
    const content = wall.expandedContent();
    if (!content || !lyricsCache || lyricsCache.trackId !== tile.trackId) return;
    const hasLines = lyricsCache.timeline.kind !== 'empty';
    const card = content.root.closest<HTMLElement>('.poster');
    const settled = card?.dataset.settled === 'true';
    const openWhenLaidOut = (): void => {
      if (lyricsOpenFrame || !context.visible) return;
      const tryOpen = (attempts: number): void => {
        lyricsOpenFrame = requestAnimationFrame(() => {
          lyricsOpenFrame = 0;
          if (disposed || !context.visible || lyricsMountedFor !== expanded.id || !settings.showLyrics) return;
          if (wall.expandedContent() !== content) return;
          lyricsView.update(clock.read(now()).positionSeconds * 1000);
          if (!lyricsContentReady(content.lyrics, expectFollowingLyric()) && attempts < 24) {
            tryOpen(attempts + 1);
            return;
          }
          setLyricsOpen(content, true);
        });
      };
      tryOpen(0);
    };
    if (lyricsMountedFor === expanded.id) {
      if (!hasLines) setLyricsOpen(content, false);
      else if (settled && card?.dataset.lyrics !== 'true') openWhenLaidOut();
      return;
    }
    if (!hasLines) {
      setLyricsOpen(content, false);
      return;
    }
    lyricsMountedFor = expanded.id;
    lyricsView.setOptions({ showTranslation: settings.showTranslation, reducedMotion: context.reducedMotion });
    lyricsView.setTimeline(lyricsCache.timeline);
    content.lyrics.replaceChildren(lyricsView.element);
    lyricsView.update(clock.read(now()).positionSeconds * 1000);
    if (settled) openWhenLaidOut();
    requestFrame();
  };

  const ensureLyrics = (trackId: string): void => {
    if (lyricsCache?.trackId === trackId || lyricsRequest === trackId) return;
    lyricsRequest = trackId;
    void bridge.getLyrics(trackId).then((lyrics) => {
      if (disposed || lyricsRequest !== trackId) return;
      lyricsRequest = null;
      if (currentTrackId() !== trackId && currentTile()?.trackId !== trackId) return;
      lyricsCache = { trackId, timeline: buildLyricsTimeline(lyrics) };
      mountLyricsIfReady();
    });
  };

  // ---- expansion ---------------------------------------------------------------------------------
  const expandedRectOf = (instance: Instance): Instance =>
    lattice!.instanceAt(instance.bc, instance.br, instance.slot, instance);

  const overviewScale = (): number => wallOverviewScale(camera.viewport.width);
  const expandedScale = (): number => wallExpandedScale(camera.viewport.width);
  const cameraScale = (): number => (wall.expanded ? expandedScale() : overviewScale());

  const mountExpandedUi = (): void => {
    const expanded = wall.expanded;
    if (!expanded) return;
    const content: ExpandedContent | null = wall.expandedContent();
    if (!content) return;
    const isCurrent = expanded.tileIndex === currentIndex;
    if (expandedUiFor !== expanded.id) {
      expandedUiFor = expanded.id;
      controls.setControlsHidden(false);
    }
    controls.mountExpanded(content.controls, isCurrent ? 'current' : 'other');
    if (isCurrent) {
      const tile = currentTile();
      if (tile && settings.showLyrics) {
        ensureLyrics(tile.trackId);
        mountLyricsIfReady();
      }
    } else {
      unmountLyrics();
    }
  };

  const reseatPlayingNear = (near: Point): void => {
    if (!lattice || currentIndex === null || tiles.length === 0) return;
    const playingAt = lattice.nearestInstance(currentIndex, near, null);
    lattice = createLattice(tiles.length, lattice.metrics, reseatPlayingToSquare(lattice, playingAt, currentIndex));
    wall.setLattice(lattice, tiles, { followTiles: true });
    wall.setCurrent(currentIndex);
  };

  const expand = (instance: Instance, flyMs = FLY_MS): void => {
    if (!lattice) return;
    const same = wall.expanded?.id === instance.id;
    if (!same) {
      const previous = wall.expanded;
      const targetTile = instance.tileIndex;
      const targetNear = lattice.centerOf(instance.rect);
      unmountLyrics();
      controls.unmountExpanded();
      expandedUiFor = null;
      if (currentIndex !== null && targetTile !== currentIndex) {
        reseatPlayingNear(previous ? lattice.centerOf(previous.rect) : { x: camera.state.x, y: camera.state.y });
        instance = lattice.nearestInstance(targetTile, targetNear, null);
      }
      wall.setExpanded(instance);
    }
    focused = wall.expanded ?? instance;
    wall.setFocus(focused);
    const target = lattice.centerOf(expandedRectOf(instance).rect);
    camera.flyTo({ x: target.x, y: target.y, scale: expandedScale() }, context.reducedMotion ? 0 : flyMs);
    mountExpandedUi();
    requestFrame();
  };

  const collapse = (options?: { reshuffle?: boolean }): void => {
    if (!wall.expanded || !lattice) return;
    const expanded = wall.expanded;
    const playing = currentIndex !== null && expanded.tileIndex === currentIndex;
    const near = lattice.centerOf(expanded.rect);
    unmountLyrics();
    controls.unmountExpanded();
    expandedUiFor = null;
    wall.setExpanded(null);
    wall.setFocus(null);
    focused = null;
    field.focus({ preventScroll: true });
    const overview = overviewScale();
    if (options?.reshuffle !== false && currentIndex !== null && tiles.length > 0) {
      const playingAt = lattice.nearestInstance(currentIndex, near, null);
      reseatPlayingNear(near);
      const landed = lattice.nearestInstance(currentIndex, lattice.centerOf(playingAt.rect), null);
      if (playing) {
        camera.flyTo(
          { x: lattice.centerOf(landed.rect).x, y: lattice.centerOf(landed.rect).y, scale: overview },
          context.reducedMotion ? 0 : 300,
        );
      } else if (Math.abs(camera.state.scale - overview) > 0.01) {
        camera.flyTo({ x: camera.state.x, y: camera.state.y, scale: overview }, context.reducedMotion ? 0 : 300);
      }
    } else if (Math.abs(camera.state.scale - overview) > 0.01) {
      camera.flyTo({ x: camera.state.x, y: camera.state.y, scale: overview }, context.reducedMotion ? 0 : 300);
    }
    requestFrame();
  };

  const revealInstance = (instance: Instance, durationMs: number): void => {
    if (!lattice) return;
    const rect = lattice.toPixels(instance.rect);
    if (camera.fisheye) {
      const screen = projectedCardBounds(rect, camera);
      if (screen.x < FOCUS_MARGIN_PX || screen.y < FOCUS_MARGIN_PX
        || screen.x + screen.w > camera.viewport.width - FOCUS_MARGIN_PX
        || screen.y + screen.h > camera.viewport.height - FOCUS_MARGIN_PX) {
        camera.flyTo(lattice.centerOf(instance.rect), context.reducedMotion ? 0 : durationMs);
        requestFrame();
      }
      return;
    }
    const bounds = camera.bounds();
    const margin = FOCUS_MARGIN_PX / camera.state.scale;
    let dx = 0;
    let dy = 0;
    if (rect.x - margin < bounds.x) dx = rect.x - margin - bounds.x;
    else if (rect.x + rect.w + margin > bounds.x + bounds.w) dx = rect.x + rect.w + margin - (bounds.x + bounds.w);
    if (rect.y - margin < bounds.y) dy = rect.y - margin - bounds.y;
    else if (rect.y + rect.h + margin > bounds.y + bounds.h) dy = rect.y + rect.h + margin - (bounds.y + bounds.h);
    if (dx !== 0 || dy !== 0) {
      camera.flyTo({ x: camera.state.x + dx, y: camera.state.y + dy }, context.reducedMotion ? 0 : durationMs);
      requestFrame();
    }
  };

  const focusCurrent = (flyMs: number): void => {
    if (!lattice || currentIndex === null) return;
    const instance = lattice.nearestInstance(currentIndex, camera.state, wall.expanded);
    expand(instance, flyMs);
  };

  // ---- wall / controls ---------------------------------------------------------------------------
  const wall = createPosterWall(world, {
    onRenderNeeded: requestFrame,
    onEntranceComplete: opening.finish,
    onActivate: (instance) => expand(instance),
    onFocusChange: (instance) => { focused = instance; },
    onExpandSettled: () => mountExpandedUi(),
    onHoverCurrent: () => {
      const tile = currentTile();
      if (tile && settings.showLyrics) ensureLyrics(tile.trackId);
    },
    onExpandedTap: () => { controls.setControlsHidden(!controls.controlsHidden); requestFrame(); },
  });

  let shuffleEnabled = boot.status?.shuffleEnabled === true || boot.queue?.shuffleEnabled === true;
  let repeatOne = boot.status?.repeatMode === 'one' || boot.queue?.repeatMode === 'one';
  const controls = createWallControls({
    play: () => void bridge.play(),
    pause: () => void bridge.pause(),
    next: () => void bridge.next(),
    previous: () => void bridge.previous(),
    seek: (seconds) => {
      clock.seek(seconds, now());
      void bridge.seek(seconds);
      requestFrame();
    },
    playThis: () => {
      const expanded = wall.expanded;
      const tile = expanded ? tiles[expanded.tileIndex] : null;
      if (tile) playTile(tile);
    },
    toggleLyrics: () => {
      const next = !settings.showLyrics;
      settings = { ...settings, showLyrics: next };
      controls.setLyricsVisible(next);
      void bridge.setSetting(SETTING_IDS.showLyrics, next);
      if (!next) unmountLyrics(true);
      else mountExpandedUi();
    },
    toggleShuffle: () => {
      shuffleEnabled = !shuffleEnabled;
      controls.setShuffleEnabled(shuffleEnabled);
      void bridge.toggleShuffle();
    },
    toggleRepeatOne: () => {
      repeatOne = !repeatOne;
      controls.setRepeatOne(repeatOne);
      void bridge.setRepeat(repeatOne ? 'one' : 'off');
    },
  });
  controls.setLyricsVisible(settings.showLyrics);
  controls.setShuffleEnabled(shuffleEnabled);
  controls.setRepeatOne(repeatOne);

  const applyVisuals = (): void => {
    camera.setFisheye(settings.fisheye, !context.reducedMotion);
    applyAppearance(settings);
    wall.setVisualOptions(wallVisualsFromSettings(settings, context.reducedMotion));
    lyricsView.setOptions({ showTranslation: settings.showTranslation, reducedMotion: context.reducedMotion });
    if (context.reducedMotion) lyricsTransition.finish();
    const content = wall.expandedContent();
    if (content) fitLyricsSlot(content);
    requestFrame();
  };

  // ---- lattice lifecycle -------------------------------------------------------------------------
  const rebuildLattice = (): void => {
    if (tiles.length === 0) return;
    const previousUnit = lattice?.unit ?? null;
    lattice = createSpreadLattice(tiles, cellMetricsFor(settings.cellSize));
    if (previousUnit !== null && previousUnit !== lattice.unit) {
      const ratio = lattice.unit / previousUnit;
      camera.setCenter(camera.state.x * ratio, camera.state.y * ratio);
      world.style.transform = camera.transform();
    }
    const hadExpanded = wall.expanded;
    wall.setLattice(lattice, tiles);
    wall.setCurrent(currentIndex);
    if (hadExpanded && !wall.expanded) {
      unmountLyrics();
      controls.unmountExpanded();
      expandedUiFor = null;
    }
    requestFrame();
  };

  const initialCamera = (): void => {
    if (!lattice) return;
    if (currentIndex !== null) {
      const instance = lattice.nearestInstance(currentIndex, { x: 0, y: 0 }, null);
      const centre = lattice.centerOf(expandedRectOf(instance).rect);
      camera.setCenter(centre.x, centre.y);
      camera.setScale(expandedScale());
      world.style.transform = camera.transform();
      wall.setExpanded(instance);
      focused = wall.expanded;
      wall.setFocus(focused);
      mountExpandedUi();
      return;
    }
    const first = lattice.nearestInstance(0, boot.camera ?? { x: 0, y: 0 }, null);
    const centre = lattice.centerOf(first.rect);
    camera.setCenter(centre.x, centre.y);
    camera.setScale(overviewScale());
    world.style.transform = camera.transform();
    focused = first;
    wall.setFocus(first);
  };

  const enterReady = (): void => {
    if (!viewportReady || !pageLoaded || tiles.length === 0) return;
    try {
      rebuildLattice();
      applyVisuals();
      initialCamera();
      wallReady = true;
      setState('ready');
      if (!context.desktop) wall.playEntrance(now());
      requestFrame();
    } catch (error) {
      wallReady = false;
      setState('error');
      console.warn('[lattice-wall] failed to render', error);
    }
  };

  const applyPlayingTrack = (trackId: string | null, follow: boolean): void => {
    playingTrackId = trackId;
    const nextIndex = currentLibraryIndex(tiles, trackId);
    const changed = nextIndex !== currentIndex;
    currentIndex = nextIndex;
    if (wallReady) wall.setCurrent(currentIndex);
    if (!changed) {
      mountExpandedUi();
      return;
    }
    if (lyricsCache && lyricsCache.trackId !== currentTile()?.trackId) {
      lyricsCache = null;
      unmountLyrics();
    }
    if (follow && settings.autoFocus && currentIndex !== null) focusCurrent(FOLLOW_FLY_MS);
    else mountExpandedUi();
  };

  const overlayCopy = (title: string, body: string): void => {
    const heading = stateEl.querySelector('h2');
    const paragraph = stateEl.querySelector('p');
    if (heading) heading.textContent = title;
    if (paragraph) paragraph.textContent = body;
  };

  const loader = createLibraryTrackLoader((query) => echo.library.getTracks(query));
  const loadPage = async (page: number, search: string, source: LibrarySource = 'local'): Promise<void> => {
    collapse({ reshuffle: false });
    wallReady = false;
    pageLoaded = false;
    tiles = [];
    currentIndex = null;
    wall.clear();
    lattice = null;
    setLocateVisible(false);
    browser.loading(page);
    overlay.setNotice(null);
    setState('booting');
    overlayCopy('正在读取曲库', '从 ECHO 曲库加载歌曲…');
    try {
      const result = await loader.load(page, search, source);
      if (!result || disposed) return;
      browser.update(result);
      tiles = libraryTrackTiles(result.items, result.page);
      currentIndex = currentLibraryIndex(tiles, playingTrackId);
      if (tiles.length === 0) {
        setState('empty');
        overlayCopy(
          search ? '没有找到歌曲' : '曲库中还没有歌曲',
          search ? '打开功能面板修改关键词，或清空搜索。' : '在 ECHO 中导入音乐后，打开功能面板并刷新。',
        );
        return;
      }
      pageLoaded = true;
      if (viewportReady) enterReady();
      overlay.setNotice(libraryPageNotice(result));
    } catch {
      if (disposed) return;
      browser.error();
      setState('empty');
      overlayCopy('暂时无法读取曲库', '打开功能面板并刷新重试；如尚未授权，请在 Workshop → 已安装 中确认读取曲库权限。');
    }
  };
  const commitSettings = (previous: LatticeSettings, persist: Partial<LatticeSettings> | null): void => {
    if (settings.cellSize !== previous.cellSize && state === 'ready') rebuildLattice();
    if (settings.immersive !== previous.immersive) void bridge.requestPresentation(PANEL_TITLE, settings.immersive);
    applyVisuals();
    if (settings.showLyrics !== previous.showLyrics) {
      if (settings.showLyrics) mountExpandedUi();
      else unmountLyrics(true);
    }
    controls.setLyricsVisible(settings.showLyrics);
    browser.syncSettings(settings);
    if (persist) {
      for (const [id, value] of settingEntries(persist)) void bridge.setSetting(id, value);
    }
  };
  const patchSettings = (patch: Partial<LatticeSettings>): void => {
    const previous = settings;
    settings = { ...settings, ...patch };
    commitSettings(previous, patch);
  };
  const browser = createControlPanel(root.querySelector<HTMLElement>('#lattice')!, {
    speed: echo.speed,
    desktop: echo.desktop,
    wall: 'library',
    settings,
    lyrics: true,
    search: {
      placeholder: '输入歌曲或艺术家',
      searchLabel: '搜索歌曲',
      unit: '首',
    },
    onLoad: (page, search, source) => { void loadPage(page, search, source); },
    onSwitchWall: (target) => {
      if (target !== 'albums') return;
      void bridge.openPanel('albums');
    },
    onPatchSettings: patchSettings,
  });

  // ---- input -------------------------------------------------------------------------------------
  const onLocate = (): void => focusCurrent(FLY_MS);
  locate.addEventListener('click', onLocate);

  const pointer = attachPointerPan(field, {
    projectPointer: (x, y) => wall.pointerPoint(x, y),
    onPan: (dx, dy) => { camera.panBy(dx, dy); requestFrame(); },
    onFling: (vx, vy) => { camera.fling(vx, vy); requestFrame(); },
    onTap: () => undefined,
    onWheel: (dx, dy) => { camera.panBy(-dx, -dy); frames.requestInteractive(); },
    onDragStart: () => { root.dataset.dragging = 'true'; },
    onDragEnd: () => { delete root.dataset.dragging; requestFrame(); },
  });

  const keyboard = attachKeyboardNav(root, {
    move: (direction) => {
      if (!lattice || !wallReady) return;
      const from = focused ?? lattice.cull(camera.bounds(), 0, wall.expanded, 1)[0];
      if (!from) return;
      const next = lattice.neighbor(from, direction, wall.expanded);
      focused = next;
      wall.setFocus(next);
      revealInstance(next, 260);
    },
    activate: () => {
      if (!focused) { focusCurrent(FLY_MS); return; }
      if (wall.expanded && wall.expanded.id === focused.id) {
        if (focused.tileIndex === currentIndex) {
          if (clock.read(now()).state === 'playing') void bridge.pause(); else void bridge.play();
        } else {
          const tile = tiles[focused.tileIndex];
          if (tile) playTile(tile);
        }
        return;
      }
      expand(focused);
    },
    secondary: () => {
      if (!focused) { focusCurrent(FLY_MS); return; }
      if (wall.expanded && wall.expanded.id === focused.id) {
        controls.setControlsHidden(!controls.controlsHidden);
        requestFrame();
      }
      else expand(focused);
    },
    escape: () => {
      if (wall.expanded) collapse();
      else void bridge.closePanel();
    },
    focusCurrent: () => focusCurrent(FLY_MS),
    toggle: (setting) => {
      const patch: Partial<LatticeSettings> = {};
      if (settings.lightingMode === 'daytime') patch.lightingMode = 'spotlight';
      if (setting === 'lights-out') patch.lightsOut = !settings.lightsOut;
      if (setting === 'vignette') patch.vignette = !settings.vignette;
      if (setting === 'tint') patch.posterTint = !settings.posterTint;
      patchSettings(patch);
    },
    seekBy: (delta) => {
      if (!controls.seekFocused) return false;
      const snapshot = clock.read(now());
      const limit = snapshot.durationSeconds > 0 ? snapshot.durationSeconds : Number.POSITIVE_INFINITY;
      const target = Math.max(0, Math.min(limit, snapshot.positionSeconds + delta));
      clock.seek(target, now());
      void bridge.seek(target);
      requestFrame();
      return true;
    },
  });

  // ---- host events -------------------------------------------------------------------------------
  if (boot.status) clock.ingest(boot.status, now());

  const unsubscribe = [
    bridge.onPlaybackStatus((status) => {
      const before = clock.read(now()).trackId;
      clock.ingest(status, now());
      if (status.currentTrackId !== before) applyPlayingTrack(status.currentTrackId ?? null, true);
      if (status.currentTrackId !== before && status.currentTrackId && settings.showLyrics && wall.expanded?.tileIndex === currentIndex) {
        ensureLyrics(status.currentTrackId);
      }
      if (status.shuffleEnabled === true || status.shuffleEnabled === false) {
        shuffleEnabled = status.shuffleEnabled;
        controls.setShuffleEnabled(shuffleEnabled);
      }
      if (status.repeatMode === 'off' || status.repeatMode === 'one' || status.repeatMode === 'all') {
        repeatOne = status.repeatMode === 'one';
        controls.setRepeatOne(repeatOne);
      }
      requestFrame();
    }),
    echo.events.on('library:changed', () => {
      overlay.setNotice('曲库已更新，打开功能面板即可刷新');
    }),
    bridge.onContextChanged((next) => {
      const reducedChanged = next.reducedMotion !== context.reducedMotion;
      context = next;
      applyContext(next);
      if (reducedChanged) applyVisuals();
      frames.setVisible(next.visible);
      if (next.visible) mountExpandedUi();
      else {
        cancelAnimationFrame(lyricsOpenFrame);
        lyricsOpenFrame = 0;
      }
    }),
    bridge.onSettingsChanged((values) => {
      const previous = settings;
      settings = resolveSettings(values);
      commitSettings(previous, null);
    }),
  ];

  // ---- viewport ----------------------------------------------------------------------------------
  const resize = new ResizeObserver((entries) => {
    const entry = entries[0];
    if (!entry) return;
    const { width, height } = entry.contentRect;
    if (width < 1 || height < 1) return;
    camera.setViewport(width, height);
    world.style.transform = camera.transform();
    if (!viewportReady) {
      viewportReady = true;
      if (pageLoaded) enterReady();
    } else if (state === 'ready' && !camera.animating) {
      camera.setScale(cameraScale());
      world.style.transform = camera.transform();
    }
    requestFrame();
  });
  resize.observe(field);
  void loadPage(1, '');

  const dispose = (): void => {
    if (disposed) return;
    disposed = true;
    opening.finish();
    wallReady = false;
    frames.dispose();
    cancelAnimationFrame(lyricsOpenFrame);
    lyricsOpenFrame = 0;
    window.removeEventListener('pagehide', dispose);
    signal?.removeEventListener('abort', dispose);
    lyricsRequest = null;
    lyricsCache = null;
    lyricsMountedFor = null;
    camera.stop();
    lattice = null;
    for (const stop of unsubscribe) stop();
    locate.removeEventListener('click', onLocate);
    pointer.dispose();
    keyboard.dispose();
    browser.dispose();
    loader.cancel();
    resize.disconnect();
    wall.dispose();
    controls.dispose();
    lyricsTransition.reset();
    lyricsView.dispose();
    bridge.dispose();
    tiles = [];
  };
  window.addEventListener('pagehide', dispose, { once: true });
  signal?.addEventListener('abort', dispose, { once: true });
  if (signal?.aborted) dispose();
  return dispose;
};

import type { RequiredCapability } from './types.ts';

export type StateOverlay = {
  show(state: 'booting' | 'ready' | 'empty' | 'denied' | 'error', detail?: { missing?: RequiredCapability[] }): void;
  /** Small persistent chip at the bottom (e.g. the 500-item truncation hint); null hides it. */
  setNotice(text: string | null): void;
};

const CAPABILITY_LABELS: Record<RequiredCapability, string> = {
  'library:read': '读取曲库',
  'playback:read': '读取播放状态',
  'playback:control': '控制播放',
  'queue:read': '读取播放队列',
  'queue:control': '播放歌曲',
  'lyrics:read': '读取歌词',
  'fs:plugin': '保存插件设置',
};

const message = (title: string, body: string): [HTMLElement, HTMLElement] => {
  const heading = document.createElement('h2');
  heading.className = 'state__title';
  heading.textContent = title;
  const paragraph = document.createElement('p');
  paragraph.className = 'state__body';
  paragraph.textContent = body;
  return [heading, paragraph];
};

export const createStateOverlay = (container: HTMLElement, host: HTMLElement, onUnavailable?: () => void): StateOverlay => {
  let notice: HTMLElement | null = null;
  return {
    show(state, detail) {
      container.replaceChildren();
      if (state === 'ready') {
        container.hidden = true;
        return;
      }
      if (state !== 'booting') onUnavailable?.();
      container.hidden = false;
      container.dataset.state = state;
      if (state === 'booting') {
        container.append(...message('正在连接 ECHO', '等待宿主返回曲库…'));
        return;
      }
      if (state === 'empty') {
        container.append(...message('曲库中还没有歌曲', '在 ECHO 中导入音乐后，打开功能面板并刷新。'));
        return;
      }
      if (state === 'error') {
        container.append(...message('拼贴墙加载失败', '请关闭拼贴墙后重试。'));
        return;
      }
      const missing = detail?.missing ?? [];
      const names = missing.length > 0
        ? missing.map((capability) => `${CAPABILITY_LABELS[capability]}（${capability}）`).join('、')
        : '与 ECHO 的连接';
      container.append(...message('拼贴墙缺少必要能力', `未批准：${names}。请在 Workshop → 已安装 中重新确认权限。`));
    },
    setNotice(text) {
      if (text === null) {
        notice?.remove();
        notice = null;
        return;
      }
      if (!notice) {
        notice = document.createElement('div');
        notice.className = 'notice';
        notice.setAttribute('role', 'note');
        host.append(notice);
      }
      notice.textContent = text;
    },
  };
};

/**
 * Shared contracts for the Lattice Wall panel.
 *
 * Every module exposes a `create*()` factory that returns one of the interfaces below; `main.ts` only
 * composes these interfaces. Keep this file free of runtime code so parallel modules never depend on
 * each other's implementation details. Host API types (`EchoWorkshop*`) come from the global SDK
 * declaration file `.echo-sdk/echo-workshop-plugin.d.ts`, which `tsconfig.json` includes.
 *
 * Node runs these sources directly for tests (type stripping), so: no `enum`, no `namespace`, no
 * constructor parameter properties, and always import with explicit `.ts` extensions.
 */

// ---------------------------------------------------------------------------------------------------
// Queue model
// ---------------------------------------------------------------------------------------------------

/** One queue entry, already sanitized by the host and reduced to what the wall renders. */
export type Tile = {
  /** 0-based position in the (possibly host-truncated) queue. */
  index: number;
  queueId: string;
  trackId: string;
  title: string;
  artist: string;
  album: string;
  /** `echo-cover:` URL or null; null renders the hashed two-colour fallback. */
  coverUrl: string | null;
  durationSeconds: number;
  /** Present for library album cards; queue cards keep their queueId playback identity. */
  albumId?: string;
};

export type QueueModel = {
  tiles: Tile[];
  /** Index into `tiles` of the item matching `currentQueueId`, or null. */
  currentIndex: number | null;
  currentQueueId: string | null;
  /** True when the host handed us its 500-item cap; the wall shows the truncation hint. */
  truncated: boolean;
};

/** What changed between two queue snapshots; drives follow-current and re-layout decisions. */
export type QueueDiff = {
  /** Tile ids or order changed, so the lattice must be rebuilt with the new tile count/order. */
  tilesChanged: boolean;
  /** `currentIndex` changed (including null transitions). */
  currentChanged: boolean;
};

// ---------------------------------------------------------------------------------------------------
// Geometry
// ---------------------------------------------------------------------------------------------------

/**
 * Solver-generated blocks (see `scripts/generate-reflows.mjs`), with the same 8-cell average card area
 * as the old 12×8. Each block holds 30 slots; a 2×2 minimum cell keeps repeated covers apart.
 */
export const BLOCK_COLS = 20;
export const BLOCK_ROWS = 12;
export const SLOTS_PER_BLOCK = 30;
export const EXPANDED_SIZE = 6;
export const TEMPLATE_COUNT = 5;

/** Rectangle in grid units. `col`/`row` may be negative in world space. */
export type GridRect = { col: number; row: number; w: number; h: number };
/** Rectangle in world pixels. */
export type PixelRect = { x: number; y: number; w: number; h: number };
export type Point = { x: number; y: number };
/** Pixel metrics: side of one grid cell and the gap between cells. */
export type Metrics = { cell: number; gap: number };
/** Block mirror: 0 = as designed, 1 = horizontal flip, 2 = vertical flip, 3 = both. */
export type Mirror = 0 | 1 | 2 | 3;
export type Direction = 'left' | 'right' | 'up' | 'down';

/**
 * A rendered occurrence of a tile. The plane is tiled periodically by a "cell": a full rectangle of
 * `blocksPerCell = cellCols × cellRows` blocks where `cellCols = ceil(sqrt(ceil(tileCount / 12)))` and
 * `cellRows = ceil(ceil(tileCount / 12) / cellCols)`. By default block `b` shows tiles
 * `(12·b + slot) mod tileCount`. The library wall replaces that identity map with a cover-aware
 * spread so identical artwork is not packed into neighbouring slots; leftover slots in the cell
 * still become extra copies, and the same assignment repeats in every periodic cell.
 */
export type Instance = {
  /** `${cellSlot}:${repeatX}:${repeatY}` — stable identity of this occurrence. */
  id: string;
  /** `blockInCell * 12 + slot`. */
  cellSlot: number;
  blockInCell: number;
  /** 0..11 slot inside the block template. */
  slot: number;
  /** Which periodic copy of the cell this instance belongs to (any integer). */
  repeatX: number;
  repeatY: number;
  /** World block coordinates: `bc = repeatX * cellCols + blockInCell % cellCols`, likewise `br`. */
  bc: number;
  br: number;
  /** Index into `QueueModel.tiles`. */
  tileIndex: number;
  /** World grid rect (already includes the block offset `bc * 12`, `br * 8`). */
  rect: GridRect;
};

/**
 * Pure geometry of the infinite wall for a fixed tile count and pixel metrics. Implemented in
 * `geometry/lattice.ts` (`createLattice`). All methods are deterministic and allocation-light; the
 * wall calls `cull` at most once per re-cull, never per frame.
 */
export type Lattice = {
  readonly tileCount: number;
  readonly metrics: Metrics;
  readonly blocksPerCell: number;
  readonly cellCols: number;
  readonly cellRows: number;
  /** World pixel size of one periodic cell. */
  readonly cellPixelSize: { w: number; h: number };
  /** Grid unit in pixels: `cell + gap`. */
  readonly unit: number;
  /** Pixel rect of a grid rect: `x = col·unit`, `w = w·cell + (w − 1)·gap`. */
  toPixels(rect: GridRect): PixelRect;
  /** Pixel centre of a grid rect. */
  centerOf(rect: GridRect): Point;
  /**
   * All 12 instances of world block `(bc, br)`. When `expanded` lies in this block, the block uses the
   * pre-solved reflow table so `expanded.slot` becomes 6×6 and the other 11 cards move; otherwise the
   * hashed template + mirror layout applies. Slot order is preserved in both cases.
   */
  blockInstances(bc: number, br: number, expanded: Instance | null): Instance[];
  /** Single instance of a block slot (same layout rules as `blockInstances`). */
  instanceAt(bc: number, br: number, slot: number, expanded: Instance | null): Instance;
  /**
   * Instances whose pixel rect intersects `bounds` grown by `overscan` px on every side, ordered
   * nearest-to-bounds-centre first and capped at `limit` (default 250).
   */
  cull(bounds: PixelRect, overscan: number, expanded: Instance | null, limit?: number): Instance[];
  /** The occurrence of `tileIndex` whose centre is closest to `point` (world px). */
  nearestInstance(tileIndex: number, point: Point, expanded: Instance | null): Instance;
  /** Rebuild an instance from its id (layout may differ depending on `expanded`); null if malformed. */
  fromId(id: string, expanded: Instance | null): Instance | null;
  /**
   * Keyboard neighbour: the instance in the same or an adjacent block whose centre lies in
   * `direction` from `from` and minimises a direction-weighted distance. Never returns `from`.
   */
  neighbor(from: Instance, direction: Direction, expanded: Instance | null): Instance;
  /** Convenience: does `instance` belong to the block that hosts `expanded`? */
  sameBlock(a: Instance, b: Instance): boolean;
};

// ---------------------------------------------------------------------------------------------------
// Camera
// ---------------------------------------------------------------------------------------------------

/** World-pixel point shown at the viewport centre plus zoom. */
export type CameraState = { x: number; y: number; scale: number };

/** Implemented in `wall/camera.ts` (`createCamera`). Owns pan/fling/fly animation; no DOM. */
export type Camera = {
  readonly state: Readonly<CameraState>;
  readonly fisheye: boolean;
  readonly fisheyeAmount: number;
  setFisheye(enabled: boolean, animate?: boolean): void;
  /** Viewport size in CSS px; main updates it on resize. */
  setViewport(width: number, height: number): void;
  readonly viewport: Readonly<{ width: number; height: number }>;
  /** Instant moves; cancel any animation. */
  setCenter(x: number, y: number): void;
  setScale(scale: number): void;
  /** Eased flight (ease-out cubic) to a target centre and optional scale. `durationMs` 0 = instant. */
  flyTo(target: { x: number; y: number; scale?: number }, durationMs: number): void;
  /** Pan by screen pixels (divides by scale internally); cancels flight and inertia. */
  panBy(dx: number, dy: number): void;
  /** Start inertia with a screen-space velocity in px/s; exponential decay, stops below 5 px/s. */
  fling(vx: number, vy: number): void;
  stop(): void;
  /** Advance flight/inertia. Returns true when the state changed this frame. */
  tick(nowMs: number): boolean;
  readonly animating: boolean;
  /** Visible world rect (px) for the current state. */
  bounds(): PixelRect;
  screenToWorld(px: number, py: number): Point;
  worldToScreen(x: number, y: number): Point;
  /** Local card transform; includes the optional screen-centred lens projection. */
  cardTransform(rect: PixelRect): string;
  /** CSS transform for `.world` with `transform-origin: 0 0`. */
  transform(): string;
};

