  shuffle: `${SVG_OPEN}<path d="M10.59 9.17 5.41 4 4 5.41l5.17 5.17 1.42-1.41zm3.91-5.17 2.04 2.04L4 18.59 5.41 20 17.96 7.46 20 9.5V4h-5.5zm.33 9.41-1.41 1.41 3.13 3.13L14.5 20H20v-5.5l-2.04 2.04-3.13-3.13z"/></svg>`,
  repeatOne: `${SVG_OPEN}<path d="M7 7h10v3l4-4-4-4v3H5v6h2V7zm10 10H7v-3l-4 4 4 4v-3h12v-6h-2v4zm-4-2V9h-1l-2 1v1h1.5v4H13z"/></svg>`,
} as const;

const TOGGLE_MARKUP =
  `<span class="controls__glyph" data-glyph="play">${ICONS.play}</span>` +
  `<span class="controls__glyph" data-glyph="pause">${ICONS.pause}</span>`;

/**
 * Native range-input keys that would jump the position without going through the ±5 s seek flow.
 * Arrow keys are deliberately left alone: keyboardNav.ts skips already-prevented events and handles
 * the slider's arrows itself (seek, then `preventDefault`).
 */
const SLIDER_KEYS = new Set(['Home', 'End', 'PageUp', 'PageDown']);

type Action = 'previous' | 'next' | 'primary' | 'lyrics' | 'shuffle' | 'repeatOne';

function createElement<K extends keyof HTMLElementTagNameMap>(tag: K, className: string): HTMLElementTagNameMap[K] {
  const element = document.createElement(tag);
  element.className = className;
  return element;
}

function createButton(className: string, action: Action, label: string, markup: string): HTMLButtonElement {
  const button = createElement('button', className);
  button.type = 'button';
  button.dataset.action = action;
  button.setAttribute('aria-label', label);
  button.innerHTML = markup;
  return button;
}

export function createWallControls(handlers: ControlHandlers): WallControls {
  const abort = new AbortController();
  const signal = abort.signal;

  let mode: 'current' | 'other' = 'current';
  let playing = false;
  let hidden = false;
  let dragging = false;

  let shownDuration = -1;
  let shownValue = -1;
  let shownProgress = '';
  let shownWholeSecond = -1;
  let shownState = '';

  const cluster = createElement('div', 'controls');
  cluster.dataset.mode = mode;
  cluster.dataset.state = 'paused';

  const row = createElement('div', 'controls__row');
  const previous = createButton('controls__button controls__button--skip', 'previous', '上一曲', ICONS.previous);
  const primary = createButton('controls__button controls__button--primary', 'primary', '播放', TOGGLE_MARKUP);
  const next = createButton('controls__button controls__button--skip', 'next', '下一曲', ICONS.next);
  const shuffle = createButton('controls__button controls__button--shuffle', 'shuffle', '随机播放', ICONS.shuffle);
  shuffle.setAttribute('aria-pressed', 'false');
  shuffle.dataset.on = 'false';
  const repeatOne = createButton('controls__button controls__button--repeat', 'repeatOne', '单曲循环', ICONS.repeatOne);
  repeatOne.setAttribute('aria-pressed', 'false');
  repeatOne.dataset.on = 'false';
  const lyrics = createButton('controls__button controls__button--lyrics', 'lyrics', '隐藏歌词', ICONS.lyrics);
  lyrics.setAttribute('aria-pressed', 'true');
  lyrics.dataset.on = 'true';
  row.append(previous, primary, next, shuffle, repeatOne, lyrics);

  const seek = createElement('div', 'controls__seek');
  const slider = createElement('input', 'controls__slider');
  slider.type = 'range';
  slider.min = '0';
  slider.max = '0';
  slider.step = '0.1';
  slider.value = '0';
  slider.setAttribute('aria-label', '播放进度');
  const time = createElement('span', 'controls__time');
  time.textContent = '0:00 / 0:00';
  seek.append(slider, time);
  cluster.append(row, seek);

  // Behaviour --------------------------------------------------------------------------------------

  function updateLabels(): void {
    primary.setAttribute('aria-label', mode === 'other' || !playing ? '播放' : '暂停');
    const collapsed = mode === 'other';
    for (const button of [previous, next, shuffle, repeatOne, lyrics]) {
      button.tabIndex = collapsed ? -1 : 0;
      button.setAttribute('aria-hidden', String(collapsed));
    }
  }

  function runAction(action: string): void {
    switch (action) {
      case 'previous':
        handlers.previous();
        break;
      case 'next':
        handlers.next();
        break;
      case 'primary':
        if (mode === 'other') handlers.playThis();
        else if (playing) handlers.pause();
        else handlers.play();
        break;
      case 'lyrics':
        if (mode !== 'other') handlers.toggleLyrics();
        break;
      case 'shuffle':
        if (mode !== 'other') handlers.toggleShuffle();
        break;
      case 'repeatOne':
        if (mode !== 'other') handlers.toggleRepeatOne();
        break;
      default:
        break;
    }
  }

  cluster.addEventListener(
    'click',
    (event) => {
      const target = event.target instanceof Element ? event.target : null;
      const button = target?.closest<HTMLButtonElement>('button[data-action]');
      if (button?.dataset.action) runAction(button.dataset.action);
    },
    { signal },
  );
  // Pointer presses on controls must never start a wall drag.
  cluster.addEventListener('pointerdown', (event) => event.stopPropagation(), { signal });

  /**
   * 0.1 % steps: on a 1200 px slider that is about one device pixel, and it turns a style write plus
   * repaint of the expanded card on nearly every frame into one every couple of hundred milliseconds.
   */
  const progressRatio = (position: number, duration: number): string =>
    (duration > 0 ? Math.min(1, Math.max(0, position / duration)) : 0).toFixed(3);

  function setSliderProgress(ratio: string): void {
    if (ratio === shownProgress) return;
    shownProgress = ratio;
    slider.style.setProperty('--progress', ratio);
  }

  slider.addEventListener(
    'input',
    () => {
      const value = Number(slider.value);
      setSliderProgress(progressRatio(value, Number(slider.max)));
      handlers.seek(value);
    },
    { signal },
  );
  slider.addEventListener(
    'pointerdown',
    () => {
      dragging = true;
    },
    { signal },
  );
  const endDrag = (): void => {
    dragging = false;
  };
  slider.addEventListener('pointerup', endDrag, { signal });
  slider.addEventListener('pointercancel', endDrag, { signal });
  slider.addEventListener('lostpointercapture', endDrag, { signal });
  slider.addEventListener('change', endDrag, { signal });
  slider.addEventListener(
    'keydown',
    (event) => {
      if (SLIDER_KEYS.has(event.key)) event.preventDefault();
    },
    { signal },
  );

  function setHidden(next: boolean): void {
    hidden = next;
    if (next) cluster.dataset.hidden = 'true';
    else delete cluster.dataset.hidden;
    cluster.inert = next;
  }

  return {
    mountExpanded(container, nextMode) {
      mode = nextMode;
      cluster.dataset.mode = nextMode;
      updateLabels();
      if (cluster.parentElement !== container) container.appendChild(cluster);
    },

    unmountExpanded() {
      const active = document.activeElement;
      // Keep DOM focus inside the card instead of letting it fall to <body> with the cluster.
      if (active && cluster.contains(active)) cluster.closest<HTMLElement>('.poster')?.focus({ preventScroll: true });
      cluster.remove();
      dragging = false;
    },

    setControlsHidden(next) {
      if (next !== hidden) setHidden(next);
    },

    get controlsHidden() {
      return hidden;
    },

    update(clock) {
      const duration = Number.isFinite(clock.durationSeconds) && clock.durationSeconds > 0 ? clock.durationSeconds : 0;
      let position = Number.isFinite(clock.positionSeconds) ? Math.max(0, clock.positionSeconds) : 0;
      if (duration > 0 && position > duration) position = duration;

      const durationChanged = duration !== shownDuration;
      if (durationChanged) {
        shownDuration = duration;
        slider.max = String(duration);
      }
      if (!dragging) {
        const value = Math.round(position * 10) / 10;
        if (value !== shownValue) {
          shownValue = value;
          slider.value = String(value);
        }
      }
      setSliderProgress(progressRatio(position, duration));

      const wholeSecond = Math.floor(position);
      if (durationChanged || wholeSecond !== shownWholeSecond) {
        shownWholeSecond = wholeSecond;
        time.textContent = `${formatTime(wholeSecond)} / ${formatTime(duration)}`;
      }

      const state = clock.state === 'playing' ? 'playing' : 'paused';
      if (state !== shownState) {
        shownState = state;
        playing = state === 'playing';
        cluster.dataset.state = state;
        updateLabels();
      }
    },

    focusSeek() {
      if (!slider.isConnected || hidden || mode === 'other') return false;
      slider.focus({ preventScroll: true });
      return document.activeElement === slider;
    },

    get seekFocused() {
      return mode === 'current' && document.activeElement === slider;
    },

    setLyricsVisible(visible) {
      lyrics.dataset.on = String(visible);
      lyrics.setAttribute('aria-pressed', String(visible));
      lyrics.setAttribute('aria-label', visible ? '隐藏歌词' : '显示歌词');
    },

    setShuffleEnabled(enabled) {
      shuffle.dataset.on = String(enabled);
      shuffle.setAttribute('aria-pressed', String(enabled));
      shuffle.setAttribute('aria-label', enabled ? '关闭随机播放' : '随机播放');
    },

    setRepeatOne(enabled) {
      repeatOne.dataset.on = String(enabled);
      repeatOne.setAttribute('aria-pressed', String(enabled));
      repeatOne.setAttribute('aria-label', enabled ? '关闭单曲循环' : '单曲循环');
    },

    dispose() {
      abort.abort();
      cluster.remove();
    },
  };
}

/** Timings match the native cover animations in 20-poster.css. */
export const ENTRANCE_BLACK_HOLD_MS = 40;
export const ENTRANCE_REVEAL_MS = 160;
export const ENTRANCE_DURATION_MS = ENTRANCE_BLACK_HOLD_MS + ENTRANCE_REVEAL_MS;
export type CoverMotion = { kind: 'enter' | 'fade'; startedAt: number; delayMs: number };

export function coverEase(progress: number, x1 = .2, y1 = .8, x2 = .2, y2 = 1): number {
  if (progress <= 0) return 0;
  if (progress >= 1) return 1;
  const curve = (t: number, a: number, b: number) => 3 * (1 - t) ** 2 * t * a + 3 * (1 - t) * t * t * b + t ** 3;
  let low = 0, high = 1;
  for (let i = 0; i < 16; i++) {
    const middle = (low + high) / 2;
    if (curve(middle, x1, x2) < progress) low = middle;
    else high = middle;
  }
  return curve((low + high) / 2, y1, y2);
}

export function sampleCoverMotion(motion: CoverMotion | null, nowMs: number, reducedMotion: boolean) {
  if (!motion || reducedMotion) return { opacity: 1, blackOpacity: 0, running: false };
  const elapsed = nowMs - motion.startedAt - motion.delayMs;
  if (motion.kind === 'enter') {
    const progress = Math.min(1, Math.max(0, (elapsed - ENTRANCE_BLACK_HOLD_MS) / ENTRANCE_REVEAL_MS));
    return { opacity: elapsed < 0 ? 0 : 1, blackOpacity: 1 - coverEase(progress, 0, 0, .58, 1),
      running: elapsed < ENTRANCE_DURATION_MS };
  }
  const progress = Math.min(1, Math.max(0, elapsed / 120));
  return { opacity: coverEase(progress, 0, 0, .58, 1), blackOpacity: 0, running: progress < 1 };
}

import { HUD_DEFAULT_TILT_ANGLE, normalizeHudTiltAngle } from '../hudSettings.ts';
import type { Point } from '../types.ts';

export const HUD_ART_PARALLAX = .018;
export const HUD_ART_OVERSCAN = .065;

export type DepthPose = { x: number; y: number; amount: number };
type Viewport = { width: number; height: number };
const clamp = (value: number): number => Math.max(-1, Math.min(1, value));

/** One perspective plane shared by native UI and the lens canvas, with enough overscan at the edges. */
export function depthSceneMatrix(pose: DepthPose, viewport: Viewport, tiltAngle = HUD_DEFAULT_TILT_ANGLE): number[] {
  const tilt = normalizeHudTiltAngle(tiltAngle);
  const pitch = -pose.y * pose.amount * tilt * (4.2 / HUD_DEFAULT_TILT_ANGLE) * Math.PI / 180;
  const yaw = pose.x * pose.amount * tilt * Math.PI / 180;
  const sx = Math.sin(pitch), cx = Math.cos(pitch), sy = Math.sin(yaw), cy = Math.cos(yaw);
  // Higher angles reserve extra wall coverage, keeping the viewport corners filled.
  const scale = 1 + .12 * pose.amount * Math.max(1, tilt / HUD_DEFAULT_TILT_ANGLE);
  const perspective = Math.max(1, viewport.width, viewport.height) * 1.35;
  return [scale * cy, scale * sx * sy, -scale * cx * sy, scale * cx * sy / perspective,
    0, scale * cx, scale * sx, -scale * sx / perspective,
    sy, -sx * cy, cx * cy, -cx * cy / perspective,
    pose.x * pose.amount * Math.min(12, viewport.width * .025),
    pose.y * pose.amount * Math.min(9, viewport.height * .025), 0, 1];
}

/** Invert the projected z=0 plane, rather than inverting a 3D point at an arbitrary screen z. */
export function depthProjectPoint(point: Point, matrix: number[], viewport: Viewport, inverse = false): Point {
  const x = point.x - viewport.width / 2, y = point.y - viewport.height / 2;
  if (!inverse) {
    const divisor = matrix[3]! * x + matrix[7]! * y + matrix[15]!;
    return { x: viewport.width / 2 + (matrix[0]! * x + matrix[4]! * y + matrix[12]!) / divisor,
      y: viewport.height / 2 + (matrix[1]! * x + matrix[5]! * y + matrix[13]!) / divisor };
  }
  const a = matrix[0]! - x * matrix[3]!, b = matrix[4]! - x * matrix[7]!;
  const c = matrix[1]! - y * matrix[3]!, d = matrix[5]! - y * matrix[7]!;
  const tx = x * matrix[15]! - matrix[12]!, ty = y * matrix[15]! - matrix[13]!;
  const divisor = a * d - b * c;
  return { x: viewport.width / 2 + (tx * d - b * ty) / divisor,
    y: viewport.height / 2 + (a * ty - tx * c) / divisor };
}

/** A bounded, frame-owner-driven motion-parallax scene. Dragging freezes the displayed pose. */
export function createDepthScene(field: HTMLElement, world: HTMLElement, requestFrame: () => void) {
  const root = document.createElement('div');
  root.className = 'wall-depth-scene';
  root.style.setProperty('--depth-art-shift', String(-HUD_ART_PARALLAX * 100) + '%');
  root.style.setProperty('--depth-art-scale', String(HUD_ART_OVERSCAN));
  field.insertBefore(root, world);
  root.append(world);
  const pose: DepthPose = { x: 0, y: 0, amount: 0 };
  let targetX = 0, targetY = 0, enabled = false, held = false, overControls = false, dirty = true;
  let viewport: Viewport = { width: field.clientWidth, height: field.clientHeight };
  let tiltAngle = HUD_DEFAULT_TILT_ANGLE;
  let matrix = depthSceneMatrix(pose, viewport, tiltAngle), lastNow: number | null = null;
  const abort = new AbortController();
  const signal = abort.signal;
  const move = (event: PointerEvent): void => {
    if (!enabled || held || event.pointerType === 'touch') return;
    overControls = event.target instanceof Element
      && event.target.closest('button, input, a, select, textarea, [role="slider"], .poster__controls') !== null;
    // Keep the displayed pose once the pointer reaches an action; UI parallax must not move the
    // intended button out from under the pointer between hover and pointerdown.
    if (overControls) return;
    const box = field.getBoundingClientRect();
    targetX = clamp((event.clientX - box.left) / Math.max(1, box.width) * 2 - 1);
    targetY = clamp((event.clientY - box.top) / Math.max(1, box.height) * 2 - 1);
    requestFrame();
  };
  field.addEventListener('pointermove', move, { signal, passive: true, capture: true });
  field.addEventListener('pointerdown', () => { held = true; }, { signal, capture: true });
  field.addEventListener('pointerleave', () => {
    if (held) return;
    overControls = false;
    targetX = targetY = 0;
    if (enabled) requestFrame();
  }, { signal });
  const release = (event: PointerEvent): void => {
    if (!held) return;
    held = false;
    // The pointer may have left the viewport during capture; resume from neutral in that case.
    const box = field.getBoundingClientRect();
    if (event.clientX < box.left || event.clientX > box.right || event.clientY < box.top || event.clientY > box.bottom) {
      overControls = false;
      targetX = targetY = 0;
      requestFrame();
    } else move(event);
  };
  field.ownerDocument.addEventListener('pointerup', release, { signal, capture: true });
  field.ownerDocument.addEventListener('pointercancel', release, { signal, capture: true });
  const resetPointer = (): void => { held = overControls = false; targetX = targetY = 0; if (enabled) requestFrame(); };
  field.addEventListener('lostpointercapture', () => { if (held) resetPointer(); }, { signal });
  field.ownerDocument.defaultView?.addEventListener('blur', resetPointer, { signal });
  return {
    root,
    pose,
    get active() { return enabled || pose.amount > 0; },
    setOptions(on: boolean, reducedMotion: boolean, requestedTilt = HUD_DEFAULT_TILT_ANGLE) {
      const nextTilt = normalizeHudTiltAngle(requestedTilt);
      const next = on && !reducedMotion;
      if (next === enabled && !reducedMotion && nextTilt === tiltAngle) return;
      tiltAngle = nextTilt;
      enabled = next;
      if (!enabled) { targetX = targetY = 0; overControls = false; }
      if (reducedMotion) pose.x = pose.y = pose.amount = 0;
      dirty = true;
      requestFrame();
    },
    tick(nowMs: number, next: Viewport): { changed: boolean; moving: boolean } {
      const dt = lastNow === null ? 1 / 60 : Math.min(.064, Math.max(0, (nowMs - lastNow) / 1000));
      lastNow = nowMs;
      let changed = dirty || viewport.width !== next.width || viewport.height !== next.height;
      viewport = next;
      let moving = false;
      if (!held) for (const [key, target] of [['x', targetX], ['y', targetY], ['amount', enabled ? 1 : 0]] as const) {
        if (overControls && enabled && key !== 'amount') continue;
        const before = pose[key];
        pose[key] += (target - before) * (1 - Math.exp(-dt * (key === 'amount' ? 15 : 11)));
        if (Math.abs(target - pose[key]) < .0001) pose[key] = target;
        else moving = true;
        if (pose[key] !== before) changed = true;
      }
      if (changed) {
        matrix = depthSceneMatrix(pose, viewport, tiltAngle);
        root.style.transform = pose.amount > 0 ? `matrix3d(${matrix.join(',')})` : '';
        root.style.willChange = this.active ? 'transform' : '';
        root.dataset.depthActive = String(this.active);
        world.dataset.depth = String(this.active);
        for (const [name, value] of [['x', pose.x], ['y', pose.y], ['amount', pose.amount]] as const) {
          root.style.setProperty(`--depth-${name}`, String(value));
        }
        dirty = false;
      }
      return { changed, moving };
    },
    pointerPoint(clientX: number, clientY: number): Point {
      const box = field.getBoundingClientRect();
      return depthProjectPoint({ x: clientX - box.left, y: clientY - box.top }, matrix, viewport, true);
    },
    screenPoint(point: Point): Point { return depthProjectPoint(point, matrix, viewport); },
    dispose() { abort.abort(); root.replaceWith(world); delete world.dataset.depth; },
  };
}

import type { Camera, CameraState, PixelRect, Point } from '../types.ts';

const STRENGTH = 2;
const NORMALIZATION = Math.asinh(STRENGTH);

/** Smooth, invertible barrel projection; the viewport axes stay anchored at their edges. */
export function fisheyeOffset(x: number, y: number, halfWidth: number, halfHeight: number, inverse = false, amount = 1): Point {
  if (!(halfWidth > 0 && halfHeight > 0) || amount <= 0) return { x, y };
  const strength = STRENGTH * amount;
  const normalization = amount === 1 ? NORMALIZATION : Math.asinh(strength);
  const radius = Math.hypot(x / halfWidth, y / halfHeight);
  if (radius === 0) return { x, y };
  const mapped = inverse ? Math.sinh(radius * normalization) / strength
    : Math.asinh(radius * strength) / normalization;
  const factor = mapped / radius;
  return { x: x * factor, y: y * factor };
}

/** The inverse-projected screen corners bound every visible source point. */
export const FISHEYE_BOUNDS_SCALE = fisheyeOffset(1, 1, 1, 1, true).x;

export function projectedCardBounds(rect: PixelRect, camera: Pick<Camera, 'worldToScreen'>): PixelRect {
  const corners = [camera.worldToScreen(rect.x, rect.y), camera.worldToScreen(rect.x + rect.w, rect.y),
    camera.worldToScreen(rect.x + rect.w, rect.y + rect.h), camera.worldToScreen(rect.x, rect.y + rect.h)];
  const left = Math.min(...corners.map(point => point.x)), top = Math.min(...corners.map(point => point.y));
  return { x: left, y: top, w: Math.max(...corners.map(point => point.x)) - left,
    h: Math.max(...corners.map(point => point.y)) - top };
}

/** Project a card's four corners with a homography, retaining native DOM hit testing. */
export function fisheyeCardMatrix(rect: PixelRect, view: Readonly<CameraState>, viewport: Readonly<{ width: number; height: number }>, amount = 1): number[] {
  const halfWidth = viewport.width / (2 * view.scale);
  const halfHeight = viewport.height / (2 * view.scale);
  const corner = (x: number, y: number): Point => {
    const offset = fisheyeOffset(x - view.x, y - view.y, halfWidth, halfHeight, false, amount);
    // Keep the matrix near the card's local origin, even after very long pans.
    return { x: view.x + offset.x - rect.x, y: view.y + offset.y - rect.y };
  };
  const p0 = corner(rect.x, rect.y);
  const p1 = corner(rect.x + rect.w, rect.y);
  const p2 = corner(rect.x + rect.w, rect.y + rect.h);
  const p3 = corner(rect.x, rect.y + rect.h);
  const dx1 = p1.x - p2.x, dx2 = p3.x - p2.x;
  const dy1 = p1.y - p2.y, dy2 = p3.y - p2.y;
  const dx3 = p0.x - p1.x + p2.x - p3.x;
  const dy3 = p0.y - p1.y + p2.y - p3.y;
  const denominator = dx1 * dy2 - dx2 * dy1;
  const g = Math.abs(denominator) > 1e-12 ? (dx3 * dy2 - dx2 * dy3) / denominator : 0;
  const h = Math.abs(denominator) > 1e-12 ? (dx1 * dy3 - dx3 * dy1) / denominator : 0;
  const width = Math.max(1, rect.w), height = Math.max(1, rect.h);
  return [
    (p1.x - p0.x + g * p1.x) / width, (p1.y - p0.y + g * p1.y) / width, 0, g / width,
    (p3.x - p0.x + h * p3.x) / height, (p3.y - p0.y + h * p3.y) / height, 0, h / height,
    0, 0, 1, 0,
    p0.x, p0.y, 0, 1,
  ];
}

type Homography = [number, number, number, number, number, number, number, number, number];

function planar(matrix: number[]): Homography {
  return [matrix[0]!, matrix[4]!, matrix[12]!, matrix[1]!, matrix[5]!, matrix[13]!, matrix[3]!, matrix[7]!, matrix[15]!];
}

function multiply(a: Homography, b: Homography): Homography {
  const result = new Array<number>(9).fill(0) as Homography;
  for (let row = 0; row < 3; row++) for (let col = 0; col < 3; col++) {
    for (let k = 0; k < 3; k++) result[row * 3 + col]! += a[row * 3 + k]! * b[k * 3 + col]!;
  }
  return result;
}

function inverse([a, b, c, d, e, f, g, h, i]: Homography): Homography {
  const cofactors: Homography = [e * i - f * h, c * h - b * i, b * f - c * e,
    f * g - d * i, a * i - c * g, c * d - a * f,
    d * h - e * g, b * g - a * h, a * e - b * d];
  const determinant = a * cofactors[0] + b * cofactors[3] + c * cofactors[6];
  return cofactors.map(value => value / determinant) as Homography;
}

/** Cancel the card's planar warp, then project a UI unit at its own place on the curved cover.
 * Work relative to the card origin so a long pan cannot lose precision in matrix inversion. */
export function fisheyeChildMatrix(card: PixelRect, local: PixelRect, view: Readonly<CameraState>,
  viewport: Readonly<{ width: number; height: number }>, amount = 1, shift: Point = { x: 0, y: 0 }, projectUnit = true): number[] {
  const parent = planar(fisheyeCardMatrix(card, view, viewport, amount));
  const child = planar(fisheyeCardMatrix({ x: card.x + local.x, y: card.y + local.y,
    w: local.w, h: local.h }, view, viewport, amount));
  const offset: Homography = [1, 0, local.x, 0, 1, local.y, 0, 0, 1];
  const undoOffset: Homography = [1, 0, -local.x, 0, 1, -local.y, 0, 0, 1];
  const translation: Homography = [1, 0, shift.x, 0, 1, shift.y, 0, 0, 1];
  // Translate after the lens in the camera plane. Keep the parent's native projection when the
  // continuous surface is unavailable, instead of changing the fallback cover/UI correspondence.
  const projected = projectUnit ? multiply(offset, child) : multiply(parent, offset);
  const result = multiply(multiply(multiply(undoOffset, inverse(parent)), translation), projected);
  const [a, b, c, d, e, f, g, h, i] = result.map(value => value / result[8]) as Homography;
  return [a, d, 0, g, b, e, 0, h, 0, 0, 1, 0, c, f, 0, i];
}

import type { Camera, Tile, WallVisualOptions } from '../types.ts';
import { FISHEYE_BOUNDS_SCALE } from './fisheye.ts';
import { fallbackGradient, type PosterElement } from './poster.ts';
import { coverEase, sampleCoverMotion } from './coverMotion.ts';
import { HUD_ART_PARALLAX, HUD_ART_OVERSCAN, type DepthPose } from './depthScene.ts';

export type SurfaceCard = { el: PosterElement; tile: Tile | undefined; current: boolean };

const VERTEX = `
attribute vec2 aPosition;
attribute vec2 aUv;
varying vec2 vUv;
void main() { vUv = aUv; gl_Position = vec4(aPosition, 0.0, 1.0); }
`;
const COVER = `
precision mediump float;
varying vec2 vUv;
uniform sampler2D uImage;
uniform float uHasImage;
uniform vec2 uCrop;
uniform vec3 uFirst;
uniform vec3 uSecond;
uniform vec3 uShadeColor;
uniform vec4 uPaint;
uniform float uOpacity;
uniform float uBlackOpacity;
uniform float uGradient;
uniform vec3 uMotion;
uniform vec3 uBackground;
uniform vec3 uDepth;
uniform vec3 uAlbumBackground;
uniform float uAlbumScrim;
void main() {
  vec2 bodyUv = (vUv - vec2(0.0, uMotion.x) - 0.5) / uMotion.yz + 0.5;
  vec2 artUv = (bodyUv - 0.5) / uDepth.z + 0.5 + uDepth.xy;
  vec3 color = mix(uFirst, uSecond, (artUv.x + artUv.y) * 0.5);
  if (uHasImage > 0.5) {
    vec4 image = texture2D(uImage, (artUv - 0.5) * uCrop + 0.5);
    color = mix(color, image.rgb, image.a);
  }
  float luminance = dot(color, vec3(0.2126, 0.7152, 0.0722));
  color = mix(vec3(luminance), color, 1.0 + (uPaint.w - 1.0) * 0.7) * uPaint.w;
  float vertical = clamp((bodyUv.y - 0.38) / 0.62, 0.0, 1.0);
  float tint = uPaint.x;
  if (uGradient > 0.5) tint = 1.0 - (1.0 - tint) * (1.0 - uPaint.x * 0.74 * vertical);
  if (uGradient > 1.5) tint = 1.0 - (1.0 - tint) * (1.0 - uPaint.x * 0.46 * clamp(1.0 - bodyUv.x / 0.4, 0.0, 1.0));
  color = mix(color, uShadeColor, tint);
  float down = bodyUv.y < 0.56 ? 0.48 * clamp((bodyUv.y - 0.14) / 0.42, 0.0, 1.0)
    : mix(0.48, 0.94, (bodyUv.y - 0.56) / 0.44);
  float side = 0.76 * clamp(1.0 - bodyUv.x / 0.58, 0.0, 1.0);
  float corner = 0.58 * clamp(1.0 - length(vec2(bodyUv.x / 0.85, (bodyUv.y - 1.0) / 0.75)) / 0.72, 0.0, 1.0);
  float scrim = 1.0 - (1.0 - down) * (1.0 - side) * (1.0 - corner);
  color = mix(color, uShadeColor, scrim * uPaint.z);
  float inside = step(0.0, bodyUv.x) * step(bodyUv.x, 1.0) * step(0.0, bodyUv.y) * step(bodyUv.y, 1.0);
  color = mix(uBackground, color * (1.0 - uPaint.y), inside);
