    }
    catch { gl.deleteTexture(cached.value); cached.value = null; cached.failed = true; }
    return cached.value;
  }

  function quad(value: WebGLProgram, x0: number, y0: number, x1: number, y1: number, flipUv = false): void {
    const top = flipUv ? 1 : 0, bottom = flipUv ? 0 : 1;
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([x0, y0, 0, top, x1, y0, 1, top, x0, y1, 0, bottom, x1, y1, 1, bottom]), gl.STREAM_DRAW);
    const { position, uv } = attributes.get(value)!;
    gl.enableVertexAttribArray(position); gl.vertexAttribPointer(position, 2, gl.FLOAT, false, 16, 0);
    gl.enableVertexAttribArray(uv); gl.vertexAttribPointer(uv, 2, gl.FLOAT, false, 16, 8);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
  }

  return {
    canvas,
    get needsReplacement() { return restored; },
    hide() { canvas.hidden = true; release(); dirty = true; },
    render(camera: Camera, cards: SurfaceCard[], visuals: WallVisualOptions, dt: number, changed: boolean, nowMs: number, depth: DepthPose, entering = false): { ready: boolean; moving: boolean } {
      if (disposed || lost) return { ready: false, moving: false };
      let moving = false;
      let paintChanged = false;
      const hasExpanded = cards.some(card => card.el.root.dataset.expanded === 'true');
      const daytime = field.ownerDocument.body.dataset.lighting === 'daytime';
      const keep = new Set<HTMLElement>();
      for (const card of cards) {
        const root = card.el.root, open = root.dataset.expanded === 'true', hover = root.dataset.lensHover === 'true';
        keep.add(root);
        const idle = !open && !card.current && !hover;
        const targetZoom = !visuals.reducedMotion && !open && !root.classList.contains('poster--enter')
          && (hover || root.dataset.focused === 'true') ? 1 : 0;
        const targetPaint = [visuals.tint && idle ? Math.min(.85, visuals.tintIntensity) : 0,
          daytime ? 0 : hasExpanded ? (open ? 0 : visuals.lightsOut ? .8 : .34) : visuals.lightsOut && idle ? .72 : 0,
          open ? 1 : 0, open ? 1.18 : hover ? 1.16 : 1];
        let state = paints.get(root);
        if (!state) {
          state = { value: [...targetPaint], alpha: 1, blackOpacity: 0, albumScrim: 0, zoom: targetZoom,
            zoomFrom: targetZoom, zoomTarget: targetZoom, zoomStart: nowMs };
          paints.set(root, state);
          paintChanged = true;
        }
        const content = card.el.expanded?.root;
        // Read the existing CSS fade so opening, closing, switching to lyrics and reduced motion
        // share one timeline. Hiding the native pseudo-element leaves its opacity animation intact.
        const albumScrim = content?.classList.contains('poster__expanded--album')
          ? Number.parseFloat(getComputedStyle(content, '::before').opacity) * Number.parseFloat(getComputedStyle(content).opacity) : 0;
        if (state.albumScrim !== albumScrim) paintChanged = true;
        state.albumScrim = albumScrim;
        const motion = sampleCoverMotion(card.el.coverMotion, nowMs, visuals.reducedMotion);
        if (state.alpha !== motion.opacity || state.blackOpacity !== motion.blackOpacity) paintChanged = true;
        state.alpha = motion.opacity; state.blackOpacity = motion.blackOpacity;
        if (motion.running) moving = true;
        else card.el.coverMotion = null;
        if (state.zoomTarget !== targetZoom) {
          state.zoomFrom = state.zoom; state.zoomTarget = targetZoom; state.zoomStart = nowMs;
        }
        const zoomProgress = visuals.reducedMotion ? 1 : Math.min(1, Math.max(0, (nowMs - state.zoomStart) / 280));
        const zoom = state.zoomFrom === state.zoomTarget ? state.zoomTarget
          : state.zoomFrom + (state.zoomTarget - state.zoomFrom) * coverEase(zoomProgress);
        if (zoom !== state.zoom) paintChanged = true;
        state.zoom = zoom;
        if (zoomProgress < 1 && state.zoomFrom !== state.zoomTarget) moving = true;
        const blend = visuals.reducedMotion ? 1 : 1 - Math.exp(-dt * 18);
        for (let i = 0; i < 4; i++) {
          const before = state.value[i]!;
          state.value[i]! += (targetPaint[i]! - state.value[i]!) * blend;
          if (Math.abs(state.value[i]! - targetPaint[i]!) > .001) moving = true;
          else state.value[i] = targetPaint[i]!;
          if (before !== state.value[i]) paintChanged = true;
        }
      }
      for (const root of paints.keys()) if (!keep.has(root)) paints.delete(root);
      if (!dirty && !changed && !paintChanged && !moving && !canvas.hidden) return { ready: true, moving: false };
      dirty = false;
      const boundsScale = FISHEYE_BOUNDS_SCALE;
      const ratio = Math.min(globalThis.devicePixelRatio || 1, 1.5, limit / (camera.viewport.width * boundsScale), limit / (camera.viewport.height * boundsScale));
      const width = Math.max(1, Math.round(camera.viewport.width * ratio)), height = Math.max(1, Math.round(camera.viewport.height * ratio));
      if (canvas.width !== width || canvas.height !== height) { canvas.width = width; canvas.height = height; }
      const fw = Math.min(limit, Math.ceil(width * boundsScale)), fh = Math.min(limit, Math.ceil(height * boundsScale));
      if (targetWidth !== fw || targetHeight !== fh) {
        if (target) gl.deleteTexture(target);
        if (framebuffer) gl.deleteFramebuffer(framebuffer);
        target = gl.createTexture()!; gl.bindTexture(gl.TEXTURE_2D, target); configureTexture();
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, fw, fh, 0, gl.RGBA, gl.UNSIGNED_BYTE, null);
        framebuffer = gl.createFramebuffer()!; gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer);
        gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, target, 0);
        if (gl.checkFramebufferStatus(gl.FRAMEBUFFER) !== gl.FRAMEBUFFER_COMPLETE) return { ready: false, moving: false };
        targetWidth = fw; targetHeight = fh;
      }
      gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer); gl.viewport(0, 0, fw, fh);
      gl.clearColor(0, 0, 0, entering ? 0 : 1); gl.clear(gl.COLOR_BUFFER_BIT);
      // Keep coverage separate so the lens preserves transparent holes between arriving tiles.
      gl.useProgram(cover); gl.enable(gl.BLEND);
      gl.blendFuncSeparate(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA, gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
      gl.activeTexture(gl.TEXTURE0); gl.uniform1i(c.uImage!, 0);
      const depthScale = 1 + depth.amount * HUD_ART_OVERSCAN;
      gl.uniform3f(c.uDepth!, depth.x * depth.amount * HUD_ART_PARALLAX / depthScale, depth.y * depth.amount * HUD_ART_PARALLAX / depthScale, depthScale);
      const tint = visuals.tintColor.replace('#', '');
      gl.uniform3f(c.uShadeColor!, parseInt(tint.slice(0, 2), 16) / 255, parseInt(tint.slice(2, 4), 16) / 255, parseInt(tint.slice(4, 6), 16) / 255);
      gl.uniform1f(c.uGradient!, visuals.tintGradient === 'diagonal' ? 2 : visuals.tintGradient === 'vertical' ? 1 : 0);
      const background = field.ownerDocument.documentElement.style.getPropertyValue('--host-panel').trim();
      const panel = /^#[0-9a-f]{6}$/i.test(background) ? background.slice(1) : '171a22';
      gl.uniform3f(c.uBackground!, parseInt(panel.slice(0, 2), 16) / 255, parseInt(panel.slice(2, 4), 16) / 255, parseInt(panel.slice(4, 6), 16) / 255);
      const wallBackground = getComputedStyle(field).getPropertyValue('--wall-background').trim();
      const albumBackground = /^#[0-9a-f]{6}$/i.test(wallBackground) ? wallBackground.slice(1) : '000000';
      gl.uniform3f(c.uAlbumBackground!, parseInt(albumBackground.slice(0, 2), 16) / 255,
        parseInt(albumBackground.slice(2, 4), 16) / 255, parseInt(albumBackground.slice(4, 6), 16) / 255);
      const used = new Set<string>();
      const ordered = cards.filter(card => card.el.root.dataset.expanded !== 'true').concat(cards.filter(card => card.el.root.dataset.expanded === 'true'));
      for (const card of ordered) {
        const rect = card.el.rect, image = card.el.cover;
        const texture = imageTexture(image);
        if (image.src) used.add(image.src);
        // Always bind a complete texture, including fallback-only cards.
        gl.bindTexture(gl.TEXTURE_2D, texture ?? empty);
        gl.uniform1f(c.uHasImage!, texture ? 1 : 0);
        const aspect = image.naturalWidth / Math.max(1, image.naturalHeight);
        const square = card.el.root.dataset.squareCover === 'true';
        const boxAspect = square ? 1 : rect.w / rect.h;
        let cropX = aspect > boxAspect ? boxAspect / aspect : 1, cropY = aspect < boxAspect ? aspect / boxAspect : 1;
        if (square) { const side = Math.max(rect.w, rect.h); cropX *= rect.w / side; cropY *= rect.h / side; }
        gl.uniform2f(c.uCrop!, cropX, cropY);
        const id = card.tile?.trackId ?? '';
        let colorsForCard = colors.get(id);
        if (!colorsForCard) { colorsForCard = palette(id); colors.set(id, colorsForCard); }
        gl.uniform3fv(c.uFirst!, colorsForCard[0]); gl.uniform3fv(c.uSecond!, colorsForCard[1]);
        const paint = paints.get(card.el.root)!;
        gl.uniform4fv(c.uPaint!, paint.value); gl.uniform1f(c.uOpacity!, paint.alpha);
        gl.uniform1f(c.uBlackOpacity!, paint.blackOpacity);
        gl.uniform1f(c.uAlbumScrim!, paint.albumScrim);
        const zoomGap = Math.max(0, card.el.shown.hoverGap) * paint.zoom;
        gl.uniform3f(c.uMotion!, 0, 1 + zoomGap / Math.max(1, rect.w), 1 + zoomGap / Math.max(1, rect.h));
        const x = (rect.x - camera.state.x) * camera.state.scale / (camera.viewport.width / 2 * boundsScale);
        const y = -(rect.y - camera.state.y) * camera.state.scale / (camera.viewport.height / 2 * boundsScale);
        quad(cover, x, y, x + rect.w * camera.state.scale / (camera.viewport.width / 2 * boundsScale), y - rect.h * camera.state.scale / (camera.viewport.height / 2 * boundsScale));
      }
      for (const [key, texture] of textures) if (!used.has(key)) { if (texture.value) gl.deleteTexture(texture.value); textures.delete(key); }
      gl.bindFramebuffer(gl.FRAMEBUFFER, null); gl.viewport(0, 0, width, height); gl.disable(gl.BLEND);
      gl.useProgram(lens); gl.bindTexture(gl.TEXTURE_2D, target); gl.uniform1i(l.uImage!, 0);
      gl.uniform1f(l.uBounds!, boundsScale);
      const strength = 2 * camera.fisheyeAmount;
      gl.uniform1f(l.uStrength!, strength); gl.uniform1f(l.uNormalization!, Math.asinh(strength));
      quad(lens, -1, 1, 1, -1, true);
      canvas.hidden = false;
      return { ready: true, moving };
    },
    dispose() { disposed = true; release(); gl.deleteTexture(empty); gl.deleteBuffer(buffer); gl.deleteProgram(cover); gl.deleteProgram(lens); canvas.remove(); },
  };
}

import type { Camera, PixelRect, Point } from '../types.ts';
import type { PosterElement } from './poster.ts';
import { fisheyeChildMatrix } from './fisheye.ts';
import type { DepthPose } from './depthScene.ts';
import { uiParallaxOffset, type UiDepthLayer } from './uiParallax.ts';

type UnitState = { revision: number; box: PixelRect; card: PixelRect; shift: Point; lens: boolean };

/** Layout offsets remain in source coordinates even while the DOM has projected transforms. */
function sourceBox(element: HTMLElement, card: HTMLElement): PixelRect {
  let x = 0, y = 0;
  for (let node: HTMLElement | null = element; node && node !== card; node = node.offsetParent as HTMLElement | null) {
    x += node.offsetLeft;
    y += node.offsetTop;
  }
  const style = getComputedStyle(element);
  return { x, y, w: Number.parseFloat(style.width) || element.offsetWidth,
    h: Number.parseFloat(style.height) || element.offsetHeight };
}

function sameBox(a: PixelRect, b: PixelRect): boolean {
  return a.x === b.x && a.y === b.y && a.w === b.w && a.h === b.h;
}

/** Keep native text, scrolling and playback input; only their presentation follows the lens. */
export function createFisheyeUiProjection(requestFrame: () => void) {
  const units = new Map<HTMLElement, UnitState>();
  const observer = new ResizeObserver(requestFrame);

  const clear = (): void => {
    observer.disconnect();
    for (const element of units.keys()) element.style.removeProperty('transform');
    units.clear();
  };

  return {
    sync(posters: Iterable<PosterElement>, camera: Camera, revision: number, surfaceReady: boolean, depth: DepthPose): boolean {
      const lens = camera.fisheye && surfaceReady;
      if (!lens && depth.amount <= 0) { clear(); return false; }
      const shownTitles = document.body.dataset.showTitles === 'true';
      const reads: { element: HTMLElement; box: PixelRect; card: PixelRect; layer: UiDepthLayer }[] = [];
      let animating = false;
      // Read all source geometry before any transform writes, including animated lyric/list slots.
      for (const poster of posters) {
        const content = poster.expanded;
        const elements: [HTMLElement, UiDepthLayer][] = content
          ? [[content.meta, 'meta'], [content.lyrics, 'lyrics'], [content.controls, 'controls']]
          : shownTitles && !poster.caption.hidden ? [[poster.caption, 'caption']] : [];
        if (content?.root.getAnimations({ subtree: true }).some(effect => effect.pending || effect.playState === 'running')) {
          animating = true;
        }
        for (const [element, layer] of elements) reads.push({ element, layer, box: sourceBox(element, poster.root), card: poster.rect });
      }
      const active = new Set(reads.map(read => read.element));
      for (const element of units.keys()) if (!active.has(element)) {
        observer.unobserve(element);
        element.style.removeProperty('transform');
        units.delete(element);
      }
      for (const { element, box, card, layer } of reads) {
        const previous = units.get(element);
        const shift = uiParallaxOffset(depth, layer, card, camera.state.scale, camera.viewport);
        if (previous?.revision === revision && previous.lens === lens && sameBox(previous.box, box)
          && sameBox(previous.card, card) && previous.shift.x === shift.x && previous.shift.y === shift.y) continue;
        if (!previous) observer.observe(element);
        units.set(element, { revision, box, card: { ...card }, shift, lens });
        if (box.w <= 0 || box.h <= 0) { element.style.removeProperty('transform'); continue; }
        const matrix = fisheyeChildMatrix(card, box, camera.state, camera.viewport, camera.fisheyeAmount, shift, lens);
        element.style.transform = `matrix3d(${matrix.join(',')})`;
      }
      return animating;
    },
    clear,
    dispose: clear,
  };
}

/** Permit 240 Hz vsync while bounding hosts whose rAF runs without vsync. */
export const INTERACTIVE_FRAME_MS = 4;

/** One demand-driven frame owner per wall. Hidden and disposed walls never re-arm themselves. */
export function createWallFrameLoop(render: (time: number) => boolean, intervalMs: number | (() => number), visible: boolean) {
  let frameId = 0;
  let disposed = false;
  let lastFrame = -Infinity;
  let interactivePending = false;
  const request = (): void => {
    if (!disposed && visible && !frameId) frameId = requestAnimationFrame(frame);
  };
  function frame(time: number): void {
    frameId = 0;
    if (disposed || !visible) return;
    const interval = interactivePending ? INTERACTIVE_FRAME_MS
      : typeof intervalMs === 'function' ? intervalMs() : intervalMs;
    if (time - lastFrame < interval) { request(); return; }
    interactivePending = false;
    lastFrame = time;
    if (render(time)) request();
  }
  const cancel = (): void => {
    cancelAnimationFrame(frameId);
    frameId = 0;
    interactivePending = false;
  };
  return {
    request,
    /** Direct input must not wait for a desktop wall's idle playback cadence. */
    requestInteractive() {
      if (disposed || !visible) return;
      interactivePending = true;
      request();
    },
    setVisible(next: boolean) {
      visible = next;
      if (!visible) cancel();
      else { lastFrame = -Infinity; request(); }
    },
    dispose() { disposed = true; cancel(); },
  };
}

import type { Direction } from '../types.ts';

export type KeyboardActions = {
  move(direction: Direction): void;
  activate(): void;
  secondary(): void;
  escape(): void;
  focusCurrent(): void;
  toggle(setting: 'lights-out' | 'vignette' | 'tint'): void;
  /** Seek relative to the current position; returns false when seeking is not applicable right now. */
  seekBy(deltaSeconds: number): boolean;
};

const SEEK_STEP_SECONDS = 5;
const ARROW_DIRECTIONS: Readonly<Record<string, Direction>> = {
  ArrowLeft: 'left',
  ArrowRight: 'right',
  ArrowUp: 'up',
  ArrowDown: 'down',
};
const TEXT_ENTRY_SELECTOR = 'input, textarea, select';
/** Elements the browser activates itself on Enter / Space; handling them here would fire twice. */
const NATIVE_ACTIVATION_SELECTOR = 'button, a[href]';

function isTextEntry(origin: Element): boolean {
  return origin.closest(TEXT_ENTRY_SELECTOR) !== null || (origin instanceof HTMLElement && origin.isContentEditable);
}

/**
 * SPEC §2.4 key map on `keydown` (bubbling) for `target`.
 *
 * - Events with Ctrl / Meta / Alt pass through untouched so host shortcuts keep working.
 * - Events already handled by a descendant (`defaultPrevented`) are ignored; card-level handlers
 *   should call `preventDefault()` when they consume a key.
 * - Text entry targets are ignored, except `input[type=range]` (the seek slider) whose arrow keys map
 *   to `seekBy(±5)` while Escape and the letter toggles keep working.
 * - `preventDefault()` is called only for keys that were handled. Arrows may auto-repeat; the other
 *   keys ignore repeats.
 */
export function attachKeyboardNav(target: HTMLElement, actions: KeyboardActions): { dispose(): void } {
  function onKeyDown(event: KeyboardEvent): void {
    if (event.ctrlKey || event.metaKey || event.altKey || event.defaultPrevented) return;
    const origin = event.target instanceof Element ? event.target : null;
    const onSlider = origin instanceof HTMLInputElement && origin.type === 'range';
    if (origin !== null && !onSlider && isTextEntry(origin)) return;

    const direction = ARROW_DIRECTIONS[event.key];
    if (direction !== undefined) {
      if (onSlider) {
        const delta = direction === 'left' || direction === 'down' ? -SEEK_STEP_SECONDS : SEEK_STEP_SECONDS;
        if (actions.seekBy(delta)) event.preventDefault();
        return;
      }
      if (direction === 'left' || direction === 'right') {
        if (actions.seekBy(direction === 'left' ? -SEEK_STEP_SECONDS : SEEK_STEP_SECONDS)) {
          event.preventDefault();
          return;
        }
      }
      actions.move(direction);
      event.preventDefault();
      return;
    }

    if (event.repeat) return;
    const key = event.code === 'Space' ? ' ' : event.key;
    // On the slider only Escape and the letter toggles apply; Enter / Space stay with the control.
    if (onSlider && key !== 'Escape' && key.length !== 1) return;
    switch (key) {
      case 'Enter':
        if (onSlider || (origin !== null && origin.closest(NATIVE_ACTIVATION_SELECTOR) !== null)) return;
        actions.activate();
        break;
      case ' ':
        if (onSlider || (origin !== null && origin.closest(NATIVE_ACTIVATION_SELECTOR) !== null)) return;
        actions.secondary();
        break;
      case 'Escape':
        actions.escape();
        break;
      case 'c':
      case 'C':
        actions.focusCurrent();
        break;
      case 'l':
      case 'L':
        actions.toggle('lights-out');
        break;
      case 'v':
      case 'V':
        actions.toggle('vignette');
        break;
      case 't':
      case 'T':
        actions.toggle('tint');
        break;
      default:
        return;
    }
    event.preventDefault();
  }

  target.addEventListener('keydown', onKeyDown);
  return {
    dispose() {
      target.removeEventListener('keydown', onKeyDown);
    },
  };
}

import type { PointerPan, PointerPanHandlers } from '../types.ts';

const DRAG_THRESHOLD_PX = 7;
/** Release velocity is measured over the samples from roughly this long before the release. */
const VELOCITY_WINDOW_MS = 80;
/** Two samples closer than this are release jitter, not a flick. */
const MIN_VELOCITY_SPAN_MS = 8;
const SAMPLE_CAPACITY = 8;
const SAMPLE_INTERVAL_MS = 10;
const CLICK_SUPPRESSION_MS = 300;
const LINE_DELTA_PX = 16;
/** Controls inside expanded cards keep their native pointer behaviour and their clicks. */
const INTERACTIVE_SELECTOR = 'button, input, a, select, textarea, [role="slider"]';

function at(values: Float64Array, index: number): number {
  return values[index] ?? 0;
}

/**
 * Drag / fling / tap / wheel input for the wall viewport.
 *
 * - The pointer is captured only once the 7 px drag threshold is crossed, so a plain tap still lets
 *   the native `click` reach the element under the pointer (the wall's delegated click handler).
 * - After a drag, the trailing `click` is swallowed in the capture phase on `field`.
 * - `onTap` reports the `pointerdown` target (the element the user pressed on).
 * - `onWheel(dx, dy)` receives normalised scroll deltas in screen px, positive = scroll down / right,
 *   i.e. the direction the content is expected to move *against*: pan the camera by `(-dx, -dy)`
 *   for the natural scrolling feel.
 */
export function attachPointerPan(field: HTMLElement, handlers: PointerPanHandlers): PointerPan {
  let activePointerId: number | null = null;
  let downTarget: EventTarget | null = null;
  let startX = 0;
  let startY = 0;
  let lastX = 0;
  let lastY = 0;
  let dragging = false;
  let rawAttached = false;
  let rawSeen = false;
  const point = (event: PointerEvent) => handlers.projectPointer?.(event.clientX, event.clientY)
    ?? { x: event.clientX, y: event.clientY };

  const sampleTimes = new Float64Array(SAMPLE_CAPACITY);
  const sampleXs = new Float64Array(SAMPLE_CAPACITY);
  const sampleYs = new Float64Array(SAMPLE_CAPACITY);
  let sampleHead = 0;
  let sampleCount = 0;

  let suppressClick = false;
  let suppressTimer: ReturnType<typeof setTimeout> | null = null;

  function pushSample(time: number, x: number, y: number): void {
    // High-polling mice must not fill the entire velocity window with < 8 ms of samples.
    // Keep the latest endpoint while retaining history in the existing fixed-size ring.
    if (sampleCount > 1) {
      const previous = (sampleHead + SAMPLE_CAPACITY - 2) % SAMPLE_CAPACITY;
      if (time - at(sampleTimes, previous) < SAMPLE_INTERVAL_MS) {
        const newest = (sampleHead + SAMPLE_CAPACITY - 1) % SAMPLE_CAPACITY;
        sampleTimes[newest] = time; sampleXs[newest] = x; sampleYs[newest] = y;
        return;
      }
    }
    sampleTimes[sampleHead] = time;
    sampleXs[sampleHead] = x;
    sampleYs[sampleHead] = y;
    sampleHead = (sampleHead + 1) % SAMPLE_CAPACITY;
    if (sampleCount < SAMPLE_CAPACITY) sampleCount += 1;
  }

  /** Screen-space velocity (px/s) between the newest sample and the oldest one inside the window. */
  function releaseVelocity(): [number, number] {
    const newest = (sampleHead + SAMPLE_CAPACITY - 1) % SAMPLE_CAPACITY;
    const endTime = at(sampleTimes, newest);
    let oldest = newest;
    for (let back = 1; back < sampleCount; back += 1) {
      const index = (newest + SAMPLE_CAPACITY - back) % SAMPLE_CAPACITY;
      if (endTime - at(sampleTimes, index) > VELOCITY_WINDOW_MS) break;
      oldest = index;
    }
    const span = endTime - at(sampleTimes, oldest);
    if (span < MIN_VELOCITY_SPAN_MS) return [0, 0];
    const perSecond = 1000 / span;
    return [
      (at(sampleXs, newest) - at(sampleXs, oldest)) * perSecond,
      (at(sampleYs, newest) - at(sampleYs, oldest)) * perSecond,
    ];
  }

  function disarmClickSuppression(): void {
    suppressClick = false;
    if (suppressTimer !== null) {
      clearTimeout(suppressTimer);
      suppressTimer = null;
    }
  }

  function armClickSuppression(): void {
    disarmClickSuppression();
    suppressClick = true;
    suppressTimer = setTimeout(disarmClickSuppression, CLICK_SUPPRESSION_MS);
  }

  function endGesture(): void {
    if (rawAttached) field.removeEventListener('pointerrawupdate', onRawUpdate);
    rawAttached = false;
    rawSeen = false;
    activePointerId = null;
    downTarget = null;
    dragging = false;
  }

  function onPointerDown(event: PointerEvent): void {
    if (activePointerId !== null || event.button !== 0 || !event.isPrimary) return;
    const target = event.target;
    if (target instanceof Element && target.closest(INTERACTIVE_SELECTOR) !== null) return;
    activePointerId = event.pointerId;
    downTarget = target;
    startX = event.clientX;
    startY = event.clientY;
    const projected = point(event);
    lastX = projected.x; lastY = projected.y;
    dragging = false;
    sampleHead = 0;
    sampleCount = 0;
    pushSample(event.timeStamp, projected.x, projected.y);
    // Only subscribe during a gesture; raw input updates the target while the wall's
    // existing rAF owner still coalesces all DOM work into one frame.
    if (field.ownerDocument.defaultView && 'onpointerrawupdate' in field.ownerDocument.defaultView) {
      field.addEventListener('pointerrawupdate', onRawUpdate, { passive: true });
      rawAttached = true;
    }
  }

  function onPointerMove(event: PointerEvent): void {
    // Once raw events arrive, the delayed/coalesced pointermove repeats their movement.
    if (!rawSeen) movePointer(event);
  }

  function onRawUpdate(event: Event): void {
    const pointer = event as PointerEvent;
    if (pointer.pointerId !== activePointerId) return;
    rawSeen = true;
    movePointer(pointer);
  }

  function movePointer(event: PointerEvent): void {
    if (event.pointerId !== activePointerId) return;
    const { x, y } = point(event);
    pushSample(event.timeStamp, x, y);
    if (!dragging) {
      if (Math.hypot(event.clientX - startX, event.clientY - startY) < DRAG_THRESHOLD_PX) return;
      // The wall follows from the crossing point, so the drag starts without a 7 px jump.
      dragging = true;
      lastX = x;
      lastY = y;
      try {
        field.setPointerCapture(event.pointerId);
      } catch {
        // The pointer can vanish between events (or be synthetic); the gesture still works uncaptured.
      }
      handlers.onDragStart();
      return;
    }
    const dx = x - lastX;
    const dy = y - lastY;
    lastX = x;
    lastY = y;
    if (dx !== 0 || dy !== 0) handlers.onPan(dx, dy);
  }

  function onPointerUp(event: PointerEvent): void {
    if (event.pointerId !== activePointerId) return;
    const projected = point(event);
    pushSample(event.timeStamp, projected.x, projected.y);
    const target = downTarget;
    const wasDragging = dragging;
    endGesture();
    if (wasDragging) {
      const [vx, vy] = releaseVelocity();
      armClickSuppression();
      handlers.onFling(vx, vy);
      handlers.onDragEnd();
    } else {
      handlers.onTap(target, event.clientX, event.clientY);
    }
  }

  function onPointerCancel(event: PointerEvent): void {
    if (event.pointerId !== activePointerId) return;
    const wasDragging = dragging;
    endGesture();
    if (wasDragging) handlers.onDragEnd();
  }

  function onClickCapture(event: MouseEvent): void {
    if (!suppressClick) return;
    disarmClickSuppression();
    event.preventDefault();
    event.stopImmediatePropagation();
  }

  function onWheel(event: WheelEvent): void {
    // Scrollable text inside a card (plain lyrics) keeps native wheel scrolling.
    if (event.target instanceof Element) {
      const scrollable = event.target.closest<HTMLElement>('[data-scrollable]');
      if (scrollable && scrollable.scrollHeight > scrollable.clientHeight) return;
    }
    event.preventDefault();
    let dx = event.deltaX;
    let dy = event.deltaY;
    if (event.deltaMode === WheelEvent.DOM_DELTA_LINE) {
      dx *= LINE_DELTA_PX;
      dy *= LINE_DELTA_PX;
    } else if (event.deltaMode === WheelEvent.DOM_DELTA_PAGE) {
      dx *= field.clientWidth;
      dy *= field.clientHeight;
    }
    // Some platforms already deliver Shift+wheel as deltaX; only convert when they did not.
    if (event.shiftKey && dx === 0) {
      dx = dy;
      dy = 0;
    }
    if (handlers.projectPointer) {
      const from = handlers.projectPointer(event.clientX, event.clientY);
      const to = handlers.projectPointer(event.clientX + dx, event.clientY + dy);
      dx = to.x - from.x; dy = to.y - from.y;
    }
    if (dx !== 0 || dy !== 0) handlers.onWheel(dx, dy);
  }

  /** A native image drag would cancel the pointer gesture halfway through a pan. */
  function onNativeDragStart(event: DragEvent): void {
    event.preventDefault();
  }

  field.addEventListener('pointerdown', onPointerDown);
  field.addEventListener('pointermove', onPointerMove);
  field.addEventListener('pointerup', onPointerUp);
  field.addEventListener('pointercancel', onPointerCancel);
  field.addEventListener('lostpointercapture', onPointerCancel);
  field.addEventListener('click', onClickCapture, true);
  field.addEventListener('wheel', onWheel, { passive: false });
  field.addEventListener('dragstart', onNativeDragStart);

  return {
    dispose() {
      field.removeEventListener('pointerdown', onPointerDown);
      field.removeEventListener('pointermove', onPointerMove);
      field.removeEventListener('pointerup', onPointerUp);
      field.removeEventListener('pointercancel', onPointerCancel);
      field.removeEventListener('lostpointercapture', onPointerCancel);
      field.removeEventListener('click', onClickCapture, true);
      field.removeEventListener('wheel', onWheel);
      field.removeEventListener('dragstart', onNativeDragStart);
      disarmClickSuppression();
      endGesture();
    },
  };
}

/**
 * One poster card: pure presentation helpers (unit-tested in Node) plus the DOM factory and the
 * incremental writers used by `posterWall.ts`. Nothing here touches `document` at module scope so
 * the pure helpers can be imported from Node tests.
 */

import type { Camera, ExpandedContent, PixelRect, Tile } from '../types.ts';
import { createCoverSwapQueue, createPosterCover, type CoverSwapQueue, type PosterCover } from './posterCover.ts';
import type { CoverMotion } from './coverMotion.ts';

export const ENTRANCE_STEP_SECONDS = 0.055;
export const ENTRANCE_MAX_SECONDS = 0.8;

// ---------------------------------------------------------------------------------------------------
// Pure helpers
// ---------------------------------------------------------------------------------------------------

function hash32(text: string): number {
  let hash = 0x811c9dc5;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

function mix32(value: number): number {
  let mixed = value ^ (value >>> 16);
  mixed = Math.imul(mixed, 0x45d9f3b);
  mixed ^= mixed >>> 16;
  return mixed >>> 0;
}

/**
 * Deterministic two-colour gradient for tiles without cover art. Hues are at least 40° apart and
 * saturation/lightness stay in a band that keeps white overlay text readable.
 */
export function fallbackGradient(trackId: string): string {
  const first = hash32(trackId);
  const second = mix32(first);
  const hue1 = first % 360;
  const spread = 40 + ((first >>> 9) % 140);
  const hue2 = (hue1 + spread) % 360;
  const sat1 = 45 + ((first >>> 17) % 21);
  const sat2 = 45 + (second % 21);
  const light1 = 28 + ((first >>> 25) % 21);
  const light2 = 28 + ((second >>> 8) % 21);
  return `linear-gradient(135deg, hsl(${hue1} ${sat1}% ${light1}%), hsl(${hue2} ${sat2}% ${light2}%))`;
}

export function formatTime(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds <= 0) return '0:00';
  const total = Math.floor(seconds);
  const hours = Math.floor(total / 3600);
  const minutes = Math.floor((total % 3600) / 60);
  const rest = String(total % 60).padStart(2, '0');
  if (hours > 0) return `${hours}:${String(minutes).padStart(2, '0')}:${rest}`;
  return `${minutes}:${rest}`;
}

/** Shuffle the whole first viewport before mounting so the DOM budget cannot determine reveal order. */
export function entranceDelaysSeconds(ids: readonly string[], random = Math.random): Map<string, number> {
  const shuffled = [...new Set(ids)];
  for (let index = shuffled.length - 1; index > 0; index--) {
    const other = Math.floor(random() * (index + 1));
    [shuffled[index], shuffled[other]] = [shuffled[other]!, shuffled[index]!];
  }
  const step = shuffled.length > 1
    ? Math.min(ENTRANCE_STEP_SECONDS, ENTRANCE_MAX_SECONDS / (shuffled.length - 1)) : 0;
  return new Map(shuffled.map((id, index) => [id, Math.round(index * step * 1000) / 1000]));
}

/** Scale factors that grow a card by exactly one gap on each axis (SPEC §2.2). */
export function hoverScale(rectPx: PixelRect, gap: number): { x: number; y: number } {
  return {
    x: rectPx.w > 0 ? (rectPx.w + gap) / rectPx.w : 1,
    y: rectPx.h > 0 ? (rectPx.h + gap) / rectPx.h : 1,
  };
}

// ---------------------------------------------------------------------------------------------------
// DOM
// ---------------------------------------------------------------------------------------------------

export type PosterElement = {
  readonly root: HTMLElement;
  readonly body: HTMLElement;
  readonly cover: HTMLImageElement;
  readonly coverLoader: PosterCover;
  readonly fallback: HTMLElement;
  readonly caption: HTMLElement;
  readonly captionTitle: HTMLElement;
  readonly captionArtist: HTMLElement;
  /** Rect last written to the inline style; `applyRect` compares against it to skip redundant writes. */
  readonly rect: PixelRect;
  expanded: ExpandedContent | null;
  coverMotion: CoverMotion | null;
  /** Primitive snapshot of what the DOM currently shows, so `applyTile` only writes real changes. */
  readonly shown: {
    /** The tile's cover URL (host thumb variant). */
    coverUrl: string | null;
    /** Card box in CSS px (target rect, not spring frames); picks the cover variant with the expanded state. */
    box: { w: number; h: number };
    scale: number;
    trackId: string | null;
    label: string;
    current: boolean;
    hoverGap: number;
    fisheye: boolean;
    projectionRevision: number;
  };
};

function createDiv(className: string): HTMLDivElement {
  const element = document.createElement('div');
  element.className = className;
  return element;
}

const LOCAL_COVER_VARIANT = /^echo-cover:\/\/(?:thumb|album|large)\//u;
/** Above this many device pixels on the longest side, ECHO's 320 px `album` variant visibly blurs. */
export const ALBUM_VARIANT_MAX_DEVICE_PX = 480;

export type CoverVariant = 'thumb' | 'album' | 'large';

/**
 * The host hands out the small `thumb` variant (≈ 96 px) of local covers, which blurs on wall cards that
 * are 260 px and up. The same id also serves ECHO's `album` (≈ 320 px, what its grid cards decode) and
 * `large` (≈ 768 px, what its track views decode) variants. Non-local URLs pass through unchanged.
 */
export function coverVariantUrl(url: string, variant: CoverVariant): string {
  return LOCAL_COVER_VARIANT.test(url) ? url.replace(LOCAL_COVER_VARIANT, `echo-cover://${variant}/`) : url;
}

/** Select from displayed pixels, retaining the large variant near the boundary to avoid churn. */
export function coverVariantFor(
  box: { w: number; h: number }, _expanded: boolean, devicePixelRatio = 1, scale = 1, previous?: CoverVariant,
): CoverVariant {
  const pixels = Math.max(box.w, box.h) * devicePixelRatio * scale;
  const threshold = previous === 'large' ? ALBUM_VARIANT_MAX_DEVICE_PX * 0.85 : ALBUM_VARIANT_MAX_DEVICE_PX;
  return pixels > threshold ? 'large' : 'album';
}

/** Budgeted after geometry settles; the wall also limits temporary decode-and-swap work. */
export function syncPosterCover(el: PosterElement, commit = true): boolean {
  const base = el.shown.coverUrl;
  const dpr = typeof globalThis.devicePixelRatio === 'number' ? globalThis.devicePixelRatio : 1;
  const previous = el.coverLoader.source?.startsWith('echo-cover://large/') ? 'large' : undefined;
  const src = base === null ? null : coverVariantUrl(base,
    coverVariantFor(el.shown.box, el.expanded !== null, dpr, el.shown.scale, previous));
  if (el.coverLoader.matches(src)) return false;
  if (!commit) return true;
  el.coverLoader.request(src, base);
  return true;
}

export function createPosterElement(coverQueue: CoverSwapQueue = createCoverSwapQueue()): PosterElement {
  const root = document.createElement('article');
  root.className = 'poster';
  root.setAttribute('role', 'button');
  root.tabIndex = -1;

  const body = createDiv('poster__body');
  const coverLoader = createPosterCover(coverQueue);
  const cover = coverLoader.image;
  const fallback = createDiv('poster__fallback');
  // The fallback precedes the cover so the image paints above the gradient in plain DOM order.
  const art = createDiv('poster__art');
  art.append(fallback, cover);
  body.append(art, createDiv('poster__shade'), createDiv('poster__tint'), createDiv('poster__lights'));
  const caption = createDiv('poster__caption');
  const captionTitle = createDiv('poster__caption-title');
  const captionArtist = createDiv('poster__caption-artist');
  caption.append(captionTitle, captionArtist);
  caption.hidden = true;
  // The card already exposes the full title and artist through its accessible label.
  caption.setAttribute('aria-hidden', 'true');
  root.append(body, caption);

  const el: PosterElement = {
    root,
    body,
    get cover() { return coverLoader.image; },
    coverLoader,
    fallback,
    caption,
    captionTitle,
    captionArtist,
    rect: { x: NaN, y: NaN, w: NaN, h: NaN },
    expanded: null,
    coverMotion: null,
    shown: { coverUrl: null, box: { w: 0, h: 0 }, scale: 1, trackId: null, label: '', current: false, hoverGap: NaN, fisheye: false, projectionRevision: -1 },
  };
  return el;
}

/** Record target size; image selection is deferred until geometry settles. */
export function applyCardBox(el: PosterElement, box: { w: number; h: number }): void {
  const shown = el.shown;
  if (shown.box.w === box.w && shown.box.h === box.h) return;
  shown.box = { w: box.w, h: box.h };
  // Reserve the bottom inset and artist line; short cards show fewer title lines.
  el.root.style.setProperty('--caption-lines', String(Math.max(1, Math.min(3, Math.floor((box.h - 50) / 35.2)))));
  // Cover changes are flushed with a separate per-frame budget after motion settles.
}

export function applyTile(el: PosterElement, tile: Tile | undefined, isCurrent: boolean): void {
  const shown = el.shown;

  const coverUrl = tile?.coverUrl ?? null;
  if (coverUrl !== shown.coverUrl) {
    shown.coverUrl = coverUrl;
    el.root.dataset.squareCover = String(coverUrl !== null && LOCAL_COVER_VARIANT.test(coverUrl));
    syncPosterCover(el);
  }

  const trackId = tile ? tile.trackId : null;
  if (trackId !== shown.trackId) {
    shown.trackId = trackId;
    el.fallback.style.background = trackId === null ? '' : fallbackGradient(trackId);
  }

  const label = tile ? (tile.artist ? `${tile.title} · ${tile.artist}` : tile.title) : '';
  if (label !== shown.label) {
    shown.label = label;
    el.root.setAttribute('aria-label', label);
  }

  const title = tile?.title ?? '';
  if (el.captionTitle.textContent !== title) {
    el.captionTitle.textContent = title;
    el.root.title = title;
  }
  const artist = tile?.artist ?? '';
  if (el.captionArtist.textContent !== artist) el.captionArtist.textContent = artist;
  el.caption.hidden = !title;

  if (isCurrent !== shown.current) {
    shown.current = isCurrent;
    if (isCurrent) el.root.dataset.current = 'true';
    else delete el.root.dataset.current;
  }

  if (el.expanded) fillMeta(el.expanded, tile);
}

function round2(value: number): number {
  return Math.round(value * 100) / 100;
}

export function applyRect(el: PosterElement, rect: PixelRect, gap: number, moving = false): void {
  const last = el.rect;
  const style = el.root.style;
  const x = round2(rect.x);
  const y = round2(rect.y);
  // Whole-pixel sizes avoid a layout on every subpixel spring tail; the settled write is exact.
  const w = moving ? Math.round(rect.w) : round2(rect.w);
  const h = moving ? Math.round(rect.h) : round2(rect.h);

  if (x !== last.x || y !== last.y) {
    el.shown.projectionRevision = -1;
    last.x = x;
    last.y = y;
    style.transform = `translate(${x}px, ${y}px)`;
  }
  let sizeChanged = false;
  if (w !== last.w) {
    last.w = w;
    sizeChanged = true;
    style.width = `${w}px`;
  }
  if (h !== last.h) {
    last.h = h;
    sizeChanged = true;
    style.height = `${h}px`;
  }
  if (sizeChanged || gap !== el.shown.hoverGap) {
    if (sizeChanged) el.shown.projectionRevision = -1;
    // Local thumbnails are square crops; keep the same crop when the full-aspect large image arrives.
    style.setProperty('--cover-side', `${Math.max(w, h)}px`);
    el.shown.hoverGap = gap;
    const scale = hoverScale(last, gap);
    style.setProperty('--hx', scale.x.toFixed(4));
    style.setProperty('--hy', scale.y.toFixed(4));
  }
}

/** Cache lens work while only the playback clock changes. */
export function syncPosterProjection(el: PosterElement, camera: Camera, revision: number): void {
  if (!camera.fisheye) {
    if (el.shown.fisheye) el.root.style.transform = camera.cardTransform(el.rect);
    el.shown.fisheye = false;
    return;
  }
  if (el.shown.fisheye && el.shown.projectionRevision === revision) return;
  el.shown.fisheye = true;
  el.shown.projectionRevision = revision;
  el.root.style.transform = camera.cardTransform(el.rect);
}

function fillMeta(content: ExpandedContent, tile: Tile | undefined): void {
  const title = content.meta.firstElementChild;
  const artist = content.meta.lastElementChild;
  const titleText = tile ? tile.title : '';
  const artistText = tile ? (tile.album ? `${tile.artist} · ${tile.album}` : tile.artist) : '';
  if (title && title.textContent !== titleText) title.textContent = titleText;
  if (artist && artist.textContent !== artistText) artist.textContent = artistText;
}

export function buildExpandedContent(el: PosterElement, tile: Tile | undefined): ExpandedContent {
  if (!el.expanded) {
    const root = createDiv('poster__expanded');
    const meta = createDiv('poster__meta');
    const title = document.createElement('h1');
    title.className = 'poster__title';
    const artist = document.createElement('p');
    artist.className = 'poster__artist';
    meta.append(title, artist);
    const controls = createDiv('poster__controls');
    const lyrics = createDiv('poster__lyrics');
    root.append(meta, controls, lyrics);
    el.root.append(root);
    el.expanded = { root, meta, controls, lyrics };
  }
  fillMeta(el.expanded, tile);
  el.root.setAttribute('role', 'group');
  return el.expanded;
}

export function removeExpandedContent(el: PosterElement): void {
  if (!el.expanded) return;
  const active = document.activeElement;
  const restore = Boolean(active && el.expanded.root.contains(active));
  el.expanded.root.remove();
  el.expanded = null;
  el.root.setAttribute('role', 'button');
  if (!restore) return;
  // Keep DOM focus on the field after collapse so a leftover card focus cannot look selected.
  if (el.root.dataset.expanded === 'true') {
    el.root.focus({ preventScroll: true });
    return;
  }
  el.root.closest<HTMLElement>('.field')?.focus({ preventScroll: true });
}

/**
 * Strip the per-instance presentation state (expansion, focus, entrance classes) so the element can be
 * pointed at another instance in place. Tile content and the geometry cache are left alone: `applyTile`
 * and `applyRect` only write what actually differs for the next instance.
 */
export function clearPosterInstance(el: PosterElement): void {
  el.coverMotion = null;
  removeExpandedContent(el);
  const root = el.root;
  root.className = 'poster';
  root.tabIndex = -1;
  delete root.dataset.instance;
  delete root.dataset.expanded;
  delete root.dataset.settled;
  delete root.dataset.focused;
  delete root.dataset.lyrics;
  delete root.dataset.lensHover;
  root.style.removeProperty('--enter-delay');
}

/** Return a card to the free list: clear instance state and drop the cover so parked cards hold no image. */
export function resetPosterElement(el: PosterElement): void {
  clearPosterInstance(el);
  if (el.shown.current) {
    el.shown.current = false;
    delete el.root.dataset.current;
  }
  el.shown.coverUrl = null;
  el.coverLoader.clear();
  el.shown.box = { w: 0, h: 0 };
}

type SwapJob = { start: (done: () => void) => () => void; cancel: (() => void) | null };

/** Shared queue for at most two temporary decoded size replacements. */
export function createCoverSwapQueue(onChanged: () => void = () => {}) {
  const waiting = new Set<SwapJob>();
  const active = new Set<SwapJob>();
  let disposed = false;
  let paused = false;
  function pump(): void {
    while (!disposed && !paused && active.size < 2 && waiting.size) {
      const job = waiting.values().next().value!;
      waiting.delete(job); active.add(job);
      job.cancel = job.start(() => {
        active.delete(job); job.cancel = null; pump();
        onChanged();
      });
      if (!active.has(job)) { job.cancel?.(); job.cancel = null; }
    }
  }
  function clear(): void {
    waiting.clear();
    for (const job of active) job.cancel?.();
    active.clear();
  }
  return {
    enqueue(start: SwapJob['start']): () => void {
      if (disposed) return () => {};
      const job: SwapJob = { start, cancel: null };
      waiting.add(job); pump();
      return () => {
        waiting.delete(job); active.delete(job);
        const cancel = job.cancel; job.cancel = null;
        cancel?.(); pump();
      };
    },
    clear,
    /** Finish at most the two in-flight decodes; defer the remaining size swaps during motion. */
    setPaused(next: boolean): void {
      if (paused === next) return;
      paused = next;
      if (!paused) pump();
    },
    dispose(): void { disposed = true; clear(); },
  };
}

export type CoverSwapQueue = ReturnType<typeof createCoverSwapQueue>;

function createImage(): HTMLImageElement {
  const image = document.createElement('img');
  image.className = 'poster__cover';
  image.loading = 'eager'; image.decoding = 'async';
  image.crossOrigin = 'anonymous';
  image.alt = ''; image.draggable = false; image.hidden = true;
  return image;
}

/** Keep the current cover visible until its replacement is decoded and ready to display. */
export function createPosterCover(queue: CoverSwapQueue) {
  let image = createImage();
  let base: string | null = null;
  let source: string | null = null;
  let failed: string | null = null;
  let pending: { source: string; cancel: (() => void) | null } | null = null;

  function cancelPending(): void {
    const previous = pending; pending = null;
    previous?.cancel?.();
  }

  function clear(): void {
    cancelPending(); base = null; source = null; failed = null;
    image.onerror = null; image.hidden = true; image.removeAttribute('src');
  }

  function showInitial(src: string): void {
    source = src;
    image.onerror = () => {
      failed ??= source;
      if (base !== null && source !== base) showInitial(base);
      else image.hidden = true;
    };
    image.src = src; image.hidden = false;
  }

  function requestCover(src: string | null, nextBase: string | null): void {
    if (src === null || nextBase === null) { clear(); return; }
    if (base !== nextBase) {
      clear(); base = nextBase;
    }
    cancelPending();
    if (source === null) { showInitial(src); return; }
    if (source === src || failed === src) return;
    const request = { source: src, cancel: null as (() => void) | null };
    pending = request;
    request.cancel = queue.enqueue(done => {
      const next = createImage();
      let timer: ReturnType<typeof setTimeout> | null = null;
      let finished = false;
      const cleanup = () => {
        if (timer !== null) clearTimeout(timer);
        timer = null; next.onload = null; next.onerror = null;
      };
      const finish = (ready: boolean) => {
        if (finished) return;
        finished = true; cleanup();
        if (pending === request) {
          pending = null;
          if (ready) {
            const previous = image;
            next.hidden = false; image = next; source = src;
            if (previous !== next) {
              previous.replaceWith(next);
              previous.onerror = null; previous.removeAttribute('src');
            }
          } else if (src !== base || failed === null) failed = src;
        }
        if (!ready || image !== next) next.removeAttribute('src');
        done();
      };
      next.onerror = () => finish(false);
      timer = setTimeout(() => finish(false), 10000);
      next.src = src;
      if (typeof next.decode === 'function') void next.decode().then(() => finish(true), () => finish(false));
      else next.onload = () => finish(true);
      return () => {
        finished = true; cleanup(); next.removeAttribute('src');
      };
    });
  }

  return {
    get image() { return image; },
    get source() { return source; },
    matches(src: string | null): boolean {
      if (src !== null && src === failed) return true;
      return src === (pending?.source ?? source);
    },
    request: requestCover,
    clear,
  };
}

export type PosterCover = ReturnType<typeof createPosterCover>;

/**
 * Poster wall renderer (SPEC §2.2, §2.3, §6): owns the `.poster` pool inside `.world`, culls it
 * against the camera, animates rect changes with rect springs and raises user intent to `main.ts`
 * through `PosterWallHandlers`. It never talks to the host and never moves the camera.
 */

import {
  BLOCK_COLS,
  BLOCK_ROWS,
  type Camera,
  type ExpandedContent,
  type GridRect,
  type Instance,
  type Lattice,
  type PixelRect,
  type PosterWall,
  type PosterWallHandlers,
  type Tile,
  type WallVisualOptions,
} from '../types.ts';
import { createRectSpring, type RectSpring } from './spring.ts';
import {
  applyCardBox,
  applyRect,
  applyTile,
  buildExpandedContent,
  clearPosterInstance,
  createPosterElement,
  ENTRANCE_MAX_SECONDS,
  entranceDelaysSeconds,
  removeExpandedContent,
  resetPosterElement,
  syncPosterCover,
  syncPosterProjection,
  type PosterElement,
} from './poster.ts';
import { createCoverSwapQueue } from './posterCover.ts';
import { ENTRANCE_DURATION_MS, sampleCoverMotion } from './coverMotion.ts';
import { FISHEYE_BOUNDS_SCALE, projectedCardBounds } from './fisheye.ts';
import { createFisheyeSurface } from './fisheyeSurface.ts';
import { createFisheyeUiProjection } from './fisheyeUi.ts';
import { createDepthScene } from './depthScene.ts';
import { HUD_DEFAULT_TILT_ANGLE } from '../hudSettings.ts';

const OVERSCAN_PX = 500;
const RECULL_MARGIN_PX = 180;
const CULL_LIMIT = 250;
const MAX_FREE = 64;
const MAX_FRAME_SECONDS = 0.064;
/** A gap longer than this means the rAF loop was idle; integrate one nominal frame instead of a big jump. */
const IDLE_GAP_SECONDS = 0.25;
/**
 * Bound DOM/image work even at first paint or after a camera jump. Visible cards take priority,
 * followed by overscan preparation. Reuse stale nodes in place instead of rebuilding the DOM tree.
 */
const MOUNT_BUDGET_PER_FRAME = 8;

type Entry = {
  el: PosterElement;
  instance: Instance;
  spring: RectSpring | null;
  tileIndex: number;
  /** Layout rect in world px; equals the written rect once no spring is active. */
  target: PixelRect;
  /** Cull generation that last saw this entry; entries left behind are recycled. */
  stamp: number;
};

function gridEquals(a: GridRect, b: GridRect): boolean {
  return a.col === b.col && a.row === b.row && a.w === b.w && a.h === b.h;
}

function pixelEquals(a: PixelRect, b: PixelRect): boolean {
  return a.x === b.x && a.y === b.y && a.w === b.w && a.h === b.h;
}

function intersects(a: PixelRect, b: PixelRect): boolean {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

function elementFromTarget(target: EventTarget | null): Element | null {
  if (target instanceof Element) return target;
  if (target instanceof Node) return target.parentElement;
  return null;
}

export function createPosterWall(world: HTMLElement, handlers: PosterWallHandlers): PosterWall {
  let lattice: Lattice | null = null;
  let tiles: Tile[] = [];
  let currentTile: number | null = null;
  let expanded: Instance | null = null;
  let focused: Instance | null = null;
  /** `setFocus` asked to move DOM focus onto a card that was not mounted yet. */
  let focusPending = false;
  let reducedMotion = false;
  let coverScale = 1;
  let cullLimit = CULL_LIMIT;
  const field = world.parentElement!;
  const depth = createDepthScene(field, world, () => handlers.onRenderNeeded?.());
  let surface: ReturnType<typeof createFisheyeSurface> = null;
  let surfaceFailed = false;
  let surfaceDirty = true;
  let interactionCamera: Camera | null = null;
  let visualOptions: WallVisualOptions = { pointer3d: false, hudTiltAngle: HUD_DEFAULT_TILT_ANGLE, lightsOut: false, vignette: true, tint: true,
    tintGradient: 'none', tintColor: '#000000', tintIntensity: .5, reducedMotion: false };

  const pool = new Map<string, Entry>();
  const free: PosterElement[] = [];
  /** Instances from the latest cull still waiting for a card, nearest to the viewport first. */
  const pendingMounts: Instance[] = [];
  /** Mounted cards that left the culled area; reused for `pendingMounts` before any new card is made. */
  const staleEntries: Entry[] = [];
  let stamp = 0;
  let needsCull = true;
  /** Set by `setLattice`: every mounted card must re-read tile + rect and snap at the next cull. */
  let layoutDirty = true;
  let culledOnce = false;
  const cullBounds: PixelRect = { x: 0, y: 0, w: 0, h: 0 };
  const lastView = { x: NaN, y: NaN, scale: NaN, width: NaN, height: NaN, fisheye: false, amount: NaN };
  let projectionRevision = 0;
  let lastNow: number | null = null;
  let entrance: 'idle' | 'pending' | 'played' = 'idle';
  let entranceStartedAt: number | null = null;
  let entranceDelays = new Map<string, number>();
  let entranceCompletionPending = false;
  /** `onExpandSettled` still owed for the current expansion. */
  let settlePending = false;
  /** Previously expanded card that keeps its content until its spring settles. */
  let collapsing: Entry | null = null;
  let hoverId: string | null = null;
  let disposed = false;
  const abort = new AbortController();
  const signal = abort.signal;
  const coverQueue = createCoverSwapQueue(() => { surfaceDirty = true; handlers.onRenderNeeded?.(); });
  const uiProjection = createFisheyeUiProjection(() => handlers.onRenderNeeded?.());

  const gap = (): number => (lattice ? lattice.metrics.gap : 0);

  function entryFromTarget(target: EventTarget | null): Entry | null {
    const card = elementFromTarget(target)?.closest<HTMLElement>('.poster');
    if (!card) return null;
    const id = card.dataset.instance;
    return id === undefined ? null : (pool.get(id) ?? null);
  }

  function entryAtPoint(clientX: number, clientY: number): Entry | null {
    if (!interactionCamera?.fisheye || world.dataset.fisheyeSurface !== 'true') return null;
    const screen = depth.pointerPoint(clientX, clientY);
    const point = interactionCamera.screenToWorld(screen.x, screen.y);
    const contains = (entry: Entry) => point.x >= entry.el.rect.x && point.y >= entry.el.rect.y
      && point.x < entry.el.rect.x + entry.el.rect.w && point.y < entry.el.rect.y + entry.el.rect.h;
    const open = expanded ? pool.get(expanded.id) : null;
    if (open && contains(open)) return open;
    for (const entry of [...pool.values()].reverse()) if (contains(entry)) return entry;
    return null;
  }

  function sameQueueId(previousTiles: Tile[], previousIndex: number, nextIndex: number): boolean {
    const before = previousTiles[previousIndex];
    const after = tiles[nextIndex];
    return before !== undefined && after !== undefined && before.queueId === after.queueId;
  }

  function setFocusAttrs(el: PosterElement): void {
    el.root.dataset.focused = 'true';
    el.root.tabIndex = 0;
  }

  function clearFocusAttrs(el: PosterElement): void {
    delete el.root.dataset.focused;
    el.root.tabIndex = -1;
  }

  function clearAllFocusAttrs(): void {
    for (const entry of pool.values()) clearFocusAttrs(entry.el);
  }

  /** Insert new cards without moving the expanded node; CSS z-index keeps it on top. */
  function insertCard(root: HTMLElement, instance: Instance): void {
    const anchor = expanded && expanded.id !== instance.id ? pool.get(expanded.id)?.el.root : undefined;
    if (anchor && anchor.parentElement === world) world.insertBefore(root, anchor);
    else world.appendChild(root);
  }

  function finishCollapse(): void {
    if (!collapsing) return;
    const entry = collapsing;
    collapsing = null;
    removeExpandedContent(entry.el);
    if (expanded) return;
    clearFocusAttrs(entry.el);
    if (focused?.id === entry.instance.id) {
      focused = null;
      focusPending = false;
      handlers.onFocusChange(null);
    }
  }

  function checkSettled(): void {
    if (!settlePending || !expanded) return;
    const entry = pool.get(expanded.id);
    if (!entry || entry.spring || layoutDirty) return;
    settlePending = false;
    entry.el.root.dataset.settled = 'true';
    const instance = expanded;
    // Deferred so main's own `setExpanded` call stack has unwound before it mounts lyrics.
    queueMicrotask(() => {
      if (!disposed && expanded && expanded.id === instance.id) handlers.onExpandSettled(instance);
    });
  }

  function moveEntry(entry: Entry, target: PixelRect, animate: boolean): void {
    const changed = !pixelEquals(entry.target, target);
    entry.target = target;
    if (!animate) {
      entry.spring = null;
      applyRect(entry.el, target, gap());
      return;
    }
    if (!changed) return;
    if (!entry.spring) entry.spring = createRectSpring({ ...entry.el.rect });
    entry.spring.setTarget(target);
  }

  function retargetBlock(lat: Lattice, bc: number, br: number, animate: boolean): void {
    for (const instance of lat.blockInstances(bc, br, expanded)) {
      const entry = pool.get(instance.id);
      if (!entry) continue;
      entry.instance = instance;
      const target = lat.toPixels(instance.rect);
      applyCardBox(entry.el, target);
      moveEntry(entry, target, animate);
    }
  }

  /** Points a card element (fresh, pooled or just unbound) at `instance` and registers it in the pool. */
  function bindEntry(lat: Lattice, el: PosterElement, instance: Instance, visible: PixelRect): Entry {
    surfaceDirty = true;
    const target = lat.toPixels(instance.rect);
    const entry: Entry = { el, instance, spring: null, tileIndex: instance.tileIndex, target, stamp };
    const tile = tiles[instance.tileIndex];
    // Commit the new box and cover together; do not request a resized variant of the old image.
    el.shown.scale = coverScale;
    applyCardBox(el, target);
    applyTile(el, tile, instance.tileIndex === currentTile);
    applyRect(el, target, lat.metrics.gap);
    el.root.dataset.instance = instance.id;
    // Only a card that appears inside the viewport needs the fade; overscan mounts are never seen
    // popping in, and skipping the animation there avoids a class + animationend cycle per card.
    if (entrance !== 'pending' && !reducedMotion && !enterCard(entry, performance.now())
      && culledOnce && intersects(target, visible)) {
      el.coverMotion = { kind: 'fade', startedAt: performance.now(), delayMs: 0 };
      el.root.classList.add('poster--fade');
    }
    if (expanded && expanded.id === instance.id) {
      el.root.dataset.expanded = 'true';
      buildExpandedContent(el, tile);
    }
    if (focused !== null && focused.id === instance.id) setFocusAttrs(el);
    pool.set(instance.id, entry);
    return entry;
  }

  /** Once the card is in the DOM, deliver the DOM focus `setFocus` asked for before it was mounted. */
  function settleFocus(entry: Entry): void {
    if (!focusPending || focused === null || focused.id !== entry.instance.id) return;
    focusPending = false;
    entry.el.root.focus({ preventScroll: true });
  }

  function mountEntry(lat: Lattice, instance: Instance, visible: PixelRect): Entry {
    const el = free.pop() ?? createPosterElement(coverQueue);
    const entry = bindEntry(lat, el, instance, visible);
    insertCard(el.root, instance);
    settleFocus(entry);
    return entry;
  }

  /** Forget the instance a card shows; `park` also drops its cover because it is going to the free list. */
  function unbindEntry(entry: Entry, park: boolean): void {
    surfaceDirty = true;
    pool.delete(entry.instance.id);
    if (collapsing === entry) collapsing = null;
    if (hoverId === entry.instance.id) hoverId = null;
    const root = entry.el.root;
    const active = document.activeElement;
    // Taking the focused node away would drop DOM focus to <body>; hand it to the field instead.
    if (active && root.contains(active)) world.parentElement?.focus({ preventScroll: true });
    if (park) resetPosterElement(entry.el);
    else clearPosterInstance(entry.el);
    entry.spring = null;
  }

  /** Re-point a card that left the culled area at a new instance without touching the DOM tree. */
  function rebindEntry(lat: Lattice, entry: Entry, instance: Instance, visible: PixelRect): Entry {
    unbindEntry(entry, false);
    const next = bindEntry(lat, entry.el, instance, visible);
    settleFocus(next);
    return next;
  }

  function refreshEntry(lat: Lattice, entry: Entry, instance: Instance, snapAll: boolean): void {
    const previousRect = entry.instance.rect;
    entry.instance = instance;
    if (!snapAll && entry.tileIndex === instance.tileIndex && gridEquals(previousRect, instance.rect)) return;
    const target = lat.toPixels(instance.rect);
    applyCardBox(entry.el, target);
    if (snapAll || entry.tileIndex !== instance.tileIndex) {
      entry.tileIndex = instance.tileIndex;
      applyTile(entry.el, tiles[instance.tileIndex], instance.tileIndex === currentTile);
    }
    if (snapAll || !gridEquals(previousRect, instance.rect)) {
      moveEntry(entry, target, !snapAll && !reducedMotion);
    }
  }

  function recycleEntry(entry: Entry): void {
    unbindEntry(entry, true);
    entry.el.root.remove();
    if (free.length < MAX_FREE) free.push(entry.el);
  }

  /** Keep each mounted card on the same song if that song still has a slot in this block. */
  function rematchPoolByTile(lat: Lattice): void {
    if (pool.size === 0) return;
    const entries = [...pool.values()];
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    for (const entry of entries) {
      const rect = entry.target;
      minX = Math.min(minX, rect.x);
      minY = Math.min(minY, rect.y);
      maxX = Math.max(maxX, rect.x + rect.w);
      maxY = Math.max(maxY, rect.y + rect.h);
    }
    const bounds: PixelRect = {
      x: minX,
      y: minY,
      w: Math.max(1, maxX - minX),
      h: Math.max(1, maxY - minY),
    };
    const available = lat.cull(bounds, OVERSCAN_PX, null, cullLimit);
    const taken = new Uint8Array(available.length);
    pool.clear();
    const leftover: Entry[] = [];
    const maxTravel = lat.unit * lat.unit * (BLOCK_COLS * BLOCK_COLS + BLOCK_ROWS * BLOCK_ROWS);
    const distanceTo = (instance: Instance, cx: number, cy: number): number => {
      const centre = lat.centerOf(instance.rect);
      const dx = centre.x - cx;
      const dy = centre.y - cy;
      return dx * dx + dy * dy;
    };
    const claim = (cx: number, cy: number, allow: (instance: Instance) => boolean): Instance | undefined => {
      let best = -1;
      let bestD = Infinity;
      for (let i = 0; i < available.length; i++) {
        if (taken[i] === 1) continue;
        const instance = available[i];
        if (!instance || !allow(instance)) continue;
        const distance = distanceTo(instance, cx, cy);
        if (distance < bestD) {
          bestD = distance;
          best = i;
        }
      }
      if (best < 0) return undefined;
      taken[best] = 1;
      return available[best];
    };
    entries.sort((a, b) => {
      const aCurrent = currentTile !== null && a.tileIndex === currentTile ? 0 : 1;
      const bCurrent = currentTile !== null && b.tileIndex === currentTile ? 0 : 1;
      return aCurrent - bCurrent;
    });
    for (const entry of entries) {
      const cx = entry.target.x + entry.target.w / 2;
      const cy = entry.target.y + entry.target.h / 2;
      const instance =
        claim(cx, cy, (next) => next.bc === entry.instance.bc && next.br === entry.instance.br && next.tileIndex === entry.tileIndex)
        ?? claim(cx, cy, (next) => next.tileIndex === entry.tileIndex && distanceTo(next, cx, cy) <= maxTravel)
        ?? claim(cx, cy, (next) => next.bc === entry.instance.bc && next.br === entry.instance.br);
      if (!instance) {
        leftover.push(entry);
        continue;
      }
      if (instance.tileIndex !== entry.tileIndex) {
        entry.tileIndex = instance.tileIndex;
        applyTile(entry.el, tiles[entry.tileIndex], entry.tileIndex === currentTile);
      }
      entry.instance = instance;
      entry.el.root.dataset.instance = instance.id;
      if (focused === null || focused.id !== instance.id) clearFocusAttrs(entry.el);
      const target = lat.toPixels(instance.rect);
      applyCardBox(entry.el, target);
      moveEntry(entry, target, !reducedMotion);
      pool.set(instance.id, entry);
    }
    for (const entry of leftover) recycleEntry(entry);
  }

  function leavesCulledArea(bounds: PixelRect): boolean {
    const margin = OVERSCAN_PX - RECULL_MARGIN_PX;
    return (
      bounds.x < cullBounds.x - margin ||
      bounds.y < cullBounds.y - margin ||
      bounds.x + bounds.w > cullBounds.x + cullBounds.w + margin ||
      bounds.y + bounds.h > cullBounds.y + cullBounds.h + margin
    );
  }

  function recull(lat: Lattice, bounds: PixelRect): void {
    // Reserve one slot for the expanded card, which remains mounted even far outside the viewport.
    const culled = lat.cull(bounds, OVERSCAN_PX, expanded, expanded ? cullLimit - 1 : cullLimit);
    stamp += 1;
    const snapAll = layoutDirty;
    layoutDirty = false;
    // All new cards share the mount budget, including first paint and fast camera jumps.
    // The expanded card is the single immediate exception so its controls remain available.
    pendingMounts.length = 0;
    staleEntries.length = 0;

    // Find reusable nodes first so even a whole-page replacement never grows beyond the DOM cap.
    const wanted = new Set(culled.map(instance => instance.id));
    for (const entry of pool.values()) {
      if (!wanted.has(entry.instance.id) && entry.instance.id !== expanded?.id) staleEntries.push(entry);
    }
    for (const instance of culled) {
      const entry = pool.get(instance.id);
      if (entry) {
        entry.stamp = stamp;
        refreshEntry(lat, entry, instance, snapAll);
      } else if (!(expanded && expanded.id === instance.id)) {
        pendingMounts.push(instance);
      } else {
        const stale = staleEntries.pop();
        if (stale) rebindEntry(lat, stale, instance, bounds);
        else mountEntry(lat, instance, bounds);
      }
    }

    // The expanded card stays mounted even off-screen; it is the only exception to the cull.
    if (expanded) {
      const entry = pool.get(expanded.id);
      if (entry && entry.stamp !== stamp) {
        entry.stamp = stamp;
        refreshEntry(lat, entry, expanded, snapAll);
      }
    }

    // Stable partition: visible work first, preserve nearest-first order within each group.
    pendingMounts.sort((a, b) => Number(intersects(lat.toPixels(b.rect), bounds)) - Number(intersects(lat.toPixels(a.rect), bounds)));

    cullBounds.x = bounds.x;
    cullBounds.y = bounds.y;
    cullBounds.w = bounds.w;
    cullBounds.h = bounds.h;
    culledOnce = true;
    needsCull = false;
  }

  /**
   * Works through the deferred cull a few cards per frame: fresh instances take over stale cards in
   * place, then any stale cards left over (the culled set shrank) go back to the free list. `render`
   * keeps the frame loop alive for urgent work; distant overscan waits until motion settles.
   */
  function flushMounts(lat: Lattice, bounds: PixelRect, cameraMoving: boolean): boolean {
    let budget = cameraMoving ? 2 : MOUNT_BUDGET_PER_FRAME;
    const deadline = performance.now() + (cameraMoving ? 1 : 3);
    // Do not repaint the wall just to prepare distant overscan while it is moving.
    // Re-evaluate against this frame's bounds: the camera can reverse between culls.
    const urgentBounds = {
      x: bounds.x - RECULL_MARGIN_PX, y: bounds.y - RECULL_MARGIN_PX,
      w: bounds.w + RECULL_MARGIN_PX * 2, h: bounds.h + RECULL_MARGIN_PX * 2,
    };
    const urgent = (instance: Instance): boolean => intersects(lat.toPixels(instance.rect), urgentBounds);
    while (pendingMounts.length > 0) {
      if (budget <= 0 || performance.now() >= deadline) break;
      const index = cameraMoving ? pendingMounts.findIndex(urgent) : 0;
      if (index < 0) break;
      const instance = pendingMounts.splice(index, 1)[0]!;
      if (pool.has(instance.id)) continue;
      const stale = staleEntries.pop();
      if (stale) rebindEntry(lat, stale, instance, bounds);
      else mountEntry(lat, instance, bounds);
      budget -= 1;
    }
    while (budget > 0 && performance.now() < deadline && pendingMounts.length === 0 && staleEntries.length > 0) {
      recycleEntry(staleEntries.pop()!);
      budget -= 1;
    }
    // Offscreen work waits for input/animation or the settling frame, not a busy rAF loop.
    return cameraMoving ? pendingMounts.some(urgent)
      : pendingMounts.length > 0 || staleEntries.length > 0;
  }

  function enterCard(entry: Entry, nowMs: number): boolean {
    const delay = entranceDelays.get(entry.instance.id);
    if (entranceStartedAt === null || delay === undefined) return false;
    const delayMs = delay * 1000;
    if (nowMs >= entranceStartedAt + delayMs + ENTRANCE_DURATION_MS) return false;
    entry.el.coverMotion = { kind: 'enter', startedAt: entranceStartedAt, delayMs };
    // Late mounts join the same timeline instead of flashing in or replaying a full delay.
    entry.el.root.style.setProperty('--enter-delay', `${(entranceStartedAt + delayMs - nowMs) / 1000}s`);
    entry.el.root.classList.remove('poster--fade');
    entry.el.root.classList.add('poster--enter');
    surfaceDirty = true;
    return true;
  }

  function finishEntrance(): void {
    entranceDelays.clear();
    entranceStartedAt = null;
    delete field.dataset.entering;
    surfaceDirty = true;
    entranceCompletionPending = true;
  }

  function applyEntrance(lat: Lattice, bounds: PixelRect, nowMs: number): void {
    entrance = 'played';
    if (reducedMotion) { finishEntrance(); return; }
    const instances = [...pool.values()].map(entry => entry.instance).concat(pendingMounts);
    entranceDelays = entranceDelaysSeconds(instances
      .filter(instance => intersects(lat.toPixels(instance.rect), bounds)).map(instance => instance.id));
    entranceStartedAt = nowMs;
    field.dataset.entering = 'true';
    for (const entry of pool.values()) enterCard(entry, nowMs);
  }

  function snapAll(): void {
    const g = gap();
    for (const entry of pool.values()) {
      if (reducedMotion) {
        entry.el.coverMotion = null;
        entry.el.root.classList.remove('poster--enter', 'poster--fade');
      }
      if (!entry.spring) continue;
      entry.spring = null;
      applyRect(entry.el, entry.target, g);
    }
    finishCollapse();
    checkSettled();
  }

  function applyFocus(instance: Instance | null, moveDomFocus: boolean): void {
    if (focused && (!instance || focused.id !== instance.id)) {
      const previous = pool.get(focused.id);
      if (previous) clearFocusAttrs(previous.el);
    }
    const changed = focused?.id !== instance?.id;
    if (changed) { surfaceDirty = true; handlers.onRenderNeeded?.(); }
    focused = instance;
    focusPending = false;
    if (!instance) {
      clearAllFocusAttrs();
      if (changed) handlers.onFocusChange(null);
      return;
    }
    for (const entry of pool.values()) {
      if (entry.instance.id !== instance.id) clearFocusAttrs(entry.el);
    }
    const entry = pool.get(instance.id);
    if (!entry) {
      focusPending = moveDomFocus;
      return;
    }
    setFocusAttrs(entry.el);
    // Focus already inside the card (e.g. on the seek slider) is left where it is.
    const active = document.activeElement;
    if (moveDomFocus && !(active && entry.el.root.contains(active))) entry.el.root.focus({ preventScroll: true });
  }

  field.addEventListener(
    'click',
    (event) => {
      const element = elementFromTarget(event.target);
      const nativeControl = element?.closest('button, input, select, textarea, a[href], .poster__controls, .poster__expanded, .poster__caption');
      const entry = nativeControl || event.detail === 0 ? entryFromTarget(event.target)
        : entryAtPoint(event.clientX, event.clientY) ?? entryFromTarget(event.target);
      if (!entry) return;
      if (expanded && entry.instance.id === expanded.id) {
        // The second click of a double-click must not immediately hide the controls just shown.
        if (event.detail > 1) return;
        const element = elementFromTarget(event.target);
        if (element?.closest('.poster__controls')) return;
        handlers.onExpandedTap(entry.instance);
        return;
      }
      handlers.onActivate(entry.instance);
    },
    { signal },
  );

  field.addEventListener('pointermove', event => {
    if (!interactionCamera?.fisheye || world.dataset.fisheyeSurface !== 'true') return;
    const entry = field.ownerDocument.body.dataset.dragging === 'true' ? null : entryAtPoint(event.clientX, event.clientY);
    if (hoverId === (entry?.instance.id ?? null)) return;
    if (hoverId) pool.get(hoverId)?.el.root.removeAttribute('data-lens-hover');
    hoverId = entry?.instance.id ?? null;
    if (entry) {
      entry.el.root.dataset.lensHover = 'true';
      if (entry.tileIndex === currentTile) handlers.onHoverCurrent(entry.instance);
    }
    surfaceDirty = true; handlers.onRenderNeeded?.();
  }, { signal, passive: true });
  field.addEventListener('pointerleave', () => {
    if (hoverId) pool.get(hoverId)?.el.root.removeAttribute('data-lens-hover');
    hoverId = null; surfaceDirty = true; handlers.onRenderNeeded?.();
  }, { signal, passive: true });

  world.addEventListener(
    'mousedown',
    (event) => {
      // A press that turns into a drag must not focus the card it started on; real taps get DOM
      // focus through `setFocus` from main. Controls keep their native press behaviour.
      const element = elementFromTarget(event.target);
      if (element && !element.closest('.poster__controls, button, input, select, textarea, a[href]')) event.preventDefault();
    },
    { signal },
  );

  world.addEventListener(
    'pointerover',
    (event) => {
      if (world.dataset.fisheyeSurface === 'true') return;
      const entry = entryFromTarget(event.target);
      if (!entry || hoverId === entry.instance.id) return;
      hoverId = entry.instance.id;
      if (currentTile !== null && entry.tileIndex === currentTile) handlers.onHoverCurrent(entry.instance);
    },
    { signal, passive: true },
  );

  world.addEventListener(
    'pointerout',
    (event) => {
      if (world.dataset.fisheyeSurface === 'true') return;
      const card = elementFromTarget(event.target)?.closest<HTMLElement>('.poster');
      if (!card) return;
      const to = event.relatedTarget;
      if (to instanceof Node && card.contains(to)) return;
      if (hoverId === card.dataset.instance) hoverId = null;
    },
    { signal, passive: true },
  );

  world.addEventListener(
    'focusin',
    (event) => {
      const entry = entryFromTarget(event.target);
      if (!entry || (focused && focused.id === entry.instance.id)) return;
      applyFocus(entry.instance, false);
      handlers.onFocusChange(entry.instance);
    },
    { signal },
  );

  world.addEventListener(
    'animationend',
    (event) => {
      if (event.animationName !== 'poster-enter' && event.animationName !== 'poster-fade') return;
      const entry = entryFromTarget(event.target);
      if (entry) entry.el.coverMotion = null;
      surfaceDirty = true; handlers.onRenderNeeded?.();
      elementFromTarget(event.target)?.closest('.poster')?.classList.remove('poster--enter', 'poster--fade');
    },
    { signal },
  );

  return {
    setLattice(nextLattice, nextTiles, options) {
      surfaceDirty = true;
      const previousTiles = tiles;
      const previousExpanded = expanded;
      const previousFocused = focused;
      const followTiles = options?.followTiles === true;
      lattice = nextLattice;
      tiles = nextTiles;
      layoutDirty = !followTiles;
      needsCull = true;
      hoverId = null;
      finishCollapse();
      if (followTiles) {
        if (previousExpanded) {
          const entry = pool.get(previousExpanded.id);
          if (entry) {
            delete entry.el.root.dataset.expanded;
            delete entry.el.root.dataset.settled;
            delete entry.el.root.dataset.lyrics;
            removeExpandedContent(entry.el);
          }
        }
        expanded = null;
        focused = null;
        focusPending = false;
        settlePending = false;
        clearAllFocusAttrs();
        rematchPoolByTile(nextLattice);
        return;
      }

      let nextExpanded: Instance | null = null;
      if (previousExpanded) {
        const base = nextLattice.fromId(previousExpanded.id, null);
        if (base && sameQueueId(previousTiles, previousExpanded.tileIndex, base.tileIndex)) {
          nextExpanded = nextLattice.fromId(previousExpanded.id, base) ?? base;
        }
      }
      let nextFocused: Instance | null = null;
      if (previousFocused) {
        const candidate = nextLattice.fromId(previousFocused.id, nextExpanded);
        if (candidate && sameQueueId(previousTiles, previousFocused.tileIndex, candidate.tileIndex)) {
          nextFocused = candidate;
        }
      }

      if (previousExpanded && !nextExpanded) {
        const entry = pool.get(previousExpanded.id);
        if (entry) {
          delete entry.el.root.dataset.expanded;
          delete entry.el.root.dataset.settled;
          delete entry.el.root.dataset.lyrics;
          removeExpandedContent(entry.el);
        }
        settlePending = false;
      }
      expanded = nextExpanded;

      if (previousFocused && !nextFocused) {
        const entry = pool.get(previousFocused.id);
        if (entry) clearFocusAttrs(entry.el);
        focused = null;
        focusPending = false;
        handlers.onFocusChange(null);
      } else {
        focused = nextFocused;
      }
    },

    setCurrent(tileIndex) {
      surfaceDirty = true;
      if (tileIndex === currentTile) return;
      const previous = currentTile;
      currentTile = tileIndex;
      for (const entry of pool.values()) {
        if (entry.tileIndex === previous || entry.tileIndex === tileIndex) {
          applyTile(entry.el, tiles[entry.tileIndex], entry.tileIndex === tileIndex);
        }
      }
    },

    setExpanded(instance) {
      surfaceDirty = true;
      if (instance && expanded && instance.id === expanded.id) return;
      if (!instance && !expanded) return;
      const previous = expanded;
      // Callers may pass an instance carrying its un-expanded rect (e.g. from `nearestInstance`);
      // store the reflowed 6×6 version so off-screen refreshes never shrink the card.
      expanded = instance && lattice ? lattice.instanceAt(instance.bc, instance.br, instance.slot, instance) : instance;
      settlePending = instance !== null;
      needsCull = true;
      const animate = !reducedMotion && !layoutDirty;
      finishCollapse();

      if (previous) {
        const entry = pool.get(previous.id);
        if (entry) {
          delete entry.el.root.dataset.expanded;
          delete entry.el.root.dataset.settled;
          delete entry.el.root.dataset.lyrics;
          if (animate) collapsing = entry;
          else removeExpandedContent(entry.el);
        }
      }

      // While the layout is dirty the next cull re-reads and snaps every rect anyway.
      if (lattice && !layoutDirty) {
        if (previous) retargetBlock(lattice, previous.bc, previous.br, animate);
        const sameBlock = previous !== null && instance !== null && previous.bc === instance.bc && previous.br === instance.br;
        if (instance && !sameBlock) retargetBlock(lattice, instance.bc, instance.br, animate);
      }

      if (instance) {
        const entry = pool.get(instance.id);
        if (entry) {
          entry.el.root.dataset.expanded = 'true';
          delete entry.el.root.dataset.settled;
          buildExpandedContent(entry.el, tiles[entry.tileIndex]);
          if (!animate) entry.el.root.dataset.settled = 'true';
        }
      }

      if (collapsing && !collapsing.spring) finishCollapse();
      checkSettled();
    },

    get expanded() {
      return expanded;
    },

    setFocus(instance, options) {
      applyFocus(instance, options?.scrollIntoView !== false);
    },

    get focused() {
      return focused;
    },

    setVisualOptions(options) {
      visualOptions = options;
      depth.setOptions(options.pointer3d, options.reducedMotion, options.hudTiltAngle);
      surfaceDirty = true;
      world.dataset.lightsOut = String(options.lightsOut);
      world.dataset.tint = String(options.tint);
      world.dataset.tintGradient = options.tintGradient;
      world.dataset.reducedMotion = String(options.reducedMotion);
      world.style.setProperty('--tint-color', options.tintColor);
      world.style.setProperty('--tint-alpha', String(Math.min(0.85, Math.max(0, options.tintIntensity))));
      const wasReduced = reducedMotion;
      reducedMotion = options.reducedMotion;
      if (reducedMotion && !wasReduced) {
        if (entranceStartedAt !== null || entrance === 'pending') finishEntrance();
        if (entrance === 'pending') entrance = 'played';
        snapAll();
      }
    },

    render(camera, nowMs) {
      if (disposed || !lattice) return false;
      interactionCamera = camera;
      const depthFrame = depth.tick(nowMs, camera.viewport);
      let dt = 1 / 60;
      if (lastNow !== null) {
        const elapsed = (nowMs - lastNow) / 1000;
        if (elapsed <= IDLE_GAP_SECONDS) dt = Math.min(MAX_FRAME_SECONDS, Math.max(0, elapsed));
      }
      lastNow = nowMs;

      coverScale = camera.state.scale;
      // The lens pulls a larger source area into view; retain its corners on large displays.
      cullLimit = camera.fisheye ? Math.ceil(CULL_LIMIT * FISHEYE_BOUNDS_SCALE ** 2) : CULL_LIMIT;
      // panBy() is an immediate move, not camera.animating. Track the displayed view so
      // pointer/wheel input and inertia share the same foreground-work budget.
      const projectionChanged = lastView.x !== camera.state.x || lastView.y !== camera.state.y
        || lastView.scale !== coverScale || lastView.width !== camera.viewport.width
        || lastView.height !== camera.viewport.height || lastView.fisheye !== camera.fisheye
        || lastView.amount !== camera.fisheyeAmount;
      const viewChanged = Number.isFinite(lastView.x) && projectionChanged;
      if (projectionChanged) projectionRevision++;
      if (lastView.fisheye !== camera.fisheye) needsCull = true;
      const cameraMoving = viewChanged || camera.animating
        || world.closest<HTMLElement>('.lattice-wall')?.dataset.dragging === 'true';
      coverQueue.setPaused(cameraMoving);
      lastView.x = camera.state.x;
      lastView.y = camera.state.y;
      lastView.scale = coverScale;
      lastView.width = camera.viewport.width;
      lastView.height = camera.viewport.height;
      lastView.fisheye = camera.fisheye;
      lastView.amount = camera.fisheyeAmount;
      const bounds = camera.bounds();
      if (needsCull || leavesCulledArea(bounds)) recull(lattice, bounds);
      const mounting = (pendingMounts.length > 0 || staleEntries.length > 0)
        && flushMounts(lattice, bounds, cameraMoving);
      if (entrance === 'pending') applyEntrance(lattice, bounds, nowMs);
      if (entranceStartedAt !== null && nowMs >= entranceStartedAt + ENTRANCE_MAX_SECONDS * 1000 + ENTRANCE_DURATION_MS) {
        finishEntrance();
      }

      let moving = mounting || entranceStartedAt !== null;
      const g = lattice.metrics.gap;
      for (const entry of pool.values()) {
        // Hidden/throttled frames may skip animationend; do not retain expired entry masks.
        if (entry.el.coverMotion && !sampleCoverMotion(entry.el.coverMotion, nowMs, reducedMotion).running) {
          entry.el.coverMotion = null;
          entry.el.root.classList.remove('poster--enter', 'poster--fade');
          surfaceDirty = true;
        }
        const spring = entry.spring;
        if (spring) {
          surfaceDirty = true;
          if (spring.step(dt)) {
            applyRect(entry.el, spring.current, g, true);
            moving = true;
          } else {
            entry.spring = null;
            applyRect(entry.el, entry.target, g);
          }
        }
        syncPosterProjection(entry.el, camera, projectionRevision);
      }

      if (collapsing && !collapsing.spring) finishCollapse();
      checkSettled();
      if (camera.fisheye) {
        if (surface?.needsReplacement) { surface.dispose(); surface = null; }
        if (!surface && !surfaceFailed) {
          surface = createFisheyeSurface(depth.root, () => handlers.onRenderNeeded?.());
          surfaceFailed = surface === null;
        }
        const painted = surface?.render(camera, [...pool.values()].map(entry => ({ el: entry.el,
          tile: tiles[entry.tileIndex], current: entry.tileIndex === currentTile })), visualOptions, dt,
          surfaceDirty || projectionChanged || moving || depthFrame.changed, nowMs, depth.pose,
          entranceStartedAt !== null || (entranceCompletionPending && pendingMounts.length > 0));
        world.dataset.fisheyeSurface = String(painted?.ready === true);
        if (painted?.moving) moving = true;
        surfaceDirty = false;
      } else {
        if (surface && !surface.canvas.hidden) surface.hide();
        delete world.dataset.fisheyeSurface;
        surfaceFailed = false;
      }
      const uiAnimating = uiProjection.sync([...pool.values()].map(entry => entry.el), camera,
        projectionRevision, world.dataset.fisheyeSurface === 'true', depth.pose);
      // Retain the existing image during motion. Settle size/zoom first, then change at most
      // four sources per frame; the shared queue bounds temporary decoded replacements.
      if (!moving && !cameraMoving) {
        let budget = 4;
        for (const entry of pool.values()) {
          entry.el.shown.scale = coverScale;
          if (!syncPosterCover(entry.el, false)) continue;
          if (budget > 0) { syncPosterCover(entry.el); budget--; }
          else moving = true;
        }
      }
      // One settling frame flushes deferred cover sizes after the final immediate move.
      if (entranceCompletionPending && pendingMounts.length === 0) {
        entranceCompletionPending = false;
        handlers.onEntranceComplete?.();
      }
      return moving || viewChanged || uiAnimating || depthFrame.moving;
    },

    playEntrance() {
      if (entrance !== 'idle') return;
      entrance = 'pending';
      handlers.onRenderNeeded?.();
    },

    expandedVisible(camera) {
      if (!expanded) return false;
      const entry = pool.get(expanded.id);
      if (!entry) return false;
      const rect = entry.spring ? entry.spring.current : entry.target;
      if (!camera.fisheye && !depth.active) return intersects(rect, camera.bounds());
      const projection = { worldToScreen: (x: number, y: number) => depth.screenPoint(camera.worldToScreen(x, y)) };
      return intersects(projectedCardBounds(rect, projection), { x: 0, y: 0, w: camera.viewport.width, h: camera.viewport.height });
    },

    expandedContent(): ExpandedContent | null {
      if (!expanded) return null;
      return pool.get(expanded.id)?.el.expanded ?? null;
    },

    instanceFromTarget(target) {
      return entryFromTarget(target)?.instance ?? null;
    },

    pointerPoint(clientX, clientY) { return depth.pointerPoint(clientX, clientY); },

    clear() {
      if (entranceStartedAt !== null || entrance === 'pending' || entranceCompletionPending) {
        entrance = 'played';
        entranceCompletionPending = false;
        handlers.onEntranceComplete?.();
      }
      uiProjection.clear();
      surface?.hide();
      surfaceDirty = true;
      delete world.dataset.fisheyeSurface;
      if (document.activeElement && world.contains(document.activeElement)) world.parentElement?.focus({ preventScroll: true });
      coverQueue.clear();
      for (const entry of pool.values()) { resetPosterElement(entry.el); entry.el.root.remove(); }
      pool.clear(); free.length = 0; pendingMounts.length = 0; staleEntries.length = 0;
      lattice = null; tiles = []; expanded = null; focused = null; currentTile = null;
      collapsing = null; hoverId = null; focusPending = false; settlePending = false;
      needsCull = true; layoutDirty = true; culledOnce = false; lastNow = null;
      entranceStartedAt = null; entranceDelays.clear();
      delete field.dataset.entering;
      lastView.x = lastView.y = lastView.scale = lastView.width = lastView.height = lastView.amount = NaN;
    },

    dispose() {
      if (disposed) return;
      disposed = true;
      abort.abort();
      uiProjection.dispose();
      surface?.dispose(); surface = null;
      depth.dispose();
      coverQueue.dispose();
      for (const entry of pool.values()) { resetPosterElement(entry.el); entry.el.root.remove(); }
      pool.clear();
      pendingMounts.length = 0;
      staleEntries.length = 0;
      free.length = 0;
      entranceStartedAt = null; entranceDelays.clear();
      entranceCompletionPending = false;
      delete field.dataset.entering;
      lattice = null;
      tiles = [];
      expanded = null;
      focused = null;
      collapsing = null;
    },
  };
}

import type { PixelRect } from '../types.ts';

export type SpringState = { value: number; velocity: number };

/** Longest step the closed form integrates; a stalled frame slows the spring instead of jumping. */
const MAX_STEP_SECONDS = 0.064;
const REST_DISTANCE = 0.5;
const REST_SPEED = 5;

/**
 * Advances a critically damped spring by `dtSeconds` using the exact solution of the ODE, so the
 * result is frame-rate independent and never gains energy. Snaps to the target and returns false
 * once within 0.5 px and 5 px/s; otherwise writes the new state back and returns true.
 */
export function stepSpring(state: SpringState, target: number, dtSeconds: number, omega: number): boolean {
  const dt = Math.min(MAX_STEP_SECONDS, Math.max(0, dtSeconds));
  const x = state.value - target;
  const v = state.velocity;
  const decay = Math.exp(-omega * dt);
  const nextX = (x + (v + omega * x) * dt) * decay;
  const nextV = (v - omega * (v + omega * x) * dt) * decay;
  if (Math.abs(nextX) < REST_DISTANCE && Math.abs(nextV) < REST_SPEED) {
    state.value = target;
    state.velocity = 0;
    return false;
  }
  state.value = target + nextX;
  state.velocity = nextV;
  return true;
}

export type RectSpring = {
  /** Same object for the lifetime of the spring; read it every frame without allocating. */
  readonly current: PixelRect;
  readonly target: PixelRect;
  readonly settled: boolean;
  setTarget(rect: PixelRect): void;
  /** Jump to `rect` (or to the current target) with zero velocity. */
  snap(rect?: PixelRect): void;
  /** Returns true while any channel is still moving. */
  step(dtSeconds: number): boolean;
};

type Channel = keyof PixelRect;
const CHANNELS: readonly Channel[] = ['x', 'y', 'w', 'h'];

function copyRect(from: PixelRect, to: PixelRect): void {
  to.x = from.x;
  to.y = from.y;
  to.w = from.w;
  to.h = from.h;
}

function sameRect(a: PixelRect, b: PixelRect): boolean {
  return a.x === b.x && a.y === b.y && a.w === b.w && a.h === b.h;
}

export function createRectSpring(initial: PixelRect, omega = 14): RectSpring {
  const current: PixelRect = { x: initial.x, y: initial.y, w: initial.w, h: initial.h };
  const target: PixelRect = { x: initial.x, y: initial.y, w: initial.w, h: initial.h };
  const velocity: PixelRect = { x: 0, y: 0, w: 0, h: 0 };
  const scratch: SpringState = { value: 0, velocity: 0 };
  let settled = true;

  return {
    current,
    target,
    get settled(): boolean {
      return settled;
    },
    setTarget(rect) {
      if (sameRect(rect, target)) return;
      copyRect(rect, target);
      settled = false;
    },
    snap(rect) {
      if (rect !== undefined) copyRect(rect, target);
      copyRect(target, current);
      velocity.x = 0;
      velocity.y = 0;
      velocity.w = 0;
      velocity.h = 0;
      settled = true;
    },
    step(dtSeconds) {
      if (settled) return false;
      let moving = false;
      for (const channel of CHANNELS) {
        scratch.value = current[channel];
        scratch.velocity = velocity[channel];
        if (stepSpring(scratch, target[channel], dtSeconds, omega)) moving = true;
        current[channel] = scratch.value;
        velocity[channel] = scratch.velocity;
      }
      settled = !moving;
      return moving;
    },
  };
}

import type { PixelRect, Point } from '../types.ts';
import type { DepthPose } from './depthScene.ts';

export type UiDepthLayer = 'meta' | 'lyrics' | 'controls' | 'caption';
const DISTANCE: Record<UiDepthLayer, number> = { meta: 26, lyrics: 18, controls: 32, caption: 10 };

/** Foreground layers follow the viewer at different depths; artwork moves in the opposite direction.
 * Return projected world offsets so camera zoom cannot exaggerate the motion. Smaller cards reserve
 * their edge padding, and the vertical motion leaves the animated lyric/control gaps open. */
export function uiParallaxOffset(pose: DepthPose, layer: UiDepthLayer, card: PixelRect, scale: number,
  viewport: Readonly<{ width: number; height: number }>): Point {
  if (pose.amount <= 0 || scale <= 0) return { x: 0, y: 0 };
  // Scale the layer distances together so smaller viewports retain distinct depths.
  const reach = Math.min(DISTANCE.controls, viewport.width * .035, viewport.height * .035,
    Math.min(card.w, card.h) * scale * .05);
  const distance = reach * DISTANCE[layer] / DISTANCE.controls;
  return { x: pose.x * pose.amount * distance / scale,
    y: pose.y * pose.amount * distance * .45 / scale };
}

/** The host shell stays transparent; only this document decides when the wall covers the old page. */
export function createWallOpening(root: HTMLElement) {
  return {
    finish() { delete root.dataset.opening; },
    configure(context: EchoWorkshopUiContext) {
      if (context.desktop) delete root.dataset.opening;
    },
  };
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

/* Fallbacks only: main.ts writes the live host appearance tokens inline on <html>. */
:root {
  color-scheme: dark;
  --host-accent: #6678ff;
  --host-accent-text: #ffffff;
  --host-app-bg: #0f1116;
  --host-text: #f2f4f8;
  --host-muted: #9aa3b5;
  --host-panel: #171a22;
  --host-border: #2a2f3b;
  --host-player: #171a22;
  --host-accent-2: color-mix(in srgb, var(--host-accent) 45%, var(--host-text));
  --shade-color: #000000;
  --wall-background: #000000;
  --wall-text: #ffffff;
  --wall-muted: rgb(255 255 255 / 72%);
}

html[data-color-scheme="light"] {
  color-scheme: light;
  --host-app-bg: #f3f4f8;
  --host-text: #15181f;
  --host-muted: #5f6777;
  --host-panel: #ffffff;
  --host-border: #d7dbe4;
  --host-player: #ffffff;
}

html,
body {
  margin: 0;
  height: 100%;
  overflow: hidden;
}

body {
  font-family: var(--ui-font, system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif);
  color: var(--host-text);
  background: var(--wall-background);
  -webkit-font-smoothing: antialiased;
}

/* Transparent from the first frame, before the bridge or library has finished booting. */
html:has(body[data-opening="true"]) {
  color-scheme: normal;
  background: transparent;
}

body[data-opening="true"] {
  background: transparent;
}

:focus-visible {
  outline: 2px solid var(--host-accent);
  outline-offset: 2px;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  border: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

body[data-reduced-motion="true"] .field__vignette,
body[data-reduced-motion="true"] .world {
  transition: none;
}

.lattice{
  position: fixed;
  inset: 0;
  overflow: hidden;
}

.field{
  position: absolute;
  inset: 0;
  /* The camera owns movement; focusing controls must never scroll this canvas. */
  overflow: clip;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
  cursor: grab;
  outline: none;
  isolation: isolate;
  background: var(--wall-background);
}

/* Unfilled areas reveal the actual previous ECHO page, not a substitute colour. */
body[data-opening="true"] .field{ background: transparent; }

body[data-dragging="true"] .field{
  cursor: grabbing;
}

/* Paint the focus outline above the poster cards. */
.field:focus-visible{
  outline: 2px solid color-mix(in srgb, var(--host-accent) 55%, transparent);
  outline-offset: -2px;
}

.world{
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  transform-origin: 0 0;
  will-change: transform;
  z-index: 1;
}

.wall-depth-scene{
  position: absolute;
  inset: 0;
  transform-origin: 50% 50%;
  --depth-x: 0;
  --depth-y: 0;
  --depth-amount: 0;
}
.wall-depth-scene[data-depth-active="true"]::after{
  content: '';
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  opacity: calc(var(--depth-amount) * .34);
  background: radial-gradient(ellipse 80% 75% at calc(50% + var(--depth-x) * 30%) calc(50% + var(--depth-y) * 30%), rgb(255 255 255 / 18%), transparent 70%);
  mix-blend-mode: screen;
}
/* Project the shared wall plane after flattening its native UI layers. Keeping a 3D context
   here lets the full-size scene hit plane occlude controls on the tilted-away half. The scene
   matrix still supplies perspective; foreground depth comes from the per-layer XY parallax. */

.fisheye-surface{
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 0;
}
.fisheye-surface[hidden]{ display: none; }

.field__vignette{
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 2;
  opacity: 0;
  transition: opacity 0.3s;
  background: radial-gradient(ellipse at center, transparent 46%, rgb(0 0 0 / 74%) 100%);
}

body[data-vignette="true"] .field__vignette{
  opacity: 1;
}

body[data-lighting="daytime"] .field__vignette{
  opacity: 0;
}

html[data-color-scheme="light"] .field__vignette{
  background: radial-gradient(ellipse at center, transparent 46%, rgb(0 0 0 / 48%) 100%);
}

body[data-opening="true"] .field__vignette,
body[data-opening="true"] .wall-depth-scene::after{ opacity: 0; transition: none; }

/* Poster cards. Position and size come from inline `transform` / `width` / `height` written by
   posterWall.ts; nothing below may set `transform` on `.poster` itself. */

.poster{
  --expanded-pad: clamp(18px, 4.5%, 40px);
  position: absolute;
  left: 0;
  top: 0;
  transform-origin: 0 0;
  box-sizing: border-box;
  border-radius: 0;
  overflow: hidden;
  contain: layout paint;
  background: var(--host-panel);
  color: #fff;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.world[data-fisheye-surface="true"] .poster{
  background: transparent;
  /* UI units follow the curved cover beyond the card's straight four-corner outline. */
  overflow: visible;
  contain: layout;
}
.world[data-fisheye-surface="true"] .poster__body{ visibility: hidden; }

.poster__meta,
.poster__lyrics,
.poster__controls,
.poster__caption{ transform-origin: 0 0; }

/* Covers stay borderless when focused or expanded. */
.poster:focus-visible{
  outline: none;
}

.poster[data-expanded="true"] {
  /* Keep the mounted node in place: re-appending it cancels its lighting transitions. */
  z-index: 10;
  cursor: default;
}

/* Layers ------------------------------------------------------------------------------------- */

.poster__body{
  position: absolute;
  inset: 0;
  transform-origin: center;
  transition: transform .28s cubic-bezier(.2, .8, .2, 1), filter .28s ease;
}

/* Scale follows pointer or keyboard focus. Lighting is only hover / playing / expanded. */
.poster:hover .poster__body,
.poster[data-focused="true"] .poster__body{
  transform: scale(var(--hx, 1.06), var(--hy, 1.06));
}

.poster:hover .poster__body{
  filter: saturate(1.22) brightness(1.16);
}

body[data-dragging="true"] .poster .poster__body{
  transform: none;
  filter: none;
}

.poster[data-expanded="true"] .poster__body{
  transform: none;
  filter: brightness(1.18) saturate(1.12);
}

.poster__fallback{
  position: absolute;
  inset: 0;
}

.poster__art{
  position: absolute;
  inset: 0;
  transform-origin: center;
}
.world[data-depth="true"] .poster__art{
  transform: translate(calc(var(--depth-x) * var(--depth-amount) * var(--depth-art-shift)), calc(var(--depth-y) * var(--depth-amount) * var(--depth-art-shift))) scale(calc(1 + var(--depth-amount) * var(--depth-art-scale)));
}

.poster__cover{
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  -webkit-user-drag: none;
}

/* Local album thumbs are centre-cropped squares; preserve that framing in the large variant. */
.poster[data-square-cover="true"] .poster__cover{
  inset: auto;
  left: 50%;
  top: 50%;
  width: var(--cover-side, 100%);
  height: var(--cover-side, 100%);
  transform: translate(-50%, -50%);
}

.poster__cover[hidden] {
  display: none;
}

.poster__shade{
  position: absolute;
  inset: 0;
  /* Keep the expanded gradient stable; idle covers use their separately configured tint. */
  background:
    linear-gradient(180deg, transparent 14%, color-mix(in srgb, var(--shade-color, #000) 48%, transparent) 56%, color-mix(in srgb, var(--shade-color, #000) 94%, transparent) 100%),
    linear-gradient(90deg, color-mix(in srgb, var(--shade-color, #000) 76%, transparent), transparent 58%),
    radial-gradient(85% 75% at 0% 100%, color-mix(in srgb, var(--shade-color, #000) 58%, transparent), transparent 72%);
  opacity: 0;
  transition: opacity .3s ease;
}

.poster[data-expanded="true"] .poster__shade{
  opacity: 1;
}

.poster__tint{
  position: absolute;
  inset: 0;
  /* theme-color-allow: neutral cover shading must stay black in every host theme. */
  --tint-fill: color-mix(in srgb, var(--tint-color, #000) calc(var(--tint-alpha, .5) * 100%), transparent);
  background: var(--tint-fill);
  opacity: 0;
  transition: opacity .3s ease;
}

.world[data-tint-gradient="diagonal"] .poster__tint{
  /* Gradients add depth above the uniform base. Alpha belongs to each paint layer so the
     base does not flatten gradients of the same colour; opacity only controls focus fading. */
  background:
    linear-gradient(180deg, transparent 38%, color-mix(in srgb, var(--tint-fill) 74%, transparent) 100%),
    linear-gradient(90deg, color-mix(in srgb, var(--tint-fill) 46%, transparent), transparent 40%),
    var(--tint-fill);
}

.world[data-tint-gradient="vertical"] .poster__tint{
  background:
    linear-gradient(180deg, transparent 38%, color-mix(in srgb, var(--tint-fill) 74%, transparent) 100%),
    var(--tint-fill);
}

.world[data-tint="true"] .poster:not([data-current="true"]):not([data-expanded="true"]):not(:hover) .poster__tint{
  opacity: 1;
}

body[data-dragging="true"] .world[data-tint="true"] .poster:not([data-current="true"]):not([data-expanded="true"]) .poster__tint{
  opacity: 1;
}

.poster__lights{
  position: absolute;
  inset: 0;
  background: #000;
  opacity: 0;
  transition: opacity .3s ease;
}

.world[data-lights-out="true"] .poster:not([data-current="true"]):not([data-expanded="true"]):not(:hover) .poster__lights{
  opacity: .72;
}

body[data-dragging="true"] .world[data-lights-out="true"] .poster:not([data-current="true"]):not([data-expanded="true"]) .poster__lights{
  opacity: .72;
}

/* An open card is the only bright one; other current-track copies dim with the rest. */
.world:has(> .poster[data-expanded="true"]) .poster:not([data-expanded="true"]) .poster__lights{
  opacity: .34;
}

.world[data-lights-out="true"]:has(> .poster[data-expanded="true"]) .poster:not([data-expanded="true"]) .poster__lights{
  opacity: .8;
}

/* Daytime: idle covers stay equally bright. Expanded cards keep their own scrim for type. */
body[data-lighting="daytime"] .poster:not([data-expanded="true"]) .poster__shade,
body[data-lighting="daytime"] .poster:not([data-expanded="true"]) .poster__tint,
body[data-lighting="daytime"] .poster:not([data-expanded="true"]) .poster__lights,
body[data-lighting="daytime"] .world:has(> .poster[data-expanded="true"]) .poster:not([data-expanded="true"]) .poster__lights{
  opacity: 0;
}

/* Expanded card content ---------------------------------------------------------------------- */

@property --lyrics-open {
  syntax: '<number>';
  inherits: true;
  initial-value: 0;
}

@property --lyrics-open-height {
  syntax: '<length>';
  inherits: true;
  initial-value: 0px;
}

.poster__expanded{
  position: absolute;
  inset: 0;
  z-index: 2;
  display: flex;
  flex-direction: column;
  row-gap: 12px;
  box-sizing: border-box;
  padding: var(--expanded-pad);
  opacity: 0;
  transition: opacity .18s ease;
}

.poster[data-expanded="true"][data-settled="true"] .poster__expanded{
  opacity: 1;
}

.poster__meta{
  order: 1;
  margin-top: auto;
  flex: none;
  min-width: 0;
  pointer-events: none;
  container-type: inline-size;
}

.poster__title{
  margin: 0;
  width: 100%;
  font-weight: 700;
  font-size: clamp(56px, 10.5cqw, 96px);
  line-height: 1.15;
  font-family: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  letter-spacing: -.02em;
  text-shadow: 0 2px 14px rgb(0 0 0 / 42%);
  overflow-wrap: break-word;
  overflow: visible;
  padding-inline-end: .04em;
}

.poster__title-text{
  display: block;
  transform-origin: top left;
  transform: scale(var(--title-scale));
  /* Stable text raster and line breaks; the parent reserves the actual scaled height. */
  will-change: transform;
}

.poster__artist{
  margin: .35em 0 0;
  font-size: clamp(16px, 2.2cqw, 24px);
  line-height: 1.3;
  color: rgb(255 255 255 / 82%);
  text-shadow: 0 2px 14px rgb(0 0 0 / 50%);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.poster__artist:empty{
  display: none;
}

.poster__lyrics{
  order: 2;
  position: relative;
  flex: 0 0 auto;
  max-height: 0;
  min-height: 0;
  overflow: hidden;
  /* inline-size only: `size` containment makes auto height ignore children, so the slot stays 0. */
  container-type: inline-size;
  /* One inherited progress value drives both directions, including interruptions. */
}

.poster__lyrics .lyrics{
  height: auto;
  overflow: visible;
  justify-content: flex-start;
}

/* Taps on the empty controls row (or on a hidden cluster) fall through to the card. */
.poster__controls{
  order: 3;
  flex: none;
  pointer-events: none;
}

.poster__controls > *{
  pointer-events: auto;
}

/* The queue wall owns this motion; album cards retain their existing layout. */
.poster__expanded:not(.poster__expanded--album) {
  flex-direction: column-reverse;
}

.poster__expanded:not(.poster__expanded--album) .poster__meta{
  order: 3;
  margin-top: 0;
}

.poster__expanded:not(.poster__expanded--album) .poster__controls{
  order: 1;
}

.poster__expanded:not(.poster__expanded--album) .poster__title{
  --title-scale: calc(1 - var(--lyrics-open) * (1 - var(--title-open-scale, 1)));
  height: calc(var(--title-natural-height) * var(--title-scale));
}

.poster__expanded:not(.poster__expanded--album) .poster__lyrics{
  max-height: none;
  height: calc(var(--lyrics-open-height, 0px) * var(--lyrics-open));
}

.poster__expanded:not(.poster__expanded--album) .lyrics{
  transform: translateZ(0);
  opacity: var(--lyrics-open);
}

.poster__expanded:not(.poster__expanded--album) .poster__artist{
  transform: translateZ(0);
}

/* App entry: each tile appears in place, black first, then quickly uncovers its artwork. */

.poster--enter{
  animation: poster-enter .2s linear both;
  animation-delay: var(--enter-delay, 0s);
}

.poster--enter::after{
  content: '';
  position: absolute;
  inset: 0;
  z-index: 20;
  background: #000;
  pointer-events: none;
  animation: poster-enter-black .2s both;
  animation-delay: var(--enter-delay, 0s);
}

.poster.poster--enter .poster__body{ transform: none; transition: none; }

.world[data-fisheye-surface="true"] .poster--enter::after{ display: none; }

.poster--enter > .poster__expanded,
.poster--enter > .poster__caption{
  animation: poster-enter-content .2s both;
  animation-delay: var(--enter-delay, 0s);
}

.poster--fade .poster__body{
  animation: poster-fade .12s ease-out both;
}

@keyframes poster-enter {
  0% { opacity: 0; }
  .01%, 100% { opacity: 1; }
}

/* 40 ms of solid black, followed by a 160 ms ease-out reveal (coverMotion.ts). */
@keyframes poster-enter-black {
  0%, 20% { opacity: 1; animation-timing-function: ease-out; }
  100% { opacity: 0; }
}

@keyframes poster-enter-content {
  0%, 20% { opacity: 0; animation-timing-function: ease-out; }
  100% { opacity: 1; }
}

@keyframes poster-fade {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

/* Reduced motion: no hover scale, no entrance, no springs (JS snaps), keep the hover filter ----- */

.world[data-reduced-motion="true"] .poster,
body[data-reduced-motion="true"] .poster{
  transition: none;
  animation: none;
}

.world[data-reduced-motion="true"] .poster .poster__body,
body[data-reduced-motion="true"] .poster .poster__body{
  transform: none;
  transition: none;
  animation: none;
}

.world[data-reduced-motion="true"] .poster .poster__expanded,
body[data-reduced-motion="true"] .poster .poster__expanded,
.world[data-reduced-motion="true"] .poster .poster__meta,
body[data-reduced-motion="true"] .poster .poster__meta,
.world[data-reduced-motion="true"] .poster .poster__title,
body[data-reduced-motion="true"] .poster .poster__title,
.world[data-reduced-motion="true"] .poster .poster__lyrics,
body[data-reduced-motion="true"] .poster .poster__lyrics,
.world[data-reduced-motion="true"] .poster .poster__shade,
body[data-reduced-motion="true"] .poster .poster__shade,
.world[data-reduced-motion="true"] .poster .poster__tint,
body[data-reduced-motion="true"] .poster .poster__tint,
.world[data-reduced-motion="true"] .poster .poster__lights,
body[data-reduced-motion="true"] .poster .poster__lights{
  transition: none;
  animation: none;
}

.world[data-reduced-motion="true"] .poster--enter::after,
body[data-reduced-motion="true"] .poster--enter::after{ display: none; }

.world[data-reduced-motion="true"] .poster .poster__caption,
body[data-reduced-motion="true"] .poster .poster__caption{ animation: none; }

.poster__caption {
  position: absolute;
  inset: auto 16px 14px;
  z-index: 1;
  display: none;
  color: var(--wall-text, currentColor);
  pointer-events: none;
}

body[data-show-titles="true"] .poster:not([data-expanded="true"]) > .poster__caption:not([hidden]) {
  display: block;
}

.poster__caption-title {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: var(--caption-lines, 3);
  overflow-wrap: anywhere;
  font-size: 32px;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -.025em;
}

.poster__caption-artist {
  margin-top: 4px;
  overflow: hidden;
  color: var(--wall-muted, currentColor);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.3;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.poster__caption-artist:empty { display: none; }

/* Playback controls: the cluster inside the expanded card, plus the corner locate button. */

.controls {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  transition: opacity .25s ease;
}

.controls[data-hidden="true"] {
  opacity: 0;
  pointer-events: none;
}

.controls__row {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  gap: 0;
}

.controls__button--skip,
.controls__button--shuffle,
.controls__button--repeat,
.controls__button--lyrics,
.controls__button--album {
  overflow: hidden;
  transition: width .32s cubic-bezier(.2, .8, .2, 1), opacity .28s ease;
}

.controls[data-mode="other"] .controls__button--skip,
.controls[data-mode="other"] .controls__button--shuffle,
.controls[data-mode="other"] .controls__button--repeat,
.controls[data-mode="other"] .controls__button--lyrics {
  width: 0;
  min-width: 0;
  margin-left: 0;
  opacity: 0;
  pointer-events: none;
}

.controls__button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  width: 52px;
  height: 52px;
  padding: 0;
  border: 0;
  border-radius: 0;
  /* theme-color-allow: icons sit on the dark cover shade in both host themes. */
  background: transparent;
  color: #fff;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: opacity .15s ease, transform .15s ease;
}

.controls__button svg {
  width: 26px;
  height: 26px;
}

.controls__button:hover {
  opacity: .72;
}

.controls__button:active {
  transform: scale(.94);
}

.controls__button:focus-visible {
  outline: 2px solid #fff;
  outline-offset: 2px;
}

.controls__button--primary {
  width: 64px;
  height: 64px;
  background: transparent;
  color: #fff;
}

.controls__button--primary svg {
  width: 30px;
  height: 30px;
}

.controls__button--primary:hover {
  background: transparent;
}

.controls__button--lyrics[data-on="false"],
.controls__button--shuffle[data-on="false"],
.controls__button--repeat[data-on="false"] {
  opacity: .4;
}

.controls__glyph {
  display: inline-flex;
  line-height: 0;
}

/* Play / pause glyph swap, driven by data-state on .controls. */
.controls[data-state="playing"] [data-glyph="play"],
.controls[data-state="paused"] [data-glyph="pause"] {
  display: none;
}

.controls[data-mode="other"] .controls__button--primary [data-glyph="play"] {
  display: inline-flex;
}

.controls[data-mode="other"] .controls__button--primary [data-glyph="pause"] {
  display: none;
}

/* Seek ---------------------------------------------------------------------------------------- */

.controls__seek {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 50%;
  min-width: 0;
}

/* The clock belongs to the playing track; a card for another track has nothing to seek. */
.controls[data-mode="other"] .controls__seek {
  display: none;
}

.controls__slider {
  -webkit-appearance: none;
  appearance: none;
  flex: 1;
  min-width: 0;
  height: 16px;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  /* theme-color-allow: a thin white fill on the dark cover shade; the thumb is invisible. */
  background: linear-gradient(90deg, #fff calc(var(--progress, 0) * 100%), rgb(255 255 255 / 28%) 0);
  background-repeat: no-repeat;
  background-size: 100% 2px;
  background-position: 0 50%;
  outline: none;
  cursor: pointer;
}

.controls__slider:focus-visible {
  box-shadow: 0 0 0 2px rgb(255 255 255 / 35%);
}

.controls__slider::-webkit-slider-runnable-track {
  height: 16px;
  background: transparent;
}

.controls__slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 12px;
  height: 16px;
  margin-top: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.controls__time {
  flex: none;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  color: rgb(255 255 255 / 85%);
  white-space: nowrap;
}

/* Locate button (SPEC §2.5) ------------------------------------------------------------------- */

/* Bottom-right corner; shown only while the playing track's expanded card is off screen. */
.locate {
  position: absolute;
  right: 18px;
  bottom: 18px;
  z-index: 5;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  padding: 0;
  border: 1px solid color-mix(in srgb, var(--host-border) 60%, transparent);
  border-radius: 50%;
  background: color-mix(in srgb, var(--host-panel) 80%, transparent);
  color: var(--host-text);
  cursor: pointer;
  backdrop-filter: blur(14px);
  -webkit-tap-highlight-color: transparent;
  transition: opacity .25s ease, transform .25s ease, background .15s ease, color .15s ease, visibility 0s linear 0s;
}

.locate svg {
  width: 20px;
  height: 20px;
}

.locate:hover {
  background: color-mix(in srgb, var(--host-panel) 92%, var(--host-text));
  color: var(--host-accent);
}

.locate:active {
  transform: scale(.94);
}

.locate:focus-visible {
  outline: 2px solid var(--host-accent);
  outline-offset: 2px;
}

.locate[data-visible="false"] {
  opacity: 0;
  visibility: hidden;
  transform: translateY(6px);
  pointer-events: none;
  transition: opacity .25s ease, transform .25s ease, visibility 0s linear .25s;
}

body[data-reduced-motion="true"] .controls,
body[data-reduced-motion="true"] .controls__button,
body[data-reduced-motion="true"] .controls__button--skip,
body[data-reduced-motion="true"] .controls__button--shuffle,
body[data-reduced-motion="true"] .controls__button--repeat,
body[data-reduced-motion="true"] .controls__button--lyrics,
body[data-reduced-motion="true"] .controls__button--album,
body[data-reduced-motion="true"] .controls__slider,
body[data-reduced-motion="true"] .controls__slider::-webkit-slider-thumb,
body[data-reduced-motion="true"] .locate {
  transition: none;
}

/* Lyrics layer inside the expanded current-track card (SPEC §9). Mounted in `.poster__lyrics`
   (`container-type: inline-size`), so cqw scales with the card width. Light text on the dark shade. */

.lyrics {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: clamp(10px, 1.8cqw, 20px);
  width: 100%;
  height: 100%;
  padding: 0;
  box-sizing: border-box;
  overflow: hidden;
  color: var(--host-text, #fff);
  font-family: system-ui, -apple-system, "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  text-align: left;
  text-shadow: 0 2px 18px rgb(0 0 0 / 55%);
  pointer-events: none;
}

/* Author `display: flex` would otherwise win over the UA `[hidden]` rule. */
.lyrics[hidden] {
  display: none;
}

.lyrics .sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.lyrics__line {
  flex: 0 0 auto;
  min-width: 0;
  transform-origin: left center;
  transition: transform .32s ease, opacity .32s ease, filter .32s ease;
}

.lyrics__line--current {
  font-size: clamp(32px, 6.4cqw, 58px);
  font-weight: 700;
  opacity: 1;
  transform: scale(1);
}

.lyrics__line--next {
  font-size: clamp(22px, 4.4cqw, 40px);
  font-weight: 600;
  opacity: .5;
  transform: scale(.8);
  filter: blur(.6px);
}

.lyrics__text {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  overflow: hidden;
  line-height: 1.25;
  overflow-wrap: anywhere;
}

.lyrics__line--next[hidden] {
  display: none;
}

.lyrics__line--current .lyrics__text {
  display: block;
  overflow: visible;
  -webkit-line-clamp: unset;
  text-shadow: none;
}

.lyrics__translation {
  display: none;
  margin-top: .25em;
  font-size: .62em;
  font-weight: 500;
  line-height: 1.3;
  opacity: .68;
}

.lyrics[data-translation="true"] .lyrics__translation:not(:empty) {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}

/* Glow follows glyphs only: no filter / overflow clip, or the bloom becomes a rectangle. */
.lyrics__word {
  display: inline;
  color: rgb(255 255 255 / 38%);
  text-shadow: none;
}

.lyrics__word--sung {
  color: rgb(255 255 255 / 94%);
}

.lyrics__word--active {
  color: #fff;
  text-shadow:
    0 0 .04em rgb(255 255 255 / 70%),
    0 0 .14em rgb(255 255 255 / 36%);
}

.lyrics__plain {
  flex: 0 1 auto;
  min-height: 0;
  max-height: 100%;
  overflow: auto;
  overscroll-behavior: contain;
  pointer-events: auto;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  font-size: clamp(22px, 3.6cqw, 32px);
  line-height: 1.6;
}

.lyrics__plain::-webkit-scrollbar {
  width: 6px;
}

.lyrics__plain::-webkit-scrollbar-thumb {
  background: rgb(255 255 255 / 30%);
  border-radius: 3px;
}

.lyrics__instrumental {
  text-align: center;
  font-size: clamp(28px, 5cqw, 46px);
  font-weight: 600;
  letter-spacing: .08em;
  opacity: .85;
}

/* Light scheme: the layer still sits on the dark shade, so text stays light with a softer shadow. */
html[data-color-scheme="light"] .lyrics,
body[data-color-scheme="light"] .lyrics {
  color: rgb(255 255 255 / 96%);
  text-shadow: 0 1px 10px rgb(0 0 0 / 40%);
}

html[data-color-scheme="light"] .lyrics__line--current .lyrics__text,
body[data-color-scheme="light"] .lyrics__line--current .lyrics__text {
  text-shadow: none;
}

/* Reduced motion: no scale, blur or transitions; the whole current line stays highlighted. */
.lyrics[data-reduced-motion="true"] .lyrics__line,
body[data-reduced-motion="true"] .lyrics .lyrics__line {
  transform: none;
  filter: none;
  transition: none;
}

.lyrics[data-reduced-motion="true"] .lyrics__line--next,
body[data-reduced-motion="true"] .lyrics .lyrics__line--next {
  opacity: .55;
}

.lyrics[data-reduced-motion="true"] .lyrics__line--current .lyrics__text,
body[data-reduced-motion="true"] .lyrics .lyrics__line--current .lyrics__text {
  filter: none;
}

.lyrics[data-reduced-motion="true"] .lyrics__word,
body[data-reduced-motion="true"] .lyrics .lyrics__word {
  color: rgb(255 255 255 / 88%);
  text-shadow: none;
}

.lyrics[data-reduced-motion="true"] .lyrics__word--active,
.lyrics[data-reduced-motion="true"] .lyrics__word--sung,
body[data-reduced-motion="true"] .lyrics .lyrics__word--active,
body[data-reduced-motion="true"] .lyrics .lyrics__word--sung {
  color: #fff;
}

body[data-state='booting'] .field,
body[data-state='empty'] .field,
body[data-state='denied'] .field{
  opacity: 0;
  pointer-events: none;
}

body[data-state='error'] .field{
  opacity: 0;
  pointer-events: none;
}

body[data-state='ready'] .field{
  opacity: 1;
}

.state{
  position: absolute;
  inset: 0;
  z-index: 6;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 10px;
  padding: 32px;
  text-align: center;
  color: var(--wall-text);
  background: var(--wall-background);
}

.state[hidden] {
  display: none;
}

body[data-opening="true"] .state,
body[data-opening="true"] .locate,
body[data-opening="true"] .notice {
  visibility: hidden;
}

.state__title{
  margin: 0;
  font-size: clamp(20px, 2.4vw, 28px);
  font-weight: 700;
  letter-spacing: -0.01em;
}

.state__body{
  max-width: 460px;
  margin: 0;
  color: var(--wall-muted);
  font-size: 14px;
  line-height: 1.6;
}

.state[data-state='denied'] .state__title::before{
  content: '';
  display: block;
  width: 10px;
  height: 10px;
  margin: 0 auto 14px;
  border-radius: 50%;
  background: var(--host-accent);
  box-shadow: 0 0 0 6px color-mix(in srgb, var(--host-accent) 22%, transparent);
}

.state[data-state='booting'] .state__title::before{
  content: '';
  display: block;
  width: 18px;
  height: 18px;
  margin: 0 auto 14px;
  border: 2px solid color-mix(in srgb, var(--host-accent) 30%, transparent);
  border-top-color: var(--host-accent);
  border-radius: 50%;
  animation: state-spin 0.9s linear infinite;
}

body[data-reduced-motion='true'] .state[data-state='booting'] .state__title::before{
  animation: none;
}

@keyframes state-spin {
  to { transform: rotate(360deg); }
}

.notice{
  position: absolute;
  left: 14px;
  bottom: 14px;
  z-index: 5;
  padding: 5px 10px;
  border: 1px solid color-mix(in srgb, var(--host-border) 60%, transparent);
  border-radius: 999px;
  color: var(--host-muted);
  background: color-mix(in srgb, var(--host-panel) 82%, transparent);
  font-size: 11px;
  letter-spacing: 0.02em;
  backdrop-filter: blur(12px);
  pointer-events: none;
}

@property --album-slot-height{
  syntax: '<length>';
  inherits: true;
  initial-value: 0px;
}
.album-tracks :focus-visible{
  outline: 2px solid var(--wall-text);
  outline-offset: -2px;
}
.poster__expanded.poster__expanded--album{
  --album-scale: 1;
  display: flex;
  flex-direction: column-reverse;
}
.poster__expanded--album::before{
  content: '';
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  /* Blend into the cover instead of outlining the list as a separate card. */
  background: linear-gradient(180deg, transparent, color-mix(in srgb, var(--wall-background) 72%, transparent) 20%, color-mix(in srgb, var(--wall-background) 82%, transparent));
  opacity: 0;
  transition: opacity .22s ease;
}
.poster__expanded--album:has(.album-details[data-open="true"])::before{
  opacity: 1;
}
.world[data-fisheye-surface="true"] .poster__expanded--album::before{
  /* The GPU paints this backdrop through the same continuous lens as the cover. Keep the
     pseudo-element's opacity timeline available to the renderer, including its closing fade. */
  visibility: hidden;
}
.poster__expanded.poster__expanded--album .poster__meta{
  order: 3;
  margin-top: 0;
  pointer-events: auto;
}
.poster__expanded.poster__expanded--album .poster__lyrics{
  display: grid;
  order: 2;
  height: calc(var(--album-slot-height) * var(--lyrics-open));
  max-height: none;
  min-height: 0;
  overflow: hidden;
}
.poster__expanded.poster__expanded--album .poster__controls{
  order: 1;
}
.poster__expanded.poster__expanded--album .poster__title{
  --title-scale: calc(1 - var(--lyrics-open) * (1 - var(--title-open-scale, 1)));
  height: calc(var(--title-natural-height) * var(--title-scale));
}
.poster__expanded.poster__expanded--album .poster__artist{
  transform: translateZ(0);
}
.album-details,
.album-lyrics{
  grid-area: 1 / 1;
  display: flex;
  flex-direction: column;
  /* Retain a stable list viewport; the outer slot owns the expansion and clipping. */
  height: var(--lyrics-open-height, 0px);
  min-height: 0;
  min-width: 0;
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  transition: opacity .22s ease, transform .22s ease, visibility 0s;
}
.album-details[data-open="false"],
.album-lyrics[data-open="false"] {
  opacity: 0;
  visibility: hidden;
  transform: translateY(calc(10px / var(--album-scale)));
  pointer-events: none;
  transition: opacity .22s ease, transform .22s ease, visibility 0s .22s;
}
/* Switching content hides the outgoing panel immediately; only the incoming panel fades in.
   A direct close still fades out, and no intermediate frame paints lyrics over track rows. */
[data-album-view="lyrics"] .album-details,
[data-album-view="tracks"] .album-lyrics{
  visibility: hidden;
  transition: none;
}
.album-lyrics{
  /* During intrinsic measurement, auto height must not stretch to the hidden track list's
     grid row. Otherwise the previous list / long lyric height keeps pushing the title up. */
  align-self: start;
  justify-content: flex-end;
  overflow: hidden;
}
.poster__expanded--album .album-lyrics .lyrics{
  max-height: 100%;
  min-height: 0;
  overflow: auto;
  scrollbar-width: none;
}
.album-lyrics .lyrics::-webkit-scrollbar{ display: none; }
.album-details__message{
  flex-shrink: 0;
  margin: 0 0 calc(8px / var(--album-scale));
  padding-inline: calc(12px / var(--album-scale));
  font-size: calc(13px / var(--album-scale));
  font-weight: 500;
  color: var(--wall-muted);
}
.album-tracks{
  flex: 1;
  min-height: 0;
  min-width: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overflow-anchor: none;
  overscroll-behavior: contain;
  touch-action: pan-y;
  scrollbar-gutter: stable;
}
/* Keep the gutter stable while the thumb is hidden, so row widths never jump. */
.album-tracks::-webkit-scrollbar{ width: calc(8px / var(--album-scale)); height: calc(8px / var(--album-scale)); background: transparent; }
.album-tracks::-webkit-scrollbar-track,
.album-tracks::-webkit-scrollbar-corner{ background: transparent; }
.album-tracks::-webkit-scrollbar-track{ margin-block: calc(48px / var(--album-scale)); }
.album-tracks::-webkit-scrollbar-thumb{
  /* A 4px visible stroke retains an 8px drag target. Insets also shorten its travel. */
  border: calc(2px / var(--album-scale)) solid transparent;
  background: transparent;
  background-clip: padding-box;
  border-radius: 999px;
}
.album-tracks[data-scrolling="true"]::-webkit-scrollbar-thumb{
  background-color: color-mix(in srgb, var(--wall-text) 45%, transparent);
}
.album-tracks[data-scrolling="true"]::-webkit-scrollbar-thumb:hover{
  background-color: color-mix(in srgb, var(--wall-text) 65%, transparent);
}
.album-tracks::-webkit-scrollbar-button{ display: none; width: 0; height: 0; }
/* Cover text keeps its overlay contrast in both host themes. */
.album-track-row{
  display: grid;
  grid-template-columns: 2.25em minmax(0, 1fr) 4.5em;
  align-items: center;
  gap: calc(12px / var(--album-scale));
  width: 100%;
  height: var(--album-track-height, calc(48px / var(--album-scale)));
  padding: calc(8px / var(--album-scale)) calc(12px / var(--album-scale));
  border: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--wall-text) 10%, transparent);
  text-align: left;
  background: transparent;
  color: var(--wall-text);
  font: inherit;
  font-size: calc(16px / var(--album-scale));
  font-weight: 500;
  line-height: 1.4;
  cursor: pointer;
  transition: background-color .16s ease;
}
.album-tracks__placeholder{ display: flex; color: var(--wall-muted); font-size: calc(13px / var(--album-scale)); }
.album-tracks__placeholder:not(button) { cursor: default; }
.album-tracks button:not(:disabled):hover,
.album-tracks button[aria-current="true"] { background: color-mix(in srgb, var(--wall-text) 6%, transparent); }
.album-tracks button[aria-current="true"] .album-track__title{ font-weight: 600; }
.album-tracks button[aria-current="true"] .album-track__number{ color: var(--wall-text); }
.album-tracks button:disabled{ color: var(--wall-muted); cursor: default; }
.album-track__title{ overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.album-track__number,
.album-track__time{ color: color-mix(in srgb, var(--wall-text) 82%, transparent); font-variant-numeric: tabular-nums; font-size: .875em; white-space: nowrap; }
.album-track__time{ text-align: right; }

.album-content-toggles{
  display: flex;
  align-items: center;
  margin-left: auto;
  gap: 8px;
}
.album-actions .controls__button--album,
.album-actions .album-content-toggle{
  width: 64px;
  height: 64px;
}
.album-actions .album-content-toggle{
  color: var(--wall-text);
  transition: color .22s ease, opacity .15s ease, transform .15s ease;
}
.album-actions .controls__button--album > svg,
.album-actions .album-content-toggle > svg{ width: 30px; height: 30px; }
.album-actions .album-content-toggle[hidden] { display: none; }
.album-content-toggle[aria-expanded="false"] { color: var(--wall-muted); }
.album-content-toggle:disabled{ opacity: .35; cursor: default; }

body[data-reduced-motion="true"] .album-details,
body[data-reduced-motion="true"] .poster__expanded--album::before,
body[data-reduced-motion="true"] .album-lyrics,
body[data-reduced-motion="true"] .album-track-row,
body[data-reduced-motion="true"] .album-actions .album-content-toggle{
  transition: none;
}

.controls.album-actions[data-mode="other"] .controls__button--primary{
  overflow: hidden;
  width: 0;
  min-width: 0;
  margin-left: 0;
  opacity: 0;
  pointer-events: none;
}

/* Function panel: monochrome editorial sheet. Opaque near-black surface, hairline rules instead of
   boxes, light display type, and inverted (ink-on-paper) selection. The host accent is reserved for
   keyboard focus. Light hosts get the same sheet in reverse. */

.control-panel {
  --cp-surface: color-mix(in srgb, var(--host-panel) 22%, var(--wall-background));
  --cp-raised: color-mix(in srgb, var(--host-text) 4%, var(--cp-surface));
  --cp-ink: var(--host-text);
  --cp-paper: var(--cp-surface);
  --cp-soft: color-mix(in srgb, var(--host-text) 62%, transparent);
  --cp-faint: color-mix(in srgb, var(--host-text) 40%, transparent);
  --cp-rule: color-mix(in srgb, var(--host-text) 9%, transparent);
  --cp-edge: color-mix(in srgb, var(--host-text) 14%, transparent);
  --cp-hover: color-mix(in srgb, var(--host-text) 5%, transparent);
  --cp-mono: ui-monospace, "SF Mono", "Cascadia Mono", "JetBrains Mono", Consolas, monospace;
  --cp-ease: cubic-bezier(.16, 1, .3, 1);
  position: fixed;
  inset: 0;
  width: min(860px, calc(100% - 40px));
  max-width: none;
  height: min(640px, calc(100dvh - 56px));
  max-height: calc(100dvh - 56px);
  margin: auto;
  padding: 0;
  overflow: hidden;
  border: 1px solid var(--cp-edge);
  border-radius: 14px;
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--host-text) 3%, transparent), transparent 140px),
    var(--cp-surface);
  color: var(--cp-ink);
  font-size: 13px;
  line-height: 1.55;
  letter-spacing: .01em;
  box-shadow:
    0 1px 0 color-mix(in srgb, var(--host-text) 6%, transparent) inset,
    0 50px 140px color-mix(in srgb, var(--wall-background) 70%, transparent),
    0 12px 32px color-mix(in srgb, var(--wall-background) 40%, transparent);
}
html[data-color-scheme="light"] .control-panel {
  --cp-surface: color-mix(in srgb, var(--host-panel) 94%, var(--host-app-bg));
}

.control-panel:not([open]),
.control-panel [hidden] { display: none; }
/* A light dim keeps the wall readable around the sheet, so lighting changes can be judged live. */
.control-panel::backdrop {
  background: color-mix(in srgb, var(--wall-background) 48%, transparent);
}
.control-panel[open] { animation: control-panel-in .32s var(--cp-ease); }
@keyframes control-panel-in {
  from { opacity: 0; transform: translateY(10px) scale(.985); }
  to { opacity: 1; transform: none; }
}
.control-panel__form {
  display: grid;
  grid-template-columns: 200px minmax(0, 1fr);
  height: 100%;
  max-height: inherit;
  margin: 0;
}

/* ---- sidebar ---------------------------------------------------------------------------------- */
.control-panel__sidebar {
  display: flex;
  flex-direction: column;
  gap: 28px;
  min-height: 0;
  padding: 28px 0 22px;
  border-right: 1px solid var(--cp-rule);
}
.control-panel__brand { padding: 0 26px; }
.control-panel__wordmark {
  margin: 0 0 10px;
  color: var(--cp-faint);
  font: 600 10px/1 var(--cp-mono);
  letter-spacing: .32em;
  text-transform: uppercase;
}
.control-panel__brand h2 {
  margin: 0;
  font-size: 17px;
  font-weight: 500;
  letter-spacing: .04em;
}
.control-panel__brand-wall {
  margin: 4px 0 0;
  color: var(--cp-soft);
  font-size: 12px;
}
.control-panel__tabs {
  display: flex;
  flex-direction: column;
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: none;
}
.control-panel .control-panel__tab {
  position: relative;
  display: flex;
  align-items: baseline;
  gap: 14px;
  width: 100%;
  min-height: 44px;
  padding: 11px 26px;
  border: 0;
  border-radius: 0;
  color: var(--cp-soft);
  font-size: 14px;
  letter-spacing: .06em;
  text-align: start;
}
.control-panel .control-panel__tab:hover:not(:disabled) { background-color: transparent; color: var(--cp-ink); }
.control-panel .control-panel__tab[aria-selected="true"] { color: var(--cp-ink); font-weight: 500; }
.control-panel .control-panel__tab:focus-visible { border-radius: 6px; outline-offset: -4px; }
/* Selected mark: a short rule on the sidebar edge. */
.control-panel__tab::before {
  content: "";
  position: absolute;
  top: 50%;
  left: 0;
  width: 2px;
  height: 0;
  background: var(--cp-ink);
  transform: translateY(-50%);
  transition: height .28s var(--cp-ease);
}
.control-panel__tab[aria-selected="true"]::before { height: 18px; }
.control-panel__tab-index {
  flex: none;
  color: var(--cp-faint);
  font: 500 10.5px/1 var(--cp-mono);
  letter-spacing: .08em;
  font-variant-numeric: tabular-nums;
}
.control-panel__tab[aria-selected="true"] .control-panel__tab-index { color: var(--cp-ink); }
.control-panel__footer {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: auto;
  padding: 0 26px;
  color: var(--cp-faint);
  font-size: 11.5px;
  letter-spacing: .04em;
}
.control-panel__shortcut { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 4px; }
.control-panel__icon { display: inline-flex; flex: none; width: 16px; height: 16px; }
.control-panel__icon svg { width: 100%; height: 100%; stroke-width: 1.5; }

/* ---- main column ------------------------------------------------------------------------------ */
.control-panel__main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
}
.control-panel__header {
  display: flex;
  flex-shrink: 0;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 30px 22px 22px 40px;
}
.control-panel__page-heading { min-width: 0; }
.control-panel__page-title {
  margin: 0;
  font-size: 28px;
  font-weight: 300;
  letter-spacing: .06em;
  line-height: 1.15;
}
.control-panel__page-description {
  margin: 8px 0 0;
  color: var(--cp-soft);
  font-size: 12.5px;
  letter-spacing: .04em;
}
.control-panel .control-panel__dismiss {
  flex: none;
  width: 34px;
  min-height: 34px;
  padding: 0;
  border: 1px solid var(--cp-rule);
  border-radius: 50%;
  color: var(--cp-soft);
}
.control-panel .control-panel__dismiss:hover:not(:disabled) { border-color: var(--cp-edge); background-color: var(--cp-hover); color: var(--cp-ink); }
.control-panel__dismiss .control-panel__icon { width: 15px; height: 15px; margin: auto; }
.control-panel__pages {
  flex: 1;
  min-height: 0;
  padding: 0 40px 36px;
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: var(--cp-edge) transparent;
}
.control-panel__page {
  display: flex;
  flex-direction: column;
  gap: 34px;
  animation: control-panel-page-in .26s var(--cp-ease);
}
@keyframes control-panel-page-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}

/* ---- sections and rows: hairline rules, no boxes ---------------------------------------------- */
.control-panel__group { display: flex; flex-direction: column; min-width: 0; }
/* Small spaced label followed by a rule that runs to the edge. */
.control-panel__group-title {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 0 0 4px;
  color: var(--cp-faint);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: .24em;
}
.control-panel__group-title::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--cp-rule);
}
.control-panel__card { display: flex; flex-direction: column; }
/* Raised above `.control-panel button` so switch rows keep their rule. */
.control-panel .control-panel__card > * + * { border-top: 1px solid var(--cp-rule); }
.control-panel__note {
  margin: 10px 0 0;
  color: var(--cp-faint);
  font-size: 11.5px;
  line-height: 1.7;
  letter-spacing: .03em;
}
.control-panel__note:empty { display: none; }
.control-panel__item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  min-width: 0;
  min-height: 60px;
  padding: 12px 0;
}
.control-panel__item--sub { position: relative; padding-left: 26px; }
/* Dependency guide: a hairline elbow from the parent setting. */
.control-panel__item--sub::before {
  content: "";
  position: absolute;
  top: 0;
  left: 6px;
  width: 9px;
  height: 50%;
  border-bottom: 1px solid var(--cp-edge);
  border-left: 1px solid var(--cp-edge);
}
.control-panel .control-panel__card > .control-panel__item--sub { border-top-color: transparent; }
.control-panel__item-text { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.control-panel__item-label {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--cp-ink);
  font-size: 14px;
  letter-spacing: .03em;
}
.control-panel__item-hint { color: var(--cp-soft); font-size: 12px; line-height: 1.5; letter-spacing: .02em; }
.control-panel__item-hint:empty { display: none; }
.control-panel__item-control {
  display: flex;
  flex: none;
  align-items: center;
  justify-content: flex-end;
  gap: 14px;
  min-width: 0;
}
.control-panel__item--wide .control-panel__item-text { flex: 0 1 auto; }
.control-panel__item--wide .control-panel__item-control { flex: 1 1 220px; max-width: 320px; }
.control-panel__item.is-disabled .control-panel__item-text { opacity: .38; }

/* ---- buttons, switches, key caps, segments ---------------------------------------------------- */
.control-panel button {
  min-height: 32px;
  padding: 6px 12px;
  border: 1px solid transparent;
  border-radius: 999px;
  background-color: transparent;
  color: var(--cp-ink);
  font: inherit;
  letter-spacing: .04em;
  white-space: nowrap;
  cursor: pointer;
  transition: background-color .2s ease, color .2s ease, border-color .2s ease;
}
.control-panel button:hover:not(:disabled) { background-color: var(--cp-hover); }
.control-panel button:disabled,
.control-panel input:disabled,
.control-panel select:disabled { opacity: .32; cursor: default; }
.control-panel :focus-visible { outline: 1.5px solid var(--host-accent); outline-offset: 3px; }
/* Hairline pills: pager, 1×, restore default, shortcut recorder. */
.control-panel .control-panel__chip,
.control-panel__pager-buttons button,
.control-panel .control-panel__shortcut-record {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-height: 30px;
  padding: 4px 14px;
  border-color: var(--cp-edge);
  font-size: 12px;
}
.control-panel .control-panel__chip:hover:not(:disabled),
.control-panel__pager-buttons button:hover:not(:disabled),
.control-panel .control-panel__shortcut-record:hover:not(:disabled) { border-color: var(--cp-ink); background-color: transparent; }
.control-panel .control-panel__chip .control-panel__icon,
.control-panel__pager-buttons .control-panel__icon { width: 13px; height: 13px; }

/* Whole-row switch. Disabled rows dim text and track instead of the whole button. */
.control-panel .control-panel__toggle {
  width: 100%;
  min-height: 60px;
  padding: 12px 0;
  border-width: 1px 0 0;
  border-radius: 0;
  font-size: inherit;
  letter-spacing: inherit;
  text-align: start;
  white-space: normal;
}
.control-panel__card > .control-panel__toggle:first-child { border-top-width: 0; }
.control-panel .control-panel__toggle:hover:not(:disabled) { background-color: transparent; }
.control-panel .control-panel__toggle.control-panel__item--sub { padding-left: 26px; }
.control-panel .control-panel__toggle:disabled { opacity: 1; }
.control-panel .control-panel__toggle:focus-visible { outline-offset: -1px; }
.control-panel__switch {
  position: relative;
  flex: 0 0 34px;
  height: 18px;
  border: 1px solid var(--cp-faint);
  border-radius: 9px;
  transition: background-color .25s ease, border-color .25s ease;
}
.control-panel__switch::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--cp-soft);
  transition: transform .3s var(--cp-ease), background-color .25s ease;
}
.control-panel__toggle:hover:not(:disabled) .control-panel__switch { border-color: var(--cp-ink); }
.control-panel__toggle[aria-checked="true"] .control-panel__switch { border-color: var(--cp-ink); background-color: var(--cp-ink); }
.control-panel__toggle[aria-checked="true"] .control-panel__switch::after { transform: translateX(16px); background: var(--cp-paper); }
.control-panel__toggle:disabled .control-panel__switch { opacity: .32; }
.control-panel__key,
.control-panel kbd {
  display: inline-block;
  min-width: 18px;
  padding: 1px 5px;
  border: 1px solid var(--cp-edge);
  border-radius: 4px;
  color: var(--cp-soft);
  font: 500 10.5px/1.5 var(--cp-mono);
  letter-spacing: .04em;
  text-align: center;
}
/* One-of-n: hairline capsule, the chosen option printed in reverse. */
.control-panel__segments {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 0;
  padding: 2px;
  border: 1px solid var(--cp-edge);
  border-radius: 999px;
}
.control-panel .control-panel__segments button {
  flex: 1;
  min-width: 44px;
  min-height: 26px;
  padding: 3px 13px;
  color: var(--cp-soft);
  font-size: 12px;
}
.control-panel .control-panel__segments button:hover:not(:disabled) { background-color: transparent; color: var(--cp-ink); }
.control-panel .control-panel__segments button[aria-pressed="true"] {
  background-color: var(--cp-ink);
  color: var(--cp-paper);
  font-weight: 500;
}

/* ---- fields and sliders ----------------------------------------------------------------------- */
.control-panel input,
.control-panel select {
  box-sizing: border-box;
  width: 100%;
  min-width: 0;
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid var(--cp-edge);
  border-radius: 8px;
  background-color: transparent;
  color: var(--cp-ink);
  font: inherit;
  letter-spacing: .02em;
  transition: border-color .2s ease;
}
.control-panel input:hover:not(:disabled),
.control-panel select:hover:not(:disabled),
.control-panel input:focus,
.control-panel select:focus { border-color: var(--cp-ink); }
.control-panel select { width: 168px; cursor: pointer; }
.control-panel select option { background-color: var(--host-panel); color: var(--host-text); }
.control-panel input::placeholder { color: var(--cp-faint); }
.control-panel input[type="color"] {
  flex: none;
  width: 30px;
  min-width: 30px;
  height: 30px;
  min-height: 30px;
  padding: 3px;
  border-radius: 50%;
  cursor: pointer;
}
.control-panel input[type="color"]::-webkit-color-swatch-wrapper { padding: 0; }
.control-panel input[type="color"]::-webkit-color-swatch { border: 0; border-radius: 50%; }
.control-panel input[type="range"] {
  --fill: 50%;
  flex: 1;
  min-width: 96px;
  height: 20px;
  min-height: 20px;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background-color: transparent;
  cursor: pointer;
  -webkit-appearance: none;
  appearance: none;
}
.control-panel input[type="range"]::-webkit-slider-runnable-track {
  height: 2px;
  background: linear-gradient(to right, var(--cp-ink) var(--fill), var(--cp-edge) var(--fill));
}
.control-panel input[type="range"]::-webkit-slider-thumb {
  width: 13px;
  height: 13px;
  margin-top: -5.5px;
  border: 0;
  border-radius: 50%;
  background: var(--cp-ink);
  box-shadow: 0 0 0 3px var(--cp-surface);
  transition: transform .2s var(--cp-ease);
  -webkit-appearance: none;
  appearance: none;
}
.control-panel input[type="range"]:hover:not(:disabled)::-webkit-slider-thumb,
.control-panel input[type="range"]:active:not(:disabled)::-webkit-slider-thumb { transform: scale(1.25); }
.control-panel__value {
  flex: none;
  min-width: 52px;
  color: var(--cp-ink);
  font: 500 12px/1 var(--cp-mono);
  font-variant-numeric: tabular-nums;
  letter-spacing: .02em;
  text-align: end;
}
.control-panel__value--code { min-width: 64px; color: var(--cp-soft); }

/* ---- browse page ------------------------------------------------------------------------------ */
.control-panel__walls {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  padding: 14px 0 2px;
}
.control-panel .control-panel__wall {
  position: relative;
  display: flex;
  align-items: flex-start;
  min-height: 78px;
  padding: 16px 44px 16px 18px;
  border: 1px solid var(--cp-rule);
  border-radius: 10px;
  text-align: start;
  white-space: normal;
}
.control-panel .control-panel__wall:hover:not(:disabled) { border-color: var(--cp-edge); background-color: transparent; }
.control-panel .control-panel__wall[aria-pressed="true"] {
  border-color: var(--cp-ink);
  background-color: var(--cp-raised);
  cursor: default;
}
.control-panel__wall-text { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.control-panel__wall-name { font-size: 15px; letter-spacing: .06em; }
.control-panel__wall-description { color: var(--cp-soft); font-size: 12px; letter-spacing: .03em; }
/* Radio mark: a hairline ring, filled for the current wall. */
.control-panel__wall-dot {
  position: absolute;
  top: 18px;
  right: 18px;
  width: 12px;
  height: 12px;
  border: 1px solid var(--cp-faint);
  border-radius: 50%;
}
.control-panel__wall[aria-pressed="true"] .control-panel__wall-dot {
  border-color: var(--cp-ink);
  background: var(--cp-ink);
  box-shadow: inset 0 0 0 2.5px var(--cp-raised);
}
.control-panel__search-body { padding: 10px 0 4px; }
.control-panel__search { position: relative; display: flex; align-items: center; }
.control-panel__search .control-panel__icon {
  position: absolute;
  left: 0;
  width: 17px;
  height: 17px;
  color: var(--cp-faint);
  pointer-events: none;
}
.control-panel input[type="search"] {
  min-height: 50px;
  padding: 0 0 0 30px;
  border-width: 0 0 1px;
  border-radius: 0;
  font-size: 18px;
  font-weight: 300;
  letter-spacing: .04em;
}
.control-panel input[type="search"]::-webkit-search-cancel-button { filter: grayscale(1); opacity: .5; cursor: pointer; }
/* Focus thickens the underline instead of boxing the field. */
.control-panel input[type="search"]:focus-visible { outline: 0; box-shadow: 0 1px 0 var(--cp-ink); }
.control-panel__search:focus-within .control-panel__icon { color: var(--cp-ink); }
.control-panel__pager {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px 16px;
  padding: 14px 0;
}
.control-panel__status {
  color: var(--cp-soft);
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  letter-spacing: .04em;
}
.control-panel__pager-buttons { display: flex; gap: 8px; }

/* ---- general page ----------------------------------------------------------------------------- */
.control-panel .control-panel__shortcut-record { justify-content: center; min-width: 120px; gap: 4px; }
.control-panel .control-panel__shortcut-record[aria-pressed="true"] { border-color: var(--cp-ink); background-color: var(--cp-hover); }
.control-panel__keys {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px 32px;
  margin: 0;
  padding: 18px 0 6px;
}
.control-panel__keys-item { display: flex; align-items: baseline; gap: 12px; min-width: 0; }
.control-panel__keys dt { display: flex; flex: none; gap: 4px; min-width: 76px; }
.control-panel__keys dd { margin: 0; color: var(--cp-soft); font-size: 12px; letter-spacing: .02em; }

/* ---- narrow windows: the sidebar becomes a top strip (see NARROW in controlPanelTabs.ts) -------- */
@media (max-width: 640px) {
  .control-panel {
    width: calc(100% - 20px);
    height: calc(100dvh - 20px);
    max-height: calc(100dvh - 20px);
  }
  .control-panel__form { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
  .control-panel__sidebar { padding: 0; border-right: 0; border-bottom: 1px solid var(--cp-rule); }
  .control-panel__brand,
  .control-panel__footer { display: none; }
  .control-panel__tabs { flex-direction: row; overflow-x: auto; }
  .control-panel .control-panel__tab { flex: none; width: auto; min-height: 48px; padding: 14px 16px; }
  .control-panel__tab::before { top: auto; bottom: 0; left: 50%; width: 0; height: 2px; transform: translateX(-50%); transition-property: width; }
  .control-panel__tab[aria-selected="true"]::before { width: 18px; height: 2px; }
  .control-panel__header { padding: 22px 14px 16px 22px; }
  .control-panel__pages { padding: 0 22px 24px; }
  .control-panel__item--wide { flex-wrap: wrap; }
  .control-panel__item--wide .control-panel__item-control { flex-basis: 100%; max-width: none; }
  .control-panel__walls,
  .control-panel__keys { grid-template-columns: minmax(0, 1fr); }
}

body[data-reduced-motion="true"] .control-panel,
body[data-reduced-motion="true"] .control-panel *,
body[data-reduced-motion="true"] .control-panel *::before,
body[data-reduced-motion="true"] .control-panel *::after { transition: none; animation: none; }
@media (prefers-reduced-motion: reduce) {
  .control-panel,
  .control-panel *,
  .control-panel *::before,
  .control-panel *::after { transition: none; animation: none; }
}

.lattice-wall-host,
.lattice-wall {
  height: 100%;
}

body[data-desktop-wall="true"] .locate {
  bottom: calc(18px + var(--desktop-wall-bottom-inset, 0px));
}

